(window.GIM_TP=window.GIM_TP||{})["Z.Nasso.0"]={"from":0,"a":[[["(במדבר ד׳:כ״א-כ״ב) וַיְדַבֵּר יְיָ אֶל מֹשֶׁה לֵאמֹר, נָשֹׂא אֶת רֹאשׁ בְּנֵי גֵּרְשׁוֹן וְגוֹ'. רִבִּי אַבָּא פָּתַח, (תהילים ל״ב:ב׳) אַשְׁרֵי אָדָם לֹא יַחֲשׁוֹב יְיָ לוֹ עָוֹן וְאֵין בְּרוּחוֹ רְמִיָּה. הַאי קְרָא, לָאו רֵישֵׁיהּ סֵיפֵיהּ, וְלָאו סֵיפֵיהּ רֵישֵׁיהּ. וְאִית לְאִסְתַּכְּלָא בֵּיהּ, וְהָא אוּקְמוּהָ.","תָּא חֲזֵי, בְּשַׁעֲתָא דִּצְלוֹתָא דְּמִנְחָה דִּינָא שַׁרְיָא בְּעָלְמָא, וְיִצְחָק תִּקֵּן צְלוֹתָא דְּמִנְחָה, וּגְבוּרָה עִלָּאָה שַׁלְטָא בְּעָלְמָא, עַד דְּאָתֵי וְעָאל לֵילְיָא, בְּגִין לְקַבְּלָא לֵיהּ (לליליא), וּמִזִּמְנָא דְּשָׁארִי צְלוֹתָא דְּמִנְחָה, אִתְפְּרַשׁ שְׂמָאלָא לְקַבְּלָא (ליה) וְאִתְּעַר לֵילְיָא.","בָּתַר דְּאִתְּעַר כָּל אִינּוּן נְטוּרֵי פִּתְחִין דִּלְבַר, כֻּלְּהוּ מִתְעָרִין בְּעָלְמָא וְאִתְפָּשָׁטוּ. וְכָל בְּנֵי עָלְמָא טַעֲמִין טַעֲמָא דְּמוֹתָא."],[[0,"וידבר וגו׳ נשא את ראש","וגו׳: ר׳ אבא פתח. אשרי אדם לא יחשוב ה׳ לו עון ואין ברוחו רמיה. מקרא זה אין ראשו סופו ואין סופו ראשו. כי תחילה אומר לא יחשוב וגו׳ משמע שיש בו עון, אלא לא יחשוב לו. ולבסוף אמר, ואין ברוחו רמיה. ויש להסתכל בו. וכבר העמידוהו."],[1,"ת״ח בשעתא דצלותא","וכו׳: בוא וראה. בשעת תפלת המנחה הדין שורה בעולם, ויצחק, שהוא גבורה עליונה וקו שמאל דז״א. תקן תפלת המנחה שאז נעשה הזווג בסוד שמאלו תחת לראשי, וע״כ גבורה עליונה שולטת בעולם עד שבא ונכנס הלילה, משום שהגבורה מקבלת את הלילה. כלומר שלילה שהיא מלכות נמשכת מגבורה, שהיא תפלת המנחה. ומזמן שמתחיל תפלת המנחה, נפרש השמאל לקבל את המלכות, ונתעורר הלילה. שהוא מלכות."],[2,"כתר דאתער כל","וכו׳: אחר שנתעורר הלילה, כל אלו שומרי פתחים החצונים כולם מתעוררים בעולם ומתפשטים. וכל בני העולם טועמים טעם המות."]],[[0,"","וַיְדַבֵּר ה' אֶל מֹשֶׁה לֵּאמֹר נָשֹׂא אֶת רֹאשׁ בְּנֵי גֵרְשׁוֹן וְגוֹ'. רַבִּי אַבָּא פָּתַח, (תהלים לב) אַשְׁרֵי אָדָם לֹא יַחְשּב ה' לוֹ עָון וְאֵין בְּרוּחוֹ רְמִיָּה. הַפָּסוּק הַזֶּה אֵין רֹאשׁוֹ סוֹפוֹ, וְאֵין סוֹפוֹ רֹאשׁוֹ. וְיֵשׁ לְהִסְתַּכֵּל בּוֹ, וְכָךְ פֵּרְשׁוּהוּ."],[1,"","בֹּא רְאֵה, בִּשְׁעַת תְּפִלַּת מִנְחָה הַדִּין שׁוֹרֶה בָּעוֹלָם, וְיִצְחָק תִּקֵּן תְּפִלַּת מִנְחָה, וּגְבוּרָה עֶלְיוֹנָה שׁוֹלֶטֶת בָּעוֹלָם, עַד שֶׁבָּא וְנִכְנָס הַלַּיְלָה, בִּשְׁבִיל לְקַבֵּל אוֹתוֹ (ללילה). וּמִזְּמַן שֶׁשּׁוֹרָה תְפִלַּת מִנְחָה, נִפְרָד הַשְּׂמֹאל לְקַבֵּל (אותו) וּמִתְעוֹרֵר הַלַּיְלָה."],[2,"","אַחַר שֶׁמִּתְעוֹרְרִים כָּל אוֹתָם שׁוֹמְרֵי הַפְּתָחִים שֶׁבַּחוּץ, כֻּלָּם מִתְעוֹרְרִים בָּעוֹלָם וּמִתְפַּשְּׁטִים, וְכָל בְּנֵי הָעוֹלָם טוֹעֲמִים טַעַם מָוֶת."]]],[["וְהָא אִתְּמַר. בְּפַלְגוּת לֵילְיָא מַמָּשׁ, אִתְּעַר שְׂמָאלָא כְּמִלְּקַדְּמִין, וּוַרְדָּא קַדִּישָׁא סַלְּקָא רֵיחִין, וְהִיא מְשָׁבַּחַת וַאֲרִימַת קָלָא, וּכְדֵין סַלְּקָא וְשַׁרְיָא רֵישָׁא לְעֵילָּא בִּשְׂמָאלָא, וּשְׂמָאלָא מְקַבֵּל לָהּ.","כְּדֵין כָּרוֹזָא קָארֵי בְּעָלְמָא, דְּהָא עִידָּן הוּא לְאִתְּעָרָא לְשַׁבְּחָא לֵיהּ לְמַלְכָּא. וּכְדֵין תּוּשְׁבְּחָן מִתְעָרִין, וְאִתְבַּסְּמוּתָא דְּכֹלָּא אִשְׁתְּכַח. זַכָּאָה חוּלָקֵיהּ מַאן דְּאִתְּעַר לְזַוְּוגָא זִוּוּגָא דָּא. כַּד אָתֵי צַפְרָא, וִימִינָא אִתְּעַר וּמְחַבְּקָא לָהּ, כְּדֵין זִוּוּגָא דְּכֹלָּא אִשְׁתְּכַח כַּחֲדָא. (ס\"א למלכא, כד אתי צפרא וימינא אתער ומחבק לה כדין זווגא דכלא אשתכח כחדא וכדין תושבחתן מתערין ואתבסמותא דכלא אשתכח זכאה חולקיה מאן דאתער לזווגא זווגא דא)","תָּא חֲזֵי, בְּשַׁעֲתָא דִּבְנֵי נָשָׁא דְּמִיכִין, וְטַעֲמִין טַעֲמָא דְּמוֹתָא, וְנִשְׁמְתָא סַלְּקָא לְעֵילָּא, קַיְּימָא בַּאֲתָר דְּקַיְּימָא, וְאִתְבְּחִינַת עַל עוֹבָדָהָא דְּעַבְדַּת כָּל יוֹמָא, וְכַתְבִין לְהוּ עַל פִּתְקָא. מַאי טַעְמָא. בְּגִין דְּנִשְׁמְתָא סַלְּקָא לְעֵילָּא, וְאַסְהִידַת עַל עוֹבָדוֹי דְּבַּר נָשׁ, וְעַל כָּל מִלָּה וּמִלָּה דְּנָפִיק מִפּוּמֵיהּ.","וְכַד הַהִיא מִלָּה דְּאַפִּיק בַּר נָשׁ מִפּוּמֵיהּ אִיהִי כְּדְקָא יָאוּת, מִלָּה קַדִּישָׁא דְּאוֹרַיְיתָא וּצְלוֹתָא. הַהִיא מִלָּה סַלְּקָא, וּבָקַע רְקִיעִין, וְקַיְּימָא בְּאֲתָר דְּקַיְּימָא, עַד דְּעָאל לֵילְיָא, וְנִשְׁמְתָא סַלְּקָא וְאָחִיד לְהַהִיא מִלָּה, וְעָאִיל לָהּ קַמֵּי מַלְכָּא.","וְכַד הַהִיא מִלָּה לָאו אִיהִי כְּדְקָא יָאוּת, וְאִיהִי מִלָּה מִמִּילִין בִּישִׁין, מִלִּישָׁנָא בִּישָׁא, הַהִיא מִלָּה סַלְּקָא לַאֲתָר דְּסַלְּקָא, וּכְדֵין אִתְרְשִׁים הַהִיא מִלָּה, וְהַהוּא חוֹבָה עָלֵיהּ דְּבַּר נָשׁ, הֲדָא הוּא דִכְתִיב, (מיכה ז׳:ה׳) מִשּׁוֹכֶבֶת חֵיקֶךָ שְׁמוֹר פִּתְחֵי פִּיךָ. וּבְגִין כָּךְ (תהילים ל״ב:ב׳) אַשְׁרֵי אָדָם לֹא יַחֲשׁוֹב יְיָ לוֹ עָוֹן. אֵימָתַי. כְּשֶׁאֵין בְּרוּחוֹ רְמִיָּה.","\u0003רעיא מהימנא\u0004 (במדבר ד׳:מ״ז) מִבֶּן שְׁלֹשִׁים שָׁנָה וָמַעְלָה וְעַד בֶּן חֲמִשִּׁים שָׁנָה כָּל הַבָּא לַעֲבוֹד עֲבוֹדַת עֲבוֹדָה וַעֲבוֹדַת מַשָּׂא בְּאֹהֶל מוֹעֵד. פִּקּוּדָא דָּא לִהְיוֹת הַלְּוִיִּם מְשׁוֹרְרִים בַּמִקְדָּשׁ. וְאַף עַל גַּב דְּאוֹקִימְנָא לְעֵילָּא, הָכָא צָּרִיךְ לְחַדֵּשׁ מִלִּין, דְּהָא כֹּהֵן אִיהוּ מַקְרִיב קָרְבְּנָא, וְאִיהוּ מִיכָאֵל. לֵוִי אִיהוּ גַּבְרִיאֵל. אִיהוּ צָּרִיךְ לְנַגְּנָא.","וְרָזָא דְּמִלָּה, (תהילים מ״ב:ט׳) יוֹמָם יְצַּוְּה יְיָ חַסְדּוֹ, דָּא חֶסֶד כַּהֲנָא רַבָּא דְּמִיכָאֵל אִיהוּ כֹּהֵן הֶדְיוֹט לְגַבֵּי מָארֵיהּ, וְעִם כָּל דָּא דְּהֶדְיוֹט אִיהוּ אֵצֶּל מָארֵיהּ. מֶלֶךְ דְּחַיּוֹת הַקֹּדֶשׁ אִיהוּ. וּבִרְכַּת הֶדְיוֹט אַל תְּהִי קַלָה בְּעֵינֶיךָ, וְהַאי אִיהוּ יוֹמָם יְצַּוְּה יְיָ חַסְדּוֹ.","וּבַלַּיְלָה שִׁירֹה עִמִּי, דָּא גְּבוּרָה. שִׁירֹה: (דברים ל״ג:י״ז) בְּכוֹר שׁוֹרוֹ הָדָר לוֹ. (יחזקאל א׳:י׳) וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל, וְגַבְרִיאֵל שְׁלוּחֵיהּ, וְצָּרִיךְ לְשׁוֹרֵר וּלְנַגֵּן בְּחֶדְוָה בְּחַמְרָא דְּאוֹרַיְיתָא, (לאתעסקא לשלחא קרבנא קמי מלכא בחדוה ומאן דלית ליה רשו) לְאִתְעַסְּקָא בְּאוֹרַיְיתָא, יְקַיֵּים (איכה ב׳:י״ט) קוּמִי רֹנִּי בַלַּיְלָה לְרֹאשׁ אַשְׁמוּרֹת.","וְיֵימָּא בְּאַשְׁמוּרוֹת, כַּמָה סְלִיחוֹת וְתַחֲנוּנִים וּבַקָּשׁוֹת, בְּכָל מִינֵי רִנָּה בִּגְרוֹנֵיהּ, דְּאִיהוּ כִּנּוֹר לְאַפָּקָא בֵּיהּ קָלָא, בְּשִׁית כַּנְפֵי רֵיאָה עִם וַורְדָא. בְּשִׁית עִזְקָאן דְּקָנֶה. וְדָא ו'. וְיִפּוּק לֵיהּ מִלִּבָּא, דְּתַמָּן בִּינָה. כְּמָה דְּאוּקְמוּהָ מָארֵי מַתְנִיתִין, הַלֵּב מֵבִין. יִפּוּק בֵּן מִבִּינָה, מִבֶּן יָהּ, דְּאִיהוּ ו', דְּאִיהוּ אֶפְרוֹחַ בְּשִׁית גַּדְפִּין. וִיסַלֵּק לֵיהּ בְּשִׁית עִזְקָאן דְּקָנֶה, דְּאִינּוּן (מלכים א י׳:י״ט) שֵׁשׁ מַעֲלוֹת לַכִּסֵּא.","וב' כֻּרְסְיָין אִינּוּן (ירמיהו י״ז:י״ב) כִּסֵּא כָבוֹד מָרוֹם מֵרִאשׁוֹן, וְאִינּוּן לִבָּא וּפוּמָא. לֵ\"ב, (שמות י״ז:ט״ז) וַיֹּאמֶר כִּי יָד עַל כֵּס יָהּ מִלְחָמָה לַיְיָ בַּעֲמָלֵק, (בנה\"ר) כָּבֵד, סָמָאֵ\"ל, פּוּמָא דְּכִסֵּ\"ה, כֵּ\"ס י\"ה, הֲדָא הוּא דִכְתִיב, (תהילים פ״א:ד׳) תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר וְגוֹ'.","מַאי שׁוֹפָר. קָנֶה, ו', קוֹל דְּסָלִיק מִן הַקָּנֶה, לְגַבֵּי פּוּמָא, דְּתַמָּן ה'. בְּה' מִינֵי תִּקּוּנִין דְּדִבּוּרָא, דְּאִינּוּן שִׂפְוָון וְשִׁינַיִם וְחֵיךְ. שִׂפְוָון תְּרֵין. שִׁינַיִם וְטוֹחֲנוֹת תְּרֵין מִינִין. וְחֵיךְ, הָא חָמֵשׁ. דְּטָחֲנִין כְּנָהָר דְּאִיהוּ קוֹל, כְּגַוְונָא דְּטָחֲנִין רֵיחַיָיא. לְאַפָּקָא קוֹל וְדִבּוּר, דְּנָפִיק מִבִּינָה דְּלִבָּא. בְּמַחֲשָׁבָה.","דְּאִיהוּ שְׁמָא מְפֹרָשׁ בְּעֶשֶׂר מִינֵי תִּלִּים. וּבְשׁוֹפָר, אֵין פּוֹחֲתִין מֵעֲשַׂרָה שׁוֹפָרוֹת. וְאוֹרַיְיתָא, קָלָא דִּילָהּ, דִּיבּוּר דִּילָהּ, בִּינָה דִּילָהּ, דְּאוּקְמוּהָ אֵיזְהוּ חָכָם הַמֵּבִין דָּבָר מִתּוֹךְ דָּבָר. מַחֲשָׁבָה דִּילֵיהּ. חָשִׁיב קָמֵי קוּדְשָׁא בְּרִיךְ הוּא, מִכָּל קָרְבְּנִין וְעִלָּוָון, הֲדָא הוּא דִכְתִיב, (ויקרא ז׳:ל״ז) זֹאת הַתּוֹרָה לְעוֹלָה וְלַמִּנְחָה. (ע\"כ רעיא מהימנא) (כ\"ד ע\"ב פקודא דא המועל בהקדש וכו')","(במדבר ה׳:ו׳) אִישׁ אוֹ אִשָׁה כִּי יַעֲשׂוּ מִכָּל חַטֹּאת הָאָדָם וְגוֹ'. תָּא חֲזֵי, כְּתִיב (שופטים ד׳:י״א) וְחֶבֶר הַקֵּינִי נִפְרָד מִקַּיִן מִבְּנֵי חוֹבָב חוֹתֵן מֹשֶׁה וְגוֹ', וְחֶבֶר הַקֵּינִי מִבְּנֵי בְּנוֹי דְּיִתְרוֹ הֲוָה, כְּמָה דְאַתְּ אָמֵר (שמואל א ט״ו:ו׳) וַיֹּאמֶר שָׁאוּל אֶל הַקֵּינִי וְגוֹ'. אֲמַאי אִקְרֵי קֵינִי. וְהָא אוּקְמוּהָ. וּכְתִיב (בראשית ט״ו:י״ט) אֶת הַקֵּינִי וְאֶת הַקְּנִיזִּי. וְאִתְּמַר דְּעַבֲד קִנָּא בְּמַדְבְּרָא, כְּעוֹפָא דָּא, בְּגִין לְמִלְעֵי בְּאוֹרַיְיתָא, וְאִתְפְּרַשׁ מִן מָתָא, נִפְרָד מִקַּיִן, אִתְפְּרַשׁ מֵהַהוּא עַמָּא דְּהֲוָה בְּקַדְמִיתָא, וְאִתְדַּבָּק בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, נִפְרַד מִקַּיִן."],[[0,"והא אתמר","וכו׳: והרי למדנו, בחצות לילה ממש, נתעורר השמאל כמקודם, כבעת תפלת המנחה, והשושנה הקדושה, שהיא מלכות, מעלה ריחות שה״ס הארת החכמה משמאל, והיא משבחת ומרימה קול, אז עולה ושורה הראש שלה למעלה בשמאל, בסו״ה שמאלו תחת לראשי, והשמאל מקבל אותה. (וענין חצות עי׳ לעיל ויגש דף י״א י״ה ביאור. ולך דף נ״ג ד״ה פירוש. וישלח קל״ח ד״ה וג׳)."],[1,"כדין כרוזא קארי","וכו׳: אז כרוז קורא בעולם: הגיע הזמן לקום משינה, ולשבח את המלך. ואז מתעוררים תשבחות, ונמצאת התבשמות הכל. אשרי חלקו מי שמעורר לזווג זווג הזה. כשבא הבקר, והימין, שהוא חסד, מתעורר ומחבק אותה, אז נמצא זווג הכל כאחד בין לחכמה ובין לחסדים. משא״כ בלילה אין שם חסדים."],[2,"ת״ח בשעתא דבני","וכו׳: בוא וראה בשעה שבני אדם ישנים וטועמים טעם המיתה, והנשמה עולה למעלה, היא עומדת במקום שעומדת ונבחנת על מעשיה שעשתה כל היום, וכותבים אותם בספר. מהו הטעם. משום שהנשמה עולה למעלה ומעידה על מעשיו של האדם, ועל כל מלה ומלה שהוציא מפיו."],[3,"וכד ההיא מלה","וכו׳: וכשהמלה ההיא שהאדם הוציא מפיו היא כראוי, שהיא מלה קדושה של תורה ותפלה, אז מלה ההיא עולה ובוקעת רקיעים, ועומדת במקום שעומדת, עד שמגיע הלילה, והנשמה עולה, ואוחזת למלה ההיא, ומכניסה אותה לפני המלך."],[4,"וכד ההיא מלה לאו","וכו׳: וכשהמלה ההיא אינה כראוי, והיא מלה מהמלים הרעות, מלשון הרע, המלה ההיא עולה למקום שעולה, ואז נרשמת המלה ההיא ואותו העון על האדם. ז״ש, משוכבת חיקך שמור פתחי פיך, דהיינו מהנשמה המעידה על מעשיו. ומשום זה כתוב, אשרי אדם לא יחשוב ה׳ לו עון. דהיינו כשאין הנשמה מעידה עליו, שירשם לו איזה עון. ומתי הוא, כשאין ברוחו רמיה. דהיינו כשאינו חוטא."],[5,"מבן שלשים שנה ומעלה","וגו׳: מצוה זו היא, להיות הלוים משוררים במקדש. ואע״פ שכבר העמדנו למעלה, כאן צריך לחדש דברים. כי הכהן הוא המקריב קרבן, והוא המלאך מיכאל, שהוא חסד, והחסד הוא כהן. לוי הוא גבריאל, שהוא גבורה, וגבורה נקראת לוי, והוא צריך לנגן."],[6,"ורזא דמלה יומם","וכו׳: וסוד הדבר, יומם יצוה ה׳ חסדו זה הוא חסד דז״א שהוא כהן גדול. כי מיכאל הוא כהן הדיוט כלפי אדונו, שהוא חסד דז״א, ועם כל זה אע״פ שהוא כהן הדיוט כלפי אדונו, הוא מלך על חיות הקודש שביצירה. ועליו אמרו, אל תהיה ברכת הדיוט קלה בעיניך. וזה הוא יומם יצוה ה׳ חסדו."],[7,"ובלילה שירה עמי:","זהו גבורה דז״א, כי \u0003שירה\u0004 היא כמו בכור \u0003שורו\u0004 הדר לו. ופני \u0003שור\u0004 מהשמאל. ושירה ושור שוים זה לזה. וגבריאל הוא שליחו של הגבורה, וצריך לשורר לנגן בשמחה ביינה של תורה, לעסוק בתורה, ולקיים, קומי רוני בלילה לראש אשמורות."],[8,"ויימא באשמורות כמה","וכו׳: ויאמר באשמורות כמה סליחות ותחנונים ובקשות, בכל מיני רנה בגרונו, שהוא כנור להוציא בו קול בשש כנפי ריאה, דהיינו חמשה אונות הריאה עם וורדא, שהיא אונה קטנה התלויה בריאה. ובשש טבעות הקנה, וזה רומז על \u0003ו׳,\u0004 כנגד ז״א, שהוא יוצא מן הלב, ששם הוא בינה. כמו שהעמידו בעלי המשנה, הלב מבין. ויצא בן, שהוא ז״א, מבינה, מבן י״ה, כי בינה היא אותיות, בן י״ה, שהוא \u0003ו׳,\u0004 שהוא אפרוח בשש כנפים, דהיינו ז״א שיש לו שש ספירות חג״ת נה״י. ויעלה אותן בשש טבעות הקנה, שהם שש מעלות לכסא, כי חג״ת נה״י דז״א הם שש מעלות אל הבינה הנקראת כסא אל החכמה."],[9,"וב׳ כרסיין אינון","וכו׳: ושני כסאות הם, שכתוב, כסא כבוד מרום מראשון, שפירושו שהוא מרומם מכסא הראשון, הרי שיש ב׳ כסאות. והם \u0003לב,\u0004 שהוא בינה, \u0003ופה,\u0004 שהוא מלכות. \u0003לב,\u0004 היינו שכתוב, ויאמר כי יד על כס יה, שהוא בינה, שהיא כס אל י״ה שהוא חכמה. והלב ה״ס מלחמה לה׳ בעמלק, שהוא סוד כבד, דהיינו סמאל. \u0003הפה\u0004 ה״ס כסה דהיינו כס \u0003ה׳.\u0004 ז״ש תקעו בחדש שופר בכס \u0003ה\u0004 וגו׳. שהוא הפה, דהיינו המלכות, שהוא כסא של \u0003ה׳\u0004 אחרונה דהויה. ויש בה ה׳ תקונים של הפה כמ״ש לפנינו."],[10,"מאי שופר קנה","וכו׳: ומפרש מהו שופר, שאומר תקעו בחדש שופר, הוא קנה, שהוא \u0003ו׳\u0004 שה״ס ז״א שנק׳ \u0003ו׳\u0004 ונקרא קול, והוא קול העולה מן הקנה, אל הפה, שהוא מלכות ששם \u0003ה׳\u0004 והיינו שכתוב, \u0003בכסה\u0004 ליום חגנו, בכס \u0003ה׳,\u0004 דהיינו ב \u0003ה׳\u0004 תקונים של הדבור, שהם שפתים ושינים וחיך. שפתים הן שתים, שינים יש בהם שינים וטוחנות שהן ב׳ מינים, הן ארבע. וחיך, הרי חמשה, שהם \u0003ה׳\u0004 תקונים של הדבור. שהם טוחנים כנהר שהוא קול, כמו שטוחנים ריחים, להוציא קול ודבור היוצא מבינה שהוא הלב. ובמחשבה, שה״ס חכמה."],[11,"דאיהו שמא מפרש","וכו׳: שהוא שם המפורש בעשרה מיני תהלים. שהם כנגד עשר ספירות, אף כאן המחשבה היא חכמה, הלב הוא בינה, הקנה ה״ס ז״א, שבו חג״ת נה״י שש טבעות הקנה. הפה הוא מלכות. ועם השורש שהוא כתר הם ע״ס. וע״כ ובשופר אין פוחתים מעשרה שופרות, שהם כנגד ע״ס. והתורה, הקול שלה הדבור שלה, בינה שלה שהעמדנו איזה חכם המבין דבר מתוך דבר, והמחשבה שלה, שהיא חכמה, הם עשר ספירות, כי קול הוא ז״א שבו חג״ת נה״י, דבור הוא מלכות, ובינה וחכמה שלה עם השורש שהוא כתר הן ע״ס. וע״כ התורה חשובה לפני הקב״ה מכל הקרבנות והעולות. ז״ש זאת התורה לעולה ולמנחה. (ע״כ רעיא מהימנא)"],[12,"איש או אשה","וגו׳: בוא וראה, כתוב, וחבר הקיני נפרד מקין מבני חובב חותן משה. וחבר הקיני היה מבני בניו של יתרו. כש״א ויאמר שאול אל הקיני וגו׳. למה נקרא קיני. וכבר העמדנו. וכתוב ואת הקיני ואת הקניזי. ולמדנו, שעשה קן במדבר לעסוק בתורה כמו עוף הזה, ונפרש מן העיר, ונפרד מקין, ונפרד מעם ההוא, דהיינו מדינים, שהיה בהם תחילה, ונתדבק בהקב״ה. וע״כ נפרד מקין."]],[[0,"","וַהֲרֵי נִתְבָּאֵר. בַּחֲצוֹת הַלַּיְלָה מַמָּשׁ מִתְעוֹרֵר הַשְּׂמֹאל כְּמִקֹּדֶם, וְשׁוֹשַׁנָּה הַקְּדוֹשָׁה מַעֲלָה רֵיחוֹת וּמְשַׁבַּחַת וּמְרִימָה קוֹל, וְאָז עוֹלֶה וְשׁוֹרֶה הָרֹאשׁ לְמַעְלָה בַּשְּׂמֹאל, וְהַשְּׂמֹאל אָז מְקַבְּלָהּ."],[1,"","אָז הַכָּרוֹז קוֹרֵא בָעוֹלָם, שֶׁהֲרֵי זְמַן הוּא לְהִתְעוֹרֵר לְשַׁבֵּחַ לַמֶּלֶךְ. וְאָז תִּשְׁבָּחוֹת מִתְעוֹרְרוֹת, וְנִמְצֵאת הִתְבַּשְּׂמוּת הַכֹּל. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁמִּתְעוֹרֵר לְזַוֵּג זִוּוּג זֶה כְּשֶׁבָּא הַבּקֶר, וְהַיָּמִין מִתְעוֹרֵר וּמְחַבְּקָהּ, וְאָז זִוּוּג הַכֹּל נִמְצָא כְאֶחָד. (למלך, כשבא הבקר והימין מתעורר ומחבק אותה, אז נמצא זווג הכל כאחד, ואז התשבחות מתעוררות ונמצאת התבשמות הכל. אשרי חלקו של מי שמעורר לזוג זווג זה)."],[2,"","בֹּא רְאֵה, בְּשָׁעָה שֶׁבְּנֵי אָדָם יְשֵׁנִים וְטוֹעֲמִים טַעַם מָוֶת וְהַנְּשָׁמָה עוֹלָה לְמַעְלָה - עוֹמֶדֶת בְּמָקוֹם שֶׁעוֹמֶדֶת, וְנִבְחֶנֶת עַל מַעֲשֶׂיהָ שֶׁעָשְׂתָה כָּל הַיּוֹם, וְכוֹתְבִים אוֹתָם עַל פֶּתֶק. מַדּוּעַ? מִשּׁוּם שֶׁהַנְּשָׁמָה עוֹלָה לְמַעְלָה וּמְעִידָה עַל מַעֲשֵׂי הָאָדָם וְעַל כָּל דִּבּוּר וְדִבּוּר שֶׁיּוֹצֵא מִפִּיו."],[3,"","וּכְשֶׁאוֹתוֹ דִבּוּר שֶׁהוֹצִיא הָאִישׁ מִפִּיו הוּא כָּרָאוּי, דִּבּוּר קָדוֹשׁ שֶׁל תְּפִלָּה וְתוֹרָה - אוֹתוֹ דִבּוּר עוֹלֶה וּבוֹקֵעַ רְקִיעִים, וְעוֹמֵד בְּמָקוֹם שֶׁעוֹמֵד, עַד שֶׁנִּכְנָס הַלַּיְלָה, וְהַנְּשָׁמָה עוֹלָה וְאוֹחֶזֶת אוֹתוֹ הַדִּבּוּר וּמַכְנִיסָתוֹ לִפְנֵי הַמֶּלֶךְ."],[4,"","וּכְשֶׁאוֹתוֹ דִבּוּר אֵינוֹ כָרָאוּי, וְהוּא דִּבּוּר מִדִּבּוּרִים רָעִים, מִלָּשׁוֹן הָרָע - אוֹתוֹ הַדִּבּוּר עוֹלֶה לְמָקוֹם שֶׁעוֹלֶה, וְנִרְשָׁם אוֹתוֹ דִבּוּר וְאוֹתוֹ חֵטְא עַל הָאָדָם. זֶהוּ שֶׁכָּתוּב (מיכה ז) מִשֹּׁכֶבֶת חֵיקֶךְ שְׁמֹר פִּתְחֵי פִיךְ. וְלָכֵן אַשְׁרֵי אָדָם לֹא יַחְשֹׁב ה' לוֹ עָון, אֵימָתַי? כְּשֶׁאֵין בְּרוּחוֹ רְמִיָּה."],[5,"","מִבֶּן שְׁלֹשִׁים שָׁנָה וָמַעְלָה וְעַד בֶּן חֲמִשִּׁים שָׁנָה כָּל הַבָּא לַעֲבֹד עֲבֹדַת עֲבֹדָה וַעֲבֹדַת מַשָּׂא בְּאֹהֶל מוֹעֵד. מִצְוָה זוֹ לִהְיוֹת הַלְוִיִּם מְשׁוֹרְרִים בַּמִּקְדָּשׁ. וְאַף עַל גַּב שֶׁבֵּאַרְנוּ לְמַעְלָה, כָּאן צָרִיךְ לְחַדֵּשׁ דְּבָרִים, שֶׁהֲרֵי הַכֹּהֵן מַקְרִיב קָרְבָּן, וְהוּא מִיכָאֵל. לֵוִי הוּא גַּבְרִיאֵל, הוּא צָרִיךְ לְנַגֵּן."],[6,"","וְסוֹד הַדָּבָר - (תהלים מב) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ, זֶה חֶסֶד כֹּהֵן גָּדוֹל, שֶׁמִּיכָאֵל הוּא כֹּהֵן הֶדְיוֹט לְגַבֵּי רִבּוֹנוֹ, וְעִם כָּל זֶה שֶׁהֶדְיוֹט הוּא אֵצֶל רִבּוֹנוֹ - הוּא מֶלֶךְ חַיּוֹת הַקֹּדֶשׁ. וּבִרְכַּת הֶדְיוֹט אַל תְּהִי קַלָּה בְּעֵינֶיךְ, וְזֶהוּ יוֹמָם יְצַוֶּה ה' חַסְדּוֹ."],[7,"","וּבַלַּיְלָה שִׁירֹה עִמִּי - זוֹ גְבוּרָה. שִׁירֹה - (דברים לג) בְּכוֹר שׁוֹרוֹ הָדָר לוֹ. (יחזקאל א) וּפְנֵי שׁוֹר מֵהַשְּׂמֹאל. וְגַבְרִיאֵל שְׁלוּחוֹ, וְצָרִיךְ לְשׁוֹרֵר וּלְנַגֵּן בְּחֶדְוָה בְּיֵין הַתּוֹרָה, (להתעסק לשלח קרבות לפני המלך בשמחה. ומי שאין לו רשות) לְהִתְעַסֵּק בַּתּוֹרָה, יְקַיֵּם (איכה ב) קוּמִי רֹנִּי בַלַּיְלָ לְרֹאשׁ אַשְׁמֻרוֹת."],[8,"","וְיֹאמַר בְּאַשְׁמוּרוֹת כַּמָּה סְלִיחוֹת וְתַחֲנוּנִים וּבַקָּשׁוֹת בְּכָל מִינֵי רִנָּה בִּגְרוֹנוֹ, שֶׁהוּא כִּנּוֹר לְהוֹצִיא בּוֹ קוֹל בְּשֵׁשׁ כַּנְפֵי רֵאָה עִם וְרָדִים בְּשֵׁשֶׁת צִנּוֹרוֹת הַקָּנֶה, וְזוֹ ו'. וְיוֹצִיאוֹ מֵהַלֵּב, שֶׁשָּׁם בִּינָה, כְּמוֹ שֶׁפֵּרְשׁוּהָ בַּעֲלֵי הַמִּשְׁנָה, הַלֵּב מֵבִין. יוֹצִיא בֵּן מִבִּינָה, מִבֶּן יָהּ, שֶׁהוּא ו', שֶׁהוּא אֶפְרוֹחַ בְּשֵׁשׁ כְּנָפַיִם, וְיַעֲלֶה בְּשֵׁשֶׁת צִנּוֹרוֹת הַקָּנֶה, שֶׁהֵם (מלכים אי) שֵׁשׁ מַעֲלוֹת לַכִּסֵּה."],[9,"","וּשְׁנֵי כִסְאוֹת הֵם, (ירמיה יז) כִּסֵּא כָבוֹד מָרוֹם מֵרִאשׁוֹן, וְהֵם הַלֵּב וְהַפֶּה. לֵ\"ב, (שמות יז) וַיּאמֶר כִּי יָד עַל כֵּס יָהּ מִלְחָמָה לַה' בַּעֲמָלֵק. כָּבֵד, סָמָאֵ\"ל, פֶּה הַכִּסֵּ\"ה, כֵּס ה', זֶהוּ שֶׁכָּתוּב (תהלים פא) תִּקְעוּ בַחֹדֶשׁ שׁוֹפָר וְגוֹ'."],[10,"","מַהוּ שׁוֹפָר? קָנֶה, ו', קוֹל שֶׁעוֹלֶה מִן הַקָּנֶה אֶל הַפֶּה, שֶׁשָּׁם ה', בַּחֲמִשָּׁה מִינֵי תִּקּוּנֵי דִבּוּר, שֶׁהֵם: הַשְּׂפָתַיִם וְשִׁנַּיִם וְחֵךְ. שְׂפָתַיִם שְׁנַיִם. שִׁנַּיִם וְטוֹחֲנוֹת שְׁנֵי מִינִים. וְחֵךְ - הֲרֵי חֲמִשָּׁה. שֶׁטּוֹחֲנִים כְּנָהָר, שֶׁהוּא קוֹל, כְּמוֹ שֶׁטּוֹחֲנִים הָרֵחַיִם. לְהוֹצִיא קוֹל וְדִבּוּר שֶׁיּוֹצֵא מֵהַבִּינָה שֶׁל הַלֵּב בְּמַחֲשָׁבָה."],[11,"","שֶׁהוּא שֵׁם מְפֹרָשׁ בַּעֲשָׂרָה מִינֵי תִלִּים. וּבְשׁוֹפָר, אֵין פּוֹחֲתִין מֵעֲשָׂרָה שׁוֹפָרוֹת. וְהַתּוֹרָה - הַקּוֹל שֶׁלָּהּ, הַדִּבּוּר שֶׁלָּהּ, הַבִּינָה שֶׁלָּהּ, שֶׁפֵּרְשׁוּהָ, אֵיזֶהוּ חָכָם? הַמֵּבִין דָּבָר מִתּוֹךְ דָּבָר. מַחֲשָׁבָה שֶׁלּוֹ חֲשׁוּבָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא מִכָּל קָרְבָּנוֹת וְעוֹלוֹת. זֶהוּ שֶׁכָּתוּב (ויקרא ז) זֹּאת הַתּוֹרָה לָעֹלָה (ו) לַמִּנְחָה."],[12,"","אִישׁ אוֹ אִשָּׁה כִּי יַעֲשׂוּ מִכָּל חַ את הָאָדָם וְגוֹ' (במדבר ה). בֹּא רְאֵה, כָּתוּב (שופטים ד) וְחֶבֶר הַקֵּינִי נִפְרָד מִקַּיִן מִבְּנֵי חֹבָב חֹתֵן מֹשֶׁה וְגוֹ'. וְחֶבֶר הַקֵּינִי מִבְּנֵי בָנָיו שֶׁל יִתְרוֹ הָיָה, כְּמוֹ שֶׁנֶּאֱמַר (שמואל א טו) וַיֹּאמֶר שָׁאוּל אֶל הַקֵּינִי וְגוֹ'. לָמָּה נִקְרָא קֵינִי? וַהֲרֵי פֵּרְשׁוּהָ. וְכָתוּב (בראשית טו) אֶת הַקֵּינִי וְאֶת הַקְּנִזִּי. וְנִתְבָּאֵר שֶׁעָשָׂה קֵן בַּמִּדְבָּר כְּעוֹף זֶה, כְּדֵי לַעֲסֹק בַּתּוֹרָה, וְנִפְרַד מִן הָעִיר. נִפְרָד מִקַּיִן, נִפְרָד מֵאוֹתוֹ עַם שֶׁהָיָה שָׁם קֹדֶם וְנִדְבָּק בַּקָּדוֹשׁ-בָּרוּךְ-הוּא, נִפְרָד מִקַּיִן."]]],[["זַכָּאָה בַּר נָשׁ דְּזָכֵי בְּאוֹרַיְיתָא, לְמֵיזָל לְאִתְדַּבְּקָא בְּאוֹרְחוֹי. דְּכַד בַּר נָשׁ אָזִיל בְּאוֹרְחוֹי דְּאוֹרַיְיתָא, מָשִׁיךְ עָלֵיהּ רוּחָא קַדִּישָׁא עִלָּאָה. כְּמָה דְאַתְּ אָמֵר, (ישעיהו ל״ב:ט״ו) עַד יֵעָרֶה עָלֵינוּ רוּחַ מִמָּרוֹם. וְכַד בַּר נָשׁ סָטֵי אוֹרְחוֹי, מָשִׁיךְ עָלֵיהּ רוּחָא אַחֲרָא מִסִּטְרָא אַחֲרָא, דְּהוּא סִטְרָא דְּמִסְאֲבָא. וְסִטְרָא דְּמִסְאֲבָא אִתְּעַר מִסִּטְרָא דְּנוּקְבָּא דִּתְהוֹמָא רַבָּא, דְּתַמָּן מָדוֹרִין דְּרוּחִין בִּישִׁין, דְּנַזְקֵי לִבְנֵי נָשָׁא, דְּאִקְרוּן נַזְקֵּי עָלְמָא. דְּהָא (קמ\"ג ע\"א ע\"ב) מִסִּטְרָא דְּקַיִן קַדְמָאָה אִשְׁתְּכָחוּ.","וְיִתְרוֹ בְּקַדְמִיתָא כּוּמָרָא לְעֲבוֹדָה זָרָה הֲוָה, וּלְהַהוּא סְטָר הֲוָה פָּלַח, וּמָשִׁךְ עָלֵיהּ רוּחָא מֵהַהוּא אֲתָר. וְעַל דָּא אִקְרֵי קֵּינִי לְבָתַר נִפְרָד מִקַּיִן (ודאי), וְאִתְדְּבַק (נ\"א ואתחבר) בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, (מאי משמע) דְּכָל מַאן דְּאִתְדַּבָּק בֵּיהּ בְּקוּדְשָׁא בְּרִיךְ הוּא, וְעָבִיד פִּקּוּדֵי אוֹרַיְיתָא, כִּבְיָכוֹל, הוּא קִיֵּים עָלְמִין, עָלְמָא דִּלְעֵילָּא וְעָלְמָא דִּלְתַּתָּא. וְהָא אוּקְמוּהָ, וַעֲשִׂיתֶם אוֹתָם כְּתִיב.","וְכָל מַאן דְּעָבַר עַל פִּקּוּדֵי אוֹרַיְיתָא, כִּבְיָכוֹל פָּגִים לְעֵילָּא, פָּגִים לְתַתָּא, פָּגִים לְגַרְמֵיהּ, פָּגִים לְכָל עָלְמִין. מְתַל לְאִינּוּן מַפְרֵישֵׁי יָמִין דְּשָׁאטֵי (ס\"א דטסרין) בְּאַרְבָּא, קָם חַד שַׁטְיָיא בֵּינַיְיהוּ, בָּעָא לְנַקְבָא וְכוּ'.","וְעַל דָּא אִישׁ אוֹ אִשָׁה כִּי יַעֲשׂוּ וְגוֹ', הָאָדָם וְגוֹ'. (תא חזי) (הושע ו׳:ז׳) וְהֵמָה כְּאָדָם עָבְרוּ בְרִית. אָדָם עָבַר עַל פִּקּוּדָא חַד דְּאוֹרַיְיתָא, גָּרִים לֵיהּ לְגַרְמֵיהּ מִיתָה, וְגָרַם לְכָל עָלְמָא, פָּגִים לְעֵילָּא, פָּגִים לְתַתָּא, וְהַהוּא חוֹבָא תַּלְיָיא, עַד דִּיקַיֵּים קוּדְשָׁא בְּרִיךְ הוּא עָלְמָא כְּמִלְּקַדְּמִין, וְיִתְעֲבָר הַהוּא פְּגִימוּ מֵעָלְמָא, הֲדָא הוּא דִכְתִיב, (ישעיהו כ״ה:ח׳) בִּלַּע הַמָּוְת לָנֶצַח וּמָחָה יְיָ אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים וְגוֹ'. וּבְגִין כָּךְ כִּי יַעֲשׂוּ מִכָּל חַטֹּאת הָאָדָם. (כתיב) הָאָדָם, אָדָם קַדְמָאָה.","לִמְעוֹל מַעַל בַּיְיָ, דְּמַאן דְּיִפּוּק מֵרַחֲמֵי, וְיַנְקָא מִן דִּינָא, הוּא גָּרִים פְּגִימוּ וְכוּ', וְעַל דָּא, רַחֲמָנָא לִישֵׁזְבָן מֵחַיָיבֵי דְּהַאי עָלְמָא, וּמִן פְּגִימוּ דִּלְהוֹן, כַּמָה זַכָּאִין מִסְתַּלְּקֵי בְּגִינַיְיהוּ, בַּר כָּל מַה דְּגַרְמֵי לְעֵילָּא וְתַתָּא.","רִבִּי יִצְחָק וְרִבִּי יְהוּדָה הֲווֹ אָזְלֵי מֵאוּשָׁא לְלוּד, אָמַר רִבִּי יְהוּדָה (יצחק) נֵימָא מִילִּין דְּאוֹרַיְיתָא וְנֵזִיל. פָּתַח רִבִּי יְהוּדָה (ס\"א יצחק) וְאָמַר, (שמות כ״א:ל״ג) כִּי יִפְתַּח אִישׁ בּוֹר אוֹ כִּי יִכְרֶה אִישׁ בּוֹר וְגוֹ'. מַה כְּתִיב בַּתְרֵיהּ, בַּעַל הַבּוֹר יְשַׁלֵּם וְגוֹ'. וּמַה עַל דָּא כַּךְ, מַאן דְּגָרִים לְאַבְאָשָׁא עָלְמָא בְּחוֹבוֹי עַל אַחַת כַּמָּה וְכַמָּה. אֶלָּא תַּוַּוהְנָא דְּאַף עַל גַּב דְּאַבְאִישׁ עָלְמָא, אֲמַאי אִית לֵיהּ תְּשׁוּבָה, כְּמָה דִּכְתִּיב אִישׁ אוֹ אִשָׁה כִּי יַעֲשׂוּ וְגוֹ' וְהִתְוַדּוּ אֶת חַטָּאתָם וְהֵשִׁיב.","אֶלָּא וַדַּאי דָּא מְהַנְיָא לְהוּ, בְּגִין דְּעָבִיד תְּשׁוּבָה, כִּבְיָכוֹל הוּא עָבִיד לֵיהּ מַמָּשׁ. דְּהָא מַה דְּפָגִים לְעֵילָּא, אַתְקִין לֵיהּ, וּבְמָה בִּתְשׁוּבָה. דִּכְתִּיב אִישׁ אוֹ אִשָּׁה כִּי יַעֲשׂוּ וְגוֹ', וְהִתְוַדּוּ אֶת חַטָּאתָם וְהֵשִׁיב, וּתְשׁוּבָה אַתְקִין כֹּלָּא, אַתְקִין לְעֵילָּא, אַתְקִין לְתַתָּא, אַתְקִין לְגַרְמֵיהּ, אַתְקִין לְכָל עָלְמָא.","פָּתַח רִבִּי יִצְחָק (ס\"א יהודה) אֲבַּתְרֵיהּ וְאָמַר, (דברים ד׳:ל׳) בַּצַּר לְךָ וּמְצָאוּךָ כָּל הַדְּבָרִים הָאֵלֶּה וְגוֹ'. בַּצַּר לְךָ, מִכָּאן דִּתְשׁוּבָה מֵעַלְּיָא מִכֹּלָּא, עַד לָא יִשְׁרֵי דִּינָא בְּעָלְמָא. דְּבָתַר דִּשְׁרֵי דִּינָא תַּקִּיף חֵילֵיהּ מַאן יַעְבַּר לֵיהּ מֵעָלְמָא וִיסַלֵּק לֵיהּ. דְּהָא כֵּיוָן דְּשָׁארִי דִּינָא, לָא אִסְתְּלִיק עַד דְּיִשְׁתְּלִים. בָּתַר דְּאִשְׁתְּלִים, וְעֲבַד תְּשׁוּבָה, אַתְקִין עָלְמִין כֻּלְּהוּ. מַשְׁמַע, דִּכְתִּיב וּמְצָאוּךָ כָּל הַדְּבָרִים הָאֵלֶּה בְּאַחֲרִית הַיָּמִים, וּכְתִיב וְשַׁבְתָּ עַד יְיָ אֱלֹהֶיךָ וְגוֹ'. כִּי אֵל רַחוּם יְיָ אֱלֹהֶיךָ וְגוֹ'."],[[0,"זכאה בר נש","וכו׳: אשרי האדם שזכה בתורה, ללכת ולהתדבק בדרכיו. כי כשהאדם הולך בדרכי התורה, מושך עליו רוח קדוש עליון, כש״א עד יערה עלינו רוח ממרום. וכשהאדם מטה דרכיו מן התורה, מושך עליו רוח אחר מצד האחר, שהוא צד הטומאה, וצד הטומאה מתעורר מצד הנקב של תהום הגדול ששם משכנות הרוחות הרעים המזיקים לבני האדם והנקראים מזיקי העולם. שהם נמצאים מצד קין הראשון."],[1,"ויתרו בקדמיתא כומרא","וכו׳: ויתרו היה מתחילה כומר לעבודה זרה, ולצד ההוא היה עובד, ומשך עליו רוח מאותו הצד, וע״כ נקרא אח״כ קיני, כי נפרד מקין ונתדבק בהקב״ה, שכל מי שמתדבק בהקב״ה ועושה מצות התורה, כביכול הוא מקיים העולמות, עולם שלמעלה ועולם שלמטה. וכבר העמידוהו, ועשיתם אותם, כתוב (כנ״ל בחוקותי אות י״ח)."],[2,"וכל מאן דעבר","וכו׳: וכל מי שעבר על מצות התורה, כביכול, פוגם למעלה, פוגם למטה, פוגם את עצמו, פוגם לכל העולמות. משל לאלו יורדי הים השטים באניה, קם שוטה אחד ביניהם ורצה לנקוב את הספינה, אמר לו חבירו למה אתה קודח. אמר לו מה איכפת לך, הלא תחתי אני קודח. אמר לו, הרי שנינו נטבעים בספינה ביחד. (ויק״ר פ״ד ו׳)"],[3,"וע״ד איש או","וכו׳: וע״כ איש או אשה כי יעשו וגו׳ \u0003האדם\u0004 וגו׳, שרומז על אדם הראשון, שכתוב, והמה כאדם עברו ברית. אדם עבר על מצוה אחת שבתורה, גרם לעצמו מיתה וגרם לכל העולם פגם למעלה ופגם למטה, ואותו עון תלוי, עד שיקיים הקב״ה העולם כבתחילה, ויהיה נעבר הפגם ההוא מן העולם. ז״ש בלע המות לנצח ומחה ה׳ אלקים דמעה מעל כל פנים וגו׳. ומשום זה כתוב כאן כי יעשו מכל חטאת האדם. \u0003האדם,\u0004 שרומז על אדם הראשון."],[4,"למעול מעל בה׳:","כי מי שיוצא מרחמים ויונק מן הדין הוא גורם פגם וכו׳ וע״כ הרחמן יצילנו מרשעי העולם הזה ומן הפגם שלהם. כי כמה צדיקים מסתלקים בשבילם, חוץ מכל מה שגורמים למעלה ולמטה."],[5,"ר׳ יצחק ור׳ יהודה","וכו׳: ר״י ור״י היו הולכים מאושא ללוד. אר״י, נאמר דברי תורה ונלך. פתח ר׳ יהודה ואמר, כי יפתח איש בור או כי יכרה איש בור וגו׳, מה כתוב אחריו בעל הבור ישלם וגו׳, ומה על זה כך, מי שגרם להרע לעולם בחטאיו על אחת כמה וכמה. אלא תמה אני, כיון שהרע לעולם, למה מועיל לו התשובה כמו שכתוב, איש או אשה וגו׳ והתודו על חטאתם והשיב."],[6,"אלא ודאי דא","וכו׳: ומשיב, אלא ודאי זה מועיל להם משום כיון שעושה תשובה כביכול הוא עושה אותו ממש. כי תשובה משיבה \u0003ה׳\u0004 אל ה \u0003ו׳,\u0004 כי מה שפגם למעלה תקן אותו, ובמה בתשובה. שכתוב, איש או אשה כי יעשו וגו׳ והתודו את חטאתם והשיב וגו׳. ותשובה מתקנת הכל, מתקנת למעלה ומתקנת למטה מתקנת את עצמו, ומתקנת לכל העולם."],[7,"פתח ר' יצחק וכו'",": פר\"י אחריו, ואמר, \u0003בצר לך\u0004 ומצאוך כל הדברים האלה וגו', בצר לך מכאן שתשובה טובה מכל, בטרם שישרה הדין בעולם. כי אחר שכבר שרה הדין, נתחזק כחו, מי יעבירו מן העולם ויסלקו. כי כיון שכבר שרה הדין אינו מסתלק עד שיושלם. אחר שנשלם הדין, ועשה תשובה, מתקן כל העולמות. זה משמע, משכתוב, ומצאוך כל הדברים האלה באחרית הימים, וכתוב, ושבת עד ה' אלקיך וגו', כי אל רחום ה' אלקיך."]],[[0,"","אַשְׁרֵי הָאִישׁ שֶׁזּוֹכֶה בַּתּוֹרָה לָלֶכֶת וּלְהִתְדַּבֵּק בִּדְרָכָיו. שֶׁכְּשֶׁאָדָם הוֹלֵךְ בְּדַרְכֵי הַתּוֹרָה, מוֹשֵׁךְ עָלָיו רוּחַ קְדוֹשָׁה עֶלְיוֹנָה, כְּמוֹ שֶׁנֶּאֱמַר (ישעיה לב) עַד יֵעָרֶה עָלֵינוּ רוּחַ מִמָּרוֹם. וּכְשֶׁאָדָם סוֹטֶה בִּדְרָכָיו, מוֹשֵׁךְ עָלָיו רוּחַ אַחֶרֶת מִצַּד אַחֵר, שֶׁהוּא צַד טֻמְאָה, וְצַד הַטֻּמְאָה מִתְעוֹרֵר מִצַּד נֶקֶב תְּהוֹם רַבָּה, שֶׁשָּׁם מְדוֹרֵי רוּחוֹת רָעוֹת שֶׁמַּזִּיקִים לָאֲנָשִׁים שֶׁנִּקְרָאִים מַזִּיקֵי הָעוֹלָם, שֶׁהֲרֵי מִצַּד קַיִן הָרִאשׁוֹן נִמְצְאוּ."],[1,"","וְיִתְרוֹ בַּהַתְחָלָה הָיָה כֹּמֶר לַעֲבוֹדָה זָרָה, וּלְאוֹתוֹ צַד עָבַד, וּמָשַׁךְ עָלָיו רוּחַ מֵאוֹתוֹ מָקוֹם, וְלָכֵן נִקְרָא קֵינִי, אַחַר שֶׁנִּפְרַד מִקַּיִן (ודאי) וְנִדְבַּק (נ\"א והתחבר) בַּקָּדוֹשׁ-בָּרוּךְ-הוּא. (מה משמיענו, ') שֶׁכָּל מִי שֶׁנִּדְבָּק בַּקָּדוֹשׁ-בָּרוּךְ-הוּא וְעוֹשֶׂה מִצְווֹת הַתּוֹרָה, כִּבְיָכוֹל הוּא מַעֲמִיד עוֹלָמוֹת, עוֹלָם הָעֶלְיוֹן וְעוֹלָם הַתַּחְתּוֹן. וַהֲרֵי פֵּרְשׁוּהָ, שֶׁכָּתוּב וַעֲשִׂיתֶם אֹתָם."],[2,"","וְכָל מִי שֶׁעוֹבֵר עַל מִצְווֹת הַתּוֹרָה, כִּבְיָכוֹל פּוֹגֵם לְמַעְלָה, פּוֹגֵם לְמַטָּה, פּוֹגֵם אֶת עַצְמוֹ, פּוֹגֵם בְּכָל הָעוֹלָמוֹת. מָשָׁל לְאוֹתָם סַפָּנִים שֶׁבַּיָּם שֶׁשָּׁטִים בָּאֳנִיָּה, קָם שׁוֹטֶה אֶחָד בֵּינֵיהֶם וְרָצָה לַעֲשׂוֹת חוֹר בַּסְּפִינָה וכו'."],[3,"","וְלָכֵן, אִישׁ אוֹ אִשָּׁה כִּי יַעֲשׂוּ וְגוֹ', הָאָדָם וְגוֹ'. (בא ראה) (הושע ו) וְהֵמָּה כְּאָדָם עָבְרוּ בְרִית. אָדָם עָבַר מִצְוָה אַחַת שֶׁל הַתּוֹרָה - גָּרַם לְעַצְמוֹ מִיתָה, וְגָרַם לְכָל הָעוֹלָם, פָּגַם לְמַעְלָה, פָּגַם לְמַטָּה. וְאוֹתוֹ חֵטְא תָלוּי עַד שֶׁיַּעֲמִיד הַקָּדוֹשׁ בָּרוּךְ הוּא הָעוֹלָם כְּמִקֹּדֶם וְיַעֲבֹר אוֹתוֹ פְּגָם מֵהָעוֹלָם. זֶהוּ שֶׁכָּתוּב (ישעיה כה) בִּלַּע הַמָּוֶת לָנֶצַח וּמָחָה ה' אֱלֹהִים דִּמְעָה מֵעַל כָּל פָּנִים וְגוֹ'. וְלָכֵן כִּי יַעֲשׂוּ מִכָּל חַטֹּאת הָאָדָם. (כתוב) הָאָדָם - אָדָם הָרִאשׁוֹן."],[4,"","לִמְעֹל מַעַל בַּה', שֶׁמִּי שֶׁיּוֹצֵא מֵרַחֲמִים וְיוֹנֵק מִדִּין, גּוֹרֵם פְּגָם. וְלָכֵן הָרַחֲמָן יַצִּילֵנוּ מֵרִשְׁעֵי הָעוֹלָם הַזֶּה וּמִפְּגָמֵיהֶם. כַּמָּה צַדִּיקִים מִסְתַּלְּקִים בִּגְלָלָם, מִלְּבַד לְכָל מַה שֶּׁגּוֹרְמִים לְמַעְלָה וּלְמַטָּה."],[5,"","רַבִּי יִצְחָק וְרַבִּי יְהוּדָה הָיוּ הוֹלְכִים מֵאוּשָׁא לְלוֹד. אָמַר רַבִּי יְהוּדָה (יצחק), נֹאמַר דִּבְרֵי תוֹרָה וְנֵלֵךְ. פָּתַח רַבִּי יְהוּדָה (יצחק) וְאָמַר, (שמות כא) כִּי יִפְתַּח אִישׁ בּוֹר אוֹ כִּי יִכְרֶה אִישׁ בֹּר וְגוֹ'. מַה כָּתוּב אַחֲרָיו? בַּעַל הַבּוֹר יְשַׁלֵּם וְגוֹ'. וּמָה עַל זֶה כָּךְ - מִי שֶׁגּוֹרֵם לְהַסְרִיחַ הָעוֹלָם בַּחֲטָאָיו עַל אַחַת כַּמָּה וְכַמָּה. אֶלָּא תָּמַהְנוּ, שֶׁאַף עַל גַּב שֶׁמַּסְרִיחַ הָעוֹלָם, לָמָּה יֵשׁ לוֹ תְּשׁוּבָה, כְּמוֹ שֶׁכָּתוּב אִישׁ אוֹ אִשָּׁה כִּי יַעֲשׂוּ וְגוֹ' וְהִתְוַדּוּ אֶת חַטָּאתָם וְהֵשִׁיב?"],[6,"","אֶלָּא וַדַּאי זֶה מוֹעִיל לָהֶם מִשּׁוּם שֶׁעָשָׂה תְשׁוּבָה, כִּבְיָכוֹל הוּא עוֹשֶׂה אוֹתוֹ מַמָּשׁ. שֶׁהֲרֵי מַה שֶּׁפָּגַם לְמַעְלָה - תִּקֵּן, וּבַמֶּה? בִּתְשׁוּבָה, שֶׁכָּתוּב אִישׁ אוֹ אִשָּׁה כִּי יַעֲשׂוּ וְגוֹ', וְהִתְוַדּוּ אֶת חַטָּאתָם וְהֵשִׁיב, וּתְשׁוּבָה מְתַקֶּנֶת הַכֹּל, מְתַקֶּנֶת לְמַעְלָה - מְתַקֶּנֶת לְמַטָּה, מְתַקֶּנֶת עַצְמוֹ - מְתַקֶּנֶת לְכָל הָעוֹלָם."],[7,"","פָּתַח רַבִּי יִצְחָק (יהודה) אַחֲרָיו וְאָמַר, (דברים ד) בַּצַּר לְךְ וּמְצָאוּךְ כֹּל הַדְּבָרִים הָאֵלֶּה וְגוֹ'. בַּצַּר לְךְ - מִכָּאן שֶׁתְּשׁוּבָה מְעֻלָּה מֵהַכֹּל עַד שֶׁלֹּא יִשְׁרֶה הַדִּין בָּעוֹלָם. שֶׁאַחַר שֶׁשּׁוֹרֶה הַדִּין מִתְחַזֵּק כֹּחוֹ, מִי יַעֲבִירוֹ מֵהָעוֹלָם וִיסַלְּקוֹ? שֶׁהֲרֵי כֵּיוָן שֶׁשּׁוֹרֶה הַדִּין, לֹא מִסְתַּלֵּק עַד שֶׁנִּשְׁלָם. אַחַר שֶׁנִּשְׁלַם וְעָשָׂה תְשׁוּבָה, מְתַקֵּן כָּל הָעוֹלָמוֹת. מַשְׁמָע שֶׁכָּתוּב וּמְצָאוּךְ כֹּל הַדְּבָרִים הָאֵלֶּה בְּאַחֲרִית הַיָּמִים, וְכָתוּב וְשַׁבְתָּ עַד ה' אֱלֹהֶיךְ וְגוֹ'. כִּי אֵל רַחוּם ה' אֱלֹהֶיךְ וְגוֹ'."]]],[["בְּאַחֲרִית הַיָּמִים, מַאי אִיכָּא הָכָא. אֶלָּא לְאַכְלְלָא כְּנֶסֶת יִשְׂרָאֵל, דְּאִיהִי בְּגָלוּתָא, וְאִשְׁתְּכָחַת בְּעָאקוּ דִּלְהוֹן, וְלָא שַׁבְקָת לוֹן לְעָלְמִין. וּבְגִין כַּךְ קוּדְשָׁא בְּרִיךְ הוּא אַף עַל גַּב דְּאַשְׁרֵי דִּינָא בְּעָלְמָא, בָּעֵי דְּיָהַדְרוּן יִשְׂרָאֵל בִּתְשׁוּבָה, לְאוֹטָבָא לְהוּ בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי, וְלֵית לָךָ מַאן דְּקָאִים קַמֵּי תְּשׁוּבָה.","תָּא חֲזֵי, אֲפִילּוּ כְּנֶסֶת יִשְׂרָאֵל, תְּשׁוּבָה אִקְרֵי. וְאִי תֵּימָא (תשובה) עִלָּאָה (ס\"א מעליא) (נ\"א ואת עלאה) מִכָּל אֲתָר לָא שְׁכִיחַ, אֶלָּא דָּא אִקְרֵי תְּשׁוּבָה, כַּד אַהְדָּר רַחֲמֵי לְקָבְלָהָא, וְהִיא תָּבַת עַל כָּל אִינּוּן אוֹכְלֹסִין וְיַנְקָא לוֹן. וּתְשׁוּבָה מֵעַלְיָא, כַּד אִתְמְסַר נַפְשָׁא לְגַבָּהּ, וְנָטִיל לָהּ בְּזִמְנָא דְּאִיהִי בִּתְשׁוּבָה, כְּדֵין כֹּלָּא אִתְתָּקַּן לְעֵילָּא וְתַתָּא, וְאִתְתָּקַּן הוּא, וְכָל עָלְמָא.","חַיָּיבָא חַד בְּעָלְמָא, קִלְקוּלָא דְּכַמָּה אַחֲרָנִין בְּגִינֵיהּ. וַוי לַחַיָּיבָא, וַוי לִשְׁבִיבֵיהּ. תָּא חֲזֵי, יוֹנָה, בְּגִין דְּלָא בָּעָא לְמֵהַךְ בִּשְׁלִיחוּתָא דְּמָארֵיהּ, כַּמָה בְּנֵי נָשָׁא הֲווֹ אִתְאֲבִידוּ בְּגִינֵיהּ בְּיַמָּא, עַד דְּכֻלְּהוּ אָהַדְרוּ עֲלוֹי, וְדָאִינוּ לֵיהּ בְּדִינָא בְּיַמָּא, וּכְדֵין אִשְׁתֵּזִיבוּ כֻּלְּהוּ, וְקוּדְשָׁא בְּרִיךְ הוּא חָס עָלֵיהּ לְבָתַר, וְשֵׁזִיב כַּמָה אוֹכְלֹסִין בְּעָלְמָא. אֵימָתַי. כַּד אַהְדָּר לְמָארֵיהּ מִגּוֹ עַקְתֵּיהּ. הֲדָא הוּא דִּכְתִּיב, (יונה ב׳:ג׳) קָרָאתִי מִצָּרָה לִי אֶל יְיָ וַיַּעֲנֵנִי. וּכְתִיב, (תהילים קי״ח:ה׳) מִן הַמֵּצַר קָרָאתִי יָהּ עָנָנִי בַמֶרְחָב יָהּ וְגוֹ'.","\u0003רעיא מהימנא\u0004 פִּקּוּדָא דָּא, הִיא מִצְּוַת תְּשׁוּבָה. וְדָא אִיהִי בִּינָה. וּבַעֲווֹנוֹתֵינוּ מִדְּחָרַב בֵּי מַקְדְּשָׁא, לָא אִשְׁתְּאַר לָנוּ אֶלָּא ודּוּי דְּבָרִים לְבַד, וְדָא מַלְכוּת. וּמַאי בִּינָה. בֶּן יָ\"הּ. וְהַאי בֶּן, ו' אִיהוּ וַדַּאי. וְכָל מַאן דְּחָזַר בְּתִיּוּבְתָּא, כְּאִלּוּ חָזַר אָת ה' לְאָת ו', דְּאִיהוּ בֶּן יָ\"הּ, וְאִשְׁתְּלִים בֵּיהּ יְדוָֹ\"ד. וְדָא אִיהוּ תְּשׁוּבָה, תָּשׁוּב ה' וַדַּאי לְגַבֵּי ו'.","דְּאָת ה' וַדַּאי אִיהוּ וִדּוּי דְּבָרִים, וְרָזָא דְּמִלָּה, (הושע י״ד:ג׳) קְחוּ עִמָּכֶם דְּבָרִים וְשׁוּבוּ אֶל יְיָ אִמְרוּ אֵלָיו וְגוֹ' וּנְשַׁלְּמָה פָּרִים שְׂפָתֵינוּ. דְּוַדַּאי כַּד בַּר נָשׁ אִיהוּ חוֹטֶא, גָּרִים לְאִתְרַחֲקָא ה' מֵאָת ו'. דְּאִסְתְּלַּק בֶּן יָ\"הּ, דָּא יה\"ו, מֵאָת ה'. וּבְגִין דָּא אִתְחָרַב בֵּי מַקְדְּשָׁא, וְאִתְרַחֲקוּ יִשְׂרָאֵל מִתַּמָּן, וְאִתְגְּלוּ בֵּינֵי עֲמַמְיָא. וּבְגִין דָּא, כָּל מַאן דְּעָבִיד תְּשׁוּבָה, גָּרִים לְאַחְזְרָא ה' לְאָת ו', וּפוּרְקָנָא בְּדָא תַּלְיָיא. וּבְגִין דָּא הַכֹּל תָּלוּי בִּתְשׁוּבָה. דְּכַךְ אָמְרוּ קַדְמָאֵי, כָּל הַקִּצִּים כָּלוּ, וְאֵין הַדָּבָר תָּלוּי אֶלָּא בִּתְשׁוּבָה, דְּאִיהוּ שְׁלִימוּ דִּשְׁמֵיהּ.","וְעַל דָּא (יחזקאל כ׳:י״ד) וָאֶעֱשֶׂה לְמַעַן שְׁמִי. וְעוֹד (ישעיהו מ״ח:י״א) לְמַעֲנִי לְמַעֲנִי אֶעֱשֶׂה. וְאִם לָאו חַזְרִין, אֲנָא אַעֲמִיד לוֹן מַלְכָּא, שֶׁקָשִׁין גְּזִרוֹתָיו מִשֶּׁל פַּרְעֹה, וְיַחְזְרוּן עַל כָּרְחַיְּיהוּ. הֲדָא הוּא דִכְתִיב וְשַׁבְתָּ עַד יְיָ אֱלֹהֶיךָ, עַד יְדוָֹ\"ד וַדַּאי.","וּתְשׁוּבָה דָּא אִתְקְרִיאַת חַיִּים, (משלי ד׳:כ״ג) כִּי מִמֶּנּוּ תּוֹצְּאוֹת חַיִּים, דְּאִינּוּן נִשְׁמָתִין דְּיִשְׂרָאֵל. וְאִיהוּ הֶבֶל דְּנָפַק וְעָאל בְּפוּמָא דְּבַּר נָשׁ, בְּלֹא עָמָל וּבְלֹא יְגִיעָה. ה' דִּבְּהִבָּרְאָם. וְעָלָהּ אִתְּמַר, (דברים ח׳:ג׳) כִּי עַל כָּל מוֹצָּא פִּי יְיָ יִחְיֶה הָאָדָם. וְהִיא עַל רֵישֵׁיהּ דְּבַּר נָשׁ. עָלָה אִתְּמַר, (במדבר י״ב:ח׳) וּתְמוּנַת יְיָ יַבִּיט. (תהילים ל״ט:ז׳) אַךְ בְּצֶּלֶם יִתְהַלֶּךְ אִישׁ.","וּבְגִין דְּאִיהִי עַל רֵישֵׁיהּ דְּבַּר נָשׁ, אָסִיר לֵיהּ לְבַּר נָשׁ לְמֵיזַל ד' אַמּוֹת בְּגִלוּי דְּרֵישָׁא, דְּאִם הִיא אִסְתָּלָקַת מֵעַל רֵישֵׁיהּ דְּבַּר נָשׁ, מִיַּד אִסְתְּלָקוּ חַיִּים מִנֵּיהּ.","וְאִי תֵּימָא דְּכַךְ שַׁרְיָא עַל אוּמִין דְּעָלְמָא, אַף עַל גַּב דְּלָא אִתְבְּרֵי בְּהוֹן שְׁמַיָא וְאַרְעָא וְכָל תּוֹלָדִין דִּבְהוֹן. לָא שַׁרְיָא וַדַּאי, דְּמֹשֶׁה בָּעָא מִּקוּדְשָׁא בְּרִיךְ הוּא, דְּלָא תִּשְׁרֵי שְׁכִינָה עַל אוּמִין דְּעָלְמָא, וְיָהִיב לֵיהּ. הָבְלָא דְּקַיְּימָא עַל אוּמִין דְּעָלְמָא מֵאָן נָפְקָא. אוֹ עַל חַיָּיבַיָּא דְּאִינּוּן עֵרֶב רַב מְעוּרָבִין עִם יִשְׂרָאֵל. אֶלָּא וַדַּאי לֵית כָּל אַפַּיָיא שָׁוִין, אֲפִילּוּ יִשְׂרָאֵל לָאו אִינּוּן שַׁוְיָן, כָּל שֶׁכֵּן אַחֲרָנִין.","אֶלָּא וַדַּאי עַל הַאי דִּיּוּקְנָא דְּאָת ה' אוּקְמוּהָ, מַתָּנָה טוֹבָה יִשׁ לִי בְּבֵית גְּנָזַי וְשַׁבָּת שְׁמָהּ. וְכַד הַאי שַׁרְיָא עַל יִשְׂרָאֵל, לֵית לוֹן יְגִיעָה וְלָא שִׁעְבּוּד. וּבָה נֶפֶשׁ עֲמֵלָה וִיגֵיעָה (שמות ל״א:י״ז) שָׁבַת וַיִּנָּפַשׁ.","דְּנֶפֶשׁ אַחֲרָא אִית עַל רֵישֵׁיהּ דְּבַּר נָשׁ, דְּאִתְקְרִיאַת עֶבֶד. וְאִיהוּ דִּיּוּקְנָא עַל בַּר נָשׁ. וְאִיהִי עֶבֶד דְּמַלְכָּא, דִּמְנַעְנְעָא כָּל אֵבָרִין דְּבַּר נָשׁ, לְמֵיזָל בְּאָרְחִין טָבִין, וּלְקַיְּימָא בְּהוֹן רמ\"ח פִּקוּדִין, לְשַׁרְיָא עָלַיְיהוּ ה' דִּבְּהִבָּרְאָם, דְּכַךְ סָלִיק הִבָּרְאָם לְרמ\"ח.","וּדְיוּקְנָא אַחֲרָא עַל רֵישֵׁיהּ, דְּאִתְקְרִיאַת יִרְאָה, וְדָא י'. וְעָלַיְיהוּ אִתְּמַר, (בראשית א׳:כ״ז) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַּלְמוֹ בְּצֶּלֶם אֱלֹהִים. תְּרֵין דִּיוּקְנִין טָבִין, דְּאִינּוּן דְּכַר וְנוּקְבָּא. דְּכַר מִסִּטְרָא דְּאָת י'. נוּקְבָּא מִסִּטְרָא דְּאָת ה'.","וּתְרֵין אַתְוָון אַתְּעֲרִין לֵיהּ לְבַּר נָשׁ לַתּוֹרָה וְלַמִּצְּוָה. י' יִרְאָה, וְדָא אִיהִי עַל רֵישֵׁיהּ דְּבַּר נָשׁ, וּמִנָהּ יֵיעוּל דְּחִילוּ לְלִבָּא דְּבַּר נָשׁ, לְמִדְחַל מְקוּדְשָׁא בְּרִיךְ הוּא, וּלְנַטְרָא גַּרְמֵיהּ דְּלָא יֶעְבַר עַל פִּקוּדִין דְּלָא תַּעֲשֶׂה. ה' אַהֲבָה עַל רֵישֵׁיהּ דְּבַּר נָשׁ, וּמִנֵּיהּ עָאל רְחִימוּ דְקוּדְשָׁא בְּרִיךְ הוּא, עַל רמ\"ח אֵבָרִין דִּילֵיהּ, לְקַיְּימָא בְּהוֹן פִּקוּדִין דַּעֲשֵׂה. ו' אִיהִי עַל רֵישֵׁיהּ דְּבַּר נָשׁ, וּמִנֵּיהּ יִיעוּל עַל פּוּמָא דְּבַּר נָשׁ מִלוּלִין לְאוֹלְפָא בְּאוֹרַיְיתָא.","וּבְהַאי קְחוּ עִמָּכֶם דְּבָרִים וְשׁוּבוּ אֶל יְיָ. וּבְהַאי דִּיְהֵא בְּכוֹן הַיִּרְאָה וְהָאַהֲבָה וְהַתּוֹרָה יִתְחַזִר יְדוָֹ\"ד דְּאִיהוּ בִּינָה תְּשׁוּבָה, ו' תָּשׁוּב לְגַבֵּי ה', דְּאִיהוּ עוֹבָדָא דִּבְרֵאשִׁית. וְאִיהִי ל\"ב אֱלֹהִים. וְיִשְׁתְּלִים יְדוָֹד וּבָה יְהֵא לְכוֹן נַיְיחָא מִכֹּלָּא, וּבָהּ שָׁבַת וַיִּנָּפַשׁ."],[[0,"באחרית הימים מה","וכו׳: שואל, באחרית הימים, מה ענין לכאן. ומשיב, שהוא לכלול כנסת ישראל הנקראת אחרית הימים, שהיא בגלות, ונמצאת עמהם בצרה, ואינה עוזבתם לעולם. ומשום זה הקב״ה אע״פ שהשרה דין בעולם, רוצה שישראל יחזרו בתשובה להטיב להם בעולם הזה ובעולם הבא. ואין לך דבר העומד בפני תשובה."],[1,"ת״ח אפילו כנסת ישראל","וכו׳: בוא וראה, אפילו כנסת ישראל שהוא מלכות, נקראת תשובה. ואם תאמר, תשובה עליונה, שהיא בינה. היא אינה מצויה בכל מקום. אלא זו, המלכות, נקראת תשובה, כשחזרו הרחמים, שהוא ז״א, כנגדה, והיא שבה להניק כל אלו ההמונים שלה. ותשובה הכי טובה היא, כשהחוטא מוסר נפשו אליה, והיא לוקחת אותה בזמן שהוא בתשובה, אז מתתקן הכל למעלה ולמטה, והוא נתתקן וכל העולם."],[2,"חייבא חד בעלמא","וכו׳: רשע אחד בעולם, כמה אחרים נזוקים בשבילו. אוי לרשע אוי לשכנו. בוא וראה, יונה, משום שלא רצה ללכת בשליחות אדונו, כמה בני אדם היו נאבדים בשבילו בים עד שכולם חזרו עליו ודנו אותו בדין להשליכו לים. ואז ניצולו כולם, והקב״ה חס עליו אח״כ, והציל כמה המונים בעולם, דהיינו אנשי נינוה, מתי היה זה. הוא כשחזר בתשובה לאדונו מתוך צרתו. זה שכתוב, קראתי מצרה לי אל ה׳ ויענני. וכתוב, מן המצר קראתי יה ענני במרחב יה, וגו׳."],[3,"פקודא דא היא","וכו׳: מצוה זו היא מצות תשובה. וזה הוא בינה. ובעונותינו כשחרב בית המקדש לא נשאר לנו אלא ודוי דברים בלבד, שזה הוא מלכות, שנקראת ודוי דברים. ומה היא בינה. היא אותיות בן י״ה, ובן הזה הוא \u0003ו׳\u0004 ודאי, שרומז, על ז״א הנקרא בן, הדבוק בה, ומקבל ממנה מוחין די״ה, וכל מי שחוזר בתשובה הוא כאלו השיב אות ה׳ שהיא המלכות, אל אות \u0003ו׳\u0004 שהוא ז״א, שהוא בן י״ה, ונשלם בו הויה, כי בן ה״ס \u0003ו׳\u0004 ועם י״ה הוא יה״ו, ועם המלכות, שהוא ה׳ שחזרה אליו נשלם כל השם. וזו היא \u0003תשובה,\u0004 ודאי, שהיא אותיות, \u0003תשוב ה׳\u0004 אל ה \u0003ו׳.\u0004"],[4,"דאת ה׳ ודאי","וכו׳: כי אות \u0003ה׳\u0004 ודאי היא, ודוי דברים, וסוד הדבר, קחו עמכם \u0003דברים\u0004 ושובו אל ה׳ אמרו אליו וגו׳ ונשלמה פרים שפתינו. כי ודאי כשאדם חוטא, גורם שתתרחק ה \u0003ה׳\u0004 מאת ה \u0003ו׳,\u0004 כי בן י״ה, שהוא \u0003ו׳\u0004 שזה כולל \u0003יה״ו\u0004 נסתלק מן אות \u0003ה׳.\u0004 ומשום זה נחרב בית המקדש ונתרחקו ישראל משם, וגלו בין העמים. ומשום זה, כל מי שעושה תשובה, גורם להשיב את ה \u0003ה׳\u0004 לאות ה \u0003ו׳.\u0004 והגאולה תלויה בזה. ומשום זה הכל תלוי בתשובה. שכך אמרו הראשונים, כל הקצים כלו ואין הדבר תלוי אלא בתשובה, שהיא שלמות שמו. כי ה״ס \u0003ה׳\u0004 המשלמת ליה״ו, כנ״ל בדבור הסמוך."],[5,"וע״ד ואעשה למען","וגו׳: וע״כ, ואעשה למען שמי, דהיינו להשלים שם הוי״ה כנ״ל. ועוד, למעני למעני אעשה. ואם אינם חוזרים בתשובה, אני אעמיד להם מלך שקשים גזרותיו יותר משל פרעה, ויחזרו בתשובה בעל כרחם. ז״ש ושבת עד הויה אלקיך, עד \u0003הויה\u0004 ודאי, דהיינו להשלים שם הויה כנ״ל."],[6,"ותשובה דא אתקריאת","וכו׳: ותשובה זו, שהיא מלכות וה׳ דהויה, נקראת חיים, שכתוב, כי ממנו תוצאות חיים, שהן נשמות ישראל שהן תוצאות של המלכות, הנקראת חיים, והיא, המלכות, היא הבל היוצא ונכנס בפיו של האדם בלא עמל ובלא יגיעה, שה״ס \u0003ה׳\u0004 דהבראם, כי אות \u0003ה׳\u0004 מתבטאת מן הפה, בקלות, יותר מכל האותיות, ועליה נאמר, כי על כל מוצא פי ה׳ יחיה האדם. כי המלכות, נקראת מוצא פי ה׳. והיא על ראשו של האדם. דהיינו, ועל ראשי שכינת אל. ועליה נאמר ותמונת ה׳ יביט. כי המלכות נקראת תמונת ה׳. וכן אך בצלם יתהלך איש."],[7,"ובגין דאיהי על","וכו׳: ומשום שהיא על ראשו של האדם, אסור לו לאדם ללכת ד׳ אמות בגילוי ראש. כי אם היא מסתלקת מעל ראשו של אדם, מיד מסתלקים החיים ממנו."],[8,"ואי תימא דכך","וכו׳: ואם תאמר שכך שורה המלכות גם על אומות העולם, אע״פ שלא נבראו בהם שמים וארץ וכל התולדות שבהם. כי בהבראם הוא אותיות באברהם, שבו נבראו שמים וארץ ותולדותיהם, וכן זרעו של אברהם ולא אומות העולם. ומשיב, אינה שורה עליהם ודאי, כי משה בקש מהקב״ה שלא תשרה השכינה על אומות העולם, ונתן לו. (ברכות ז.) וא״כ ההבל הנמצא על אומות העולם מאיזה מקום יוצא, או הנמצא על הרשעים שהם ערב רב המעורבים בישראל. מאין הוא. ומשיב, אלא ודאי אין כל פנים שוים. ואפילו בישראל אין כל אחד שוה, כל שכן אחרים. כמ״ש לפנינו (באות מ״א ומ״ב)."],[9,"אלא ודאי על","וכו׳: אלא ודאי, על צורה זו של אות \u0003ה׳,\u0004 העמידו, מתנה טובה יש לי בבית גנזי ושבת שמה. כי שבת היא המלכות. בשעה שהיא עולה לבינה, וכשזו המלכות שה״ס שבת, שורה על ישראל, אין להם יגיעה ולא שעבוד. ובה, נפש העמלה והיגיעה שבת וינפש."],[10,"דנפש אחרא אית","וכו׳: כי נפש אחרת ישנה על ראשו של אדם, שאינה ממלכות, שנקראת עבד, כי נמשכת ממטטרו״ן, שנקרא עבד, והיא הצורה שעל האדם במקום המלכות, והיא, עבד מלך המנענע כל אבריו של אדם ללכת בדרכים טובים ולקיים בהם רמ״ח מצות, שתשרה עליהם \u0003ה׳\u0004 דבהבראם, שה״ס המלכות, כי כך עולה הבראם במספר רמ״ח."],[11,"ודיוקנא אחרא על רישיה","וכו׳: אחר שביאר בחינת נפש האדם הוא מפרש בחינת נרנח״י דרוח הנמשכת לאדם הזוכה, מבחינת ד׳ אותיות הויה דז״א, ששורים על ראשו. ואומר, וצורה אחרת יש על ראשו שנקראת \u0003יראה,\u0004 וזו היא \u0003י׳\u0004 דהויה, שה״ס כתר וחכמה, דהיינו האורות של יחידה חיה, דרוח. וכיון שה״ס כתר היא בחינת יראה. כי היראה נמשכת מכתר. ועליהם נאמר, ויברא אלקים את האדם בצלמו בצלם אלקים, דהיינו ב״פ בצלם, שהם ב׳ צורות טובות שהם זכר ונקבה, הזכר מצד אות \u0003י׳,\u0004 דהויה, שה״ס יחידה חיה, והנקבה מצד אות \u0003ה׳\u0004 דהויה, שה״ס נשמה."],[12,"ותרין אתוון אתערין","וכו׳: וב׳ אותיות \u0003י״ה\u0004 מעוררות את האדם לתורה ולמצוה, שהתורה ה״ס ו׳, והמצוה ה״ס ה׳. ה \u0003י׳\u0004 היא יראה, שזו היא על ראשו של האדם, וממנה נמשכת היראה אל הלב של האדם לירא מהקב״ה, ולשמור עצמו שלא יעבור על מצות לא תעשה. \u0003ה׳\u0004 היא אהבה שעל ראשו של אדם וממנה נמשכת אהבת הקב״ה על רמ״ח אברים שלו לקיים בהם רמ״ח מצות עשה. \u0003ו׳\u0004 דהויה, שמצדה שורה אור הרוח דרוח על האדם, היא על ראשו של האדם וממנה נכנסים \u0003דבורים\u0004 בפה של האדם ללמוד בתורה. דהיינו המלכות שה״ס הנפש דרוח, שנקראת \u0003דברים,\u0004 שה״ס \u0003ה׳,\u0004 ונשלם \u0003הויה.\u0004"],[13,"ובהאי קחו עמכם","וגו׳: ובזה, בדבורים שנמשכים לפיו ללמוד בתורה. נאמר קחו עמכם \u0003דברים\u0004 ושובו אל \u0003הויה.\u0004 כי הדיבורים משלימים יה״ו, עם ה׳ אחרונה, שנקראת דברים. ובזה, שיהיה בכם היראה והאהבה והתורה, שה״ס י״ה ו״ה, כי יראה ואהבה ה״ס \u0003י״ה\u0004 והתורה ה״ס \u0003ו׳\u0004 והדבורים שבפה, ה״ס \u0003ה׳\u0004 ישוב \u0003הויה\u0004 שהוא ז״א, להיות בינה, שהיא תשובה, שפירושה, תשוב \u0003ו׳\u0004 שהוא ז״א ל \u0003ה׳\u0004 ראשונה, שהיא מעשה בראשית והיא ל״ב פעם אלקים שבמעשה בראשית. דהיינו בינה. דהיינו שז״א ומלכות עולים ומלבישים את הג״ר דבינה, שה״ס או״א עלאין. ויושלם הוי״ה, ובה במלכות שעלתה לבינה, יהיה לכם מנוחה מכל, ובה שבת וינפש. כלומר שהמלכות העולה לבינה נקראת שבת, והיא בסוד המנוחה והנפישה. וכל עוד שאינה עולה לבינה, אין המלכות נקראת שבת."]],[[0,"","בְּאַחֲרִית הַיָּמִים, מַה יֵּשׁ כָּאן? אֶלָּא לְהַכְלִיל כְּנֶסֶת יִשְׂרָאֵל, שֶׁהִיא בַּגָּלוּת וְנִמְצֵאת בְּצָרָתָם, וְלֹא עוֹזֶבֶת אוֹתָם לְעוֹלָמִים. וְלָכֵן הַקָּדוֹשׁ בָּרוּךְ הוּא, אַף עַל גַּב שֶׁמַּשְׁרֶה דִין בָּעוֹלָם, רוֹצֶה שֶׁיַּחְזְרוּ יִשְׂרָאֵל בִּתְשׁוּבָה לְהֵיטִיב לָהֶם בָּעוֹלם הַזֶּה וּבָעוֹלָם הַבָּא, וְאֵין לְךְ מִי שֶׁיַּעֲמֹד בִּפְנֵי הַתְּשׁוּבָה."],[1,"","בֹּא רְאֵה, אֲפִלּוּ כְּנֶסֶת יִשְׂרָאֵל נִקְרֵאת תְּשׁוּבָה. וְאִם תֹּאמַר, (תשובה) עֶלְיוֹנָה (מעלה) (ואות עליונה) מִכָּל מָקוֹם לֹא נִמְצֵאת - אֶלָּא זוֹ נִקְרֵאת תְּשׁוּבָה, כְּשֶׁחוֹזֵר רַחֲמִים לְמוּלָהּ, וְהִיא חוֹזֶרֶת עַל כָּל אוֹתָם אוּכְלוּסִים וּמֵינִיקָתָם. וּתְשׁוּבָה מְעֻלָּה - כְּשֶׁנִּמְסֶרֶת הַנֶּפֶשׁ אֵלֶיהָ וְלוֹקַחַת אוֹתָהּ בִּזְמַן שֶׁהִיא בִּתְשׁוּבָה, אָז הַכֹּל מִתְתַּקֵּן לְמַעְלָה וּלְמַטָּה, וּמִתְתַּקֵּן הוּא וְכָל הָעוֹלָם."],[2,"","רָשָׁע אֶחָד בָּעוֹלָם - בִּגְלָלוֹ יֵשׁ קִלְקוּל לְכַמָּה אֲחֵרִים. אוֹי לָרָשָׁע, אוֹי לִשְׁכֵנוֹ! בּא רְאֵה, יוֹנָה, מִשּׁוּם שֶׁלֹּא רָצָה לָלֶכֶת בִּשְׁלִיחוּת רִבּוֹנוֹ, כַּמָּה אֲנָשִׁים הָיוּ אוֹבְדִים בִּגְלָלוֹ בַּיָּם, עַד שֶׁכֻּלָּם חָזְרוּ עָלָיו וְדָנוּ אוֹתוֹ בְּדִין בַּיָּם, וְאָז נִצְּלוּ כֻלָּם, וְאַחַר כָּךְ הַקָּדוֹשׁ בָּרוּךְ הוּא רִחֵם עָלָיו, וְהִצִּיל כַּמָּה אוּכְלוּסִים בָּעוֹלָם. מָתַי? כְּשֶׁחָזַר לְרִבּוֹנוֹ מִתּוֹךְ צָרָתוֹ. זֶהוּ שֶׁכָּתוּב (יונה ב) קָרָאתִי מִצָּרָה לִי אֶל ה' וַיַּעֲנֵנִי. וְכָתוּב (תהלים קיח) מִן הַמֵּצַר קָרָאתִי יָּהּ עָנָנִי בַמֶּרְחָב יָהּ וְגוֹ'."],[3,"","מִצְוָה זוֹ הִיא מִצְוַת תְּשׁוּבָה, וְזוֹהִי בִּינָה. וּבַעֲונוֹתֵינוּ, מִשֶּׁחָרַב בֵּית הַמִּקְדָּשׁ, לֹא נִשְׁאָר לָנוּ אֶלָּא וִדּוּי דְּבָרִים לְבַד, וְזוֹ מַלְכוּת. וּמַה זֶּה בִּינָה? בֶּן יָ\"הּ. וּבֵן זֶה הוּא ו' בְּוַדַּאי. וְכָל מִי שֶׁחוֹזֵר בִּתְשׁוּבָה, כְּאִלּוּ הֶחֱזִיר ה' לָאוֹת ו', שֶׁהִיא בֶּן יָ\"הּ, וְנִשְׁלָם בּוֹ יְהֹוָ\"ה. וְזוֹהִי תְּשׁוּבָה - תָּשׁוּב ה' וַדַּאי לְו'."],[4,"","שֶׁאוֹת ה' וַדַּאי הִיא וִדּוּי דְּבָרִים, וְסוֹד הַדָּבָר - (הושע יד) קְחוּ עִמָּכֶם דְּבָרִים וְשׁוּבוּ אֶל ה' אִמְרוּ אֵלָיו וְגוֹ' וּנְשַׁלְּמָה פָרִים שְׂפָתֵינוּ. שֶׁוַּדַּאי כְּשֶׁאָדָם חוֹטֵא, גּוֹרֵם לְהַרְחִיק ה' מֵאוֹת ו'. שֶׁמִּסְתַּלֵּק בֶּן יָ\"הּ, זֶה יה\"ו, מֵאוֹת ה'. וְלָכֵן חָרַב בֵּית הַמִּקְדָּשׁ, וְהִתְרַחֲקוּ יִשְׂרָאֵל מִשָּׁם וְגָלוּ לְבֵין הָעַמִּים. וּמִשּׁוּם זֶה, כָּל מִי שֶׁעוֹשֶׂה תְשׁוּבָה, גּוֹרֵם לְהַחֲזִיר ה' לָאוֹת ו', וְהַגְּאֻלָּה תְלוּיָה בָּזֶה. וּמִשּׁוּם זֶה הַכֹּל תָּלוּי בִּתְשׁוּבָה. שֶׁכָּךְ אָמְרוּ הָרִאשׁוֹנִים, כָּל הַקִּצִּים כָּלוּ, וְאֵין הַדָּבָר תָּלוּי אֶלָּא בִּתְשׁוּבָה, שֶׁהוּא שְׁלֵמוּת שְׁמוֹ."],[5,"","וְעַל כָּךְ, (יחזקאל כ) וָאֶעֱשֶׂה לְמַעַן שְׁמִי. וְעוֹד, (ישעיה מח) לְמַעֲנִי לְמַעֲנִי אֶעֱשֶׂה. וְאִם לֹא חוֹזְרִים, אֲנִי אַעֲמִיד לָהֶם מֶלֶךְ שֶׁקָּשִׁים גְּזֵרוֹתָיו מִשֶּׁל פַּרְעֹה, וְיַחְזְרוּ בְּעַל כָּרְחָם. זֶהוּ שֶׁכָּתוּב (דברים ד) וְשַׁבְתָּ עַד ה' אֱלֹהֶיךְ, עַד יְהֹוָ\"ה וַדַּאי."],[6,"","וּתְשׁוּבָה זוֹ נִקְרֵאת חַיִּים, (משלי ד) כִּי מִמֶּנּוּ תּוֹצְאוֹת חַיִּים, שֶׁהֵם נִשְׁמוֹת יִשְׂרָאֵל. וְהוּא הֶבֶל שֶׁיּוֹצֵא וְנִכְנָס בְּפִי הָאָדָם בְּלֹא עָמָל וּבְלֹא יְגִיעָה, ה' שֶׁל הִבָּרְאָם, וְעָלָיו נֶאֱמַר (דברים ח) כִּי עַל כָּל מוֹצָא פִי ה' יִחְיֶה הָאָדָם. וְהִיא עַל רֹאשׁ הָאִישׁ, עָלֶיהָ נֶאֱמַר (במדבר יב) וּתְמוּנַת ה' יַבִּיט. (תהלים לט) אַךְ בְּצֶלֶם יִתְהַלֶּךְ אִישׁ."],[7,"","וּמִשּׁוּם שֶׁהִיא עַל רֹאשׁ הָאִישׁ, אָסוּר לוֹ לָאָדָם לָלֶכֶת אַרְבַּע אַמּוֹת בְּגִלּוּי רֹאשׁ, שֶׁאִם הִיא מִסְתַּלֶּקֶת מֵעַל רֹאשׁוֹ שֶׁל הָאָדָם, מִיָּד מִסְתַּלְּקִים מִמֶּנּוּ הַחַיִּים."],[8,"","וְאִם תֹּאמַר שֶׁכָּךְ שׁוֹרֶה עַל רֹאשׁ אֻמּוֹת הָעוֹלָם, אַף עַל גַּב שֶׁלֹּא נִבְרְאוּ בָהֶם שָׁמַיִם וָאָרֶץ וְכָל תּוֹלְדוֹתֵיהֶם - לֹא שׁוֹרֶה וַדַּאי. שֶׁמֹּשֶׁה בִּקֵּשׁ מֵהַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא תִשְׁרֶה שְׁכִינָה עַל אֻמּוֹת הָעוֹלָם, וְנָתַן לוֹ. הַהֶבֶל הָעוֹמֵד עַל אֻמּוֹת הָעוֹלָם מֵאֵיפֹה יוֹצֵא? אוֹ עַל הָרְשָׁעִים שֶׁהֵם עֵרֶב רַב, מְעֹרָבִים עִם יִשְׂרָאֵל? אֶלָּא וַדַּאי לֹא כָּל הַפָּנִים שָׁוִים. אֲפִלּוּ יִשְׂרָאֵל אֵינָם שָׁוִים, כָּל שֶׁכֵּן אֲחֵרִים."],[9,"","אֶלָּא וַדַּאי עַל דְּמוּת זוֹ שֶׁל אוֹת ה' פֵּרְשׁוּהָ, מַתָּנָה טוֹבָה יֵשׁ לִי בְּבֵית גְּנָזַי וְשַׁבָּת שְׁמָהּ. וּכְשֶׁהִיא שׁוֹרָה עַל יִשְׂרָאֵל, אֵין לָהֶם יְגִיעָה וְלֹא שִׁעְבּוּד, וּבָהּ נֶפֶשׁ עֲמֵלָה וִיגֵעָה (שמות לב) שָׁבַת וַיִּנָּפַשׁ."],[10,"","שֶׁנֶּפֶשׁ אַחֶרֶת יֵשׁ עַל רֹאשׁ הָאָדָם, שֶׁנִּקְרֵאת עֶבֶד, וְהִיא דְּמוּת עַל הָאִישׁ, וְהוּא עֶבֶד הַמֶּלֶךְ, שֶׁמְּנַעְנַעַת כָּל אֵיבְרֵי הָאָדָם לָלֶכֶת בִּדְרָכִים טוֹבוֹת וּלְקַיֵּם בָּהֶם רמ\"ח מִצְווֹת, לְהַשְׁרוֹת עֲלֵיהֶם ה' שֶׁל בְּהִבָּרְאָם, שֶׁכָּךְ עוֹלֶה הִבָּרְאָם לְרמ\"ח."],[11,"","וּדְיוֹקָן אַחֵר עַל רֹאשׁוֹ, שֶׁנִּקְרָא יִרְאָה, וְזֶה י'. וַעֲלֵיהֶם נֶאֱמַר, וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם אֱלֹהִים. שְׁתֵּי דְמֻיּוֹת טוֹבוֹת, שֶׁהֵם זָכָר וּנְקֵבָה. זָכָר מִצַּד הָאוֹת י', נְקֵבָה מִצַּד הָאוֹת ה'."],[12,"","וּשְׁתֵּי אוֹתִיּוֹת מְעוֹרְרוֹת אֶת הָאָדָם לַתּוֹרָה וְלַמִּצְוָה. י' יִרְאָה, וְזוֹהִי עַל רֹאשׁ הָאָדָם, וּמִמֶּנָּה תִּכָּנֵס יִרְאָה לְלֵב הָאָדָם לִירָא מֵהַקָּדוֹשׁ בָּרוּךְ הוּא וְלִשְׁמֹר אֶת עַצְמוֹ שֶׁלֹּא יַעֲבֹר עַל מִצְווֹת לֹא תַעֲשֶׂה. ה' אַהֲבָה עַל רֹאשׁוֹ שֶׁל הָאָדָם, וּמִמֶּנָּה נִכְנֶסֶת אַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא עַל רמ\"ח אֵיבָרָיו לְקַיֵּם בָּהֶם מִצְווֹת עֲשֵׂה. ו' הִיא עַל רֹאשׁ הָאָדָם, וּמִמֶּנָּה יִכָּנֵס עַל פֶּה הָאָדָם דִּבּוּרִים לִלְמֹד בַּתּוֹרָה."],[13,"","וּבָזְהִ קְחוּ עִמָּכֶם דְּבָרִים וְשׁוּבוּ אֶל ה'. וּבְזֶה שֶׁתִּהְיֶה בָּכֶם הַיִּרְאָה וְהָאַהֲבָה וְהַתּוֹרָה, יַחֲזֹּר יְהֹוָ\"ה שֶׁהוּא בִּינָה, תְּשׁוּבָה, ו' תָּשׁוּב לְה', שֶׁהִיא מַעֲשֵׂה בְרֵאשִׁית, וְהִיא ל\"ב אֱלֹהִים. וְיִשְׁתַּלֵּם יְהֹוָה, וּבָהּ תִּהְיֶה לָכֶם מְנוּחָה וְנַחַת מֵהַכֹּל, וּבָהּ שָׁבַת וַיִּנָּפַשׁ."]]],[["וּבָהּ יִתְכְּלִיל יד\"ו, וּבְגִין דָּא וַיְכֻלּוּ: שְׁלִימוּ דְּכֹלָּא. בָּהּ, אִתְבְּרֵי כָּל עָלְמָא, וְעָלָהּ קַיְימִין שְׁמַיָא וְאַרְעָא וְיַמָּא וְכָל בִּרְיָין דְּאִתְבְּרוּן, דִּכְתִּיב, (בראשית ב׳:ד׳) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, בְּה' בְּרָאָם. וְאִם הִיא אִתְרַחֲקַת מֵעָלְמָא אֲפִילּוּ רִגְעָא, כֹּלָּא אִתְחֲרֵב וְאִתְבָּטֵל, וְלָא הֲוִי קִיוּמָא בְּעָלְמָא.","הַאי ה' לָא תֵּיזִיל מִגּוּפָא, וּבָהּ קַיְימָא וְכַד הִיא תֵּיזִיל מִינֵּיהּ, הוּא סַם הַמָּוְת תֵּיתֵי וְתִשְׁרֵי עֲלֵיהּ, דְּתִתְקְרֵי טוּמְאָה, נְבֵלָה, פְּסוּלָה, מַלְאַךְ הַמָּוְת, חֹשֶׁךְ, אֲפֵלָּה, וְשַׁרְיָא עַל גּוּפָא דְּבַּר נָשׁ. וּבְהַהוּא זִמְנָא אִתְקְרֵי בַּר נָשׁ מֵת. וְרָזָא דְּמִלָּה, (יחזקאל י״ח:ל״ב) כִּי לֹא אֶחְפּוֹץ בְּמוֹת הַמֵּת נְאֻם יְיָ אֱלֹהִים וְהָשִׁיבוּ וִחְיוּ.","כָּל פִּקוּדִין דַּעֲשֵׂה, דַּהֲווֹ עֲתִידִין לְשַׁרְיָא בְּרמ\"ח אֵבָרִין דִּילֵיהּ, כֻּלְּהוּ מִתְאַבְּלִין עָלֵיהּ. וְרָזָא דְּמִלָּה, (ישעיהו נ״ז:י״ח) דְּרָכָיו רָאִיתִי וְאֶרְפָּאֵהוּ וְגוֹ'. וְלַאֲבֵלָיו. מַאי וְלַאֲבֵלָיו. אִילֵּין רמ\"ח אֵבָרִין, דְּקָא מִתְאַבְּלִין עָלֵיהּ, דְּאִינּוּן דִּיּוּקְנָא עִלָּאָה דְּשַׁרְיָא עַל רֵישֵׁיהּ, דְּבָהּ שַׁרְיָא הַוָיָ\"ה. דִּכְמָה דְּאִית (וישלח קס\"ה, שמות ק\"ו ע\"ב) דִּיּוּקְנָא טָבָא עַל צַּדִּיק, וּמַנְהִיג לֵיהּ לְכָל עוֹבָדִין טָבִין, לְזַכָּאָה לֵיהּ לְעָלְמָא דְּאָתֵי. כַּךְ אִית דִּיּוּקְנָא בִּישָׁא, עַל רֵישָׁא דְּחַיָּיבַיָּא, לְאַנְהָגָא לוֹן בְּעוֹבָדִין בִּישִׁין, דְּיַרְתּוּן גֵּיהִנָּם. וּבְגִין דָּא אִית הֶבֶל וְאִית הֶבֶל, אִית הֶבֶל טָב, דְּאִתְּמַר בֵּיהּ, (דברים ח׳:ג׳) כִּי עַל כָּל מוֹצָּא פִי יְיָ יִחְיֶה הָאָדָם. וְאִית הֶבֶל בִּישׁ, דְּאִתְּמַר בֵּיהּ (קהלת ב׳:כ״ו) גַּם זְה הֶבֶל וּרְעוּת רוּחַ.","וְתָּא חֲזֵי בְּעוֹבָדִין דְּבַּר נָשׁ אִשְׁתְּמוֹדַע פַּרְצּוּפָא, דְּאִיהִי עָלֵיהּ, וּפַרְצּוּפָא דְּאַנְפּוֹי. הֲדָא הוּא דִכְתִיב, (ישעיהו ג׳:ט׳) הַכָּרַת פְּנֵיהֶם עָנְתָה בָּם. בְּדִיּוּקְנָא, אִשְׁתְּמוֹדַע פַּרְצּוּפָא דְּחַיָּה דְּשַׁרְיָא עָלֵיהּ, אִם הוּא אַרְיִה, אוֹ שׁוֹר אוֹ נֶשֶׁר, אוֹ אָדָם. מֵהַמֶּרְכָּבָה דְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ. אוֹ מֵהַמֶּרְכָּבָה דְּמַלְאָךְ שַׂר הַפָּנִים. אוֹ מֵהַמֶּרְכָּבָה בִּישָׁא דְּסָמָאֵל. אוֹ מֵהַמֶּרְכָּבָה דְּאַרְבַּע יְסוֹדִין דְּעָלְמָא. וְלֵית בְּהוֹן לָא הַיִצֶּר טוֹב, וְלָא הַיִצֶּר הָרָע, אֶלָּא כִּבְעִירִין דְּעָלְמָא. וּבְגִין דָּא כַּמָה הֲבָלִים אִית בִּבְנֵי נָשָׁא, כָּל חַד לְמִינֵיהּ. וְרָזָא דְּמִלָּה, (בראשית א׳:כ״ד) תּוֹצֵּא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ. וּבְגִין דָּא, בְּמִּדָּה שֶׁאָדָם מוֹדֵד בָּהּ מוֹדְדִין לוֹ. וּבְכָל פַּרְצּוּפָא אִית מְמָנָא עָלֵיהּ.","תָּא חֲזִי, לְשִׁית יוֹמֵי בְּרֵאשִׁית, לְכָל חַד אִית לֵיהּ פַּרְצּוּפֵיהּ, דְּהַהוּא דַּרְגָּא דְּאַנְהִיג לֵיהּ, וְלָא תִּשְׁכַּח יוֹם דְּלֵית בֵּיהּ טוֹב. וְאַף עַל גַּב דִּבְיוֹמָא תִּנְיָינָא לָא אִית בֵּיהּ טוֹב, בְּיוֹמָא תְּלִיתָאָה תִּשְׁכַּח לֵיהּ. וּבְגִין דָּא אִתְּמַר בֵּיהּ תְּרֵי זִמְנֵי טוֹב.","וְכָל יוֹמָא אִית לֵיהּ גָּדֵר מִלְּבַר, דְּלָא יִיעוּל כָּל בַּר נָשׁ לְהַהוּא טוֹב. כְּגוֹן חֹשֶׁךְ דְּכַסֵּי לִנְהוֹרָא. דְּתִשְׁכַּח בְּיוֹמָא קַדְמָאָה אוֹר, וְתִשְׁכַּח בֵּיהּ חוֹשֵׁךְ. בְּכָל יוֹמָא תִּשְׁכַּח נְטִירָא. וְאִינּוּן נְטִירִין אִינּוּן, כְּגוֹן קוֹצִּים לַכֶּרֶם. וְאִית נְטִירִין אַחֲרָנִין, כְּגוֹן נְחָשִׁים וְעַקְרַבִּים וּשְׂרָפִים, וְנַטְרִין הַהוּא טוֹב, דְּלָא יִיעוּל תַּמָּן דְּלָאו אִיהוּ רָאוּי לְמֵיעַל. וְאִי לָאו, כָּל חַיָּיבַיָּא הֲווֹ עָאלִין בְּרָזִין דְּאוֹרַיְיתָא.","וּבְגִין דָּא מַאן דְּאִיהוּ חַיָיבָא, וְיִיעוּל לְמִנְדַּע רָזִין דְּאוֹרַיְיתָא, כַּמָה מַלְאֲכֵי חַבָּלָה דְּאִתְקְרִיאוּ חֹשֶׁךְ וַאֲפֵלָה, נְחָשִׁים וְעַקְרַבִּים חֵיוַת בָּרָא אִתְקְרִיאוּ, וּמְבַלְבְּלִין מַחֲשַׁבְתֵּיהּ, דְּלָא יִיעוּל לַאֲתָר דְּלָאו דִּילֵיהּ.","אֲבָל מַאן דְּאִיהוּ טוֹב, כָּל אִלֵּין נְטִירִין אִינּוּן לְמֶמְרֵיהּ, וְקַטֵיגוֹר נֶעֱשָׂה סַנֵיגוֹר, וְיִיעָלוּן (ליה) לְטוֹב הַגָנוּז, וְיֵימְרוּן לֵיהּ מָרָנָא, הָא בַּר נָשׁ טוֹב וְצַּדִּיק יְרֵא שָׁמַיִם, בָּעֵי לְאַעֲלָא קֳדָמָךְ, אָמַר לָנוּ, (תהילים קי״ח:י״ט) פִּתְחוּ לִי שַׁעֲרֵי צֶּדֶק אָבֹא בָם אוֹדֶה יָהּ. הַהוּא טוֹב הַגָנוּז יִימָּא לוֹן, פִּתְחוּ לֵיהּ בְּהַאי תַּרְעָא דְּאִתְקְרֵי אַהֲבָה, אוֹ בְּהַאי תַּרְעָא דְּאִיהִי תְּשׁוּבָה. כָּל צַּדִּיק יִיעוּל כְּפוּם דַּרְגָּא דִּילֵיהּ, וְרָזָא דְּמִלָּה (ישעיהו כ״ו:ב׳) פִּתְחוּ שְׁעָרִים וְיָבֹא גּוֹי צַּדִּיק וְגוֹ'.","כְּעַן צָּרִיךְ לְאָהַדְּרָא עַל פֶּתַח הַתְּשׁוּבָה. וְכִי מִכַּמָּה מִינִין אִיהוּ תְּשׁוּבָה דְּעַבְדִין בְּנֵי נָשָׁא, כֻּלְּהוּ טָבִין, אֲבָל לָאו כָּל אַפַּיָיא שָׁוִין. אִית בַּר נָשׁ דְּאִיהוּ רָשָׁע גָּמוּר כָּל יָמָיו, וְאִיהוּ עוֹבֵר עַל כַּמָה פִּקוּדִין דְּלָא תַּעֲשֶׂה, וּמִתְחָרֵט וּמוֹדֶה עָלַיְיהוּ, וּלְבָתַר כֵּן לָא עָבֵד לָא טַב וְלָא בִּישׁ. לְדָא וַדַּאי יִמְחוֹל לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, אֲבָל לָא דְּיִזְכֶּה לִתְשׁוּבָה עִלָּאָה. אִית בַּר נָשׁ לְבָתַר דְּיֵיתוּב מֵחַטָאָיו, וּמִתְכַּפֵּר לֵיהּ, אִיהוּ אָזִיל בְּדֶּרֶךְ מִצְּוָה, וּמִתְעַסֵּק בְּכָל כֹּחוֹ בִּדְחִילוּ וּרְחִימוּ דְקוּדְשָׁא בְּרִיךְ הוּא. דָּא זָכֵי לִתְשׁוּבָה תַּתָּאָה, דְּאִתְקְרֵי ה'. וְדָא אִיהוּ תְּשׁוּבָה תַּתָּאָה.","וְאִית בַּר נָשׁ לְבָתַר דְּמִתְחָרֵט מֵחוֹבוֹי, וְיַעְבִיד תְּשׁוּבָה, וְיִתְעֲסָק בְּאוֹרַיְיתָא בִּדְחִילוּ וּרְחִימוּ דְקוּדְשָׁא בְּרִיךְ הוּא, וְלָא עַל מְנָת לְקַבֵּל פְּרָס. דָּא זָכֵי לְאָת ו', וְאִיהוּ בֶּן יָ\"הּ, וְעַל שְׁמֵיהּ אִתְקְרֵי בִּינָה, וְדָא גָּרִים דְּתָשׁוּב ו' לְגַבֵּי ה'. וּמִלַּת תְּשׁוּבָה כַּךְ הִיא, תָּשׁוּב ו' לְה'."],[[0,"ובה יתכליל יה״ו","וכו׳: ובה, במלכות שעלתה לבינה, שהיא \u0003ה׳\u0004 אחרונה, יוכלל יה״ו, ויושלם השם. ומשום זה, ויכולו השמים והארץ, שהוא בשבת, היא שלמות הכל. בה, נברא כל העולם, ועליה עומדים שמים וארץ והים וכל הבריות שנבראו, שכתוב, אלה תולדות השמים והארץ בהבראם שהוא אותיות ב \u0003ה׳\u0004 בראם, שהיא מלכות ואם היתה מתרחקת מן העולם אפילו רגע אחד, היה הכל נחרב ומתבטל, ולא היה קיום לעולם."],[1,"האי ה׳ לא","וכו׳: ה׳ זו לא תלך מן הגוף של האדם ובו היא עומדת, וכשהיא הולכת ממנו, יבא סם המות וישרה עליו, שהוא נקראת, טומאה, נבלה, פסולה, מלאך המות, חשך, אפלה, ושורה על גוף האדם. ובעת ההוא, נקרא האדם מת. וסוד הדבר, כי לא אחפוץ במות המת נאם ה׳ אלקים והשיבו וחיו. שהיה לו לומר, במות החי. אלא שהרשע הוא כבר מת, וע״כ כתוב במות המת."],[2,"כל פקודין דעשה","וכו׳: כל מצות עשה, שהיו עתידים לשרות ברמ״ח אברים שלו, כולם מתאבלים עליו. וסוד הדבר דרכיו ראיתי וארפאהו וגו׳ ולאבליו. מהו ולאבליו, אלו הם רמ״ח אברים שמתאבלים עליו, שהם צורה עליונה, השורה על ראשו שבה שורה יה״ו ה׳ (כנ״ל אות ל״ז) וכמו שישנה צורה טובה על צדיק המנהיגו לעשות כל המעשים הטובים לזכותו לעולם הבא, כך ישנה צורה רעה על ראש הרשעים להנהיגם במעשים רעים שירשו גיהנם. ומשום זה יש הבל ויש הבל. יש הבל טוב שנאמר בו, כי על כל מוצא פי ה׳ יחיה האדם. ויש הבל רע, שנאמר בו, גם זה הבל ורעות רוח."],[3,"ות״ח בעובדין דב״נ","וכו׳: ובוא וראה במעשים של האדם, ניכר הפרצוף השורה עליו, ופרצוף הפנים. ז״ש הכרת פניהם ענתה בם. בצורה השורה עליו, ניכר פרצוף החיה השורה עליו, אם הוא אריה או שור או נשר או אדם ואם מן המרכבה של הקב״ה ושכינתו או מהמרכבה של המלאך שר הפנים. או מהמרכבה הרעה של סמאל, או מהמרכבה של ד׳ יסודות העולם, שאין בהם לא יצר הטוב ולא יצר הרע, אלא כבהמות העולם. ומשום זה כמה הבלים יש באדם כל אחד למינו. וסוד הדבר, תוצא הארץ נפש חיה למינה. ומשום זה במדה שאדם מודד מודדים לו. ובכל פרצוף יש ממונה עליו."],[4,"ת״ח לשית יומי","וכו׳: בוא וראה, לששת ימי בראשית, לכל אחד יש לו פרצוף של אותה המדרגה המנהיגה אותו. ולא תמצא יום שאין בו טוב, דהיינו שנאמר בהם וירא אלקים כי טוב. ואע״פ שביום שני לא נאמר בו כי טוב, תמצא אותו ביום השלישי, שמשום זה נאמר בו שתי פעמים טוב."],[5,"וכל יומא אית","וכו׳: וכל יום יש לו גדר מבחוץ, שלא כל אדם יוכל לכנוס לטוב ההוא שבו, דהיינו שיש חשך המכסה את האור. כמו שתמצא ביום הראשון אור, ותמצא בו חשך. וכן בכל יום תמצא שמירה, ואלו הם שמירה, כמו קוצים השומרים הכרם, שלא יכנוס זר אליו. ויש שומרים אחרים כמו נחשים ועקרבים ושרפים ששומרים הטוב ההוא, שלא יכנוס שם מי שאינו ראוי להכנס. ואם לא היתה שמירה, היו כל הרשעים יכולים לכנוס בסודות התורה."],[6,"ובג״ד מאן דאיהו","וכו׳: ומשום זה, מי שהוא רשע, ויכנוס לדעת סודות התורה, כמה מלאכי חבלה הנקראים חשך ואפלה, נחשים ועקרבים, שנקראים חיות השדה, מבלבלים מחשבתו שלא יכנוס למקום שאינו שלו."],[7,"אבל מאן דאיהו","וכו׳: אבל מי שהוא טוב, כל אלו השומרים הם לפקודתו לעזרו, וקטגור נעשה סנגור. ומביאים אותו לטוב הגנוז, ויאמרו, אל הטוב הגנוז, אדוננו, הרי איש טוב וצדיק ירא שמים רוצה לכנוס לפניך, ואמר לנו, פתחו לי שערי צדק אבא בם אודה יה. אז, אותו טוב הגנוז, יאמר להם, פתחו לו באותו שער שנקרא אהבה, או באותו שער שנקרא תשובה. וכל צדיק יכנוס כפי המדרגה שלו. וסוד הדבר, פתחו שערים ויבוא גוי צדיק וגו׳."],[8,"כען צריך לאהדרא","וכו׳: עתה צריכים לחזור, על פתח התשובה. כי מכמה מינים היא התשובה שעושים בני אדם, וכולם טובים, אבל לא כל הפנים שוים. יש בן אדם שהוא רשע גמור כל ימיו, והוא עבר על כמה מצות לא תעשה, והוא מתחרט ומתודה עליהם. ואח״כ אינו עושה לא טוב ולא רע, לזה, ודאי שהקב״ה ימחול לו. אבל לא שיזכה לתשובה עליונה, ויש בן אדם, שאחר ששב מחטאיו ונתכפר לו, הוא הולך בדרך מצוה, ועוסק בכל כחו בהם, ביראה ובאהבה להקב״ה, זה זוכה לתשובה תחתונה שנקראת \u0003ה׳\u0004 דהיינו מלכות, שזו היא תשובה תחתונה."],[9,"ואית ב״נ לבתר","וכו׳: ויש אדם, שאחר שמתחרט על עונותיו ועושה תשובה, הוא עוסק בתורה ביראה ואהבה להקב״ה, ולא על מנת לקבל פרס. זה זוכה לאות \u0003ו׳\u0004 דהויה, שהוא ז״א, והיא בן י״ה, ועל שמו נקרא בינה, וזה גורם שתשוב \u0003ו׳,\u0004 שהוא ז״א, אל ה \u0003ה׳\u0004 שהיא מלכות. והמלה תשובה היא אותיות תשוב \u0003ו׳\u0004 ל \u0003ה׳.\u0004"]],[[0,"","וּבָהּ יִכָּלֵל יה\"ו, וּמִשּׁוּם זֶה וַיְכֻלּוּ - שְׁלֵמוּת הַכֹּל. בָּהּ נִבְרָא כָּל הָעוֹלָם, וְעָלֶיהָ עוֹמְדִים שָׁמַיִם וָאָרֶץ וְהַיָּם וְכָל הַבְּרִיּוֹת שֶׁנִּבְרְאוּ, שֶׁכָּתוּב (בראשית ב) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, בְּה' בְּרָאָם. וְאִם הִיא תִּתְרַחֵק מֵהָעוֹלָם אֲפִלּוּ רֶגַע, הַכֹּל יֶחֱרַב וְיִתְבַּטֵּל, וְלֹא תִהְיֶה עֲמִידָה לָעוֹלָם."],[1,"","ה' זֹּאת לֹא תֵלֵךְ מֵהַגּוּף, וּבוֹ הוּא עוֹמֵד. וּכְשֶׁהִיא תֵּלֵךְ מִמֶּנּוּ, הוּא סַם הַמָּוֶת יָבֹא וְיִשְׁרֶה עָלָיו, שֶׁתִּקָּרֵא טֻמְאָה, נְבֵלָה, פְּסוּלָה, מַלְאַךְ הַמָּוֶת, חֹשֶׁךְ, אֲפֵלָה, וְשׁוֹרָה עַל גּוּף הָאִישׁ. וּבְאוֹתוֹ זְמַן נִקְרָא הָאָדָם מֵת, וְסוֹד הַדָּבָר - (יחזקאל יח) כִּי לֹא אֶחְפֹּץ בְּמוֹת הַמֵּת נְאֻם ה' אֱלהִים וְהָשִׁיבוּ וִחְיוּ."],[2,"","כָּל מִצְווֹת עֲשֵׂה שֶׁהָיוּ עֲתִידוֹת לִשְׁרוֹת בְּרמ\"ח אֵיבָרָיו, כֻּלָּן מִתְאַבְּלוֹת עָלָיו, וְסוֹד הַדָּבָר - (ישעיה נז) דְּרָכָיו רָאִיתִי וְאֶרְפָּאֵהוּ וְגוֹ', וְלַאֲבֵלָיו. מַה זֶּה וְלַאֲבֵלָיו? אֵלּוּ רמ\"ח אֵיבָרִים שֶׁמִּתְאַבְּלִים עָלָיו, שֶׁהֵם דְּמוּת עֶלְיוֹנָה שֶׁשּׁוֹרָה עַל רֹאשׁוֹ, שֶׁבָּהּ שׁוֹרֶה הֲוָיָ\"ה. שֶׁכְּמוֹ שֶׁיֵּשׁ דְּמוּת טוֹבָה עַל צַדִּיק וּמַנְהִיגָה אוֹתוֹ לְכָל מַעֲשִׂים טוֹבִים לְזַכּוֹתוֹ לָעוֹלָם הַבָּא, כָּךְ יֵשׁ דְּמוּת רָעָה עַל רֹאשׁ הָרְשָׁעִים לְהַנְהִיגָם בְּמַעֲשִׂים רָעִים, שֶׁיָּרְשׁוּ גֵיהִנֹּם. וּמִשּׁוּם זֶה יֵשׁ הֶבֶל וְיֵשׁ הֶבֶל. יֵשׁ הֶבֶל טוֹב, שֶׁנֶּאֱמַר בּוֹ כִּי עַל כָּל מוֹצָא פִי ה' יִחְיֶה הָאָדָם. וְיֵשׁ הֶבֶל רָע, שֶׁנֶּאֱמַר בּוֹ גַּם זֶה הֶבֶל וּרְעוּת רוּחַ."],[3,"","וּבֹא וּרְאֵה, בְּמַעֲשֵׂי הָאָדָם נוֹדָע הַפַּרְצוּף שֶׁעָלָיו וּפַרְצוּף פָּנָיו. זֶהוּ שֶׁכָּתוּב (שם ג) הַכָּרַת פְּנֵיהֶם עָנְתָה בָּם. בַּדְּמוּת נוֹדָע פַּרְצוּף הַחַיָּה שֶׁשּׁוֹרָה עָלָיו, אִם הוּא אַרְיֵה, אוֹ שׁוֹר, אוֹ נֶשֶׁר, אוֹ אָדָם. מִמֶּרְכֶּבֶת הַקָּדוֹשׁ בָּרוּךְ הוּא וּשְׁכִינָתוֹ, אוֹ מִמֶּרְכֶּבֶת מַלְאָךְ שַׂר הַפְּנִים, אוֹ מִמֶּרְכָּבָה רָעָה שֶׁל סָמָאֵ\"ל, אוֹ מִמֶּרְכֶּבֶת אַרְבָּעָה יְסוֹדוֹת שֶׁל הָעוֹלָם. וְאֵין בָּהֶם לֹא הַיֵּצֶר הַטּוֹב, וְלֹא הַיֵּצֶר הָרָע, אֶלָּא כְּבַהֲמוֹת הָעוֹלָם. וּמִשּׁוּם זֶה כַּמָּה הֲבָלִים יֵשׁ בִּבְנֵי אָדָם, כָּל אֶחָד לְמִינוֹ. וְסוֹד הַדָּבָר - (בראשית א) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה לְמִינָהּ. וּמִשּׁוּם זֶה, בְּמִדָּה שֶׁאָדָם מוֹדֵד - בָּהּ מוֹדְדִים לוֹ. וּלְכָל פַּרְצוּף יֵשׁ מְמֻנֶּה עָלָיו."],[4,"","בֹּא רְאֵה, לְשֵׁשֶׁת יְמֵי בְרֵאשִׁית, לְכָל אֶחָד יֵשׁ אֶת פַּרְצוּפוֹ שֶׁל אוֹתָהּ דַּרְגָּה שֶׁמַּנְהִיגָה אוֹתוֹ, וְלֹא תִמְצָא יוֹם שֶׁאֵין בּוֹ טוֹב. וְאַף עַל גַּב שֶׁבַּיּוֹם הַשֵּׁנִי אֵין בּוֹ טוֹב, תִּמְצָאֶנּוּ בַּיּוֹם הַשְּׁלִישִׁי. וּמִשּׁוּם זֶה נֶאֱמַר בּוֹ פַּעֲמַיִם כִּי טוֹב."],[5,"","וּלְכָל יוֹם יֵשׁ גָּדֵר מִבַּחוּץ שֶׁלֹּא יִכָּנֵס כָּל אָדָם לְאוֹתוֹ טוֹב, כְּמוֹ חֹשֶׁךְ שֶׁמְּכַסֶּה אֶת הָאוֹר. שֶׁתִּמְצָא בְּיוֹם רִאשׁוֹן אוֹר, וְתִמְצָא בּוֹ חֹשֶׁךְ. בְּכָל יוֹם תִּמְצָא שְׁמִירָה, וְאוֹתָם שׁוֹמְרִים הֵם כְּמוֹ קוֹצִים לַכֶּרֶם. וְיֵשׁ שׁוֹמְרִים אֲחֵרִים, כְּמוֹ נְחָשִׁים וְעַקְרַבִּים וּשְׂרָפִים, וְשׁוֹמְרִים אוֹתוֹ טוֹב שֶׁלֹּא יִכָּנֵס לְשָׁם מִי שֶׁאֵינוֹ רָאוּי לְהִכָּנֵס. וְאִם לא - כָּל הָרְשָׁעִים הָיוּ נִכְנָסִים! בְּסוֹדוֹת הַתּוֹרָה."],[6,"","וּמִשּׁוּם זֶה, מִי שֶׁהוּא רָשָׁע וְיִכָּנֵס לָדַעַת סוֹדוֹת הַתּוֹרָה, כַּמָּה מַלְאֲכֵי חַבָּלָה שֶׁנִּקְרָאִים חֹשֶׁךְ וַאֲפֵלָה, נְחָשִׁים וְעַקְרַבִּים, חַיּוֹת בָּר נִקְרָאִים, וּמְבַלְבְּלִים מַחֲשַׁבְתּוֹ שֶׁלֹּא יִכָּנֵס לְמָקוֹם שֶׁאֵינוֹ שֶׁלּוֹ."],[7,"","אֲבָל מִי שֶׁהוּא טוֹב, כָּל הַשּׁוֹמְרִים הֵם לְמָרוּתוֹ, וְקָטֵגוֹר נַעֲשֶׂה סָנֵגוֹר, וְיַכְנִיסוּ (אותו) לַטּוֹב הַגָּנוּז, וְיֹאמְרוּ לוֹ: מוֹרֵנוּ, אִישׁ זֶה הוּא טוֹב וְצַדִּיק, יְרֵא שָׁמַיִם, רוֹצֶה לְהִכָּנֵס לְפָנֶיךְ, אָמַר לָנוּ (תהלים קיח) פִּתְחוּ לִי שַׁעֲרֵי צֶדֶק אָבֹא בָם אוֹדֶה יָהּ. אוֹתוֹ טוֹב הַגָּנוּז יֹאמַר לָהֶם: פִּתְחוּ לוֹ בְּשַׁעַר זֶה שֶׁנִּקְרָא אַהֲבָה, אוֹ בְּשַׁעַר זֶה שֶׁנִּקְרָא תְּשׁוּבָה. כָּל צַדִּיק יִכָּנֵס כְּפִי דַרְגָּתוֹ, וְסוֹד הַדָּבָר - (ישעיה כו) פִּתְחוּ שְׁעָרִים וְיָבֹא גוֹי צַדִּיק וְגוֹ'."],[8,"","כָּעֵת צָרִיךְ לַחֲזֹּר עַל פֶּתַח הַתְּשׁוּבָה. וְכִי מִכַּמָּה מִינִים הִיא הַתְּשׁוּבָה שֶׁעוֹשִׂים בְּנֵי אָדָם? כֻּלָּם טוֹבִים, אֲבָל לֹא כָּל הַפָּנִים שָׁוִים. יֵשׁ אָדָם שֶׁהוּא רָשָׁע גָּמוּר כָּל יָמָיו, וְהוּא עוֹבֵר עַל כַּמָּה מִצְווֹת לֹא תַעֲשֶׂה, וּמִתְחָרֵט וּמוֹדֶה עֲלֵיהֶם, וְאַחַר כָּךְ לֹא עוֹשֶׂה לֹא טוֹב וְלֹא רַע - לָזֶה בְּוַדַּאי יִמְחֹל הַקָּדוֹשׁ בָּרוּךְ הוּא, אֲבָל לֹא יִזְכֶּה לִתְשׁוּבָה עֶלְיוֹנָה. יֵשׁ אָדָם שֶׁלְּאַחַר שֶׁיָּשׁוּב מֵחֲטָאָיו וּמִתְכַּפֵּר לוֹ, הוּא הוֹלֵךְ בְּדֶרֶךְ מִצְוָה וּמִתְעַסֵּק בְּכָל כֹּחוֹ בְּיִרְאָה וְאַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא - זֶה זוֹכֶה לִתְשׁוּבָה תַחְתּוֹנָה שֶׁנִּקְרֵאת ה', וְזוֹ הִיא תְּשׁוּבָה תַחְתּוֹנָה."],[9,"","וְיִשִׁ אָדָם שֶׁלְּאַחַר שֶׁהִתְחָרֵט עַל חֲטָאָיו וְעָשָׂה תְשׁוּבָה, וְיִתְעַסֵּק בַּתּוֹרָה בְּיִרְאָה וְאַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא, וְלֹא עַל מְנָת לְקַבֵּל פְּרָס - זֶה זוֹכֶה לָאוֹת ו', וְהוּא בֶּן יָ\"הּ, וְעַל שְׁמוֹ נִקְרֵאת בִּינָה, וְזֶה גּוֹרֵם שֶׁתָּשׁוּב ו' לְה'. וּמִלַּת תְּשׁוּבָה כָּךְ הִיא, תָּשׁוּב ו' לְה'."]]],[["וּלְעוֹלָם לָא שַׁרְיָא ה' בְּבַר נָשׁ, וְלֹא ו', בְּלָא דְּחִילוּ וּבְלָא רְחִימוּ, דְּאִינּוּן יָ\"הּ, יִרְאָה וְאַהֲבָה קָרֵינָן לֵיהּ וַדַּאי. וּמִתַּמָּן אִתְיְיהִיבוּ הַתּוֹרָה וְהַמִּצְּוָה דְּאִינּוּן בֵּן וּבַת. וּבְגִין דְּיִשְׂרָאֵל מְקַיְּימִין הַתּוֹרָה וְהַמִּצְּוָה, אִתְקְרִיאוּ בָּנִים לְּקוּדְשָׁא בְּרִיךְ הוּא, הֲדָא הוּא דִכְתִיב, (דברים י״ד:א׳) בָּנִים אַתֶּם לַיְיָ אֱלֹהֵיכֶם.","הַנִּסְתָּרוֹת: יִרְאָה וְאַהֲבָה, דְּאִינּוּן בְּמוֹחָא וְלִבָּא. בַּחֲלָלָא דְּגוּפָא. וּבְרֵישָׁא. וְהַנִּגְלוֹת: הַתּוֹרָה וְהַמִּצְּוָה, דְּאִינּוּן בְּגוּפָא וּבְרֵישָׁא לְבַר. וְרָזָא דְּמִלָּה הָכִי הוּא וַדַּאי, דְּאִי בַּר נָשׁ דָּחִיל לְּקוּדְשָׁא בְּרִיךְ הוּא, אוֹ רָחִים לֵיהּ, דָּא לָא יָדַע בַּר נָשׁ אַחֲרָא, בְּגִין דְּאִיהוּ מִלָּה דְּלָא אִתְגַּלְיָא אֶלָּא בֵּינוֹ לְבֵין קוֹנוֹ.","אֲבָל בַּר נָשׁ דְּמִתְעֲסָק בְּאוֹרַיְיתָא, וְאָזִיל בְּפִקּוּדִין דַּעֲשֵׂה, דָּא אִתְגַּלְיָא לְכָל בַּר נָשׁ, בְּגִין דְקוּדְשָׁא בְּרִיךְ הוּא עָבֵד לֵיהּ פּוּמָא בְּאִתְגַּלְיָא, לְאִתְעַסְּקָא בְּאוֹרַיְיתָא, וְעַיְינִין לְאִסְתַּכְּלָא בָּהּ, וְאוּדְנִין לְמִשְׁמַע בָּהּ. וְעָבִיד קוּדְשָׁא בְּרִיךְ הוּא בְּבַּר נָשׁ, יְדִין וְרַגְלִין וְגוּפָא, לְמֶעְבַּד בְּהוֹן פִּקוּדִין דְּעֲשֵׂה.","אִם כֵּן חוֹטָמָא לְמַאי נָפְקָא מִנֵּיהּ. (בראשית ב׳:ז׳) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים, דָּא אִיהִי דִּיּוּקְנָא דְּעַל בַּר נָשׁ, דְּאִתְּמַר בֵּיהּ (בראשית כ״ח:י״ב) וַיַחֲלוֹם וְהִנֵּה סֻלָּם. סֻלָּם וַדַּאי אִיהִי נִשְׁמַת חַיִּים, כֻּרְסְיָיא לְשֵׁם יְדוָֹ\"ד דְּאִיהוּ הַיִּרְאָה וְהָאַהֲבָה הַתּוֹרָה וְהַמִּצְּוָה וּבָה שַׁרְיָא, וְהַאי כֻּרְסְיָיא, מִנָּהּ גְּזוּרוֹת כָּל נִשְׁמָתִין דְּיִשְׂרָאֵל, וְאִיהִי דִּיּוּקְנָא עַל רֵישָׁא דְּבַּר נָשׁ.","וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עוֹלִים וְיוֹרְדִים בּוֹ. אִלֵּין הֲבָלִים דְּסַלְּקִין וְנָפְקִין בְּגוּפָא, בְּהַאי סֻלָּם. אִיהוּ חַד, שְׁבִיעָאָה דְּכֹלָּא. וְאִיהוּ מֻצָּב אַרְצָּה, תְּרֵין. וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמַיְמָה, תְּלַת. וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עוֹלִים, תְּרֵי. וְיוֹרְדִים תְּרֵי. אִינּוּן לָקֳבֵל ד' רוּחוֹת וְהַשָּׁמַיִם וְהָאָרֶץ. וְרָזָא, דְּמִלָּה (קהלת א׳:ב׳) הֲבֵל הֲבָלִים אָמַר קֹהֶלֶת הֲבֵל הֲבָלִים הַכֹּל הָבֶל. אִינּוּן שִׁבְעָה, לָקֳבֵל כּוּרְסְיָיא, דְּאִיהוּ הַסֻּלָּם, וְהַשָּׁמַיִם וְהָאָרֶץ, וְד' יְסוֹדִין דְּעָלְמָא, וְאִינּוּן שִׁבְעָה. לָקֳבֵל שִׁבְעָה יוֹמֵי בְּרֵאשִׁית. אִית כָּל בִּרְיָין דִּשְׁמַיָּא, וְיַמָּא, וְאַרְעָא. כְּגוֹן חַיוֹת עוֹפוֹת בְּהֵמוֹת דָּגִים, וְכַמָּה תּוֹלָדִין דְּתַּלְיָין מִינֵּיהּ.","וּבְגִין דְּכֹלָּא אִתְבְּרֵי בְּהַאי צּוּלְמָא, דְּעַל כָּל יִשְׂרָאֵל דְּאִיהִי צַּדִּיק, אִתְּמַר בְּהוֹן (בראשית ט׳:ב׳) וּמוֹרַאֲכֶם וְחִתְּכֶם יִהְיְה עַל כָּל חַיַּת הָאָרֶץ וְעַל כָּל עוֹף הַשָּׁמָיִם וְגוֹ'. וְדָא מְמַלֵּל עַל בְּנֵי נָשָׁא, דְּאִינּוּן מְתִילִין לְחֵיוָן בָּרָא, וְלִבְעִירָן, וּלְעוֹפִין, וּלְנוּנֵי יַמָּא. דְּאִית בַּר נָשׁ דְּמַזָּלֵיהּ שׁוֹר, וּמַזָּלֵיהּ אַרְיִה, וּמַזָּלֵיהּ נֶשֶׁר, וּמַזָּלֵיהּ אָדָם.","וְכָל אִלֵּין, לָמָּה מִתְפַּחֲדִין מֵהַאי דִּיּוּקְנָא דְּאִינּוּן מִתַּמָּן אִתְבְּרִיאוּ. אֶלָּא מִשּׁוּם דְּשֵׁם יְדוָֹ\"ד שַׁרְיָא עָלֵיהּ. רָזָא דְּמִלָּה, (דברים כ״ח:י׳) וְרָאוּ כָּל עַמֵּי הָאָרֶץ וְגוֹ'. וְכָל מַאן דְּפָגִים עוֹבָדוֹי, אִתְפְּגִים דִּיּוּקְנֵיהּ. וְשֵׁם יְיָ לָא שַׁרְיָא בַּאֲתָר פָּגִים, וּבְהַהוּא פְּגִימוּ שַׁרְיָא חֹשֶׁךְ, בְּגִין פְּגִימוּ דְּסִיהֲרָא דְּשַׁרְיָא בֵּיהּ חַשׁוֹכָא. וְהַאי בַּר נָשׁ כְּמָה דְּאִיהוּ פָּגִים דִּיּוּקְנֵיהּ, כַּךְ אִתְפְּגִים אִיהוּ לְתַתָּא, אוֹ אִתְעָבִיד אִלֵּם, אוֹ חֵרֵשׁ, אוֹ סוּמָא, אוֹ חִגֵּר. בְּגִין דִּיְּהֵא רָשִׁים לְעֵילָּא וְתַתָּא.","וְהַהוּא חֹשֶׁךְ שַׁרְיָא בִּפְגִּימוּ דִּילֵיהּ, וּמִיַּד אִשְׁתְּמוֹדְעָאן בֵּיהּ דַּרְגִּין קַדִּישִׁין, דְּאִינּוּן חֵילוֹי דְקוּדְשָׁא בְּרִיךְ הוּא, וּמִתְרַחֲקִין מִנֵּיהּ, דִּכְבַר יַדְעִין דִּבְהַהוּא פְּגִימוּ לָא שַׁרְיָא מַלְכָּא. וּבְגִין דָּא חֵילוֹי דְּמַלְכָּא מִתְרַחֲקִין מִנֵּיהּ, דְּחַיָּילִין דְּמַלְכָּא לָא שַׁרְיָין, וְלָא מִתְקָרְבָן, אֶלָּא בְּאֲתָר דְּמַלְכָּא שַׁרְיָא, דְּכַךְ אִינּוּן מִתְנַהֲגִין אֲבַּתְרֵיהּ, כְּאֵבָרִין בָּתַר גּוּפָא.","וּבְהַהוּא אֲתָר דְּשָׁרֵי הַהוּא חֹשֶׁךְ, כַּמָה מַלְאֲכֵי חַבָּלָה, דְּאִתְקְרִיאוּ נְחָשִׁים וְעַקְרַבִּים, מִתְקָרְבִין לֵיהּ, וְיָהֲבִין לֵיהּ כַּמָה נְשִׁיכִין, וְאִלֵּין אִינּוּן יִסּוּרִין. וְאִי אִית לֵיהּ מָמוֹנָא דְּעוֹבָדִין טָבִין דְּעָבִיד, אִתְמַעֲטוּן מִנֵּיהּ. וְאֵיךְ אִתְמַעֲטוּן מִנֵּיהּ, אֶלָּא כָּל זְכוּת דְּנָחִית לֵיהּ מִלְעֵילָּא, יָהִיב לֵיהּ לְאִלֵּין מַלְאֲכֵי חַבָּלָה, וּבַטְלִין מִנֵּיהּ יִסוּרִין. וְאִי לֵיהּ לֵיהּ זְכוּ, וְלָא חוֹבָא לְעֵילָּא, אֶלָּא כֹּלָּא לְתַתָּא, בְּכָל זְכוּ דְּעָבִיד נָחִית לֵיהּ מָמוֹנִין, וְאוּמִין דְּעָלְמָא מִתְקָרְבִין לֵיהּ, לָקֳבֵל מַלְאֲכֵי חַבָּלָה, וְיָהִיב לוֹן מָמוֹנָא, וְאִשְׁתְּזִיב מִנַּיְיהוּ.","וּבְגִין דָּא הֲווֹ יִשְׂרָאֵל מְקָרְבִין לַעֲזָאזִל, לְגַבֵּי הַהוּא חֹשֶׁךְ. וְשִׁבְעִים פָּרִים, לָקֳבֵל שִׁבְעִים אוּמִין, לְקַיְּימָא קְרָא, (משלי כ״ה:כ״א) אִם רָעֵב שׂוֹנַאֲךָ הַאֲכִילֵהוּ לָחֶם וְאִם צָּמֵא הַשְׁקֵהוּ מָיִם. וּמִיַּד דְּהַדְרִין בְּתִיּוּבְתָּא, אִתְעַבָּר הַהוּא חֹשֶׁךְ מֵהַהוּא פְּגִימוּ, וְיִשְׁתְּלִים. וְרָזָא דְּמִלָּה, (שמואל ב י״ב:י״ג) גַּם יְיָ הֶעֱבִיר חַטָאתְךָ לֹא תָמוּת. וּמִיַּד אִתְהַדָּר בֵּיהּ שְׁמָא דַּיְיָ, וְאִתְּרָעֵי (נ\"א ויתרפי) בֵּיהּ, מֵאִנּוּן נְשִׁיכִין דְּיִסוּרִין, הֲדָא הוּא דִּכְתִּיב, (ישעיהו ו׳:י׳) וְשָׁב וְרָפָא לוֹ. וּמִנַּיִן דְּאִתְהַדָּר קוּדְשָׁא בְּרִיךְ הוּא מִיַּד דְּהָדַר בְּתִיּוּבְתָּא וְאִשְׁתְּלִים הַהוּא פְּגִימוּ. הֲדָא הוּא דִּכְתִּיב, (מלאכי ג׳:ז׳) שׁוּבוּ אֵלַי וְאָשׁוּבָה אֲלֵיכֶם."],[[0,"ולעולם לא שריא","וכו׳: ולעולם אינה שורה באדם לא \u0003ה׳\u0004 ולא \u0003ו׳,\u0004 בלי יראה ובלי אהבה, שהם י״ה, יראה ואהבה אנו קוראים אותם ודאי, ומשם ניתנה התורה והמצוה, שהם בן ובת, דהיינו ו״ה, ז״א ומלכות. (כנ״ל אות ל״ז) ומשום שישראל מקיימים התורה והמצוה, הם נקראים בנים להקב״ה ז״ש בנים אתם לה׳ אלקיכם."],[1,"הנסתרות יראה ואהבה","וכו׳: הנסתרות לה׳ אלקינו, הם יראה ואהבה, שהם במוח ולב. הנמצאים בחלל הגוף ובפנימיות הראש. שהם סוד י״ה כנ״ל. \u0003והנגלות\u0004 לנו ולבנינו, היינו התורה והמצוה שהם בחיצוניות הגוף והראש, שה״ס ו״ה. וסוד הדבר כך הוא ודאי, כי אם אדם מתירא מהקב״ה או אוהב אותו, זאת אין אדם אחר יודע, משום שהוא דבר שאינו מתגלה אלא בינו ובין קונו."],[2,"אבל ב״נ דמתעסק","וכו׳: אבל אדם העוסק בתורה והולך במצות עשה, זה מתגלה לכל אדם, משום שהקב״ה עשה לו פה בגלוי לעסוק בתורה, ועינים להסתכל בה, ואזנים לשמוע בה. ועשה הקב״ה באדם, ידים ורגלים וגוף, לעשות בהם מצות עשה."],[3,"א״כ חוטמא למאי","וכו׳: שואל, א״כ החוטם של האדם למה עשאו הקב״ה. ומשיב, ויפח באפיו נשמת חיים, זו היא צורה שעל האדם, שנאמר בו, ויחלום והנה סולם, \u0003סולם,\u0004 ודאי הוא נשמת חיים, שהיא מלכות, שהוא כסא לשם הויה, שהוא יראה ואהבה ותורה ומצוה, שיראה ואהבה הם \u0003י״ה,\u0004 ותורה ומצוה הם \u0003ו״ה,\u0004 כנ״ל. ובה, בנשמת חיים, שורה השם הויה. וזה הכסא, שהוא הסולם, ממנו נחתכות כל נשמות ישראל, והוא צורה על ראשו של האדם."],[4,"והנה מלאכי","וגו׳: והנה מלאכי אלקים עולים ויורדים בו, אלו הם ההבלים העולים ויוצאים בגוף, בסולם הזה. הוא, הסולם, אחד, השביעי מכולם. והוא מוצב ארצה, הוא עוד אחד, והם שנים. וראשו מגיע השמימה, הוא עוד א׳, והם שלשה. והנה מלאכי אלקים עולים, הם עוד שנים והם חמשה. ויורדים, הם עוד שנים והם שבעה. והם כנגד ד׳ רוחות העולם והשמים והארץ, שמאירים בסולם ההוא. וסוד הדבר, הבל הבלים אמר קהלת הבל הבלים הכל הבל. שהם שבעה הבלים כנגד הכסא, כי הבל הבלים הם ג׳. ופעם ב׳ הבל הבלים הם ששה, ועם הבל האחרון הם שבעה. שהם הסולם והשמים והים והארץ וד׳ יסודות העולם. שהם שבעה. וכנגד שבעת ימי בראשית, שהם חג״ת נהי״מ. וכנגדם יש כל בריות השמים והארץ, דהיינו חיות ועופות בהמות דגים וכמה תולדות התלויות מהם."],[5,"ובגין דכלא אתברי","וכו׳: ומשום שהכל נברא בצלם ההוא שעל כל ישראל, שהוא צדיק, דהיינו יסוד, נאמר בהם, ומוראכם וחתכם יהיה על כל חית הארץ ועל כל עוף השמים וגו׳. וכתוב הזה, מדבר על בני אדם שהם משולים לחיות השדה ולבהמות ולעופות ולדגת הים. שיש אדם שמזלו שור, ויש שמזלו אריה, ויש שמזלו נשר, ויש שמזלו אדם."],[6,"וכל אלין למה","וכו׳: וכל אלו למה מפחדים מצורה זו, שעל האדם, שהם נבראו משם. אלא הוא משום ששם הויה שורה עליו. וסוד הדבר, וראו כל עמי הארץ כי שם הויה נקרא עליך ויראו ממך. וכל מי שפוגם מעשיו נפגמת צורתו, ושם הויה איני שורה במקום פגום. שבפגם ההוא שורה חשך, משום שבפגם הלבנה שהיא המלכות, שורה החשך, והאדם הזה כמו שפגם צורתו, כך הוא נפגם למטה, או שנעשה אלם או חרש או עור או פסח, כדי שיהיה רשום למעלה ולמטה."],[7,"וההוא חשך שריא","וכו׳: והחשך ההוא שורה בפגם שלו, ומיד מכירים אותו המדרגות הקדושות, שהן צבאות הקב״ה, ומתרחקים ממנו, שכבר יודעים שבפגם ההוא אין המלך שורה. ומשום זה צבאות המלך מתרחקים ממנו, שחיילות המלך אינם שורים ואינם מתקרבים אלא למקום שהמלך שורה. שכך הם מונהגים אחריו כאברים אחר הגוף."],[8,"ובההוא אתר דשרי","וכו׳: ובמקום ההוא ששורה החשך ההוא, כמה מלאכי חבלה, הנקראים נחשים ועקרבים, מתקרבים אליו, ונותנים לו כמה נשיכות ואלו הם יסורים. ואם יש לו כסף, דהיינו רכוש ממעשים טובים שעשה, כלומר, אם הרכוש שלו הוא מעשים טובים הם מתמעטים ממנו. ואיך הם מתמעטים ממנו. הוא, שכל זכות דהיינו כל הארה, היורדת אליו מלמעלה בעד המעשים הטובים, נותנים אותו לאלו מלאכי חבלה, ובעד זה מבטלים ממנו היסורים. ואם אין לו לא זכות ולא חוב למעלה, אלא כל רכוש שלו הוא למטה, ובכל זכות שעושה יורד לו כסף גשמי. אז אומות העולם מתקרבים אליו, במקום מלאכי חבלה, ונותן להם כספו, וניצל מהם."],[9,"ובג״ד הוו ישראל","וכו׳: ומשום זה, היו ישראל מקריבים לעזאזל, אל אותו החשך. וע׳ פרים כנגד ע׳ אומות, שהקריבו בסוכות, לקיים הכתוב, אם רעב שונאך האכילהו לחם ואם צמא השקהו מים. ומיד שחוזרים בתשובה נעבר אותו חשך מפגם ההוא ונשלמים. וסוד הדבר, גם ה׳ העביר חטאתך לא תמות. ומיד חוזר עליו שם הויה, וירפא אותו מאלו הנשיכות של היסורים. ז״ש, ושב ורפא לו. ומאין לנו שהקב״ה חוזר אליו מיד אחר שחזר בתשובה, ונשלם אותו הפגם. זהו שכתוב, שובו אלי ואשובה אליכם."]],[[0,"","וּלְעוֹלָם לֹא שׁוֹרָה ה' בְּאִישׁ, וְלֹא ו', לְלֹא יִרְאָה וּלְלֹא אַהֲבָה, שֶׁהֵם יָ\"הּ, יִרְאָה וְאַהֲבָה נִקְרָאִים בְּוַדַּאי. וּמִשָּׁם נִתְּנוּ הַתּוֹרָה וְהַמִּצְוָה, שֶׁהֵם בֵּן וּבַת. וּמִשּׁוּם שֶׁיִּשְׂרָאֵל מְקַיְּמִים הַתּוֹרָה וְהַמִּצְוָה, נִקְרְאוּ בָּנִים לַקָּדוֹשׁ-בָּרוּךְ-הוּא. זֶהוּ שֶׁכָּתוּב (דברים יב) בָּנִים אַתֶּם לַה' אֱלֹהֵיכֶם."],[1,"","הַנִּסְתָּרֹת (דברים כט) - יִרְאָה וְאַהֲבָה, שֶׁהֵם בַּמֹּחַ וּבַלֵּב, בַּחֲלַל הַגּוּף וּבָרֹאשׁ. וְהַנִּגְלֹת - הַתּוֹרָה וְהַמִּצְוָה, שֶׁהֵם בַּגּוּף וּבָרֹאשׁ מִבַּחוּץ. וְסוֹד הַדָּבָר כָּךְ הוּא וַדַּאי, שֶׁאִם הָאָדָם פּוֹחֵד מֵהַקָּדוֹשׁ בָּרוּךְ הוּא אוֹ אוֹהֵב אוֹתוֹ - אֶת זֶה לֹא יוֹדֵעַ אָדָם אַחֵר, מִשּׁוּם שֶׁזֶּהוּ דָּבָר שֶׁלֹּא הִתְגַּלָּה אֶלָּא בֵּינוֹ לְבֵין קוֹנוֹ."],[2,"","אֲבָל אָדָם שֶׁמִּתְעַסֵּק בַּתּוֹרָה וּמִתְעַסֵּק בְּמִצְות עֲשֵׂה - זֶה גָּלוּי לְכָל אָדָם, כִּי הַקָּדוֹשׁ בָּרוּךְ הוּא עָשָׂה לוֹ פֶּה בְּגִלּוּי לְהִתְעַסֵּק בַּתּוֹרָה, וְעֵינַיִם לְהִסְתַּכֵּל בָּהּ, וְאָזְנַיִם לִשְׁמֹעַ אוֹתָהּ, וְעָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא יָדַיִם וְרַגְלַיִם וְגוּף לַעֲשׂוֹת בָּהּ מִצְווֹת עֲשֵׂה."],[3,"","אִם כָּךְ, חֹטֶם לָמָּה צָרִיךְ? (בראשית ב) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים, זוֹהִי דְּמוּת שֶׁעַל הָאָדָם, שֶׁנֶּאֱמַר בָּהּ (שם כח) וַיַּחֲלֹם וְהִנֵּה סֻלָּם. סֻלָּם וַדַּאי הִיא נִשְׁמַת חַיִּים, כִּסֵּא לְשֵׁם יְהֹוָ\"ה, שֶׁהוּא הַיִּרְאָה וְהָאַהֲבָה, הַתּוֹרָה וְהַמִּצְוָה, וּבוֹ שׁוֹרֶה. וְכִסֵּא זֶה, מִמֶּנּוּ גְּזוּרוֹת כָּל נִשְׁמוֹת יִשְׂרָאֵל, וְהִיא דְּמוּת עַל רֹאשׁ הָאָדָם."],[4,"","וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ - אֵלּוּ הֲבָלִים שֶׁעוֹלִים וְיוֹצְאִים בַּגּוּף בְּסֻלָּם זֶה. הוּא אֶחָד, שְׁבִיעִי שֶׁל הַכֹּל. וְהוּא מֻצָּב אַרְצָה - שְׁנַיִם. וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמַיְמָה - שְׁלֹשָׁה. וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים - שְׁנַיִם. וְיֹרְדִים - שְׁנַיִם. אֵלֶּה כְּנֶגֶד אַרְבַּע רוּחוֹת וְהַשָּׁמַיִם וְהָאָרֶץ. וְסוֹד הַדָּבָר - (קהלתא) הֲבֵל הֲבָלִים אָמַר קֹהֶלֶת הֲבֵל הֲבָלִים הַכֹּל הָבֶל. הֵם שִׁבְעָה כְּנֶגֶד הַכִּסֵּא, שֶׁהוּא הַסֻּלָּם, וְהַשָּׁמַיִם וְהָאָרֶץ, וְאַרְבָּעָה יְסוֹדוֹת הָעוֹלָם, וְהֵם שִׁבְעָה כְּנֶגֶד שִׁבְעַת יְמֵי בְרֵאשִׁית. יֵשׁ כָּל בְּרִיּוֹת הַשָּׁמַיִם וְהַיָּם וְהָאָרֶץ, כְּמוֹ חַיּוֹת, עוֹפוֹת, בְּהֵמוֹת וְדָגִים, וְכַמָּה תוֹלָדוֹת שֶׁתְּלוּיוֹת מִמֶּנּוּ."],[5,"","וּמִשּׁוּם שֶׁהַכֹּל נִבְרָא בַּצֶּלֶם הַזֶּה שֶׁעַל כָּל יִשְׂרָאֵל, שֶׁהוּא צַדִּיק, נֶאֱמַר בָּהֶם (בראשית ט) וּמוֹרַאֲכֶם וְחִתְּכֶם יִהְיֶה עַל כָּל חַיַּת הָאָרֶץ וְעַל כָּל עוֹף הַשָּׁמָיִם וְגוֹ'. וְזֶה מְדַבֵּר עַל בְּנֵי אָדָם שֶׁמְּשׁוּלִים לְחַיּוֹת הַשָּׂדֶה, לִבְהֵמוֹת וּלְעוֹפוֹת וְלִדְגֵי הַיָּם. שֶׁיֵּשׁ אָדָם שֶׁמַּזָּלוֹ שׁוֹר, וּמַזָּלוֹ אַרְיֵה, וּמַזָּלוֹ נֶשֶׁר, וּמַזָּלוֹ אָדָם."],[6,"","וְכָל אֵלֶּה לָמָּה מִתְפַּחֲדִים מִדְּמוּת זוֹ שֶׁהֵם נִבְרְאוּ מִשָּׁם? אֶלָּא מִשּׁוּם שֶׁשֵּׁם ה' שׁוֹרֶה עָלָיו. סוֹד הַדָּבָר - (דברים כח) וְרָאוּ כָּל עַמֵּי הָאָרֶץ וְגוֹ'. וְכָל מִי שֶׁפּוֹגֵם מַעֲשָׂיו, נִפְגֶּמֶת דְּמוּתוֹ, וְשֵׁם ה' לֹא שׁוֹרֶה בְּמָקוֹם פָּגוּם. וּבְאוֹתוֹ פְגָם שׁוֹרֶה חֹשֶׁךְ, בִּגְלַל פְּגִימַת הַלְּבָנָה שֶׁהַחֹשֶׁךְ שׁוֹרֶה בָּהּ. וְאָדָם זֶה, כְּמוֹ שֶׁהוּא פָּגַם דְּמוּתוֹ - כָּךְ נִפְגָּם הוּא לְמַטָּה, אוֹ שֶׁנַּעֲשֶׂה אִלֵּם, אוֹ חֵרֵשׁ, אוֹ סוּמָא, אוֹ חִגֵּר, בִּשְׁבִיל שֶׁיִּהְיֶה רָשׁוּם לְמַעְלָה וּלְמַטָּה."],[7,"","וְאוֹתוֹ חֹשֶׁךְ שׁוֹרֶה בַּפְּגָם שֶׁלּוֹ, וּמִיָּד יוֹדְעִים בּוֹ דְּרָגוֹת הַקְּדוֹשׁוֹת, שֶׁהֵם כֹּחוֹת הַקָּדוֹשׁ בָּרוּךְ הוּא, וּמִתְרַחֲקִים מִמֶּנּוּ, שֶׁכְּבָר יוֹדְעִים שֶׁבְּאוֹתוֹ פְּגָם לֹא שׁוֹרֶה הַמֶּלֶךְ. וּמִשּׁוּם זֶה חַיּוֹת הַמֶּלֶךְ מִתְרַחֲקוֹת מִמֶּנּוּ, שֶׁחֵילוֹת הַמֶּלֶךְ לֹא שׁוֹרִים וְלֹא מִתְקָרְבִים, אֶלָּא בְּמָקוֹם שֶׁהַמֶּלֶךְ שׁוֹרֶה. שֶׁכָּךְ הֵם מִתְנַהֲגִים אַחֲרָיו, כְּאֵיבָרִים אַחַר הַגּוּף."],[8,"","וּבְאוֹתוֹ מָקוֹם שֶׁשּׁוֹרֶה אוֹתוֹ חֹשֶׁךְ, כַּמָּה מַלְאֲכֵי חַבָּלָה, שֶׁנִּקְרָאִים נְחָשִׁים וְעַקְרַבִּים, מִתְקָרְבִים אֵלָיו, וְנוֹתְנִים לוֹ כַּמָּה נְשִׁיכוֹת, וְאֵלֶּה אוֹתָם יִסּוּרִים. וְאִם יֵשׁ לוֹ מָמוֹן שֶׁל מַעֲשִׂים טוֹבִים שֶׁעָשָׂה - יִתְמַעֲטוּ מִמֶּנּוּ. וְאֵיךְ יִתְמַעֲטוּ מִמֶּנּוּ? אֶלָּא כָּל זְכוּת שֶׁיּוֹרֶדֶת לוֹ מִלְמַעְלָה, נוֹתְנִים אוֹתָהּ לְאוֹתָם מַלְאֲכֵי חַבָּלָה, וּמְבַטְּלִים מִמֶּנּוּ יִסּוּרִים. וְאִם אֵין לוֹ זְכוּת וְלֹא חוֹבָה לְמַעְלָה, אֶלָּא הַכֹּל לְמַטָּה - בְּכָל זְכוּת שֶׁעוֹשֶׂה, יוֹרֵד לוֹ מָמוֹנוֹת, וְאֻמּוֹת הָעוֹלָם מִתְקָרְבִים אֵלָיו כְּנֶגֶד מַלְאֲכֵי הַחַבָּלָה, וְנוֹתֵן לָהֶם מָמוֹן וְנִצָּל מֵהֶם."],[9,"","וּמִשּׁוּם זֶה הָיוּ יִשְׂרָאֵל מַקְרִיבִים לַעֲזָאזֵל אֵצֶל אוֹתוֹ הַחֹשֶׁךְ. וְשִׁבְעִים פָּרִים כְּנֶגֶד שִׁבְעִים אֻמּוֹת, לְקַיֵּם הַפָּסוּק (משלי כה) אִם רָעֵב שּנַאֲךְ הַאֲכִילֵהוּ לָחֶם וְאִם צָמֵא הַשְׁקֵהוּ מָיִם. וּמִיָּד שֶׁחוֹזְרִים בִּתְשׁוּבָה, עוֹבֵר אוֹתוֹ חֹשֶׁךְ מֵאוֹתוֹ פְגָם וְנִשְׁלָם. וְסוֹד הַדָּבָר - (שמואל ב יב) גַּם ה' הֶעֱבִיר חַטָּאתְךְ לֹא תָמוּת. וּמִיָּד חוֹזֵר בּוֹ שֵׁם ה' וּמִתְרַצֶּה (ומתרפא) בּוֹ מֵאוֹתָן נְשִׁיכוֹת שֶׁל הַיִּסּוּרִים, זֶהוּ שֶׁכָּתוּב (ישעיה ו) וְשָׁב וְרָפָא לוֹ. וּמִנַּיִן שֶׁחוֹזֵר הַקָּדוֹשׁ בָּרוּךְ הוּא מִיָּד כְּשֶׁחָזַר בִּתְשׁוּבָה וְנִשְׁלָם אוֹתוֹ הַפְּגָם? זֶהוּ שֶׁכָּתוּב (מלאכי ג) שׁוּבוּ אֵלַי וְאָשׁוּבָה אֲלֵיכֶם."]]],[["וְדָא אִיהוּ בִּתְשׁוּבָה גְּמוּרָה, דְּגָרִים לְאָהַדְּרָא בִּינָה דְּאִיהוּ יד\"ו, לְגַבֵּי ה' דְּאִיהִי מַלְכוּת. דְּאַזְלָא מְנַדְּדָא מִן קִנָהָא, דְּאִיהִי הַהִיא דִּיּוּקְנָא, דְּמִתְקַטְרִין בָּהּ כָּל פִּקוּדִין. וּבָהּ מִתְקַטְרִין עֶשֶׂר סְפִירָן. כַּד בַּר נָשׁ עָבֵד פִּקּוּדָא חֲדָא וְלָא יַתִּיר, וְעָבִיד לָהּ בִּדְחִילוּ וּרְחִימוּ דְקוּדְשָׁא בְּרִיךְ הוּא. בְּגִינָהּ שַׁרְיָין עָלֵיהּ י' סְפִירָן. וְכָל מַאן דְּקִיֵּים פִּקּוּדָא חַד כַּדְקָא יָאוּת, כְּאִלּוּ מְקַיֵּים רמ\"ח פִּקּוּדִין דַּעֲשֵׂה, דְּלֵית פִּקּוּדָא דְּלָאו אִיהוּ כְּלִילָא מִכֻּלְּהוּ רמ\"ח. (ע\"כ רעיא מהימנא).","(במדבר ה׳:י״ב) אִישׁ אִישׁ כִּי תִשְׂטֶה אִשְׁתּוֹ וְגוֹ'. מַאי הַאי לְגַבֵּי הַאי. אֶלָּא כְּמָה דִּכְתִּיב, (במדבר ה׳:י״ב) לִמְעוֹל מַעַל בַּיְיָ. רִבִּי אֶלְעָזָר אָמַר, אִישׁ אִישׁ, מַאי אִישׁ אִישׁ, דְּהָא בְּחַד סַגֵּי, אֶלָּא הָא אוֹקְמוּהָ, אֲבָל אִישׁ אִישׁ, מַשְׁמַע אִישׁ דְּאִיהוּ אִישׁ, וְקִיֵּים קְרָא דִּכְתִּיב, (משלי ה׳:ט״ו) שְׁתֵה מַיִם מִבּוֹרֶךָ וְגוֹ'. כְּדֵין הוּא אִישׁ בְּעָלְמָא, אִישׁ לְגַבֵּי אִתְּתֵיהּ. וּמָעֲלָה בוֹ מָעַל, הָא בְּחַד סַגֵּי, אֲמַאי תְּרֵי. אֶלָּא חַד לְעֵילָּא וְחַד לְתַתָּא. חַד לִכְּנֶסֶת יִשְׂרָאֵל, וְחַד לְבַעְלָהּ. בְּגִין כַּךְ וְהֵבִיא הָאִישׁ אֶת אִשְׁתּוֹ.","אֲמַאי אֶל הַכֹּהֵן. רָזָא דְּמִלָּה, בְּגִין דְּכַהֲנָא שׁוּשְׁבִינָא אִיהוּ דְּמַטְרוֹנִיתָא. הָכָא אִית לְאִסְתַּכְּלָא, הָא כְּתִיב (ויקרא א׳:ה׳) וְשָׁחַט אֶת בֶּן הַבָּקָר, וְשָׁחַט אַחֲרָא, וְלָאו כַּהֲנָא, דְּכַהֲנָא אָסִיר לֵיהּ בְּדִינָא, בְּגִין דְּלָא יַפְגִּים הַהוּא אֲתָר דְּאָחִיד בֵּיהּ, וְאַתְּ אַמְרַת, וְהֵבִיא הָאִישׁ אֶת אִשְׁתּוֹ אֶל הַכֹּהֵן, לְמֵידָן דִּינָהָא. אֶלָּא וַדַּאי כַּהֲנָא לְדָא חֲזֵי, בְּגִין דְּאִיהוּ שׁוּשְׁבִינָא לְמַטְרוֹנִיתָא, וְכָל נְשֵׁי עָלְמָא מִתְבָּרְכָן (נ\"א אתאחדת) בִּכְּנֶסֶת יִשְׂרָאֵל, וְעַל דָּא אִתְּתָא דִּלְתַּתָּא מִתְבָּרְכָא בְּשֶׁבַע בְּרָכוֹת, דַּאֲחִידַת בָּהּ בִּכְנֶסֶת יִשְׂרָאֵל, וְכַהֲנָא קָאִים לְאַתְקְנָא מִלֵּי דְּמַטְרוֹנִיתָא, וּלְעַיְּינָא בְּכָל מַה דְּאִצְטְרִיךְ, בְּגִין כַּךְ כַּהֲנָא לְדָא, וְלָא אַחֲרָא.","וְאִי תֵּימָא דְּאִיהוּ עָבִיד דִּינָא, לָאו הָכִי, אֶלָּא לְאַסְגָּאָה שְׁלָמָא בְּעָלְמָא קָא אִשְׁתָּדַּל בְּהַאי, וּלְאַסְגָּאָה חֶסֶד. דְּאִי הַהִיא אִתְּתָא אִשְׁתְּכַחַת זַכָּאָה, כַּהֲנָא אַסְגֵּי שְׁלָמָא בְּהוּ, וְלֹא עוֹד אֶלָּא דְּמִתְעַבְּרָא בִּבְרָא דְּכַר, וְאִתְעָבִיד שְׁלָמָא עַל יְדֵיהּ. וְאִי לָא אִשְׁתְּכַחַת זַכָּאָה, אִיהוּ לָא עָבִיד דִּינָא, אֶלָּא הַהוּא שְׁמָא קַדִּישָׁא דְּאִיהִי קָא מְשַׁקְּרַת בֵּיהּ, הוּא עָבִיד דִּינָא, וְהוּא בָּדִיק לָהּ.","תָּא חֲזֵי, כַּהֲנָא לָא עָיֵיל גַּרְמֵיהּ לְהַאי, אֶלָּא כַּד הִיא יָהֲבַת גַּרְמָהּ קַמֵּיהּ, מִפְּאָה (נ\"א לזכאה) זִמְנָא, וּתְרֵין שָׁאִיל לָהּ, כֵּיוָן דְּאִיהִי בַּעְיָא לְאִשְׁתַּכְּחָא זַכָּאָה, כְּדֵין כַּהֲנָא עָבִיד עוֹבָדָא, בְּגִין לְאַסְגָּאָה שְׁלָמָא."],[[0,"ודא איהו בתשובה","וכו׳: וכל זה הוא בתשובה גמורה שגורם להחזיר הבינה, שהוא יה״ו אל הה׳ שהיא המלכות, שהלכה נודדת מן קנה, שהיא אותה הצורה שעל ראש האדם, שמתקשרות בה כל המצות (כנ״ל אות נ״ב) ובה מתקשרות עשר ספירות. כשאדם עושה מצוה אחת ולא יותר, אלא שעושה אותה ביראה ואהבה להקב״ה, שורות עליו בשבילה עשר ספירות. וכל מי שמקיים מצוה אחת כראוי, הוא כאלו מקיים רמ״ח מצות עשה. כי אין מצוה שאינה כלולה מכל רמ״ח מצות עשה. (ע״כ רעיא מהימנא)."],[1,"איש איש כי תשטה אשתו","וגו׳: שואל, מה זה אצל זה. כלומר למה נסמכה פרשת סוטה לפרשת מעילה. ומשיב, אלא כמו שכתוב, שם למעול מעל בה׳ כתוב גם כאן בסוטה, ומעלה בו מעל. והם ענין אחד, וע״כ נסמכו זה לזה. ר׳ אלעזר אמר, \u0003איש איש,\u0004 מהו איש איש ב׳ פעמים, הרי באחת היה די. ומשיב, אלא כבר העמידוהו, אבל איש איש פירושו, איש שהוא איש, דהיינו שקיים הכתוב, שתה מים מבורך, ולא נתן עיניו באשה אחרת, אז הוא איש בעולם, איש אל אשתו. \u0003ומעלה בו מעל,\u0004 שואל, הרי במעל אחד היה די למה ב״פ מעל. ומשיב, אלא מעל אחד למעלה ואחד למטה, דהיינו אחד לכנסת ישראל, שהיא מלכות, ואחד לבעלה, שהוא ז״א משום זה והביא האיש את אשתו אל הכהן."],[2,"אמאי אל הכהן","וכו׳: שואל, למה יביא אשתו אל הכהן. ולא לשופט. ומשיב, סוד הדבר הוא, משום שהכהן הוא שושבינה של המטרוניתא, דהיינו המתקן את המלכות לזווג עם ז״א. וע״כ שייך לו תקון הפגם של הסוטה המגיע עד המלכות. כנ״ל. כאן יש להסתכל, הרי כתוב ושחט את בן הבקר, אשר שחט פירושו, אחר ולא הכהן. משום שהכהן אסור לו לפעול בדין, כדי שלא יפגום אותו מקום שהכהן אחוז בו, דהיינו חסד. ואתה אומר, והביא איש את אשתו אל הכהן לדון הדין שלה. אלא ודאי רק הכהן ראוי לזה, משום שהוא שושבינה של המטרוניתא, וכל נשי העולם מתברכים מכנסת ישראל. וע״כ האשה שלמטה, מתברכת, בשעת נשואין, בשבע ברכות, משום שהיא אחוזה בכנסת ישראל, שיש בה ז׳ ספירות חג״ת נהי״מ. והכהן עומד לתקן דברי המטרוניתא, שהיא המלכות, ולעיין בכל מה שהיא צריכה. משום זה רק הכהן ראוי לזה ולא אחר."],[3,"ואי תימא דאיהו","וכו׳: ואם תאמר שהכהן עושה דין, שהוא סותר למדרגתו שהיא חסד. ומשיב, אינו כן, אלא כדי להרבות שלום בעולם הוא משתדל בזה, ולהגדיל החסד. כי אם האשה ההיא נמצאת נקיה, הכהן מרבה שלום בהם, באשה ובבעלה, ולא עוד אלא שמתעברת בבן זכר. ונעשה שלום על ידו. ואם אינה נמצאת נקיה, אין הכהן עושה דין, אלא שם הקדוש ההוא שהיא שקרה בו, הוא עושה דין, והוא בודק אותה."],[4,"תא חזי כהנא","וכו׳: בוא וראה, הכהן לא הכניס עצמו לזה, אלא כשהיא נותנת עצמה לפניו להשקותה, כדי שתזכה. פעם ושתים שואל אותה, וכיון שהיא רוצה להמצא נקיה, אז עושה הכהן מעשה, כדי להרבות השלום. בינה לבעלה."]],[[0,"","וְזוֹהִי תְּשׁוּבָה גְמוּרָה שֶׁגּוֹרֶמֶת לְהַחֲזִיר בִּינָה, שֶׁהִיא יה\"ו, לְגַבֵּי ה' שֶׁהִיא מַלְכוּת. שֶׁהוֹלֶכֶת וְנוֹדֶדֶת מִקִּנָּהּ, שֶׁהִיא אוֹתָהּ דְּמוּת שֶׁנִּקְשָׁרוֹת בָּהּ כָּל הַמִּצְווֹת, וּבָהּ נִקְשָׁרוֹת עֶשֶׂר סְפִירוֹת. כְּשֶׁאָדָם עוֹשֶׂה מִצְוָה אַחַת וְלֹא יוֹתֵר, וְעוֹשֶׂה אוֹתָהּ בְּיִרְאָה וְאַהֲבַת הַקָּדוֹשׁ בָּרוּךְ הוּא, בִּגְלָלָהּ שׁוֹרוֹת עָלָיו עֶשֶׂר סְפִירוֹת. וְכָל מִי שֶׁקִּיֵּם מִצְוָה אַחַת כָּרָאוּי, כְּאִלּוּ מְקַיֵּם רמ\"ח מִצְווֹת עֲשֵׂה, שֶׁאֵין מִצְוָה שֶׁאֵינָהּ כְּלוּלָה מִכָּל הָרמ\"ח."],[1,"","אִישׁ אִישׁ כִּי תִשְׂטֶה אִשְׁתּוֹ וְגוֹ'. מַה זֶּה לְגַבֵּי זֶה. אֶלָּא כְּמוֹ שֶׁכָּתוּב, לִמְעֹל מַעַל בַּה'. רַבִּי אֶלְעָזָר אָמַר, אִישׁ אִישׁ, מַה זֶּה אִישׁ אִישׁ, שֶׁהֲרֵי בְּאֶחָד מַסְפִּיק? אֶלָּא הֲרֵי פֵּרְשׁוּהָ, אֲבָל אִישׁ אִישׁ, מַשְׁמָע אִישׁ שֶׁהוּא אִישׁ, וְקִיֵּם פָּסוּק שֶׁכָּתוּב (משלי ה) שְׁתֵה מַיִם מִבּוֹרֶךְ וְגוֹ', אָז הוּא אִישׁ בָּעוֹלָם, אִישׁ לְגַבֵּי אִשְׁתּוֹ. וּמָעֲלָה בוֹ מָעַל, הֲרֵי בְּאֶחָד מַסְפִּיק, לָמָּה שְׁנַיִם? אֶלָּא אֶחָד לְמַעְלָה וְאֶחָד לְמַטָּה, אֶחָד לִכְנֶסֶת יִשְׂרָאֵל לְאֶחָד לְבַעְלָהּ. בִּגְלַל זֶה, וְהֵבִיא הָאִישׁ אֶת אִשְׁתּוֹ."],[2,"","לָמָּה אֶל הַכֹּהֵן? סוֹד הַדָּבָר - מִשּׁוּם שֶׁהַכֹּהֵן הוּא שׁוֹשְׁבִין הַמַּלְכָּה. כָּאן יֵשׁ לְהִסְתַּכֵּל, הֲרֵי כָּתוּב (ויקראא) וְשָׁחַט אֶת בֶּן הַבָּקָר, וְשָׁחַט אַחֵר וְלֹא הַכֹּהֵן, שֶׁהַכֹּהֵן אָסוּר לוֹ בְּדִין בִּשְׁבִיל שֶׁלֹּא יִפְגֹּם אוֹתוֹ מָקוֹם שֶׁהוּא אָחוּז בּוֹ, וְאַתָּה אָמַרְתָּ וְהֵבִיא הָאִישׁ אֶת אִשְׁתּוֹ אֶל הַכֹּהֵן, לָדוּן דִּינָהּ? אֶלָּא וַדַּאי כֹּהֵן לָזֶה רָאוּי, מִשּׁוּם שֶׁהוּא שׁוֹשְׁבִין הַמַּלְכָּה, וְכָל נְשׁוֹת הָעוֹלָם מִתְבָּרְכוֹת (נאחזת) בִּכְנֶסֶת יִשְׂרָאֵל, וְעַל זֶה הָאִשָּׁה שֶׁלְּמַטָּה מִתְבָּרֶכֶת בְּשֶׁבַע בְּרָכוֹת, שֶׁאֲחוּזָה בָּהּ בִּכְנֶסֶת יִשְׂרָאֵל, וְהַכֹּהֵן עוֹמֵד לְתַקֵּן דִּבְרֵי הַמַּלְכָּה וּלְעַיֵּן בְּכָל מַה שֶּׁצָּרִיךְ, וּמִשּׁוּם זֶה הַכֹּהֵן לָזֶה, וְלֹא אַחֵר."],[3,"","וְאִם תֹּאמַר שֶׁהוּא עוֹשֶׂה דִּין - לֹא כָּךְ, אֶלָּא כְּדֵי לְהַרְבּוֹת שָׁלוֹם בָּעוֹלָם הוּא מִשְׁתַּדֵּל בָּזֶה, וּלְהַגְדִּיל חֶסֶד. שֶׁאִם אוֹתָהּ אִשָּׁה תִּמָּצֵא צַדֶּקֶת וְזַכָּאִית, הַכֹּהֵן מַגְדִּיל שְׁלוֹמָם, וְלֹא עוֹד, אֶלָּא שֶׁמִּתְעַבֶּרֶת בְּבֵן זָכָר, וְנַעֲשֶׂה שָׁלוֹם עַל יָדוֹ. וְאִם לֹא תִמָּצֵא צַדֶּקֶת, הוּא לֹא עוֹשֶׂה דִּין, אֶלָּא אוֹתוֹ שֵׁם קָדוֹשׁ שֶׁהִיא מְשַׁקֶּרֶת בּוֹ, הוּא עוֹשֶׂה אֶת הַדִּין וְהוּא בּוֹדֵק אוֹתָהּ."],[4,"","בֹּא רְאֵה, הַכֹּהֵן לֹא מַכְנִיס אֶת עַצְמוֹ לָזֶה, רַק כְּשֶׁהִיא נוֹתֶנֶת אֶת עַצְמָהּ לְפָנָיו לְכַסּוֹת (להזדכות), פַּעַם וּפַעֲמַיִם שׁוֹאֵל אוֹתָהּ. כֵּיוָן שֶׁהִיא רוֹצָה לְהִמָּצֵא זַכָּאִית, אָז הַכֹּהֵן עוֹשֶׂה מַעֲשֶׂה כְּדֵי לְהַרְבּוֹת שָׁלוֹם."]]],[["כַּהֲנָא כְּתִיב שְׁמָא קַדִּישָׁא חַד זִמְנָא בְּאֹרַח מֵישָׁר, לְבָתַר כָּתַב לֵיהּ לְמַפְרֵעַ אַתְוָון (נ\"א סריטין) טְרִיסִין בִּטְהִירִין, דִּינָא בְּדִינָא, רַחֲמֵי בְּרַחֲמֵי, רַחֲמֵי בְּדִינָא, וְדִינָא בְּרַחֲמֵי. אִשְׁתְּכַחַת זַכָּאָה, אַתְוָון רַחֲמֵי אִשְׁתְּכָחוּ, וְדִינִין סַלְּקִין. לָא אִשְׁתְּכַחַת כַּדְּקָא יָאוּת, רַחֲמֵי סַלְּקִין, וְדִינִין אִשְׁתְּאָרוּ, וּכְדֵין דִּינָא אִתְעָבִיד.","רִבִּי אֶלְעָזָר פָּתַח וְאָמַר, (שמות ט״ו:כ״ג) וַיָבֹאוּ מָרָתָה וְלֹא יָכְלוּ לִשְׁתּוֹת מַיִם מִמָּרָה כִּי מָרִים הֵם, הָא אוּקְמוּהָ. אָמַר, תַּוַּוהְנָא אֵיךְ בְּנֵי עָלְמָא לָא מִסְתַּכְּלִין וְלָא מִשְׁתַּדְּלִין בְּמִלִּין דְּאוֹרַיְיתָא, הָכָא אִית לְאִסְתַּכְּלָא, אֲמַאי כְּתִיב הָכָא שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ.","אֲבָל וַדַּאי רָזָא דְּמִלָּה, דְּהָכָא עַל מַיָּיא הֲוָה, בְּגִין דְּמִצְרָאֵי הֲווֹ אָמְרֵי, דִּבְנַיְיהוּ דְּיִשְׂרָאֵל הֲווֹ מִנַּיְיהוּ, וַהֲווּ כַּמָה בְּיִשְׂרָאֵל דְּחַשְׁדִין לְאִנְתְּתַיְיהוּ בְּדָא. עַד דְקוּדְשָׁא בְּרִיךְ הוּא מָטָא לוֹן לְהַאי אֲתָר, וּבָעֵי לְמִבְדַּק לוֹן, מַה כְּתִיב וַיָבֹאוּ מָרָתָה וְגוֹ'. וְיִצְעַק אֶל יְיָ וְגוֹ'.","אָמַר קוּדְשָׁא בְּרִיךְ הוּא לְמֹשֶׁה, מֹשֶׁה מַה אַתְּ בָּעֵי, הָא כַּמָה חֲבִילִין קַיְימִין גַּבַּיְיכוּ הָכָא, וַאֲנָא בָּעֵינָא לְמִבְדַּק הָכָא נְשֵׁיהוֹן דְּיִשְׂרָאֵל, כְּתוֹב שְׁמָא קַדִּישָׁא, וּרְמֵי לְמַיָּיא, וְיִבָּדְקוּן כֻּלְּהוֹן, נְשֵׁי וְגוּבְרִין, וְלָא יִשְׁתְּאַר לַעַז עַל בָּנַי. וְעַד דְּיִבָּדְקוּן כֻּלְּהוּ הָכָא, לָא אַשְׁרֵי שְׁמִי עָלַיְיהוּ, מִיַּד וַיּוֹרֵהוּ יְיָ עֵץ וַיַּשְׁלֵךְ אֶל הַמַּיִם, דָּא שְׁמָא קַדִּישָׁא, הַהוּא דְּהֲוָה כּוֹתֵב כַּהֲנָא לְמִבְדַּק נְשֵׁיהוֹן דְּיִשְׂרָאֵל, כְּדֵין, שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ.","וְאִי תֵּימָא נְשֵׁיהוֹן דְּיִשְׂרָאֵל יָאוּת, אִינּוּן אֲמַאי. אֶלָּא אוּף אִינּוּן בַּעְיָין, דְּלָא אִסְתַּאֲבוּ בִּנְשֵׁיהוֹן דְּמִצְרָאֵי. וּנְשֵׁיהוֹן דְּיִשְׂרָאֵל לָא אִסְתַּאֲבוּ בְּמִצְרָאֵי, כָּל אִינּוּן שְׁנִין דַּהֲווֹ בֵּינַיְיהוּ, וְכֻלְּהוּ נָפְקוּ גּוּבְרִין וְנוּקְבִין זַכָּאִין, וְאִשְׁתְּכָחוּ זַרְעָא דְּיִשְׂרָאֵל קַדִּישִׁין, זַכָּאִין, כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא אַשְׁרֵי שְׁמֵיהּ בֵּינַיְיהוּ, וְעַל דָּא עַל מַיָּא וַדַּאי, שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ אוּף הָכָא, בְּמַיָּא בָּדִיק כַּהֲנָא לְאִתְּתָא, וּבִשְׁמָא קַדִּישָׁא."],[[0,"כהנא כתיב שמא","וכו׳: הכהן כותב את השם הקדוש, פעם אחת בדרך ישר, דהיינו י״ה ו״ה. ולאחר כך כותב אותו למפרע, דהיינו ה״ו ה״י. והאותיות, שנמחו לתוך המים, היו נשרטים באורות עליונים ד׳ בחינות, שהם, דין בדין, רחמים ברחמים, רחמים בדין דין ברחמים. אם נמצאת נקיה, האותיות של רחמים נמצאו ואותיות הדין עלו. ואם לא נמצאת כראוי, אותיות הרחמים עלו, ואותיות הדין נשארו. ואז נעשה הדין."],[0,"","ביאור הדברים. כבר נתבאר לעיל (אמור אות קנ״ג) ענין הסוטה. עש״ה. כי אשת חיל שה״ס המלכות הקדושה, מעולם לא סוטה תחת בעלה, שפירושו שאינה ממשכת החכמה ממעלה למטה הנבחן לדבקות באל אחר. אלא היא דבוקה בבעלה ז״א שה״ס קו האמצעי המתקן הארת החכמה שתאיר רק ממטה למעלה. והסוטה שסטתה מתחת בעלה, היא מתדבקת באשת זנונים, הדבוקה באל אחר, הממשיך החכמה ממעלה למטה."],[0,"","ונודע שהמלכות נקראת עץ הדעת טוב ורע, משום שיש בה ב׳ נקודות, נקודה דמדת הדין, שה״ס מלכות דצמצום א׳ שמחמתה אינה ראויה לקבל אור. ונקודה הממותקת במדת הרחמים, שעל ידיה מקבלת כל האורות. ואם האדם זוכה, נעשה תקון במלכות לגנוז הנקודה דמדת הדין, ורק נקודה הממותקת במדת הרחמים היא בגלוי. ואז היא טובה. שהאדם מקבל כל האורות על ידה. ואם האדם אינו זוכה אז מתגלה נקודה דמדת הדין שבמלכות ואז כל האורות מסתלקים. והרי רע. כמ״ש כל זה לעיל (הקדמת ספר הזהר אות קכ״ג, ויצא י״ג ד״ה סתרא) ולפיכך, כדי לברר אם הסוטה זנתה תחת בעלה נעשית בדיקה זו ע״י הכהן ע״ד הזה."],[0,"","וז״ש, \u0003כהנא כתיב שמא קדישא חד זמנא בארח מישר,\u0004 שהויה ביושר, י״ה ו״ה מורה על התפשטות הבינה שהיא מדת הרחמים. \u0003לבתר כתב ליה למפרע,\u0004 שהויה למפרע שהוא ה״ו ה״י, מורה על התפשטות מדת הדין שבמלכות, כי ההין שהם נוקבין שולטים על י״ו שהם דכורין, וה׳ תתאה שהיא מלכות שולטת על אותיות ו׳ ה׳ י׳, שכל אות העומדת בראשונה היא השולטת. ולפיכך הויה למפרע מורה על מלכות של מדת הדין. וכשמחה לתוך המים, נתערבו האותיות דרחמים, שהם מבינה, והאותיות דדין, שהם ממלכות דמדת הדין, אלו באלו, ונעשו מהם ד׳ בחינות א׳ \u0003דינא בדינא,\u0004 שהם מאותיות של בחינת המלכות בלבדה, \u0003ורחמי ברחמי,\u0004 שהם מבחינת הבינה בלבדה, \u0003ורחמי בדינא,\u0004 שהם מבינה המעורבת במלכות, \u0003ודינא ברחמי,\u0004 שהם ממלכות המעורבת בבינה. ואם \u0003אשתכחת זכאה,\u0004 דהיינו שלא זנתה תחת בעלה, הרי היא דבוקה באשת חיל, במלכות העליונה, ואז שורה עליה התקון שבה, דהיינו שנקודה דמדת הדין שהיא מנעולא, היא בגניזו, ונקודה דמדת הרחמים שולטת בה בגלוי. וע״כ, \u0003אתוון רחמי אשתכחו,\u0004 שהמה שולטים, \u0003ודינין סלקין,\u0004 דהיינו שמסתלקים ונגנזים. כתקון המלכות ואז כששותה המים האלו, היא מתברכת ממדת הרחמים ונקתה ונזרעה זרע, ואם \u0003לא אשתכחת כדקא יאות,\u0004 אלא שסטתה תחת בעלה, שאז היא דבוקה באשת זנונים, שהיא המלכות דקליפה, שבה אין שום תקון הגניזה. אז \u0003רחמי סלקין ודינין אשתארו,\u0004 שמחמת גילוי הדינים דמנעולא, מסתלקים כל האורות דבינה, והדינים נשארים, ואז כששותה את המים והיו בה מים המאררים למרים וצבתה בטנה ונפלה ירכה וגו׳."],[1,"ר׳ אלעזר פתח","וכו׳: רא״פ ואמר, ויבאו מרתה ולא יכלו לשתות מים ממרה כי מרים הם. הרי העמידוהו. אמר, תמה אני איך בני העולם אינם מסתכלים ואינם עוסקים בדברי תורה. הרי כאן יש להסתכל, למה כתוב כאן, שם שם לו חק ומשפט ושם נסהו."],[2,"אבל ודאי רזא","וכו׳: ומשיב, אבל ודאי סוד הדבר, שכאן היה הנס על המים. כי המצריים היו אומרים, שמהם הם בניהם של ישראל. והיו כמה אנשים בישראל שהיו חושדים נשיהם בזה. עד שהקב״ה הביאם למקום הזה, מרה, ורצה לבדוק אותם. מה כתוב, ויבאו מרתה וגו׳. ויצעק אל ה׳ וגו׳."],[3,"אמר קב״ה למשה","וכו׳: אמר הקב״ה למשה, משה, מה אתה רוצה, הרי כמה גדודים מקטרגים, עומדים עליכם כאן, ואני רוצה לבדוק כאן נשיהם של ישראל, כתוב שם הקדוש והשלך אל המים ויבדקו כל ישראל, נשים וגברים, ולא ישאר לעז על בני, וכל עוד שלא יבדקו כולם כאן, לא אשרה שמי עליהם. מיד, ויורהו ה׳ עץ וישלך אל המים. עץ הוא שם הקדוש ההוא שהיה כותב הכהן לבדוק נשיהם של ישראל. אז, שם שם לו חק ומשפט ושם נסהו."],[4,"ואי תימא נשיהון","וכו׳: ואם תאמר, נשיהם של ישראל שנבדקו יפה היא, שהוא מטעם החשד של המצריים, אבל הם הגברים למה נבדקו. ומשיב, אלא אף הם, הגברים, היו צריכים להבדק, אם לא נטמאו בנשיהם של המצריים, ונשיהם של ישראל לא נטמאו במצרים כל אלו השנים שהיו ביניהם, וכולם, גברים ונקבות יצאו זכאים, ונמצא זרע ישראל קדושים, זכאים. אז השרה הקב״ה שמו ביניהם. ועל כן על מים ודאי, שם שם לו חק ומשפט ושם נסהו. אף כאן במים בדק הכהן את האשה, ובשם הקדוש."]],[[0,"","הַכֹּהֵן כּוֹתֵב אֶת הַשֵּׁם הַקָּדוֹשׁ פַּעַם בְּדֶרֶךְ יָשָׁר, אַחַר כָּךְ כּוֹתְבוֹ לְמַפְרֵעַ אוֹתִיּוֹת (רשומות) מְהֻפָּכוֹת בְּאוֹרוֹתֵיהֶן, דִּין בְּדִין, רַחֲמִים בְּרַחֲמִים, רַחֲמִים בְּדִין, וְדִין בְּרַחֲמִים. נִמְצְאָה זַכָּאִית - אוֹתִיּוֹת הָרַחֲמִים נִמְצָאִים, וְהַדִּינִים מִסְתַּלְּקִים. לֹא נִמְצֵאת כָּרָאוּי - הָרַחֲמִים מִסְתַּלְּקִים, וְנִשְׁאָרִים הַדִּינִים, וְאָז נַעֲשֶׂה הַדִּין."],[1,"","רַבִּי אֶלְעָזָר פָּתַח וְאָמַר, (שמות טו) וַיָּבֹאוּ מָרָתָה וְלֹא יָכְלוּ לִשְׁתּוֹת מַיִם מִמָּרָה כִּי מָרִים הֵם, הֲרֵי פֵּרְשׁוּהָ. אָמַר, תּוֹהֶה אֲנִי אֵיךְ בְּנֵי אָדָם לֹא מִסְתַּכְּלִים וְלֹא מִשְׁתַּדְּלִים בְּדִבְרֵי תוֹרָה. כָּאן יֵשׁ לְהִסְתַּכֵּל, לָמָּה כָּתוּב כָּאן, שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ?"],[2,"","אֲבָל וַדַּאי סוֹד הַדָּבָר, שֶׁכָּאן עַל מַיִם זֶה הָיָה, מִשּׁוּם שֶׁהַמִּצְרִים הָיוּ אוֹמְרִים, שֶׁבָּנִים שֶׁל יִשְׂרָאֵל הָיוּ מֵהֶם, וְהָיוּ כַּמָּה בְּיִשְׂרָאֵל שֶׁחָשְׁדוּ בָזֶה בִּנְשׁוֹתֵיהֶם, עַד שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא הֱבִיאָם לְמָקוֹם זֶה וְרָצָה לְבָדְקָם. מַה כָּתוּב? וַיָּבאוּ מָרָתָה וְגוֹ'. וַיִּצְעַק אֶל ה' וְגוֹ'."],[3,"","אָמַר הַקָּדוֹשׁ בָּרוּךְ הוּא לְמֹשֶׁה, מֹשֶׁה, מָה אַתָּה רוֹצֶה? הֲרֵי כַּמָּה חֲבִילוֹת עוֹמְדוֹת עֲלֵיכֶם כָּאן, וַאֲנִי רוֹצֶה לִבְדּק כָּאן אֶת נְשׁוֹת יִשְׂרָאֵל. כְּתֹב שֵׁם קָדוֹשׁ וּזְרֹק אוֹתוֹ לַמַּיִם, וְיִבָּדְקוּ כֻלָּם, נָשִׁים וּגְבָרִים, וְלֹא יִשָּׁאֵר לַעַז עַל בָּנַי. וְעַד שֶׁיִּבָּדְקוּ כֻלָּם כָּאן, לֹא אַשְׁרֶה אֶת שְׁמִי עֲלֵיהֶם. מִיָּד - וַיּוֹרֵהוּ ה' עֵץ וַיַּשְׁלֵךְ אֶת הַמַּיִם, זֶה הַשֵּׁם הַקָּדוֹשׁ, אוֹתוֹ שֶׁהַכֹּהֵן הָיָה כּוֹתֵב לִבְדֹּק אֶת נְשׁוֹת יִשְׂרָאֵל, וְאָז - שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ."],[4,"","וְאִם תֹּאמַר, נְשׁוֹת יִשְׂרָאֵל רָאוּי, הֵם לָמָּה? אֶלָּא גַּם הֵם צְרִיכִים, שֶׁלֹּא נִטְמְאוּ בִּנְשׁוֹת מִצְרַיִם. וּנְשׁוֹת יִשְׂרָאֵל לֹא נִטְמְאוּ בַמִּצְרִים כָּל אוֹתָן שָׁנִים שֶׁהָיוּ בֵינֵיהֶם, וְכֻלָּם יָצְאוּ, גְּבָרִים וְנָשִׁים, זַכָּאִים, וְנִמְצְאוּ זֶרַע יִשְׂרָאֵל קְדוֹשִׁים וְזַכָּאִים. אָז הַקָּדוֹשׁ בָּרוּךְ הוּא הִשְׁרָה שְׁמוֹ בֵּינֵיהֶם, וְעַל זֶה עַל מַיִם וַדַּאי, שָׁם שָׂם לוֹ חֹק וּמִשְׁפָּט וְשָׁם נִסָּהוּ. גַּם כָּאן בְּמַים בּוֹדֵק הַכֹּהֵן אֶת הָאִשָּׁה, וּבַשֵּׁם הַקָּדוֹשׁ."]]],[["(במדבר ה׳:י״ז) וּמִן הֶעָפָר אֲשֶׁר יִהְיֶה בְּקַרְקַע הַמִּשְׁכָּן. מַאן הֶעָפָר. הָא תָּנֵינָן, כְּתִיב (קהלת ג׳:כ׳) הַכֹּל הָיָה מִן הֶעָפָר וְהַכֹּל שָׁב אֶל הֶעָפָר הַכֹּל הָיָה מִן הֶעָפָר, אֲפִילּוּ גַּלְגַּל חַמָּה, כָּל שֶׁכֵּן בַּר נָשׁ דְּאִשְׁתְּכָחוּ מִנֵּיהּ.","אָמַר רִבִּי יוֹסֵי, אִלּוּ כְּתִיב וּמִן הֶעָפָר וְלָא יַתִּיר, הֲוִינָא אָמַר הָכִי. אֲבָל כֵּיוָן דִּכְתִּיב וּמִן הֶעָפָר אֲשֶׁר יִהְיֶה בְּקַרְקַע הַמִּשְׁכָּן, מַשְׁמַע דְּאַחֲרָא הוּא. אֶלָּא כְּתִיב (ישעיהו מ״א:ב׳) יִתֵּן כֶּעָפָר חַרְבּוֹ, אִלֵּין מָארֵיהוֹן דְּקִיסְטִין וּבַלִיסְטְרָאִין, מָארֵי דְּדִינָא קַשְׁיָא. מַשְׁמַע דִּכְתִּיב בְּקַרְקַע הַמִּשְׁכָּן, דַּאֲחִידָן לְתַתָּא. וְעַל דָּא יִקַּח הַכֹּהֵן וְנָתַן אֶל הַמָּיִם.","מֵי הַמָּרִים הַמְאָרְרִים, אִלֵּין מֵי יַמָּא, דְּאִינּוּן מְרִירִין. מַאי הוּא. דָּא שְׁמָא קַדִישָׁא, בְּשַׁעֲתָא דְּאִשְׁתְּכַח בְּדִינָא, כְּדֵין אִקְרוּן מֵי הַמָּרִים הַמְאָרְרִים. וּבְגִין כָּךְ מַיָּא דְּיַמָּא דִּלְתַתָּא כֻּלְּהוֹן מְרִירִין.","תָּא חֲזֵי, הַאי יַמָּא קַדִישָׁא כַּמָה נַהֲרִין מְתִיקִין עָאלִין בְּגַוָּוהּ, וּבְגִין דְּאִיהִי דִּינָא דְּעָלְמָא, מֵימוֹי מְרִירָן, בְּגִין דְּאָחִיד בָּהּ מוֹתָא לְכָל בְּנֵי עָלְמָא. וְאַף עַל גַּב דְּאִינּוּן מְרִירָן, כַּד מִתְפַּשְּׁטִין מְתִיקִין אִינּוּן. לְזִמְנִין מַיִין דְּיַמָּא מְרִירָן. לְזִמְנִין יַמָּא דְּבָלַע לְכָל שְׁאַר מֵימִין, וְאִקְרֵי יַמָּא דְּקָפָא, וּבָלַע כָּל אִינּוּן אַחֲרָנִין, וְשָׁאִיב לוֹן בְּגַוִויהּ, וְלָא נִיגָרִין לְבַר. לְזִמְנִין שָׁארָן מַיָּיא, וְנַגְדִין מֵהַהוּא יַמָּא, כָּל מַה דְּנָגִיד לְתַתָּאֵי. וּבְכַמָּה גְּוָונִין קַיְּימָא הַאי יַמָּא. הַמַּיִם הַמְאָרְרִים, בְּשַׁעֲתָא דְּאָתֵי חִיוְיָא וְאָטִיל זוּהֲמָא, כְּדֵין הַמַּיִם הַמְאָרְרִים וְעַל דָּא כַּהֲנָא עָבִיד עוֹבָדָא לְתַתָּא, וְאוֹמֵי אוֹמָאָה, וְאִתְעָבִיד דִּינָא."],[[0,"ומן העפר אשר","וכו׳: ומן העפר אשר יהיה בקרקע המשכן. שואל מהו העפר. ומשיב, הרי למדנו, כתוב, הכל היה מן העפר והכל שב אל העפר. הכל היה מן העפר אפילו גלגל החמה. כל שכן אדם שנמצא ממנו. (כמ״ש לעיל צו קע״ג)."],[1,"א״ר יוסי","וכו׳: אר״י, אלו היה כתוב ומן העפר, ולא יותר, הייתי אומר כך, שהפירוש והוא מן העפר, שהוא מלכות. אבל כיון שכתוב, ומן העפר אשר יהיה בקרקע המשכן, משמע שהוא עפר אחר. אלא כתוב, יתן כעפר חרבו, אלו בעלי כלי זיין, ובעלי אבני הקלע, בעלי דין הקשה. זה משמע משכתוב בקרקע המשכן, שפירושו סיום המלכות הנקראת משכן, והיינו בעלי הדין הנאחזים למטה בסופה, במלכות דמלכות, בסו״ה לפתח חטאת רובץ, וע״כ, יקח הכהן ונתן אל המים. כי מבחינת עפר הזה יטיל לתוך המים. \u0003קיסטין\u0004 הוא כלי זיין, מלשון לבוש בכלי זיין קסטיא (ילמדנו שופטים) \u0003ובליסטראין,\u0004 הוא כמ״ש, וכי משה רבינו ע״ה קניגי ובליסטרי היה (חולין ס:)."],[2,"מי המרים המאררים","וכו׳: אלו הם מי הים שהם מרים. מה הם מי הים. הם השם הקדוש, דהיינו מלכות הנקראת ים, בעת שנמצאת בדין, ואז נקראים מי המרים המאררים. ומשום זה מי הים התחתון, שהוא ענף אל המלכות, כולם מרים."],[3,"ת״ח האי ימא","וכו׳: בוא וראה, הים הקדוש הזה, שהוא מלכות, כמה נהרות מתוקים, שהם ספירות דז״א, נכנסים בתוכה, ומשום שהיא דין של העולם, מימיה מרים, משום שאחוז בה המות של כל בני העולם. בסו״ה ורגליה יורדות מות. ואע״פ שהם מרים, כשמתפשטים הם מתוקים. לפעמים מי הים מרים, היינו מצד שהמות נאחז במלכות. לפעמים מי הים בולעים כל שאר מימות. כמ״ש לעיל (ב״א אות צ״ו) ונקראת ימא דקפא (כמ״ש ב״א דף רמ״ז ד״ה ימא דקאפו) ובלע לכל אלו מימות האחרים ושואב אותם בתוכו ואינם נגרים לחוץ. ולפעמים נפתחים המים ונמשך מהים ההוא כל מה שנמשך לתחתונים. ובכמה אפנים עומד הים ההוא. המים המאררים, הם נקראים, בשעה שבא נחש והטיל זוהמא, אז המים המאררים, וע״כ הכהן עשה מעשה למטה, והשביע השבועה, ונעשה הדין."]],[[0,"","וּמִן הֶעָפָר אֲשֶׁר יִהְיֶה בְּקַרְקַע הַמִּשְׁכָּן. אֵיזֶה עָפָר? הֲרֵי לָמַדְנוּ, כָּתוּב (קהלת ג) הַכֹּל הָיָה מִן הֶעָפָר וְהַכֹּל שָׁב אֶל הֶעָפָר. הַכֹּל הָיָה מִן הֶעָפָר - אֲפִלּוּ גַּלְגַּל חַמָּה, כָּל שֶׁכֵּן בֶּן אָדָם שֶׁנִּמְצָא מִמֶּנּוּ."],[1,"","אָמַר רַבִּי יוֹסֵי, אִלּוּ כָּתוּב וּמִן הֶעָפָר וְלֹא יוֹתֵר - הָיִיתִי אוֹמֵר כָּךְ. אֲבָל כֵּיוָן שֶׁכָּתוּב וּמִן הֶעָפָר אֲשֶׁר יִהְיֶה בְּקַרְקַע הַמִּשְׁכָּן, מַשְׁמָע שֶׁאַחֵר הוּא. אֶלָּא כָּתוּב (ישעיה מא) יִתֵּן כֶּעָפָר חַרְבּוֹ, אֵלֶּה בַּעֲלֵי כְּלֵי זַיִן וּבַלִּיסְטְרָאוֹת, בַּעֲלֵי דִּין הַקָּשֶׁה. מַשְׁמָע שֶׁכָּתוּב בְּקַרְקַע הַמִּשְׁכָּן, שֶׁאֲחוּזִים לְמַטָּה. וְעַל זֶה, יִקַּח הַכֹּהֵן וְנָתַן אֶל הַמָּיִם."],[2,"","מֵי הַמָּרִים הַמְאָרֲרִים - אֵלֶּה מֵי יָם שֶׁהֵם מְרִירִים. מַהוּ? זֶה שֵׁם הַקָּדוֹשׁ בְּשָׁעָה שֶׁנִּמְצָא בְדִין, אָז נִקְרָאִים מֵי הַמָּרִים הַמְאָרֲרִים. וּמִשּׁוּם זֶה מֵי הַיָּם שֶׁלְּמַטָּה כֻּלָּם מְ רִירִים."],[3,"","בֹּא רְאֵה, יָם קָדוֹשׁ זֶה, כַּמָּה נְהָרוֹת מְתוּקִים נִכְנָסִים בְּתוֹכוֹ, וּמִשּׁוּם שֶׁהוּא דִּין הָעוֹלָם, מֵימָיו מְרִירִים, מִשּׁוּם שֶׁאָחוּז בָּהֶם הַמָּוֶת לְכָל בְּנֵי הָעוֹלָם. וְאַף עַל גַּב שֶׁהֵם מְרִירִים, כְּשֶׁמִּתְפַּשְּׁטִים הֵם מְתוּקִים. לִפְעָמִים מֵי הַיָּם מְרִירִים. לִפְעָמִים הַיָּם שֶׁבּוֹלֵעַ לְכָל שְׁאָר הַמַּיִם, וְנִקְרָא יָם קָפוּא, וּבוֹלֵעַ כָּל אוֹתָם אֲחֵרִים וְשׁוֹאֵב אוֹתָם לְתוֹכוֹ, וְלֹא נִגָּרִים הַחוּצָה. לִפְעָמִים שׁוֹרִים הַמַּיִם וּמַשְׁפִּיעִים מֵאוֹתוֹ הַיָּם כָּל מַה שֶּׁשּׁוֹפֵעַ לַתַּחְתּוֹנִים. וּבְכַמָּה גְוָנִים עָמַד יָם זֶה. הַמַּיִם הַמְאָרַרִים, בְּשָׁעָה שֶׁבָּא הַנָּחָשׁ וְהִטִּיל זֻהֲמָה, אָז הַמַּיִם הַמְאָרַרִים, וְעַל כָּךְ הַכֹּהֵן עוֹשֶׂה מַעֲשֶׂה לְמַטָּה, וְנִשְׁבָּע שְׁבוּעָה, וְנַעֲשֶׂה דִין."]]],[["תָּא חֲזֵי, אִי אִתְּתָא אִשְׁתְּכָחַת זַכְיָּיתָא, אִלֵּין מַיִין עָאלִין בְּגַוָּוהּ, וְאִתְהַפְּכָן מְתִיקָן, וְנָקָאן גַּרְמָהּ, וְקַיְימִין בְּגַוָּוהּ, עַד דְּמִתְעַבְּרָא. כֵּיוָן דְּמִתְעַבְּרָא, הֲווֹ מְשַׁפְּרֵי בְּשַׁפִירֵי לְעוּבָּרָא דִּמְעָהָא, וְנָפִיק בְּרָא שַׁפִּירָא, נָקִי בְּלָא מוּמָא דְּעָלְמָא. וְאִי לָאו, אִינּוּן מַיִין עַיְילִין בְּגַוָּוהּ, וְאָרְחָא רֵיחָא דְּזוּהֲמָא, וְאִינּוּן מַיִין מִתְהַפְּכִין לְחִוְיָא בִּמְעָהָא, בְּמָה דְּקִלְקְלָה אִתְפְּסַת, וְאִתְחַזֵּי קְלָנָא לְכֹלָּא, וְהָא אוּקְמוּהָ חַבְרַיָּיא.","תָּא חֲזֵי, כָּל אִינּוּן נְשֵׁי עָלְמָא, בְּאַתְרַיְיהוּ קַיְימֵי וְאִתְדָּנוּ, וְעַל דָּא הַהוּא אֲתָר מַמָּשׁ דְּאִינְהוּ קַיְימֵי, בֵּיהּ אִתְדָנוּ. זַכָּאָה חוּלָקֵיהוֹן דְּיִשְׂרָאֵל, דְקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּהוּ, וּבָעֵי לְדַכְּאָה לְהוּ.","רִבִּי חִזְקִיָּה פָּתַח, (תהילים קכ״ח:ג׳) אֶשְׁתְּךָ כְּגֶפֶן פּוֹרִיָּה וְגוֹ', מַה גֶּפֶן לָא מְקַבֵּל עָלֵיהּ אֶלָּא מִדִּידֵיהּ, כַּךְ אִתְּתָא דְּיִשְׂרָאֵל, קַיְּימָא בְּהַאי גַּוְונָא, דְּלָא מְקַבְּלָא עָלָהּ אֶלָּא הַהוּא בַּר זוּגָהּ. כְּשַׁפְּנִינָא (נ\"א כתורא) דָּא, דְּלָא מְקַבְּלָא אֶלָּא הַהוּא בַּר זוּגָהּ. וְעַל דָּא כְּגֶפֶן פּוֹרִיָּה בְּיַרְכְּתֵי בֵיתֶךָ. מַהוּ פּוֹרִיָּה. כְּמָה דְאַתְּ אָמֵר (דברים כ״ט:י״ז) פּוֹרֶה רֹאשׁ. פּוֹרִיָּה: פּוֹרַחַת, דְּאַפִּיקַת עֲנָפִים לְכָל סִטְרָא. וְאָן. בְּיַרְכְּתֵי בֵיתֶךָ, וְלָאו לְבַר בְּשׁוּקָא, בְּגִין דְּלָא תֵּיתֵי לְשַׁקְּרָא בִּבְרִית עִלָּאָה.","וּשְׁלֹמֹה אָמַר, (משלי ב׳:י״ז) הָעוֹזֶבֶת אַלּוּף נְעוּרֶיהָ וְאֶת בְּרִית אֱלֹהֶיהָ שָׁכֵחָה. מַאן בְּרִית אֱלֹהֶיהָ. הַהוּא אֲתָר דְּאִקְרֵי בְּרִית. וְהִיא אִתְקַשְּׁרָא בֵּיהּ, בְּגִין כַּךְ בְּיַרְכְּתֵי בֵיתֶךָ.","אָמַר רִבִּי חִזְקִיָּה, תּוּנְבָא לֵיתֵי עַל הַהוּא בַּר נָשׁ, דְּשָׁבַק לְאִנְתְּתֵיהּ דְּתִתְחַזֵי מִשַׂעֲרָא דְּרֵישָׁה לְבַר. וְדָא הוּא חַד מֵאִינּוּן צְנִיעוּתָא דְּבֵיתָה. וְאִתְּתָא דַּאֲפִּיקַת מִשַׂעֲרָא דְּרֵישָׁה לְבַר, לְאִתְתַּקְּנָא בֵּיהּ, גָּרִים מִסְכְּנוּתָא לְבֵיתָא. וְגָרִים לִבְנָהָא דְּלָא יִתְחַשְּׁבוּן בְּדָרָא. וְגָרִים מִלָּה אַחֲרָא דְּשַׁרְיָא בְּבֵיתָא. מַאן גָּרִים דָּא. הַהוּא שַׂעֲרָא דְּאִתְחֲזֵי מֵרֵישָׁהּ לְבַר. וּמַה בְּבֵיתָא הַאי, כָּל שֶׁכֵּן בְּשׁוּקָא, וְכָּל שֶׁכֵּן חֲצִיפוּתָא אַחֲרָא. וּבְגִין כָּךְ אֶשְׁתְּךָ כְּגֶפֶן פּוֹרִיָּה בְּיַרְכְּתֵי בֵיתֶךָ."],[[0,"ת״ח אי אתתא","וכו׳: בוא וראה, אם האשה נמצאת נקיה, אלו המים נכנסים בתוכה ומתהפכים להיות מתוקים, ומנקים אותה ועומדים בתוכה, עד שמתעברת. כיון שנתעברה, היו המים מייפים ביופי את העובר שבמעיה, ויצא בן יפה ונקי מכל בלי שום מום שבעולם. ואם לא היתה נקיה, אז נכנסים בתוכה אלו המים, והיא מריחה ריח של הזוהמא, של הנחש, כנ״ל, והמים האלו מתהפכים לנחש במעיה. ובמה שקלקלה נתפסת, דהיינו וצבתה בטנה ונפלה ירכה, ונראה חרפתה לכל. וכבר העמידו החברים."],[1,"ת״ח כל אינון","וכו׳: בוא וראה, כל נשי העולם עומדות ונדונות במקומן, מאלו המים ששתתה הסוטה, וע״כ אותו מקום ממש שהם נמצאים ממנו, שהוא המלכות, שהנשים הן ענפיה, בה נדונו. כי המלכות דנה אותן (כנ״ל אמור קנ״ג). אשרי חלקם של ישראל, שהקב״ה רצה בהם, ורצה לטהר אותם."],[2,"ר׳ חזקיה פתח","וכו׳: רח״פ, אשתך כגפן פוריה וגו׳. מה גפן אינה מקבלת עליה ממין אחר אלא ממין שלה. כך אשה בישראל עומדת באותו אפן, שאינה מקבלה עליה אלא בן זוגה. כיונה זו שאינה מקבלת אלא בן זוגה. וע״כ, כגפן פוריה בירכתי ביתך. מהו פוריה. הוא כמש״א פורה ראש. פוריה, היינו שפורחת ומוציאה ענפים לכל צד. ואיפה הוא בירכתי ביתך, ולא לחוץ מן השוק, כי לא תבוא לשקר בברית עליון."],[3,"ושלמה אמר","וכו׳: ושלמה אמר העוזבת אלוף נעוריה ואת ברית אלקיה שכחה. מהו ברית אלקיה. היינו מקום ההוא שנקרא ברית, שהוא יסוד, והיא נתקשרה בו, משום זה כתוב, בירכתי ביתך."],[4,"א״ר חזקיה תונבא","וכו׳: א״ר חזקיה, חלחלה תבוא על אותו אדם, העוזב את אשתו שתראה משערות ראשה לחוץ, וזה הוא אחד מאלו צניעות שבבית. ואשה המוציאה שערות ראשה לחוץ להתיפות בו, גורמת עניות לבית. וגורמת, שבניה לא יהיו חשובים בדור. וגורמת דבר אחר שישרה בבית. דהיינו צרעת. מי גרם לכל זה, היינו שער ההוא הנראה מראשה לחוץ. ומה בבית כך, כל שכן בשוק, וכל שכן חציפות אחר אם תראה ממנה. ומשום זה כתוב,,אשתך כגפן פוריה בירכתי ביתך \u0003תונבא,\u0004 פירושו תמהון וחלחלה (יומא פ\"ג)."]],[[0,"","בֹּא רְאֵה, אִם הָאִשָּׁה נִמְצֵאת זַכָּאִית, מַיִם אֵלֶּה נִכְנָסִים בְּתוֹכָהּ וְנֶהְפָּכִים לִמְתוּקִים, וּמְנַקִּים עַצְמָהּ, וְעוֹמְדִים בְּתוֹכָהּ עַד שֶׁמִּתְעַבֶּרֶת. כֵּיוָן שֶׁמִּתְעַבֶּרֶת, הָיוּ מְיַפִּים בְּיֹפִי לָעֻבָּר שֶׁבְּמֵעֶיהָ, וְיוֹצֵא בֵּן יָפֶה, נָקִי בְּלִי מוּם שֶׁל הָעוֹלָם. וְאִם לֹא - הַמַּיִם הָאֵלֶּה נִכְנָסִים בְּתוֹכָהּ, וּמְרִיחָה רֵיחַ זֻהֲמָה, וְאוֹתָם מַיִם מִתְהַפְּכִים לְנָחָשׁ בְּמֵעֶיהָ. בְּמַה שֶּׁקִּלְקְלָה נִתְפֶּסֶת, וְנִרְאֶה קָלוֹן לַכֹּל, וְכָךְ פֵּרְשׁוּהָ הַחֲבֵרִים."],[1,"","בֹּא רְאֵה, כָּל נְשׁוֹת הָעוֹלָם עוֹמְדוֹת בִּמְקוֹמָן וְנִדּוֹנוֹת, וְעַל כָּךְ, אוֹתוֹ מָקוֹם מַמָּשׁ שֶׁהֵן עוֹמְדוֹת, שָׁם נִדּוֹנוֹת. אַשְׁרֵי חֶלְקָם שֶׁל יִשְׂרָאֵל שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מִתְרַצֶּה בָהֶם וְרוֹצֶה לְזַכּוֹתָם."],[2,"","רַבִּי חִזְקִיָּה פָּתַח, (תהלים קכח) אֶשְׁתְּךְ כְּגֶפֶן פֹּרִיָּה וְגוֹ'. מַה גֶּפֶן לֹא מְקַבֶּלֶת עָלֶיהָ אֶלָּא מִשֶּׁלָּהּ - כָּךְ אֵשֶׁת יִשְׂרָאֵל עוֹמֶדֶת בִּכְגוֹן זֶה, שֶׁלֹּא מְקַבֶּלֶת עָלֶיהָ אֶלָּא אוֹתוֹ בֶּן זוּגָהּ, כְּמוֹ הַיּוֹנָה (כיונה) הַזּוֹ שֶׁלֹּא מְקַבֶּלֶת עָלֶיהָ אֶלָּא אוֹתוֹ בֶּן זוּגָהּ. וְעַל כֵּן, כְּגֶפֶן פֹּרִיָּה בְּיַרְכְּתֵי בֵיתֶךְ. מַה זֶּה פֹּרִיָּה? כְּמוֹ שֶׁנֶּאֱמַר (דברים כט) פֹּרֶה רֹאשׁ. פֹּרִיָּה - פּוֹרַחַת, שֶׁמּוֹצִיאָה עֲנָפִים לְכָל צַד. וְאֵיפֹה? בְּיַרְכְּתֵי בֵיתֶךְ, וְלֹא לַחוּץ בַּשּׁוּק, מִשּׁוּם שֶׁלֹּא תָבֹא לְשַׁקֵּר בִּבְרִית עֶלְיוֹנָה."],[3,"","וּשְׁלֹמֹה אָמַר, (משלי ב) הַעֹזֶבֶת אַלּוּף נְעוּרֶיהָ וְאֶת בְּרִית אֱלֹהֶיהָ שָׁכֵחָה. מַה זֶּה בְּרִית אֱלֹהֶיהָ? אוֹתוֹ מָקוֹם שֶׁנִּקְרָא בְּרִית וְהִיא הִתְקַשְּׁרָה בּוֹ, בִּגְלַל כָּךְ בְּיַרְכְּתֵי בֵיתֶךְ."],[4,"","אָמַר רַבִּי חִזְקִיָּה, קְלָלָה תָּבֹא עַל אוֹתוֹ אִישׁ שֶׁמַּשְׁאִיר אֶת אִשְׁתּוֹ לְהֵרָאוֹת עִם שַׂעֲרוֹת רֹאשָׁהּ בַּחוּץ, וְזֶה אֶחָד מֵאוֹתָם צְנִיעֻיּוֹת שֶׁל הַבַּיִת. וְאִשָּׁה שֶׁמּוֹצִיאָה מִשַּׂעֲרוֹת רֹאשָׁהּ הַחוּצָה לְהִתְתַּקֵּן בּוֹ, גּוֹרֶמֶת עֹנִי לַבַּיִת, וְגוֹרֶמֶת לְבָנֶיהָ שֶׁלֹּא יֵחָשְׁבוּ בַּדּוֹר, וְגוֹרֶמֶת דָּבָר אַחֵר שֶׁשּׁוֹרֶה בַּבַּיִת. מִי גָרַם זֶה? אוֹתוֹ שֵׂעָר שֶׁנִּרְאֶה מֵרֹאשָׁהּ הַחוּצָה. וּמַה בַּבַּיִת כָּךְ - כָּל שֶׁכֵּן בַּשּׁוּק, וְכָל שֶׁכֵּן חֲצִיפוּת אַחֶרֶת. וּמִשּׁוּם זֶה, אֶשְׁתְּךְ כְּגֶפֶן פֹּרִיָּה בְּיַרְכְּתֵי בֵיתֶךְ."]]],[["אָמַר רִבִּי יְהוּדָה, שַׂעֲרָא דְּרֵישָׁא דְּאִתְּתָא דְּאִתְגַּלְיָיא, גָּרִים שַׂעֲרָא אַחֲרָא לְאִתְגַּלְיָיא, וּלְאַפְגְּמָא לָהּ. בְּגִין כַּךְ, בַּעְיָא אִתְּתָא דְּאֲפִילּוּ טְסִירֵי דְּבֵיתָא, לָא יֶחמוּן שַׂעֲרָא חַד מֵרֵישָׁא, כָּל שֶׁכֵּן לְבַר.","תָּא חֲזֵי, כְּמָה בִּדְכוּרָא שַׂעֲרָא הוּא חוּמְרָא דְּכֹלָּא, הָכִי נָמֵי לְנוּקְבָּא. פּוּק חָמֵי, כַּמָה פְּגִימוּ גָּרִים הַהוּא שַׂעֲרָא דְּאִתְּתָא. גָּרִים לְעֵילָּא, גָּרִים לְתַתָּא, גָּרִים לְבַעְלָהּ דְּאִתְלַטְּיָיא, גָּרִים מִסְכְּנוּתָא, גָּרִים מִלָּה אַחֲרָא בְּבֵיתָא, גָּרִים דְּיִסְתְלִק חַשִׁיבוּתָא מִבְּנָהָא. רַחֲמָנָא לִישֵׁזְבוּן, מֵחֲצִיפוּ דִּלְהוֹן.","וְעַל דָּא, בַּעְיָא אִתְּתָא לְאִתְכַּסְּיָיא, בְּזִיווֹתֵי דְּבֵיתָא. וְאִי עַבְדַּת כֵּן מַה כְּתִיב, (תהילים קכ״ח:ג׳) בָּנֶיךָ כִּשְׁתִילֵי זֵיתִים. מַהוּ כִּשְׁתִילֵי זֵיתִים. מַה זַיִת דָּא, בֵּין בְּסִתְוָוא, בֵּין בְּקַיְיטָא, לָא אִתְאֲבִידוּ טַרְפּוֹי, וְתָדִיר אִשְׁתְּכַח בֵּיהּ חֲשִׁיבוּת יַתִיר עַל שְׁאַר אִילָנִין. כַּךְ בְּנָהָא יִסְתַּלְּקוּן בַּחֲשִׁיבוּ עַל שְׁאַר בְּנֵי עָלְמָא. וְלֹא עוֹד אֶלָּא דְּבַעְלָהּ מִתְבָּרֵךְ בְּכֹלָּא, בְּבִרְכָאן דִּלְעֵילָּא, בְּבִרְכָאן דִּלְתַּתָּא, בְּעוּתְרָא, בִּבְנִין, בִּבְנֵי בְּנִין. הֲדָא הוּא דִכְתִיב, (תהילים קכ״ח:ד׳) הִנֵּה כִּי כֵן יְבוֹרַךְ גָּבֶר יְרֵא יְיָ. וּכְתִיב (תהילים קכ״ח:ה׳-ו׳) יְבָרֶכְךָ ה' מִצִּיּוֹן וּרְאֵה בְּטוּב יְרוּשָׁלָיִם כֹּל יְמֵי חַיֶּיךָ וּרְאֵה בָּנִים לְבָנֶיךָ שָׁלוֹם עַל יִשְׂרָאֵל. (ישראל סבא קדישא)","\u0003רעיא מהימנא\u0004 אֵלִיָּהוּ, קוּם אַפְתַּח עַמִּי בְּפִקּוּדִין, דְּאַנְתְּ הוּא עוֹזִר לִי, בְּכָל סִטְרָא. דְּהָא עֲלָךְ אִתְּמַר בְּקַדְמִיתָא, פִּנְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן. וּבֶן אַהֲרֹן וַדַּאי אִיהוּ אָח דִּילִי, (משלי י״ז:י״ז) אָח לְצָּרָה יִוָּלֵד.","פָּתַח וְאָמַר, פִּקּוּדָא לָדוּן בְּדִינֵי סוֹטָה, הֲדָא הוּא דִכְתִיב וְעָבַר עָלָיו רוּחַ קִנְאָה וְקִנֵּא וְגוֹ'. וַדַּאי רוּחַ טוּמְאָה מִתְּרֵין סִטְרִין אִשְׁתְּכַח, חַד בְּשִׁקְרָא, וְחַד בִּקְשׁוֹט. בְּגִין דָּא, בְּרוּחַ שִׁקְרָא וְקִנֵּא אֶת אִשְׁתּוֹ, וְהִיא לֹא נִטְמָאָה. וְתָנֵינָא, וְעָבַר עָלָיו וְגוֹ', וְקִנֵּא אֶת אִשְׁתּוֹ וְהִיא נִטְמָאָה.","וְכִי אִית קוּשְׁטָא בְּרוּחַ מִסְאֲבָא. אֶלָּא בְּבַר נָשׁ מִסִּטְרָא דְּאִילָנָא דְּטוֹב וָרָע, תַּמָּן יֵצֶּר הָרָע, נָחָשׁ. בְּזִמְנָא דְּאִית לְבַּר נָשׁ אִתְּתָא שַׁפִּירָא, בְּכָל עוֹבָדִין טָבִין, דְּאִתְּמַר בָּהּ (משלי י״ב:ד׳) אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ. יִצֶּר הָרָע אִית לֵיהּ קִנְאָה, כְּגַוְונָא דְּאַשְׁכַּחְנָא דְּקַנֵּי אָדָם עַל אִנְתְּתֵיהּ, עַד דְּפַתֵּי לָהּ, וְגָרַם לָהּ מִיתָה. וּלְזִמְנִין שַׁלִּיט עָלָהּ בְּחוֹבִין, וּמְסָאַב לָהּ, וְהָא אִתְעָבִידַת נְבֵלָה.","וְיִצֶּר הָרָע, מִסִּטְרָא דִּימִינָא, דִּילֵיהּ, דַּרְגָּא דְּיִשְׁמָעֵאל, אִתְקְרֵי נָחָשׁ. וּמִסִּטְרָא דִּשְׂמָאלָא, דַּרְגֵּיהּ דְּעֵשָׂו סָמָאֵ\"ל, אִתְקְרֵי כֶּלֶב, מְמָנָא דְּגֵיהִנָּם דְּצּווִֹחַ הַב הַב, הֲדָא הוּא דִּכְתִּיב, (משלי ל׳:ט״ו) לַעֲלוּקָה שְׁתֵּי בָנוֹת הַב הַב, וּבִרְעוּתָא דִּילֵיהּ לְמֵיכַל נִשְׁמְתָא מִסְאֲבָא, בְּנוּרָא דִּילֵיהּ, גֵּיהִנָּם. וְעָבַר עָלָיו רוּחַ קִנְאָה וְקִנֵּא אֶת אִשְׁתּוֹ בִּקְשׁוֹט, וְהִיא נִטְמָאָה.","וּבְגִינָהּ אִתְּמַר, (ויקרא כ״א:ט׳) וּבַת אִישׁ כֹּהֵן, דָּא מִיכָאֵל, כִּי תֵּחֵל לִזְנוֹת אֶת אָבִיהָ הִיא מְחַלֶּלֶת בָּאֵשׁ תִּשָּׂרֵף. וְתַמָּן אִתּוֹקְדַת הַהִיא זוּהֲמָא, וְאִתְלַבְּנַת אִיהִי מִנֵּיהּ, כַּכֶּסֶף דְּאִתְלָבַּן בְּנוּרָא, וְהַהִיא עוֹפֶרֶת דְּזוּהֲמָא אִתּוֹקַד, וְאִתְעָבִיד עָפָר, וְאִתְאֲבִיד.","כְּגַוְונָא דָּא בְּיִשְׂרָאֵל, כַּד אִינּוּן מְחַלְּלִין אוֹרַיְיתָא, קוּדְשָׁא בְּרִיךְ הוּא יֵיעוּל לוֹן בְּגָלוּתָא דִּבְנֵי עֵשָׂו וּבְנֵי יִשְׁמָעֵאל, תְּחוֹת שִׁעְבּוּדָא דִּלְהוֹן, דְּדַרְגַּיְיהוּ כֶּלֶ\"ב וְנָחָ\"שׁ, וְאִתְּדָנוּ תַּמָּן, וּבְהוֹן יִתְבָּרְרוּ וְיִתְלַבְּנוּ וְיִצּוֹרְפוּ כִּצְּרוֹף הַכֶּסֶף וְכִבְחוֹן הַזָּהָב, הֲדָא הוּא דִכְתִיב, (זכריה י״ג:ט׳) וּצְּרַפְתִּים כִּצְּרֹף אֶת הַכֶּסֶף וּבְחַנְתִּים כִּבְחֹן אֶת הַזָּהָב, עַד דְּיִתְקַיֵּים בְּהוּ, (ישעיהו א׳:י״ח) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ.","וְאִילָנָא דְּטוֹב וָרָע, בְּגִינֵיהּ אִתְּמַר, (שמות ט״ו:כ״ה) וַיּוֹרֵהוּ יְיָ עֵץ וַיַּשְׁלֵךְ אֶל הַמַּיִם וַיִּמְתְּקוּ הַמָּיִם וְגוֹ'. בְּגִין דַּהֲווֹ יִשְׂרָאֵל עִם עֵרֶב רַב, כֻּלְּהוּ הֲווֹ אִילָנָא דְּטוֹב וָרָע, וְעַל דָּא, חֶצְּיוֹ מָתוֹק מִסִּטְרָא דִּימִינָא. וְחֶצְּיוֹ מַר, מִסִּטְרָא דִּשְׂמָאלָא. וּבְזִמְנָא דְּעֵרֶב רַב הֲווֹ מַחֲטִיאִין לוֹן לְיִשְׂרָאֵל, הֲוִי כְּאִילּוּ הֲווֹ כֻּלְּהוּ מִסִּטְרָא דְּרָע. וּמַיָא אִתְהַדְרָא כֻּלְּהוּ מְרִירִין, כְּהַהוּא עֵץ מַר בְּמַיָּא, הֲדָא הוּא דִכְתִיב, (שמות ט״ו:כ״ג) וַיָבֹאוּ מָרָתָה וְלֹא יָכְלוּ לִשְׁתּוֹת מַיִם מִמָּרָה כִּי מָרִים הֵם.","וְהַאי עֵץ מַר, אִיהוּ כְּגַוְונָא דְּנִסְיוֹנָא דְּסוֹטָה, אִי סָטַת תְּחוֹת בַּעְלָהּ, אִינּוּן מַיִין דְּאַשְׁקְיָּין לָהּ אִתְהֲדָרוּ מְרִירִין, וּבְהוֹן וְצָּבְתָה בִטְנָהּ וְנָפְלָה יְרֵיכָהּ, וְאִי לָא סָטַת מַה כְּתִיב, וְנִקְּתָה וְנִזְרְעָה זָרַע, וְאוֹלִידַת בַּר. אוּף הָכָא וַיִמְתְּקוּ הַמָּיִם.","כְּגַוְונָא דָּא, יִתְעֲבִיד לְנַסְּאָה לוֹן לְיִשְׂרָאֵל בְּפוּרְקָנָא בַּתְרַיְיתָא, הֲדָא הוּא דִכְתִיב, (דניאל י״ב:י׳) יִתְבָּרְרוּ וְיִתְלַבְּנוּ וְיִצָּרְפוּ רַבִּים, דְּאִינּוּן מִסִּטְרָא דְּטוֹב, וְקַיְימִין בְּנִסְיוֹנָא. וְהִרְשִׁיעוּ רְשָׁעִים אִינּוּן מִסִּטְרָא דְּרַע, וְיִתְקַיֵּים בְּהוֹן (יחזקאל י״ג:ט׳) וְאֶל אַדְמַת יִשְׂרָאֵל לֹא יָבֹאוּ וְקָטִיל לוֹן.","(דניאל י״ב:י׳) וְהַמַשְׂכִּילִים יָבִינוּ, מִסִּטְרָא דְּבִינָה, דְּאִיהוּ אִילָנָא דְּחַיִּי, בְּגִינַיְיהוּ אִתְּמַר, (דניאל י״ב:ג׳) וְהַמַשְׂכִּילִים יַזְהִירוּ כְּזוֹהַר הָרָקִיעַ בְּהַאי חִבּוּרָא דִּילָךְ דְּאִיהוּ סֵפֶר הַזֹּהַר, מִן זוֹהֲרָא דְּאִימָא עִלָּאָה תְּשׁוּבָה. בְּאִלֵּין לָא צָּרִיךְ נִסָּיוֹן, וּבְגִין דַּעֲתִידִין יִשְׂרָאֵל לְמִטְעַם מֵאִילָנָא דְּחַיִּי, דְּאִיהוּ הַאי סֵפֶר הַזֹּהַר, יִפְּקוּן בֵּיהּ מִן גָּלוּתָא בְּרַחֲמֵי. וְיִתְקַיֵּים בְּהוֹן, (דברים ל״ב:י״ב) יְיָ בָּדָד יַנְחֶנּוּ וְאֵין עִמּוֹ אֵל נֵכָר.","וְאִילָנָא דְּטוֹב וָרָע, דְּאִיהוּ אִיסוּר וְהֶיתֵּר טוּמְאָה וְטָהֳרָה, לָא שַׁלְטָא עַל יִשְׂרָאֵל יַתִּיר, דְּהָא פַּרְנָסָה דִּילָן לָא לִיהֱוִי, אֶלָּא מִסִּטְרָא דְּאִילָנָא דְּחַיִּי, דְּלֵית תַּמָּן לָא קַשְׁיָא מִסִּטְרָא דְּרַע, וְלָא מַחֲלוֹקֶת מֵרוּחַ הַטוּמְאָה, דִּכְתִּיב, (זכריה י״ג:ב׳) וְאֶת רוּחַ הַטוּמְאָה אַעֲבִיר מִן הָאָרֶץ.","דְּלָא יִתְפַּרְנְסוּן תַּלְמִידֵי חֲכָמִים מֵעַמֵּי הָאָרֶץ, אֶלָּא מִסִּטְרָא דְּטוֹב, דְּאָכְלִין טָהֳרָה כָּשֵׁר הֵיתֶּר, וְלָא מֵעֵרֶב רַב, דְּאָכְלִין טוּמְאָה פָּסוּל אִיסוּר, דְּאִינּוּן מְסָאֲבִין, דִּמְסָאֲבִין גַּרְמַיְיהוּ בְּנִדָּה שִׁפְחָה גּוֹיָה זוֹנָה. בְּגִין דְּאִינּוּן בְּנוֹי דְּלִילִית, דְּאִיהִי, נִדָּה שִׁפְחָה גּוֹיָה זוֹנָה חַזְרִין לְשָׁרְשַׁיְהוּ. וְעָלַיְיהוּ אִתְּמַר, (ישעיהו י״ד:כ״ט) כִּי מִשֹּׁרֶשׁ נָחָשׁ יִצֵּא צֶּפַע.","וּבְזִמְנָא דְּאִילָנָא דְּטוֹב וָרָע שַׁלְטָא, דְּאִיהוּ חוּלִין דְּטַהֲרָה, וְחוּלִין דְּטוּמְאָה. אִינּוּן חֲכָמִים דְּדַמְיָין לְשַׁבָּתוֹת וְיוֹם טוֹב, לֵית לוֹן אֶלָּא מַה דְּיָהֲבִין לוֹן אִינּוּן חוּלִין. כְּגַוְונָא דְּיוֹם הַשַּׁבָּת, דְּלֵית לֵיהּ, אֶלָּא מַה דִּמְתַקְּנִין לֵיהּ בְּיוֹמֵי דְּחוֹל.","וּבְזִמְנָא דְּשַׁלְטָא אִילָנָא דְּחַיִּי, אִתְכַּפְיָיא אִילָנָא דְּטוֹב וָרָע, וְלָא יְהֵא לְעַמֵי הַאָרָצּוֹת, אֶלָּא מַה דְּיָהֲבִין לוֹן תַּלְמִידֵי חֲכָמִים, וְאִתְכַּפְיָין תְּחוֹתַיְיהוּ, וּכְאִלּוּ לָא הֲווֹ בְּעָלְמָא.","וְהָכִי אִיסוּר וְהֶיתֵּר, טוּמְאָה וְטַהֲרָה, לָא אִתְעַבָּר מעַמֵּי הָאָרֶץ. דְּמִסִּטְרַיְיהוּ לֵית בֵּין גָּלוּתָא לִימוֹת הַמָשִׁיחַ (לגבייהו) אֶלָּא שִׁעְבּוּד מַלְכִיּוֹת בִּלְבַד דְּאִינּוּן לָא טַעֲמִין מֵאִילָנָא דְּחַיִּי, וְצָּרִיךְ לוֹן מַתְנִיתִין בְּאִיסוּר וְהֵיתֵר טוּמְאָה וְטָהֳרָה. אֶלָּא יִהוֹן מְבוּזִים קֳדָם תַּלְמִידֵי חֲכָמִים, כְּגַוְונָא דַּחֲשׁוֹכָא קַמֵּי נְהוֹרָא, דְּעֵרֶב רַב אִינּוּן עַמֵּי הָאָרֶץ אִינּוּן חֲשׁוּכִין. וְלָא אִתְקְרִיאוּ יִשְׂרָאֵל, אֶלָּא עַבְדִּין זְבִינִין לְיִשְׂרָאֵל, בְּגִין דְּאִינּוּן כִּבְעִירִין. וְהָא אוּקְמוּהָ.","וְיִשְׂרָאֵל אִתְקְרִיאוּ אָדָם, וּמִנַיִן דְּאִית בְּהוֹן בְּעִירָא וְאָדָם. הֲדָא הוּא דִכְתִיב, (יחזקאל ל״ד:ל״א) וְאַתֵּן צֹּאנִי צֹּאן מַרְעִיתִי אָדָם אַתֶּם. וְאַתֵּן צֹּאנִי צֹּאן מַרְעִיתִי, אִינּוּן עַמֵּי הָאָרֶץ, טָבִין, מִסִּטְרָא דְּטוֹב. אָדָם אַתֶּם, תַּלְמִידֵי חֲכָמִים.","וּבִקְרָא דָּא נָמֵי רָמִיז לֵיהּ, (תהילים פ״א:י״ד) לוּ עַמִּי שׁוֹמֵעַ לִי יִשְׂרָאֵל וְגוֹ'. בָּתַר דְּאָמַר עַמִּי, אֲמַאי קָאָמַר יִשְׂרָאֵל. אֶלָּא עַמִּי: עַמֵּי הָאָרֶץ. יִשְׂרָאֵל: תַּלְמִידֵי חֲכָמִים. וּבְגִינַיְיהוּ אִתְּמַר (שמות י״ד:ח׳) וּבְנֵי יִשְׂרָאֵל יוֹצְּאִים בְּיָד רָמָה.","כְּגַוְונָא דְּפָלִיג לוֹן קוּדְשָׁא בְּרִיךְ הוּא בְּטוּרָא דְּסִינַי, הָכִי פָּלִיג לוֹן בְּפוּרְקָנָא בַּתְרַיְיתָא, דְּיִשְׂרָאֵל דְּאִתְּמַר בְּהוֹן, (שמות י״ג:י״ח) וַחֲמוּשִׁים עָלוּ בְּנֵי יִשְׂרָאֵל מֵאֶרֶץ מִצְּרָיִם. מִסִּטְרָא דְּאִילָנָא דְּחַיִּי, דְּאִינּוּן נ' שְׁנִין דְּיוֹבְלָא. אִתְּמַר בְּהוֹן, (שמות י״ט:י״ג) הֵמָּה יַעֲלוּ בָהָר. וּבְהוֹן (שמות י״ד:י״ט) וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהוֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל. וְלוֹן אִתְּמַר (שמות י״ט:ד׳) וָאֶשָּׂא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים, דְּאִינּוּן עֲנָנֵי כָּבוֹד. וָאָבִיא אֶתְכֶם אֵלָי. וּבְנֵי יִשְׂרָאֵל יוֹצְּאִים בְּיָד רָמָה, הָכִי יָפִיק לְתַּלְמִידֵי חֲכָמִים, בְּכָל הַאי יְקָר.","וּכְגַוְונָא דְּאִתְּמַר בְעַמֵי הָאָרֶץ מִסִּטְרָא דְּטוֹב, (שמות י״ט:י״ז) וַיִּתְיַצְּבוּ בְּתַחְתִּית הָהָר. הָכִי יְהוֹן בְּמַפְּקָנָא בַּתְרַיְיתָא, תְּחוֹת תַּלְמִידֵי חֲכָמִים, כְּעַבְדָא דְּאָזִיל לְרַגְלַיָּא דְּסוּסְיָא דְּמָארֵיהּ. וּכְגַוְונָא דְּאָמַר לוֹן בְּתַחְתִּית הָהָר, אִם תְּקַבְּלוּ תּוֹרָתִי מוּטָב, וְאִם לָאו שָׁם תְּהֵא קְבוּרַתְכֶם. הָכִי יִימָּא בְּמַפְּקָנוּ פּוּרְקָנָא בַּתְרַיְיתָא, אִם תְּקַבְּלוּן עֲלֵיכוֹן תַּלְמִידֵי חֲכָמִים בְּמַפְּקָנוּ דְּגָלוּתָא, כְּאָדָם דְּרָכִיב עַל סוּסְיָא, וְעַבְדָא דִּמְשַׁמֵּשׁ לֵיהּ מוּטָב. וְאִם לָאו תַּמָּן תְּהֵא קְבוּרַתְכֶם, בְּגָלוּתָא.","וְעֵרֶב רַב כְּגַוְונָא דְּאִתְּמַר בְּהוֹן, (שמות כ׳:ט״ו) וַיַּרְא הָעָם וַיָּנוּעוּ וַיַּעַמְדוּ מֵרָחוֹק. הָכִי יְהוֹן רְחִיקִין מִן פּוּרְקָנָא, וְיִחְמוּן לְתַּלְמִידֵי חֲכָמִים, וּלְעַמָא קַדִּישָׁא בְּכָל הַאי יְקָר, וְאִינּוּן רְחִיקִין מִינַּיְיהוּ. וְאִי בָּעוּ לְאִתְחַבְּרָא בַּהֲדַיְיהוּ מַה כְּתִיב בְּהוּ, (שמות י״ט:י״ג) לֹא תִגַּע בּוֹ יָד כִּי סָקוֹל יִסָּקֵל אוֹ יָרֹה יִיָּרֶה. בְּהַהוּא זִמְנָא יִתְקַיֵּים בְּהוּ בְּיִשְׂרָאֵל, (דברים ל״ב:י״ב) יְיָ בָּדָד יַנְחֶנּוּ וְאֵין עִמּוֹ אֵל נֵכָר, וְהָא אוּקְמוּהָ אֵין מְקַבְּלִין גֵּרִים לִימוֹת הַמָּשִׁיחַ. (שמואל א ב׳:ט׳) וּרְשָׁעִים בַּחֹשֶׁךְ יִדָּמוּ, אִינּוּן עֵרֶב רַב. וּבְגִין דָּא אָמַר נְבִיאָה עָלַיְיהוּ, (יחזקאל י״ג:ט׳) וְאֶל אַדְמַת יִשְׂרָאֵל לֹא יָבֹאוּ.","אָמַר אֵלִיָּהוּ, רַעְיָא מְהֵימָנָא, הָא שַׁעֲתָא אִיהִי לְסַלְּקָא לְעֵילָּא, בְּאוֹמָאָה אִימָּא אַנְתְּ, דְּהָא בְּגִינָךְ אֲנָא בָּעֵי לְסַלְּקָא. דְּיָהִיב לִי קוּדְשָׁא בְּרִיךְ הוּא רְשׁוּ, לְאִתְגַּלְיָיא לָךְ בְּבֵית אֲסוּרִים דִּילָךְ, בִּקְבוּרָה דִּילָךְ, וּלְמֶעְבַּד עִמָּךְ טִיבוּ, דְּאַנְתְּ מְחוֹלָל בְּחוֹבִין דְּעַמָּא. הֲדָא הוּא דִכְתִיב, (ישעיהו נ״ג:ה׳) וְהוּא מְחוֹלָל מִפְּשָׁעֵינוּ.","אָמַר לֵיהּ רַעְיָא מְהֵימָנָא, בְּאוֹמָאָה עֲלָךְ בִּשְׁמָא דִּיְדוָֹ\"ד, לָא תְּאַחֵר בְּכָל יְכוֹלְתָּךְ, דְּהָא אֲנָא בְּצַּעֲרָא סַגֵּי. (שמות ב׳:י״ב) וַיִּפֶן כֹּה וָכֹה וַיַּרְא כִּי אֵין אִישׁ, עוֹזִר לִי, לְאַפָּקָא לִי מֵהַאי צַּעֲרָא, בְּהַאי קְבוּרָה דְּאִתְּמַר עָלַי, (ישעיהו נ״ג:ט׳) וַיִּתֵּן אֶת הָרְשָׁעִים קִבְרוֹ, וְלָא אִשְׁתְּמוֹדְעָן בִּי, וַאֲנִי חָשִׁיב בְּעֵינַיְיהוּ בֵּין עֵרֶב רַב רַשִׁיעֲיָיא, כְּכֶּלֶב מֵת דְּסָּרַח בֵּינַיְיהוּ, דְּחָכְמַת סוֹפְרִים תִּסְרַח בֵּינַיְיהוּ, בְּכָל קַרְתָּא וְקַרְתָּא, וּבְכָל אֲתָר דְּיִשְׂרָאֵל מְפוּזָרִין בֵּינַיְיהוּ בֵּין מַלְכְּוָון. וְאִתְהַדְּרוּ אִינּוּן עֵרֶב רַב רַעְיָין עַל יִשְׂרָאֵל, עָאנָא דְקוּדְשָׁא בְּרִיךְ הוּא, דְּאִתְּמַר בְּהוּ (יחזקאל ל״ד:ל״א) וְאַתֵּן צֹּאנִי צֹּאן מַרְעִיתִי אָדָם אַתֶּם, וְלֵית לוֹן יְכוֹלֶת לְמֶעְבַּד טִיבוּ עִם תַּלְמִידֵי חֲכָמִים.","וְאַנְשֵׁי חַיִל וְיִרְאֵי חֵטְא מְסוֹבְבִים מֵעִיר לָעִיר וְלֹא יְחוֹנָנוּ, וּמַחֲרִימִין עֵרֶב רַב בֵּינַיְיהוּ. וְלָא יַהֲבִין לוֹן בְּאַתְרִין סַגִּיאִין אֶלָּא דָּבָר קָצּוּב, דְּלָא יְהֵא תְּקוּמָה לִנְפִילוּ דִּלְהוֹן, וַאֲפִילּוּ חַיִּי שָׁעָה. וְכָל חֲכָמִים וְאַנְשֵׁי חַיִל וְיִרְאֵי חֵטְא בְּצַּעֲרָא בְּדוֹחֲקָא בְּיַגוֹנָא, חֲשִׁיבִין כִּכְלָבִים. (איכה ד׳:ב׳) בָּנִים הַמְסוּלָאִים בַּפָּז אֵיכָה נֶחְשְׁבוּ לְנִבְלֵי חֶרֶשׂ בְּרֹאשׁ כָּל חוּצּוֹת. דְּלָא אַשְׁכָּחוּ אַכְסַנְיָא בֵּינַיְיהוּ.","וְאִינּוּן עֵרֶב רַב, אִינּוּן עֲתִירִין, בְּשַׁלְוָה, בְּחֶדְוָוא, בְּלָא צַּעֲרָא, בְּלָא יְגוֹנָא כְּלָל, גַּזְלָנִין מָארֵי שׁוֹחַד, דְּאִינּוּן דַּיָּינִין רֵישֵׁי עַמָּא. (בראשית ו׳:י״ג) כִּי מָלְאָה הָאָרֶץ חָמָס מִפְּנֵיהֶם, עָלַיְיהוּ אִתְּמַר (איכה א׳:ה׳) הָיוּ צָּרֶיהָ לְרֹאשׁ. בְּאוֹמָאָה עָלָךְ זִמְנָא תִּנְיָינָא, בְּחַי יְיָ צְּבָאוֹת אֱלֹהֵי יִשְׂרָאֵל יוֹשֵׁב הַכְּרוּבִים, דְּכָל אִלֵּין מִלִּין לָא יִפְּלוּן מִפּוּמָךְ, בְּכָל יְכָלְתָּךְ לְמַלְּלָא בְּהוֹן קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, וּלְאַחְזָאָה דּוֹחֲקָא דִּלְהוֹן. (ע\"כ רעיא מהימנא) (אמור פ\"ט ע\"א כי אם בתולה וכו')","(במדבר ו׳:ב׳) אִישׁ כִּי יַפְלִיא לִנְדּוֹר וְגוֹ'. רִבִּי אֶלְעָזָר פָּתַח, (ישעיהו נ׳:ב׳) מַדוּעַ בָּאתִי וְאֵין אִישׁ וְגוֹ'. מַדוּעַ בָּאתִי. כַּמָה חֲבִיבִין אִינּוּן יִשְׂרָאֵל קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, דִּבְכָל אֲתָר דְּאִינּוּן שַׁרְיָין, קוּדְשָׁא בְּרִיךְ הוּא אִשְׁתְּכַח בֵּינַיְיהוּ, בְּגִין דְּלָא אַעְדֵי רְחִימוּתָא דִּילֵיהּ מִנְּהוֹן, מַה כְּתִיב, (שמות כ״ה:ח׳) וְעָשׂוּ לִי מִקְדָּשׁ וְשָׁכַנְתִּי בְּתוֹכָם. וְעָשׂוּ לִי מִקְדָּשׁ סְתָם, דְּכָל בֵּי כְּנִישְׁתָּא דְּעָלְמָא מִקְדָּשׁ אִקְרֵי. וְהָא אוּקְמוּהָ. וּשְׁכִינְתָּא אַקְדִימַת לְבֵי כְּנִישְׁתָּא.","זַכָּאָה הַהוּא בַּר נָשׁ דְּאִשְׁתְּכַח מֵאִינּוּן עַשְׂרָה קַדְמָאָה בְּבֵי כְּנִישְׁתָּא, בְּגִין דִּבְהוּ אִשְׁתְּלִים מַה דְּאִשְׁתְּלִים, וְאִינּוּן מִתְקַדְּשֵׁי בְּקַדְמִיתָא בִּשְׁכִינְתָּא. וְהָא אִתְּמַר. וְהָא בַּעְיָא דְּיִשְׁתְּכָחוּ עַשְׂרָה בְּזִמְנָא חֲדָא בְּבֵי כְּנִישְׁתָּא. וְלָא יֵיתוּ פִּסְקֵי פִּסְקֵי, דְּלָא יִתְעַכֵּב שְׁלִימוּ דְּשַׁיְיפִין, דְּהָא בַּר נָשׁ בְּזִמְנָא חַד עָבֵד לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, וְאַתְקִין לֵיהּ כַּחֲדָא כָּל שַׁיְיפֵי, הֲדָא הוּא דִכְתִיב, (דברים ל״ב:ו׳) הוּא עָשְׂךָ וַיְכוֹנֲנֶךָ. (חסר וזהו הוא)","תָּא חֲזֵי, כֵּיוָן דְּבַּר נָשׁ אִשְׁתְּלִימוּ שַׁיְיפוֹי, בְּהַהוּא זִמְנָא אִתְתָּקַּן לְכָל שַׁיְיפָא וְשַׁיְיפָא כַּדְּקָא יָאוּת. כְּגַוְונָא דָּא, כֵּיוָן דִּשְׁכִינְתָּא אַקְדִּימַת לְבֵי כְּנִישְׁתָּא, בַּעְיָין עַשְׂרָה דְּיִשְׁתַּכְּחוּן תַּמָּן כַּחֲדָא, וְיִשְׁתְּלִים מַה דְּיִשְׁתְּלִים. וּלְבָתַר דְּאִתְתְּקַן כֹּלָּא. וּבְמָּה הִיא תִּיקוּנָא דְּכֹלָּא. כְּמָה דְאַתְּ אָמֵר (משלי י״ד:כ״ח) בְּרָב עָם הַדְרַת מֶלֶךְ, וְעַל דָּא עַמָּא דְּאַתְיָיאן לְבָתַר כֵּן, כֻּלְּהוּ תִּיקוּנָא דְּגוּפָא.","וְכַד אָתַת אַקְדִּימַת שְׁכִינְתָּא, וּבְנֵי נָשָׁא לָא אַתְיָיאן כַּחֲדָא כַּדְּקָא יָאוּת. קוּדְשָׁא בְּרִיךְ הוּא קָארֵי, מַדוּעַ בָּאתִי וְאֵין אִישׁ. מַאי וְאֵין אִישׁ. דְּלָא מִתְתַּקְּנֵי שַׁיְיפֵי, וְלָא אִשְׁתְּלִים גּוּפָא. דְּכַד גּוּפָא לָא אִשְׁתְּלִים, אֵין אִישׁ. וּבְגִין כָּךְ, וְאֵין אִישׁ דַּיְיקָא. וְתָּא חֲזֵי, בְּשַׁעֲתָא דְּגוּפָא אִשְׁתְּלִים לְתַתָּא, קְדוּשָׁה עִלָּאָה אַתְיָא וְעָאל בְּהַאי גּוּפָא, וְאִתְעָבִיד תַּתָּאָה, כְּגַוְונָא דִּלְעֵילָּא מַמָּשׁ. וּכְדֵין, כֹּלָּא בַּעְיָין דְּלָא יִפְתְּחוּן פּוּמָא בְּמִילֵּי דְּעָלְמָא. בְּגִין דְּהָא קַיְימֵי יִשְׂרָאֵל בִּשְׁלִימוּ עִלָּאָה, וּמִתְקַדְּשֵׁי בִּקְדוּשָּׁה עִלָּאָה, זַכָּאָה חוּלָקֵיהוֹן.","(במדבר ו') אִישׁ כִּי יַפְלִיא וְגוֹ'. מַאי כִּי יַפְלִיא. דְּאִתְפְּרַשׁ מִשְּׁאַר בְּנֵי עָלְמָא, לְאִתְקַדְּשָׁא כְּגַוְונָא דִּלְעֵילָּא, וּלְאִשְׁתַּכְּחָא שְׁלִים. בְּשַׁעֲתָא דְּבַר נָשׁ אָתֵי לְאִתְדַכְּאָה, מַדְכִּין לֵיהּ. בַּר נָשׁ דְּבָעֵי לְאִתְקַדְּשָׁא, מְקַדְּשִׁין לֵיהּ. וּפַרְסֵי עָלֵיהּ קְדוּשָּׁה דִּלְעֵילָּא, קְדוּשָּׁה דְּאִתְקְדַּשׁ בָּהּ קוּדְשָׁא בְּרִיךְ הוּא. (חסר)","רִבִּי אַבָּא פָּתַח, (תהילים ק״ג:א׳) לְדָוִד בָּרְכִי נַפְשִׁי אֶת יְיָ וְכָל קְרָבַי אֶת שֵׁם קָדְשׁוֹ. כַּמָּה אִית לֵיהּ לְבַר נָשׁ לְאִסְתַּכְּלָא וּלְמִנְדַּע בְּפוּלְחָנָא דְּמָארֵיהּ, דְּהָא בְּכָל יוֹמָא וְיוֹמָא כָּרוֹזָא קָארֵי וְאָמַר, (משלי א׳:כ״ב) עַד מָתַי פְּתָאִים תְּאֶהֲבוּ פֶתִי וְגוֹ'. (ירמיהו ג׳:כ״ב) שׁוּבוּ בָּנִים שׁוֹבָבִים אֶרְפָּא מְשׁוּבוֹתֵיכֶם. וְלֵית מַאן דְּיַרְכִּין אוּדְנֵיהּ, אוֹרַיְיתָא קָא מַכְרְזָא קַמַּיְיהוּ, וְלֵית מַאן דְּיַשְׁגַּח.","תָּא חֲזֵי, בַּר נָשׁ אָזִיל בְּהַאי עָלְמָא, וְהוּא חָשִׁיב דְּדִילֵיהּ הוּא תָּדִיר וְיִשְׁתְּאַר בְּגַוִיהּ לְדָרֵי דָּרִין, עַד דְּאִיהוּ אָזִיל בְּעָלְמָא, יָהֲבִין לֵיהּ בְּקוּלְרָא, עַד דְּאִיהוּ יְתִיב, דַּיְינִין לֵיהּ בְּקִינְפּוֹן עִם שְׁאַר בְּנֵי דִּינָא. אִי אִשְׁתְּכַח לֵיהּ סַנֵיגוֹרָא, הָא אִשְׁתְּזִיב מִן דִּינָא. הֲדָא הוּא דִכְתִיב, (איוב ל״ג:כ״ג-כ״ד) אִם יֵשׁ עָלָיו מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף לְהַגִּיד לְאָדָם יָשְׁרוֹ וַיְחֻנֶּנּוּ וַיֹּאמֶר וְגוֹ'. מַאן הוּא סַנֵיגוֹרָא. אִלֵּין עוֹבָדִין דְּכַשְׁרָן, דְּקַיְימֵי עָלֵיהּ דְּבַּר נָשׁ בְּשַׁעֲתָא דְּאִצְטְרִיךְ לֵיהּ."],[[0,"אמר ר׳ יהודה","וכו׳: אר״י, שערות ראשה של האשה שנגלו גורמים לשער אחר להתגלות, דהיינו כחות הסטרא אחרא הנאחזים בשערות, ולפגום אותה, משום זה צריכה האשה שאפילו קורות ביתה לא יראו שער אחד מראשה, כל שכן לחוץ. \u0003טסירי\u0004 פירושו קורות. לפי הענין."],[1,"ת״ח כמה בדכורא","וכו׳: בוא וראה, כמו בזכר, נמצאות השערות, קשים מכל. שהם דינים, כן הוא בנקבה, צא וראה כמה פגמים גורמות שערות של האשה, גורמות למעלה, גורמות למטה. גורמות לבעלה שיתקלל. גורמות עניות. גורמות דבר אחר בבית. דהיינו צרעת. גורמות לסלוק חשיבות מבניה. הרחמן יצילנו מחוצפה שלהם."],[2,"וע״ד בעיא אתתא","וכו׳: וע״כ צריכה האשה להתכסות בזויות הבית. ואם עושה כן, מה כתוב, בניך כשתילי זיתים. מהו כשתילי זיתים. היינו מה זית זה בין בחורף ובין בקיץ אינו מאבד עליו, ותמיד נמצאת בו חשיבות יותר מהשאר אילנות, כך בניה יתעלו בחשיבות על שאר בני העולם. ולא עוד אלא שבעלה מתברך בכל, בברכות שלמעלה ובברכות שלמטה, בעושר בבנים ובבני בנים. ז״ש הנה כי כן יבורך גבר ירא ה׳. וכתוב, יברכך ה׳ מציון וראה בטוב ירושלים כל ימי חייך וראה בנים לבניך שלום על ישראל."],[3,"אליהו קום אפתח","וכו׳: אליהו, קום פתח עמי במצות, כי אתה עוזר לי בכל צד, כי עליך נאמר בתחילה, פנחס בן אלעזר בן אהרן הכהן, ופנחס זה הוא אליהו, ובן אהרן, ודאי שהוא אח שלו. אח לצרה יולד."],[4,"פתח ואמר פקודא לדון","וכו׳: פו״א מצוה לדון בדיני סוטה, ז״ש ועבר עליו רוח קנאה וקנא וגו׳. ודאי רוח הטומאה נמצא מב׳ צדדים, א׳ בשקר, וא׳ באמת. משום זה, ברוח שקר, וקנא את אשתו והיא לא נטמאה. והשני, ועבר עליו וגו׳ וקנא את אשתו והיא נטמאה."],[5,"וכי אית קושטא","וכו׳: שואל, וכי יש אמת ברוח הטומאה. ומשיב. אלא באדם שהוא מצד עץ טוב ורע, שם יש יצר הרע, נחש. בזמן שיש לו לאדם אשה יפה שהיא הנשמה, בכל מעשים טובים, שנאמר בה אשת חיל עטרת בעלה, יש ליצר הרע קנאה, כמו שמצאנו שהנחש קנא את אדם על אשתו עד שפיתה אותה וגרם לה מיתה. ולפעמים שולט עליה בחטאים ומטמא אותה, והיא נעשית נבלה."],[6,"ויצר הרע מסטרא","וכו׳: ויצה״ר, מצד הימין שלו, שהוא מדרגת ישמעאל, הוא נקרא נחש. ומצד השמאל, שהוא מדרגת עשו שהוא סמאל, נקרא כלב, שהוא הממונה של גיהנם שצועק ונובח הב הב. ז״ש לעלוקה שתי בנות הב הב. וברצונו לשרוף הנשמה שנטמאה, באש שלו, בגיהנם. וזהו, ועבר עליו רוח קנאה וקנא את אשתו, \u0003באמת,\u0004 והיא נטמאה. ולפעמים מקטרג עליה \u0003בשקר,\u0004 שהיא לא נטמאה."],[7,"ובגינה אתמר ובת","וכו׳: ובשבילה נאמר, ובת איש כהן, שזה מיכאל, שהוא חסד, והנשמה היא בתו, כי תחל לזנות את אביה היא מחללת באש תשרף. ושם נשרפת הזוהמא ההיא שבה, והיא מתלבנת ממנו, כמו כסף המתלבן באש, והעופרת שהיא הפסולת נשרפת ונעשית עפר ונאבדת."],[8,"כגוונא דא בישראל","וכו׳: כעין זה בישראל, כשמחללים התורה הקב״ה מכניסם בגלות של בני עשו ובני ישמעאל תחת השעבוד שלהם, שמדרגתם היא כלב ונחש, ונדונים שם. ובהם יתבררו ויתלבנו ויצורפו כצרוף הכסף וכבחון הזהב. ז״ש וצרפתים כצרף את הכסף ובחנתים כבחן את הזהב. עד שיתקיים בהם, אם יהיו חטאיכם כשנים כשלג ילבינו."],[9,"ואילנא דטוב ורע","וכו׳: ואילן טוב ורע בשבילו נאמר, ויורהו ה׳ עץ וישלך אל המים וימתקו המים וגו׳. משום שהיו ישראל מעורבים עם ערב רב, היו כולם אילן טוב ורע, ועל כן, חציו מתוק, מצד הימין, וחציו מר, מצד השמאל. ובזמן שהערב רב היו מחטיאים את ישראל, היו, כאלו היו כולם מצד הרע. וע״כ המים הוחזרו להיות מרים כאותו עץ מר שהשליך במים. ז״ש ויבאו מרתה ולא יכלו לשתות מים ממרה כי מרים הם."],[10,"והאי עץ מר","וכו׳: ועץ מר הזה, שהשליך תוך המים, היה כאפן הנסיון של הסוטה, אם סטתה תחת בעלה, אלו המים שהשקוה חזרו להיות מרים, ובהם וצבתה בטנה ונפלה ירכה, ואם לא סטתה, מה כתוב, ונקתה ונזרעה זרע ומולידה בן. אף כאן וימתקו המים."],[10,"","פירוש. כי הבדיקה דסוטה היתה שהשליך שם בחינת הדין דמנעולא, שה״ס כתיבת הויה למפרע, ונתעברה בהויה דיושר שה״ס בינה, אשר אם היתה דבוקה באשת זנונים, לא היה המנעולא מתערב בבינה ולא נמתק בה, ואז היו אורות הרחמים מסתלקים והדין דמנעולא פעל בה, ואז וצבתה בטנה ונפלה ירכה. ואם לא סטתה תחת בעלה, והיתה דבוקה באשת חיל, אז נמתק המנעולא בבינה ונגנזה, והמפתחא נגלה ושלט ואז ונקתה ונזרעה זרע, (כנ״ל אות ס״ד ע״ש) אף כאן, ויורהו ה׳ עץ, הוא \u0003עץ מר,\u0004 דהיינו מבחינת המנעולא, שכל אותם שהיו דבוקים בימין, נכללו בבינה ונמתקו המים. וכל אותם שהיו דבוקים בשמאל נפרדו מהם מחמת שעליהם פעלה מדת הדין דמנעולא, ונתבטלו. וישראל יצאו טהורים."],[11,"כגוונא דא יתעביד","וכו׳: כעין זה יעשה לנסות ישראל בגאולה האחרונה. ז״ש יתבררו ויתלבנו ויצרפו רבים, שהם מצד הטוב, ועומדים בנסיון. והרשיעו רשעים, שהם מצד הרע, ויתקיים בהם ואל אדמת ישראל לא יבאו, והורג אותם."],[12,"והמשכילים יבינו מסטרא","וכו׳: ואז, והמשכילים יבינו. כי הם מצד הבינה, שהוא עץ החיים, בשבילם נאמר, והמשכילים יזהירו כזהר הרקיע, בחבור הזה שלך, של רשב״י, שהוא ספר הזהר, מזוהר של אמא עלאה, שנקראת תשובה, אלו לא צריכים נסיון, ומשום שעתידים ישראל לטעום מעץ החיים שהוא ספר הזהר הזה, יצאו בו מן הגלות ברחמים, ויתקיים בהם, ה׳ בדד ינחנו ואין עמו אל נכר."],[13,"ואילנא דטוב ורע","וכו׳: ועץ הדעת טוב ורע, שהוא איסור והיתר טומאה וטהרה, לא ישלוט יותר על ישראל, כי הפרנסה שלנו לא תהיה אלא מצד עץ החיים, שאין שם, לא קשיא, שהוא מצד הרע, ולא מחלוקת מרוח הטומאה, כי כתוב, ואת רוח הטומאה אעביר מן הארץ."],[14,"דלא יתפרנסון ת״ח","וכו׳: שלא יתפרנסו תלמידי חכמים מעמי הארץ, אלא מצד הטוב, שאוכלים טהרה כשר היתר, ולא מערב רב, שאוכלים טומאה פסול איסור, שהם טמאים המטמאים עצמם בנדה שפחה גויה זונה. משום שהם בניה של לילית, שהיא נדה שפחה גויה זונה, וחוזרים לשרשם. ועליהם נאמר, כי משרש נחש יצא צפע."],[15,"ובזמנא דאילנא טוב ורע","וכו׳: ובזמן שאילן טוב ורע שולט, שהוא חולין דטהרה וחולין דטומאה, אלו החכמים הדומים לשבתות ויום טוב, אין להם אלא מה שנותנים להם אלו אנשי חולין כמו יום השבת שאין לו אלא מה שמתקנים לו בימי חול."],[16,"ובזמנא דשלטא אילנא","וכו׳: ובזמן ששולט עץ החיים נכנע האילן של טוב ורע, ולא יהיה לעמי הארץ אלא מה שיתנו להם תלמידי חכמים, ונכנעים תחתיהם עמי הארץ, כמו שלא היו בעולם."],[17,"והכי איסור והיתר","וכו׳: וכך, איסור והיתר וטומאה וטהרה לא יעברו מעמי הארץ, כי מצדם אין בין הגלות לימות המשיח אלא שעבוד מלכיות בלבד. כי הם אינם טועמים מעץ החיים שיתגלה לימות המשיח, והם צריכים משנה, באיסור והיתר וטומאה וטהרה. אלא שיהיו מבוזים לפני תלמיד חכם כמו חושך לפני אור. כי הערב רב, הם עמי הארץ שהם חשך, ולא נקראו ישראל אלא עבדים מכורים לישראל, משום שהם כבהמות. וכבר העמידוהו."],[18,"וישראל אתקריאו אדם","וכו׳: וישראל נקראים אדם. ומאין לנו שיש בישראל בהמה ואדם, ז״ש ואתן צאני צאן מרעיתי אדם אתם. \u0003ואתן צאני צאן מרעיתי,\u0004 אלו הם עמי הארץ, שהם טובים מצד הטוב. \u0003אדם אתם,\u0004 היינו תלמידי חכמים."],[19,"ובקרא דא נמי","וכו׳: וגם במקרא הזה רומז לזה. שכתוב, לו עמי שומע לי ישראל וגו׳. אחר שאמר \u0003עמי,\u0004 למה אמר \u0003ישראל.\u0004 אלא עמי, הם עמי הארץ. ישראל, הם תלמידי חכמים. ובשבילם נאמר, ובני ישראל יוצאים ביד רמה."],[20,"כגוונא דפליג לון","וכו׳: כמו שחלק אותם הקב״ה בהר סיני, כך יחלוק אותם בגאולה אחרונה. כי ישראל נאמר בהם, וחמושים עלו בני ישראל מארץ מצרים. וחמושים, פירושו מצד עץ החיים שהוא ז״א, שהם חמשים שנה של יובל, שהוא בינה, שז״א מקבלם מבינה, ונאמר בהם, המה יעלו בהר. ובהם ויסע מלאך האלקים ההולך לפני מחנה ישראל. ולהם נאמר, ואשא אתכם על כנפי נשרים, שהם ענני כבוד, ואביא אתכם אלי וכן, ובני ישראל יוצאים ביד רמה. כך יוציא את תלמידי החכמים בכל הכבוד הזה."],[21,"וכגוונא דאתמר בע״ה","וכו׳: וכמו שנאמר בעמי הארץ מצד הטוב, ויתיצבו בתחתית ההר, כך יהיו בגאולה האחרונה, תחת תלמידי החכמים, כעבד שהולך לרגלי הסוס של אדונו. וכמו שנאמר להם בתחתית ההר, אם תקבלו את התורה מוטב, ואם לאו, שם תהא קבורתכם, כך יאמר להם בגאולה האחרונה, אם תקבלו עליכם תלמיד חכם ביציאה מן הגלות כמו אדם הרוכב על סוס, ועבד המשמש לו, מוטב, ואם לא, שם, בגלות, תהא קבורתכם."],[22,"וערב רב כגוונא","וכו׳: וערב רב, הם, כמו שנאמר בהם, וירא העם וינועו ויעמדו מרחוק, כך יהיו רחוקים מן הגאולה ויראו את תלמידי החכמים והעם הקדוש בכל הכבוד הזה, והם יהיו רחוקים מהם, ואם ירצו להתחבר עמהם, מה כתוב בהם, לא תגע בו יד כי סקול יסקל או ירה יירה. בזמן ההוא נתקיים בהם בישראל, ה׳ בדד ינחנו ואין עמו אל נכר. וכבר העמידוהו, אין מקבלים גרים לימות המשיח. ורשעים בחשך ידמו, אלו הם ערב רב, ומשים זה אמר הנביא עליהם, ואל אדמת ישראל לא יבאו."],[23,"אמר אליהו","וכו׳: אמר אליהו לרעיא מהימנא. רעיא מהימנא, הרי השעה היא לעלות למעלה, ולהביא הגאולה השלמה, אמור אתה עלי בשבועה, כלומר שתשביעני למהר הגאולה. כי בשבילך אני רוצה לעלות. כי נתן לי הקב״ה רשות להתגלות לך בבית האסורים שלך, בקבורה שלך, ולעשות עמך טוב, כי אתה מחולל מעונות העם. שכמו בבית האסורים הוא ביניהם, ז״ש, והוא מחולל מפשעינו."],[24,"א״ל רעיא מהימנא","וכו׳: אמר לו רעיא מהימנא, בשבועה עליך בשם הוי״ה, שלא תאחר הגאולה בכל יכלתך, כי אני נמצא בצער רב. כי עלי כתוב, ויפן כה וכה וירא כי אין איש, עוזר לי. להוציאני מצער הזה מקבורה הזו, שנאמר עלי ויתן את רשעים קברו, ואינם מכירים אותי ואני נחשב בעיניהם בין הערב רב הרשעים, ככלב מת שסרח ביניהם, כי חכמת סופרים תסרח ביניהם בכל עיר ועיר, ובכל מקום שישראל מפוזרים ביניהם בין המלוכות. ונעשו הערב רב רועים על ישראל, שהם צאן הקב״ה, שנאמר עליהם ואתן צאני צאן מרעיתי אדם אתם. ואין להם יכולת לעשות טוב עם ת״ח."],[24,"","פירוש. כי משה רבינו שנקרא רעיא מהימנא, ה״ס התורה ודעת הפנימי, שלא תתגלה אלא בגאולה השלמה, ועד אז נאמר עליו והוא מחולל מפשעינו. כי התורה שה״ס רעיא מהימנא, נתחוללה ונעשתה חללה, כי נעלמה הפנימיות שבה, ולא נשארה לנו רק החצוניות. \u0003ואני חשיב בעינייהו בין ערב רב רשיעייא ככלב מת שסרח,\u0004 כלומר שהם מתרחקים מפנימיות התורה כמו שמתרחקים מסרחון. שעליה אמרו, וחכמת חכמים תסרח."],[25,"ואנשי חיל ויראי","וגו׳: ואנשי חיל ויראי חטא מסובבים מעיר לעיר ולא יחוננו, והערב רב מחרימים אותם ביניהם. ובמקומות רבים אין נותנים להם רק דבר קצוב באפן שלא תהיה תקומה לנפילה שלהם, ואפילו חיי שעה. וכל החכמים ואנשי חיל ויראי חטא נמצאים בצער בדוחק וביגון, ונחשבים ככלבים. בנים המסולאים בפז איכה נחשבו לנבלי חרש בראש כל חוצות. שאינם מוצאים אכסניא ביניהם."],[26,"ואינון ערב רב","וכו׳: ואלו הערב רב, הם עשירים, בשלוה, בשמחה, בלי צער, ובלי יגון כלל, גזלנים בעלי שוחד, שהם דיינים ראשי העם. כי מלאה הארץ חמס מפניהם, עליהם נאמר, היו צריה לראש. אמר רעיא מהימנא לאליהו, בשבועה עליך, פעם שנית, בחי ה׳ צבאות אלקי ישראל יושב הכרובים, שכל אלו הדברים לא יפלו מפיך ובכל יכלתך תאמר אותם לפני הקב״ה, ולהראות הדחק שלהם. (ע״כ רעיא מהימנא)."],[27,"איש כי יפליא לנדור","וגו׳: ר׳ אלעזר פתח, מדוע באתי ואין איש וגו׳. \u0003מדוע באתי,\u0004 כמה אהובים הם ישראל לפני הקב״ה, שבכל מקום שהם שורים הקב״ה נמצא ביניהם, משום שאינו מסיר מהם האהבה שלו. מה כתוב, ועשו לי מקדש ושכנתי בתוכם. ועשו לי מקדש, הוא סתם מקדש, כי כל בית הכנסת שבעולם נקרא מקדש. וכבר העמידוהו. ושכנתי בתוכם, כי השכינה מקדמת לבית הכנסת."],[28,"זכאה ההוא ב״נ","וכו׳: אשרי הוא האדם הנמצא מאלו עשרה הראשונים בבית הכנסת, משום שבהם נשלם מה שנשלם דהיינו העדה. שאינו פחות מעשרה. והם מתקדשים תחילה בשכינה. וכבר למדנו. וצריכים שיהיו נמצאים עשרה בבית הכנסת בבת אחת, ולא יבואו קצתם קצתם, כדי שלא יתעכב שלמות האברים. כי כל העשרה הם כאברים של גוף אחד שבהם שורה השכינה. כי האדם בפעם אחת עשה אותו הקב״ה, והתקין לו כל האברים ביחד. ז״ש, הוא עשך ויכוננך."],[29,"ת״ח כיון דב״נ","וכו׳: בוא וראה, כיון שנשלמו כל אבריו של האדם, בזמן ההוא, נתתקן כל אבר ואבר בפני עצמו כראוי. כעין זה, כיון שהשכינה הקדימה לבית הכנסת צריכים שימצאו שם עשרה ביחד, ואז נשלם מה שנשלם, כי אין עדה פחות מעשרה. שהם כנגד ע״ס המלכות. וכל עוד שאין שם עשרה ביחד אף אחד מהם אינו נשלם. ולאחר כך מתתקן הכל, דהיינו תקון כל העדה, ובמה הוא תקון הכל, היינו כמ״ש ברב עם הדרת מלך. וע״כ העם הבא אחר עשרה הראשונים, כולם תקון הגוף הוא, כלומר תקון העדה. כי רבוי העם מגדיל כבוד המלך."],[30,"וכד אתת אקדימת","וכו׳: וכשהשכינה מקדמת ובאה, ובני אדם עוד לא באו עשרה ביחד כראוי. הקב״ה קורא, מדוע באתי ואין איש. מהו ואין איש. היינו שהאברים לא נתתקנו, ולא נשלם הגוף הנקרא עדה, כי כשהגוף לא נשלם, אין איש. היינו שגם אברים הפרטים שכבר באו, אינם נשלמים. ומשום, זה \u0003ואין איש\u0004 הוא בדיוק. ובוא וראה, בשעה שהגוף נשלם למטה, דהיינו שיש עשרה ביחד, באה קדושה העליונה ונכנסת בגוף ההוא ונעשה התחתון כעין עשר ספירות של מעלה ממש. אז כולם צריכים, שלא יפתחו פיהם לדבר בדברי העולם, משום שישראל נמצאים עתה בשלמות העליון, ומתקדשים בקדושה העליונה. אשרי חלקם."],[31,"איש בי יפליא","וגו׳: שואל, מהו כי יפליא. ומשיב, היינו שנפרש משאר בני העולם, להתקדש כעין של מעלה, ולהמצא שלם. בשעה שאדם בא לטהר מטהרים אותו. אדם הבא להתקדש מקדשים אותו, ופורשים עליו קדושה שלמעלה, קדושה שהקב״ה נתקדש בה."],[32,"ר׳ אבא פתח","וכו׳: רא״פ, לדוד ברכי נפשי את ה׳ וכל קרבי את שם קדשו. כמה יש לבן אדם להסתכל ולדעת בעבודת אדונו, כי בכל יום ויום הכרוז קורא ואמר, עד מתי פתאים תאהבו פתי וגו׳. שובו בנים שובבים ארפא משובותיכם. ואין מי שיטה אזנו. התורה מכרזת לפניהם ואין מי שישגיח."],[33,"ת״ח בר נש","וכו׳: בוא וראה, אדם הולך בעולם הזה, והוא חושב ששלו הוא תמיד, וישאר בו לדורי דורות. ובעוד שהוא הולך בעולם, נותנים אותו בכבלים, דהיינו שנחלה ונקשר אל מטתו. ובעוד שהוא יושב כך, דנים אותו בחברת שאר בני הדין. אם נמצא לו מליץ טוב, הוא ניצול מן הדין. ז״ש אם יש עליו מלאך מליץ אחד מני אלף להגיד לאדם ישרו ויחננו ויאמר וגו׳. מי הוא מליץ טוב, אלו הם מעשים הטובים העומדים לאדם בשעה שצריך להם. קינפון פירושו חבורה ומקום קבוץ. מלשון שעומדים עליו בקנפון (כלים כ״ג)."]],[[0,"","אָמַר רַבִּי יְהוּדָה, שְׂעַר רֹאשׁ הָאִשָּׁה שֶׁמִּתְגַּלֶּה, גּוֹרֵם לְשֵׂעָר אַחֵר לְהִתְגַּלּוֹת וְלִפְגֹּם אוֹתָהּ. מִשּׁוּם כָּךְ צְרִיכָה אִשָּׁה שֶׁאֲפִלּוּ קוֹרוֹת בֵּיתָהּ לֹא יִירְאוּ שַׂעֲרָה אַחַת מֵרֹאשָׁהּ, וְכָל שֶׁכֵּן בַּחוּץ."],[1,"","בֹּא רְאֵה, כְּמוֹ שֶׁבַּזָּכָר הַשֵּׂעָר הוּא חֻמְרַת הַכֹּל - כָּךְ גַּם לַנְּקֵבָה. צֵא וּרְאֵה כַּמָּה פְגָם גּוֹרֵם אוֹתוֹ שְׂעַר הָאִשָּׁה: גּוֹרֵם לְמַעְלָה וְגוֹרֵם לְמַטָּה, גּוֹרֵם לְבַעְלָהּ לְהִתְקַלֵּל, גּוֹרֵם עֹנִי, וְגוֹרֵם דָּבָר אַחֵר בַּבַּיִת, גּוֹרֵם שֶׁתִּסְתַּלֵּק חֲשִׁיבוּת מִבָּנֶיהָ. הָרַחֲמָן יַצִּילֵנוּ מֵחֲצִיפוּתָן."],[2,"","וְעַל כָּךְ צְרִיכָה אִשָּׁה לְהִתְכַּסּוֹת בְּזָוִיּוֹת בֵּיתָהּ. וְאִם עוֹשָׂה כָּךְ, מַה כָּתוּב? (תהלים קכח) בָּנֶיךְ כִּשְׁתִלֵי זֵיתִים. מַה זֶּה כִּשְׁתִלֵי זֵיתִים? מַה זַּיִת זֶה, בֵּין בַּסְּתָו בֵּין בַּקַּיִץ לֹא אוֹבְדִים עָלָיו, וְתָמִיד נִמְצֵאת בּוֹ חֲשִׁיבוּת יְתֵרָה עַל שְׁאָר הָאִילָנוֹת - כָּךְ בָּנֶיהָ יַעֲלוּ בַחֲשִׁיבוּת עַל שְׁאָר בְּנֵי הָעוֹלָם. וְלֹא עוֹד, אֶלָּא שֶׁבַּעְלָהּ מִתְבָּרֵךְ בַּכֹּל: בַּבְּרָכוֹת שֶׁלְּמַעְלָה, בַּבְּרָכוֹת שֶׁלְּמַטָּה, בְּעֹשֶׁר, בְּבָנִים וּבִבְנֵי בָנִים. זֶהוּ שֶׁכָּתוּב (שם) הִנֵּה כִּי כֵן יְבֹרַךְ גָּבֶר יְרֵא ה'. וְכָתוּב, יְבָרֶכְךְ ה' מִצִּיּוֹן וּרְאֵה בְּטוּב יְרוּשָׁלם כֹּל יְמֵי חַיֶּיךְ וּרְאֵה בָנִים לְבָנֶיךְ שָׁלוֹם עַל יִשְׂרָאֵל. (ישראל הזקן הקדוש)"],[3,"","אֵלִיָּהוּ, קוּם פְּתַח אִתִּי בְּמִצְווֹת, שֶׁאַתָּה הוּא עוֹזֵר לִי בְּכָל צַד, שֶׁהֲרֵי עָלֶיךְ נֶאֱמַר בַּתְּחִלָּה, (במדבר כה) פִּינְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן. וּבֶן אַהֲרֹן הוּא וַדַּאי אָח שֶׁלִּי, אָח לְצָרָה יִוָּלֵד."],[4,"","פָּתַח וְאָמַר, מִצְוָה לָדוּן בְּדִינֵי סוֹטָה, זֶהוּ שֶׁכָּתוּב וְעָבַר עָלָיו רוּחַ קִנְאָה וְקִנֵּא וְגוֹ'. וַדַּאי רוּחַ קִנְאָה נִמְצֵאת בִּשְׁנֵי צְדָדִים, אֶחָד בְּשֶׁקֶר וְאֶחָד בֶּאֱמֶת, בִּגְלַל זֶה, בְּרוּחַ שֶׁקֶר - וְקִנֵּא אֶת אִשְׁתּוֹ, וְהִיא לֹא נִטְמָאָה. וְלָמַדְנוּ, וְעָבַר עָלָיו וְגוֹ', וְקִנֵּא אֶת אִשְׁתּוֹ וְהִיא נִטְמָאָה."],[5,"","וְכִי יֵשׁ אֱמֶת בְּרוּחַ טֻמְאָה? אֶלָּא בָּאָדָם מִצַּד עֵץ טוֹב וָרָע, שָׁם יֵצֶר הָרָע, נָחָשׁ. בִּזְמַן שֶׁיֵּשׁ לָאָדָם אִשָּׁה יָפָה בְּכָל מַעֲשִׂים טוֹבִים, שֶׁנֶּאֱמַר בָּהּ (משלי יב) אֵשֶׁת חַיִל עֲטֶרֶת בַּעְלָהּ, לַיֵּצֶר הָרָע יֵשׁ קִנְאָה, כְּמוֹ שֶׁלָּמַדְנוּ שֶׁקִּנֵּא אָדָם עַל אִשְׁתּוֹ, עַד שֶׁפִּתָּה אוֹתָהּ וְגָרַם לָהּ מִיתָה. וְלִפְעָמִים שׁוֹלֵט עָלֶיהָ בַּעֲבֵרוֹת וּמְטַמֵּא אוֹתָהּ וְנַעֲשֵׂית נְבֵלָה."],[6,"","וְיֵצֶר הָרָע מִצַּד יָמִין שֶׁלּוֹ, דַּרְגַּת יִשְׁמָעֵאל, נִקְרָא נָחָשׁ. וּמִצַּד שְׂמֹאלוֹ דַּרְגַּת עֵשָׂו, סָמָאֵ\"ל, נִקְרָא כֶּלֶב, מְמֻנֶּה שֶׁל גֵּיהִנֹּם שֶׁצּוֹוֵחַ הַב הַב. זֶהוּ שֶׁכָּתוּב (משלי ל) לַעֲלוּקָה שְׁתֵּי בָנוֹת הַב הַב. וּבִרְצוֹנוֹ לֶאֱכֹל נְשָׁמָה טְמֵאָה בָּאֵשׁ שֶׁלּוֹ, גֵּיהִנֹּם. וְעָבַר עָלָיו רוּחַ טֻמְאָה וְקִנֵּא אֶת אִשְׁתּוֹ בֶּאֱמֶת, וְהִיא נִטְמָאָה."],[7,"","וּבִגְלָלָהּ נֶאֱמַר, (ויקרא כא) וּבַת אִישׁ כֹּהֵן - זֶה מִיכָאֵל - כִּי תֵחֵל לִזְנוֹת אֶת אָבִיהָ הִיא מְחַלֶּלֶת בָּאֵשׁ תִּשָּׂרֵף. וְשָׁם נִשְׂרֶפֶת אוֹתָהּ זֻהֲמָא, וּמִתְלַבֶּנֶת הִיא מִמֶּנּוּ כְּכֶסֶף שֶׁמִּתְלַבֵּן בָּאֵשׁ, וְאוֹתָהּ עֹפֶרֶת שֶׁל זֻהֲמָא נִשְׂרֶפֶת, וְנַעֲשֵׂית עָפָר וְנֶאֱבֶדֶת."],[8,"","כְּמוֹ זֶה יִשְׂרָאֵל, כְּשֶׁהֵם מְחַלְּלִים אֶת הַתּוֹרָה, הַקָּדוֹשׁ בָּרוּךְ הוּא מַכְנִיס אוֹתָם לְגָלוּת בְּנֵי עֵשָׂו וּבְנֵי יִשְׁמָעֵאל שֶׁתַּחַת שִׁעְבּוּדָם, שֶׁדַּרְגָּתָם כֶּלֶ\"ב וְנָחָ\"שׁ, וְנִדּוֹנִים שָׁם, וּבָהֶם יִתְבָּרְרוּ וְיִתְלַבְּנוּ וִיצֹרְפוּ כִּצְרֹף הַכֶּסֶף וְכִבְחֹן הַזָּהָב. זֶהוּ שֶׁכָּתוּב (זכריה יג) וּצְרַפְתִּים כִּצְרֹף אֶת הַכֶּסֶף וּבְחַנְתִּים כִּבְחֹן אֶת הַזָּהָב, עַד שֶׁיִּתְקַיֵּם בָּהֶם, (ישעיה א) אִם יִהְיוּ חֲטָאֵיכֶם כַּשָּׁנִים כַּשֶּׁלֶג יַלְבִּינוּ."],[9,"","וְעֵץ טוֹב וָרָע, בִּגְלָלוֹ נֶאֱמַר (שמות טו) וַיּוֹרֵהוּ ה' עֵץ וַיַּשְׁלֵךְ אֶל הַמַּיִם וַיִּמְתְּקוּ הַמָּיִם וְגוֹ'. מִשּׁוּם שֶׁהָיוּ יִשְׂרָאֵל עִם עֵרֶב רַב, כֻּלָּם הָיוּ עֵץ שֶׁל טוֹב וָרָע, וְעַל זֶה חֶצְיוֹ מָתוֹק מִצַּד יָמִין, וְחֶצְיוֹ מַר מִצַּד שְׂמֹאל. וּבִזְמַן שֶׁעֵרֶב רַב הָיוּ מַחֲטִיאִים אֶת יִשְׂרָאֵל, הָיָה כְּאִלּוּ הָיוּ כֻלָּם מִצַּד הָרָע, וְהַמַּיִם חָזְרוּ לִהְיוֹת מְרִירִים כְּמוֹ אוֹתוֹ עֵץ מַר בַּמַּיִם. זֶהוּ שֶׁכָּתוּב וַיָּבֹאוּ מָרָתָה וְלֹא יָכְלוּ לִשְׁתּוֹת מַיִם מִמָּרָה כִּי מָרִים הֵם."],[10,"","וְעֵץ מַר זֶה הוּא כְּמוֹ נִסְיוֹן הַסּוֹטָה. אִם סָטְתָה תַּחַת בַּעְלָהּ, אוֹתָם מַיִם שֶׁמַּשְׁקִים אוֹתָם חוֹזְרִים לִהְיוֹת מְרִירִים, וּבָהֶם צָבְתָה בִטְנָהּ וְנָפְלָה יְרֵכָהּ. וְאִם לֹא סָטְתָה, מַה כָּתוּב? וְנִקְּתָה וְנִזְרְעָה זָרַע, וּמוֹלִידָה בֵּן. אַף כָּאן וַיִּמְתְּקוּ הַמָּיִם."],[11,"","כְּמוֹ זֶה יַעֲשֶׂה לְנַסּוֹת אֶת יִשְׂרָאֵל בַּגְּאֻלָּה הָאַחֲרוֹנָה, זֶהוּ שֶׁכָּתוּב (דניאל יב) יִתְבָּרְרוּ וְיִתְלַבְּנוּ וְיִצָּרְפוּ רַבִּים - שֶׁהֵם מִצַּד הַטּוֹב, וְעוֹמְדִים בַּנִּסָּיוֹן. וְהִרְשִׁיעוּ רְשָׁעִים - הֵם מִצַּד הָרָע, וְיִתְקַיֵּם בָּהֶם (יחזקאל יג) וְאֶל אַדְמַת יִשְׂרָאֵל לֹא יָבאוּ, וְהוֹרֵג אוֹתָם."],[12,"","וְהַמַּשְׂכִּילִים יָבִינוּ - מִצַּד הַבִּינָה, שֶׁהוּא עֵץ הַחַיִּים, בִּגְלָלָם נֶאֱמַר (דניאל יב) וְהַמַּשְׂכִּלִים יַזְהִרוּ כְּזֹּהַר הָרָקִיעַ, בְּחִבּוּר זֶה שֶׁלְּךְ, שֶׁהוּא סֵפֶר הַזֹּהַר, מִזֹּהַר הָאֵם הָעֶלְיוֹנָה תְּשׁוּבָה. בְּאֵלֶּה לֹא צָרִיךְ נִסָּיוֹן, וּמִשּׁוּם שֶׁעֲתִידִים יִשְׂרָאֵל לִטְעֹם מֵעֵץ הַחַיִּים, שֶׁהוּא סֵפֶר הַזֹּהַר הַזֶה, יֵצְאוּ בוֹ מֵהַגָּלוּת, וְיִתְקַיֵּם בָּהֶם (דברים לב) ה' בָּדָד יַנְחֶנּוּ וְאֵין עִמּוֹ אֵל נֵכָר."],[13,"","וְעֵץ טוֹב וָרָע, שֶׁהוּא אִסּוּר וְהֶתֵּר, טֻמְאָה וְטָהֳרָה, לֹא שׁוֹלֵט יוֹתֵר עַל יִשְׂרָאֵל, שֶׁהֲרֵי פַּרְנָסָתֵנוּ לֹא תִהְיֶה אֶלָּא מִצַּד עֵץ הַחַיִּים, שֶׁאֵין שָׁם לֹא קֹשִׁי מִצַּד הָרָע, וְלֹא מַחֲלֹקֶת מֵרוּחַ הַטֻּמְאָה, שֶׁכָּתוּב (זכריה יג) וְאֶת רוּחַ הַטֻּמְאָה אַעֲבִיר מִן הָאָרֶץ."],[14,"","שֶׁלֹּא יִתְפַּרְנְסוּ תַּלְמִידֵי חֲכָמִים מֵעַמֵּי הָאָרֶץ אֶלָּא מִצַּד הַטּוֹב, שֶׁאוֹכְלִים טָהֳרָה, כָּשֵׁר, הֶתֵּר, וְלֹא מֵעֵרֶב רַב שֶׁאוֹכְלִים טֻמְאָה, פָּסוּל, אִסּוּר. שֶׁהֵם טְמֵאִים, שֶׁמְּטַמְּאִים עַצְמָם בְּנִדָּה שִׁפְחָה גּוֹיָה זוֹנָה, מִשּׁוּם שֶׁהֵם בְּנֵי לִילִית, שֶׁהִיא נִדָּה שִׁפְחָה גּוֹיָה זוֹנָה, חוֹזְרִים לְשָׁרְשָׁם, וַעֲלֵיהֶם נֶאֱמַר (ישעיהיד) כִּי מִשֹּׁרֶשׁ נָחָשׁ יֵצֵא צֶפַע."],[15,"","וּבִזְמַן שֶׁעֵץ טוֹב וָרָע שׁוֹלֵט, שֶׁהוּא חֻלִּין שֶׁל טָהֳרָה וְחֻלִּין שֶׁל טֻמְאָה, הֵם חֲכָמִים שֶׁדּוֹמִים לְשַׁבָּתוֹת וְיָמִים טוֹבִים, אֵין לָהֶם אֶלָּא מַה שֶּׁנּוֹתְנִים לָהֶם אוֹתָם חֻלִּין, כְּמוֹ יוֹם הַשַּׁבָּת שֶׁאֵין לוֹ אֶלָּא מַה שֶּׁמְּתַקְּנִים לוֹ בִּימוֹת הַחֹל."],[16,"","וּבִזְמַן שֶׁשּׁוֹלֵט עֵץ הַחַיִּים, נִכְפֶּה עֵץ טוֹב וָרָע, וְלֹא יִהְיֶה לְעַמֵּי הָאָרֶץ, רַק מַה שֶּׁנּוֹתְנִים לָהֶם תַּלְמִידֵי חֲכָמִים, וְנִכְפִּים תַּחְתֵּיהֶם, וּכְאִלּוּ לֹא הָיוּ בָעוֹלָם."],[17,"","וְכֵן אִסּוּר וְהֶתֵּר, טֻמְאָה וְטָהֳרָה, לֹא עוֹבֵר מֵעַמֵּי הָאָרֶץ, שֶׁמִּצִּדָּם אֵין בֵּין גָּלוּת לִימוֹת הַמָּשִׁיחַ (אליהם) אֶלָּא שִׁעְבּוּד מַלְכֻיּוֹת בִּלְבַד, שֶׁהֵם לֹא טוֹעֲמִים מֵעֵץ הַחַיִּים, וְצָרִיךְ לָהֶם מִשְׁנָה בְּאִסּוּר וְהֶתֵּר, טֻמְאָה וְטָהֳרָה. אֶלָּא יִהְיוּ מְבֻזִּים לִפְנֵי תַּלְמִידֵי חֲכָמִים כְּמוֹ חֹשֶׁךְ לִפְנֵי הָאוֹר, שֶׁעֵרֶב רַב הֵם עַמֵּי הָאָרֶץ, הֵם חֲשׁוּכִים. וְלֹא נִקְרְאוּ יִשְׂרָאֵל, אֶלָּא עֲבָדִים מְכוּרִים לְיִשְׂרָאֵל, מִשּׁוּם שֶׁהֵם כִּבְהֵמוֹת, וְכָךְ פֵּרְשׁוּהָ."],[18,"","וְיִשְׂרָאֵל נִקְרְאוּ אָדָם. וּמִנַּיִן שֶׁיֵּשׁ בָּהֶם בְּהֵמָה וְאָדָם? זֶהוּ שֶׁכָּתוּב (יחזקאל לד) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי אָדָם אַתֶּם. וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי - הֵם עַמֵּי אֲרָצוֹת טוֹבִים מִצַּד הַטּוֹב. אָדָם אַתֶּם - תַּלְמִידֵי חֲכָמִים."],[19,"","וּבְפָסוּק זֶה גַּם רָמוּז לוֹ, (תהלים פא) לוּ עַמִּי שׁוֹמֵעַ לִי יִשְׂרָאֵל וְגוֹ'. אַחַר שֶׁאָמַר עַמִּי, לָמָּה אָמַר יִשְׂרָאֵל? אֶלָא עַמִּי - עַמֵּי הָאֲרָצוֹת. יִשְׂרָאֵל - תַּלְמִידֵי חֲכָמִים וּבִגְלָלוֹ נֶאֱמַר (שמות יד) וּבְנֵי יִשְׂרָאֵל יצְאִים בְּיָד רָמָה."],[20,"","כְּמוֹ שֶׁחִלְּקָם הַקָּדוֹשׁ בָּרוּךְ הוּא בְּהַר סִינַי, כָּךְ חִלְּקָם בַּגְּאֻלָּה הָאַחֲרוֹנָה, שֶׁיִּשְׂרָאֵל שֶׁנֶּאֱמַר בָּהֶם (שם יג) וַחֲמֻשִׁים עָלוּ בְנֵי יִשְׂרָאֵל מֵאֶרֶץ מִצְרָיִם, מִצַּד עֵץ הַחַיִּים, שֶׁהֵם חֲמִשִּׁים שְׁנוֹת יוֹבֵל, נֶאֱמַר בָּהֶם (שם יט) הֵמָּה יַעֲלוּ בָהָר. וּבָהֶם (שם יד) וַיִּסַּע מַלְאַךְ הָאֱלֹהִים הַהֹלֵךְ לִפְנֵי מַחֲנֵה יִשְׂרָאֵל. וְלָהֶם נֶאֱמַר (שם יט) וָאֶשָּׂא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים, שֶׁהֵם עַנְנֵי כָבוֹד, וָאָבִא אֶתְכֶם אֵלָי. וּבְנֵי יִשְׂרָאֵל יֹצְאִים בְּיָד רָמָה, כָּךְ יוֹצִיא אֶת הַתַּלְמִידֵי חֲכָמִים בְּכָל הַכָּבוֹד הַזֶּה."],[21,"","וּכְמוֹ שֶׁנֶּאֱמַר בְּעַמֵּי הָאָרֶץ מִצַּד הַטּוֹב, (שם) וַיִּתְיַצְּבוּ בְּתַחְתִּית הָהָר - כָּךְ יִהְיֶה בַיְצִיאָה הָאַחֲרוֹנָה תַּחַת תַּלְמִידֵי חֲכָמִים, כְּעֶבֶד שֶׁהוֹלֵךְ לְרַגְלֵי סוּס בְּעָלָיו, וּכְמוֹ שֶׁאָמַר לָהֶם בְּתַחְתִּית הָהָר: אִם תְּקַבְּלוּ תוֹרָתִי - מוּטָב, וְאִם לָאו - שָׁם תְּהֵא קְבוּרַתְכֶם. כָּךְ יִהְיֶה בִּיצִיאַת גְּאֻלָּה אַחֲרוֹנָה: אִם תְּקַבְּלוּ עֲלֵיכֶם תַּלְמִידֵי חֲכָמִים בִּיצִיאַת הַגָּלוּת, כְּאָדָם שֶׁרוֹכֵב עַל סוּס וְעֶבֶד שֶׁמְּשַׁמְּשׁוֹ - מוּטָב. וְאִם לֹא - שָׁם תְּהֵא קְבוּרַתְכֶם בַּגָּלוּת."],[22,"","וְעֵרֶב רַב, כְּמוֹ שֶׁנֶּאֱמַר בָּהֶם, (שמות כ) וַיַּרְא הָעָם וַיָּנֻעוּ וַיַּעַמְדוּ מֵרָחֹק. כָּךְ יִהְיוּ רְחוֹקִים מִן הַגְּאֻלָּה, וְיִרְאוּ תַלְמִידֵי חֲכָמִים וְהָעָם הַקָּדוֹשׁ בְּכָל הַכָּבוֹד הַזֶּה, וְהֵם רְחוֹקִים מֵהֶם. וְאִם יֵרְדוּ לְהִתְחַבֵּר אִתָּם, מַה כָּתוּב בָּהֶם? (שם יט) לֹא תִגַּע בּוֹ יָד כִּי סָקוֹל יִסָּקֵל אוֹ יָרֹה יִיָּרֶה. בְּאוֹתוֹ זְמַן יִתְקַיֵּם בְּיִשְׂרָאֵל, (דברים לב) ה' בָּדָד יַנְחֶנּוּ וְאֵין עִמּוֹ אֵל נֵכָר, וַהֲרֵי פֵּרְשׁוּהָ, אֵין מְקַבְּלִים גֵּרִים לִימוֹת הַמָּשִׁיחַ. (שמואל א ב) וּרְשָׁעִים בַּחֹשֶׁךְ יִדָּמּוּ - הֵם עֵרֶב רַב. וּמִשּׁוּם זֶה אָמַר עֲלֵיהֶם הַנָּבִיא, (יחזקאל יג) וְאֶל אַדְמַת יִשְׂרָאֵל לֹא יָבֹאוּ."],[23,"","אָמַר אֵלִיָּהוּ, רוֹעֶה הַנֶּאֱמָן, הֲרֵי שָׁעָה הִיא לַעֲלוֹת לְמַעְלָה, בִּשְׁבוּעָה אֱמֹר אַתָּה, שֶׁהֲרֵי בִּגְלָלְךְ אֲנִי רוֹצֶה לַעֲלוֹת. שֶׁנָּתַן לִי הַקָּדוֹשׁ בָּרוּךְ הוּא רְשׁוּת לְהִתְגַּלּוֹת לְךְ בְּבֵית הָאֲסוּרִים שֶׁלְּךְ, בִּקְבוּרָתְךְ, וְלַעֲשׂוֹת עִמְּךְ טוֹב, שֶׁאַתָּה מְחוֹלָל בַּחֲטָאֵי הָעָם. זֶהוּ שֶׁכָּתוּב (ישעיה נג) וְהוּא מְחוֹלָל מִפְּשָׁעֵינוּ."],[24,"","אָמַר לוֹ רוֹעֶה הַנֶּאֱמָן, בִּשְׁבוּעָה עָלֶיךְ בְּשֵׁם ה', אַל תְּאַחַר בְּכָל יְכָלְתְּךְ, שֶׁהֲרֵי אֲנִי בְּצַעַר רַב. (שמות ב) וַיִּפֶן כֹּה וָכֹה וַיַּרְא כִּי אֵין אִישׁ, עוֹזֵר לִי, לְהוֹצִיאֵנִי מִצַּעַר זֶה, בִּקְבוּרָה זוֹ שֶׁנֶּאֱמַר עָלַי, (ישעיה נג) וַיִּתֵּן אֶת הָרְשָׁעִים קִבְרוֹ, וְלֹא נוֹדָע בִּי, וַאֲנִ חָשׁוּב בְּעֵינֵיהֶם, בֵּין עֵרֶב רַב הָרְשָׁעִים, כְּכֶלֶב מֵת שֶׁסָּרַח בֵּינֵיהֶם, שֶׁחָכְמַת סוֹפְרִים תִּסְרַח בֵּינֵיהֶם בְּכָל עִיר וָעִיר וּבְכָל מָקוֹם שֶׁיִּשְׂרָאֵל מְפֻזָּרִים בֵּינֵיהֶם בֵּין הַמְּלָכִים. וְחָזְרוּ אוֹתָם עֵרֶב רַב רוֹעִים עַל יִשְׂרָאֵל, צֹאן הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁנֶּאֱמַר בָּהֶם (יחזקאל לד) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי אָדָם אַתֶּם, וְאֵין לָהֶם יְכֹלֶת לַעֲשׂוֹת טוֹב עִם תַּלְמִידֵי חֲכָמִים."],[25,"","וְאַנְשֵׁי חַיִל וְיִרְאֵי חֵטְא מְסוֹבְבִים מֵעִיר לְעִיר וְלֹא יְחוֹנָנוּ, וּמַחֲרִימִים עֵרֶב רַב בֵּינֵיהֶם. וְלֹא נוֹתְנִים לָהֶם בִּמְקוֹמוֹת רַבִּים, אֶלָּא דָּבָר קָצוּב, שֶׁלֹּא תִהְיֶה תְקוּמָה לִנְפִילָתָם, וַאֲפִלּוּ חַיֵּי שָׁעָה. וְכָל הַחֲכָמִים וְאַנְשֵׁי חַיִל וְיִרְאֵי חֵטְא בְּדחַק וְיָגוֹן, חֲשׁוּבִים כִּכְלָבִים, בָּנִים הַמְסֻלָּאִים בַּפָּז אֵיכָה נֶחְשְׁבוּ לְנִבְלֵי חֶרֶשׂ בְּרֹאשׁ כָּל חוּצוֹת. שֶׁלֹּא מָצְאוּ אַכְסַנְיָה בֵּינֵיהֶם."],[26,"","וְאוֹתָם עֵרֶב רַב הֵם עֲשִׁירִים בְּשַׁלְוָה, בְּשִׂמְחָה, בְּלִי צַעַר, בְּלֹא יָגוֹן כְּלָל, גַּזְלָנִים, בַּעֲלֵי שֹׁחַד, שֶׁהֵם דַּיָּנִים רָאשֵׁי הָעָם. (בראשית ז) כִּי מָלְאָה הָאָרֶץ חָמָס מִפְּנֵיהֶם. עֲלֵיהֶם נֶאֱמַר (איכה א) הָיוּ צָרֶיהָ לְרֹאשׁ. בִּשְׁבוּעָה עָלֶיךְ פַּעַם שְׁנִיָּה, בְּחַי ה' צְבָאוֹת אֱלֹהֵי יִשְׂרָאֵל יוֹשֵׁב הַכְּרוּבִים, שֶׁכָּל הַדְּבָרִים הָאֵלֶּה לֹא יִפְּלוּ מִפִּיךְ, בְּכָל יְכָלְתְּךְ לְדַבֵּר אוֹתָם לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא וּלְהַרְאוֹת אֶת הַדּחַק שֶׁלָּהֶם."],[27,"","אִישׁ כִּי יַפְלִא לִנְדֹּר וְגוֹ'. רַבִּי אֶלְעָזָר פָּתַח, (ישעיה נ) מַדּוּעַ בָּאתִי וְאֵין אִישׁ וְגוֹ'. מַדּוּעַ בָּאתִי. כַּמָּה חֲבִיבִים יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁבְּכָל מָקוֹם בּוֹ הֵם שׁוֹרִים, הַקָּדוֹשׁ בָּרוּךְ הוּא נִמְצָא בֵינֵיהֶם, מִשּׁוּם שֶׁלֹּא מַעֲבִיר אַהֲבָתוֹ מֵהֶם. מַה כָּתוּב? (שמות כה) וְעָשׂוּ לִי מִקְדָּשׁ וְשָׁכַנְתִּי בְּתוֹכָם. וְעָשׂוּ לִי מִקְדָּשׁ סְתָם. שֶׁכָּל בֵּית כְּנֶסֶת בָּעוֹלָם נִקְרָא מִקְדָּשׁ, וַהֲרֵי פֵּרְשׁוּהָ. וְהַשְּׁכִינָה מַקְדִּימָה לְבֵית הַכְּנֶסֶת."],[28,"","אַשְׁרֵי הָאִישׁ שֶׁנִּמְצָא מֵעֲשָׂרָה הָרִאשׁוֹנִים בְּבֵית הַכְּנֶסֶת, מִשּׁוּם שֶׁבּוֹ נִשְׁלָם מַה שֶּׁנִּשְׁלָם, וְהֵם מִתְקַדְּשִׁים בַּהַתְחָלָה בַּשְּׁכִינָה, וַהֲרֵי נִתְבָּאֵר. וַהֲרֵי צָרִיךְ שֶׁיִּמָּצְאוּ עֲשָׂרָה בִּזְמַן אֶחָד בְּבֵית הַכְּנֶסֶת, וְלֹא יָבֹאוּ קְבוּצוֹת קְבוּצוֹת, שֶׁלֹּא תִתְעַכֵּב שְׁלֵמוּת הָאֵיבָרִים, שֶׁהֲרֵי הָאָדָם בִּזְמַן אֶחָד עֲשָׂאוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, וְהִתְקִינוֹ כְאֶחָד כָּל הָאֵיבָרִים. זֶהוּ שֶׁכָּתוּב (דברים לב) הוּא עָשְׂךְ וַיְכֹנֲנֶךְ."],[29,"","בֹּא רְאֵה, כֵּיוָן שֶׁנִּשְׁלְמוּ אֵיבְרֵי הָאָדָם, בְּאוֹתוֹ זְמַן הִתְתַּקֵּן לְכָל אֵיבָר וְאֵיבָר כָּרָאוּי. כְּמוֹ זֶה, כֵּיוָן שֶׁשְּׁכִינָה מַקְדִּימָה לְבֵית הַכְּנֶסֶת, צָרִיךְ עֲשָׂרָה שֶׁיִּמָּצְאוּ שָׁם כְּאֶחָד, וְיִשְׁתַּלֵּם מַה שֶּׁיִּשְׁתַּלֵּם. וְאַחַר שֶׁמִּתְתַּקֵּן הַכֹּל. וּבַמָּה הוּא תִּקּוּן הַכֹּל? כְּמוֹ שֶׁנֶּאֱמַר (משלי יד) בְּרָב עָם הַדְרַת מֶלֶךְ. וְעַל זֶה הָעָם שֶׁבָּא אַחַר כָּךְ, כֻּלָּם תִּקּוּן הַגּוּף."],[30,"","וּכְשֶׁבָּאָה וּמַקְדִּימָה שְׁכִינָה, וּבְנֵי אָדָם לֹא בָאִים כָּרָאוּי - הַקָּדוֹשׁ בָּרוּךְ הוּא קוֹרֵא, מַדּוּעַ בָּאתִי וְאֵין אִישׁ. מַה זֶּה וְאֵין אִישׁ? שֶׁלֹּא מְתֻקָּנִים הָאֵיבָרִים וְלֹא הֻשְׁלַם הַגּוּף. שֶׁכְּשֶׁגּוּף לֹא מֻשְׁלָם, אֵין אִישׁ. וּמִשּׁוּם זֶה, וְאֵין אִישׁ דַּוְקָא. וּבֹא וּרְאֵה, בְּשָׁעָה שֶׁהַגּוּף הֻשְׁלַם לְמַטָּה, קְדֻשָּׁה עֶלְיוֹנָה בָּאָה וְנִכְנֶסֶת בְּגוּף זֶה, וְנַעֲשֶׂה לְמַטָּה כְּמוֹ לְמַעְלָה מַמָּשׁ, וְאָז הַכֹּל צְרִיכִים שֶׁלֹּא יִפְתְּחוּ פֶּה בְּדִבְרֵי הָעוֹלָם. מִשּׁוּם שֶׁהֲרֵי עוֹמְדִים יִשְׂרָאֵל בִּשְׁלֵמוּת עֶלְיוֹנָה וּמִתְקַדְּשִׁים בִּקְדֻשָּׁה עֶלְיוֹנָה, אַשְׁרֵי חֶלְקָם."],[31,"","אִישׁ כִּי יַפְלִא וְגוֹ'. מַה זֶּה כִּי יַפְלִא? שֶׁנִּפְרָד מִשְּׁאָר בְּנֵי הָעוֹלָם לְהִתְקַדֵּשׁ כְּמוֹ שֶׁלְּמַעְלָה וּלְהִמָּצֵא שָׁלֵם. בְּשָׁעָה שֶׁבָּא אָדָם לִטָּהֵר - מְטַהֲרִים אוֹתוֹ. אָדָם שֶׁרוֹצֶה לְהִתְקַדֵּשׁ - מְקַדְּשִׁים אוֹתוֹ, וּפוֹרְסִים עָלָיו קְדֻשָּׁה עֶלְיוֹנָה, קְדֻשָּׁה שֶׁהִתְקַדֵּשׁ בָּהּ הַקָּדוֹשׁ בָּרוּךְ הוּא."],[32,"","רַבִּי אַבָּא פָּתַח, (תהלים קג) לְדָוִד בָּרְכִי נַפְשִׁי אֶת ה' וְכָל קְרָבַי אֶת שֵׁם קָדְשׁוֹ. כַּמָּה יֵשׁ לוֹ לָאָדָם לְהִסְתַּכֵּל וְלָדַעַת בַּעֲבוֹדַת רִבּוֹנוֹ, שֶׁהֲרֵי בְּכָל יוֹם וָיוֹם הַכָּרוֹז קוֹרֵא וְאוֹמֵר: (משלי א) עַד מָתַי פְּתָיִם תְּאֵהֲבוּ פֶתִי וְגוֹ'. (ירמיה ג) שׁוּבוּ בָּנִים שׁוֹבָבִים אֶרְפָּה מְשׁוּבֹתֵיכֶם. וְאֵין מִי שֶׁיַּרְכִּין אָזְנָיו. הַתּוֹרָה מַכְרִיזָה לִפְנֵיהֶם, וְאֵין מִי שֶׁיַּשְׁגִּיחַ."],[33,"","בֹּא רְאֵה, בֶּן אָדָם הוֹלֵךְ בָּעוֹלָם הַזֶּה וְחוֹשֵׁב שֶׁשֶּׁלּוֹ הוּא תָּמִיד וְיִשָּׁאֵר בְּתוֹכוֹ לְדוֹרֵי דוֹרוֹת. עַד שֶׁהוּא הוֹלֵךְ בָּעוֹלָם, נוֹתְנִים אוֹתוֹ בְּקוֹלָר. עַד שֶׁהוּא יוֹשֵׁב, דָּנִים אוֹתוֹ בְּמוֹשַׁב הַדַּיָּנִים עִם שְׁאָר בְּנֵי הַדִּין. אִם נִמְצָא לוֹ סָנֵגוֹר - הֲרֵי נִצּוֹל מֵהַדִּין. זֶהוּ שֶׁכָּתוּב (איוב לג) אִם יֵשׁ עָלָיו מַלְאָךְ מֵלִיץ אֶחָד מִנִּי אָלֶף לְהַגִּיד לְאָדָם יָשְׁרוֹ וַיְחֻנֶּנּוּ וַיֹּאמֶר וְגוֹ'. מִי הוּא הַסָּנֵגוֹר? אֵלֶּה מַעֲשִׂים כְּשֵׁרִים שֶׁעוֹמְדִים עַל הָאָדָם בְּשָׁעָה שֶׁמִּצְטָרֵךְ לָהֶם."]]],[["וְאִי לָא יִשְׁתְּכַּח עָלֵיהּ סַנֵיגוֹרָא, הָא אִתְחַיָּיב מִן דִּינָא לְאִסְתַּלְּקָא מִן עָלְמָא. בְּהַהִיא שַׁעֲתָא כַּד אִיהוּ שָׁכִיב בְּקוּלְרָא דְּמַלְכָּא, עַד דְּזָקִיף עֵינוֹי, חָמָא דְּאַתְיָין לְגַבֵּיהּ תְּרֵין, דְּכַתְבִין קַמֵּיהּ כָּל מַה דְּעָבִיד בְּהַאי עָלְמָא. וְכָל מַה דְּאַפִּיק מִן פּוּמָא, וְיָהִיב דִּינָא (נ\"א חושבנא) עַל כֹּלָּא וְכַתְבִין קַמֵּיהּ. הֲדָא הוּא דִכְתִיב, (עמוס ד׳:י״ג) כִּי הִנֵּה יוֹצֵר הָרִים וּבוֹרֵא רוּחַ וּמַגִּיד לְאָדָם מַה שִׂיחוֹ וְגוֹ'. וְהוּא אוֹדֵי עָלַיְיהוּ.","מַאי טַעֲמָא, בְּגִין דְּהַהוּא עוֹבָדָא דְּאִיהוּ עָבִיד, סַלְּקָא וְקַיְּימָא עָלֵיהּ לְאַסְהֲדָא בֵּיהּ, וְקַיְימִין לְאַסְהֲדָא עָלֵיהּ, וְכֻלְּהוּ נַחְתִּין וְאִתְרְשִׁימוּ קַמֵּיהּ, וְקַיְימֵי קַמֵּיהּ, וְלָא מִתְעַבְּרָן מִנֵּיהּ, עַד שַׁעֲתָא דְּאִתְדָּן בְּהוּ בְּהַהוּא עָלְמָא. תָּא חֲזֵי, כָּל אִינּוּן מִלִּין דְּעָבִיד בַּר נָשׁ בְּהַאי עָלְמָא, כֻּלְּהוּ זְמִינִין וְקַיְימֵי לְאַסְהֲדָא בֵּיהּ, וְלָא אִתְאֲבִידוּ מִינֵּיהּ. וּבְשַׁעֲתָא דְּמַפְּקֵי לֵיהּ לְקִבְרָא, כֻּלְּהוּ מִתְעַתְּדָן וְאָזְלֵי קַמֵּיהּ. וּתְלַת כָּרוֹזֵי מַכְרְזֵי. חַד קַמֵּיהּ, וְחַד מִימִינֵיהּ, וְחַד מִשְּׂמָאלֵיהּ. וְאָמְרֵי דָּא פְּלַנְיָיא דְּמָרִיד בְּמָארֵיהּ. מָרִיד לְעֵילָּא, מָרִיד לְתַתָּא, מָרִיד בְּאוֹרַיְיתָא, מָרִיד בְּפִיקוּדוֹי. חָמוּ עוֹבָדוֹי, חָמוּ מִלּוֹי, טַב לֵיהּ דְּלָא אִבְרֵי.","עַד דְּמָטֵי לְגַבֵּי קִבְרָא, כֻּלְּהוּ מֵתִין אִתְרַגְזוּן מִדּוּכְתַּיְיהוּ עָלֵיהּ, וְאַמְרֵי וַוי וַוי דְּדָא אִתְקְבַר בְּגַוָּון. עוֹבָדוֹי וּמִלּוֹי אַקְדְמָן וְעָאלִין לְקִבְרָא, וְקַיְימֵי עָלֵיהּ דְּהַהוּא גּוּפָא, וְרוּחֵיהּ אָזְלָא וְשָׁאט, וּמִתְאַבְּלָא עַל גּוּפָא. כֵּיוָן דְּבַּר נָשׁ אִתְטְמַר בְּבֵי קִבְרֵי, דּוּמָ\"ה קָדִים (ס\"א קאים) וְנָפִיק תְּחוֹת יְדֵיהּ, תְּלָתָא בֵּי דִּינָא, דִּי מְמָנָן עַל דִּינָא דְּקִבְרָא, וּתְלַת שַׁרְבִיטֵי דְּאֶשָּׁא בִּידַיְיהוּ, וְדַיְינִין רוּחָא וְגוּפָא כַּחֲדָא. וַוי עַל הַהוּא דִּינָא, וַוי עַל עוֹבָדוֹי.","בְּשַׁעֲתָא דְּאִיהוּ תָּפִיס בְּקוּלְרָא דְּמַלְכָּא, וְאִתְּדָּן דִּינֵיהּ, וְאִשְׁתְּלִים, דְּלָא אִשְׁתְּכַח עָלֵיהּ סַנֵיגוֹרְיָא. וְסַנְטִירָא דְּמַלְכָּא נָחִית, וְקָאִים קָמֵיהּ, לְרַגְלוֹי, וְחַד סַיְיפָא שִׁנָּנָא בִּידֵיהּ.","זָקִיף בַּר נָשׁ עֵינוֹי, וְחָמֵי כֹּתְלֵי בֵּיתָא דְּמִתְלַהֲטָן בְּאֶשָּׁא (דזיוא) מִנֵּיהּ אַדְּהָכִי חָמֵי לֵיהּ קַמֵּיהּ כּוּלֵיהּ מָלֵי עַיְינִין, לְבוּשֵׁיה אֶשָּׁא דְּלָהִיט קַמֵּיהּ דְּבַר נָשׁ. הָכִי הוּא וַדַּאי, דְּהָא כַּמָה בְּנֵי נָשָׁא חָמוּ מַלְאָכָא בְּשׁוּקָא, וְקַיְימֵי קַמֵּיהּ, וּשְׁאַר בְּנֵי נָשָׁא לָא חָמָאן לֵיהּ.","וְאִי תֵּימָא, הָא כְּתִיב (תהילים ק״ד:ד׳) עוֹשֶׂה מַלְאָכָיו רוּחוֹת וְגוֹ'. הֵיךְ יָכִיל לְאִתְחֲזָאָה בְּאַרְעָא. אֶלָּא מִלָּה דָּא, הָא אוּקְמוּהָ, דְּכֵיוָן דְּנָחִית מַלְאָכָא לְאַרְעָא, אִתְלְבַּשׁ בְּגוּפָא, וְאִתְחַזֵּי לְמַאן דְּאִתְחֲזֵי, בְּהַהוּא לְבוּשָׁא דְּאִתְלְבַּשׁ בֵּיהּ. וְאִי לָאו, לָא יָכִיל לְמִסְבַּל לֵיהּ עָלְמָא וּלְאִתְחֲזָאָה. כָּל שֶׁכֵּן וְכָל שֶׁכֵּן הַאי דְּכָל בְּנֵי עָלְמָא צְרִיכִין לֵיהּ.","תְּלַת טִפִּין בְּחַרְבֵּיהּ וְכוּ', וְהָא אוּקְמוּהָ חַבְרַיָא. כֵּיוָן דְּחָמֵי לֵיהּ, אִזְדַּעְזָע כָּל גּוּפֵיהּ וְרוּחֵיהּ, וְלִבֵּיהּ לָא שָׁכִיךְ, בְּגִין דְּאִיהוּ מַלְכָּא דְּכָל גּוּפָא. וְרוּחָא דִּילֵיהּ אַזְלָא בְּכָל שַׁיְיפֵי גּוּפָא, וְאִשְׁתְּאִיל מִנַּיְיהוּ, כְּבַר נָשׁ דְּאִשְׁתְּאִיל מֵחַבְרֵיהּ, לְמֵהַךְ לַאֲתָר אַחֲרָא. כְּדֵין הוּא אוֹמֵר וַוי עַל מַה דְּעֲבַד, וְלָא מְהַנְיָיא לֵיהּ, אֶלָּא אִי אַקְדִּים אַסְוָותָא דִּתְשׁוּבָה, עַד לָא מָטָא הַהִיא שַׁעֲתָא.","דָּחִיל הַהוּא בַּר נָשׁ, וּבָעֵי לְאִתְטַמְּרָא וְלָא יָכִיל. כֵּיוָן דְּחָמֵי דְּלָא יָכִיל, הוּא פָּתַח עֵינוֹי, וְאִית לֵיהּ לְאִסְתַּכְּלָא בֵּיהּ, וְאִסְתָּכַּל בֵּיהּ בְּעַיְינִין פְּקִיחִין. וּכְדֵין הוּא מָסִיר גַּרְמֵיהּ וְנַפְשֵׁיהּ. וְהַהוּא שַׁעֲתָא, הוּא עִידָּן דְּדִינָא רַבָּא, דְּבַּר נָשׁ אִתְּדָּן בֵּיהּ בְּהַאי עָלְמָא. וּכְדֵין רוּחָא אָזְלָא בְּכָל שַׁיְיפֵי גּוּפָא, וְאִשְׁתְּאִיל מִינַיְיהוּ, וְשָׁאט בְּכָל שַׁיְיפִין, וְאִזְדַּעְזְעָא לְכָל סִטְרִין וְכָל שַׁיְיפֵי גּוּפָא כֻּלְּהוּ מִזְדַּעְזְעָן.","כַּד מָטָא רוּחָא לְכָל שַׁיְיפָא וְשַׁיְיפָא, וְאִשְׁתְּאִיל מִנֵּיהּ. נָפַל זִיעָא עַל הַהוּא שַׁיְיפָא, וְרוּחָא אִסְתָּלִיק מִנֵּיהּ. וּמִיַּד מִית הַהוּא שַׁיְיפָא. וְכֵן בְּכֻלְּהוּ.","כֵּיוָן דְּמָטֵי רוּחָא לְמֵיפַּק, דְּהָא אִשְׁתְּאִיל מִכָּל גּוּפָא, כְּדֵין שְׁכִינְתָּא קַיְּימָא עָלֵיהּ. וּמִיַּד פַּרְחָא מִן גּוּפָא. זַכָּאָה חוּלָקֵיהּ דְּמַאן דְּאִתְדְּבַק בָּהּ, וַוי לְאִינּוּן חַיָּיבַיָּא דִּרְחִיקִין מִנָּהּ, וְלָא מִתְדַּבְּקִין בָּהּ.","וְכַמָּה בֵּי דִּינָא אַעְבַּר בַּר נָשׁ כַּד נָפִק מֵהַאי עָלְמָא. חַד הַהוּא דִּינָא עִלָּאָה דְּקָאָמַרָן, כַּד נָפִיק רוּחָא מִן גּוּפָא. וְחַד דִּינָא, כַּד עוֹבָדוֹי וּמִלּוֹי אָזְלִין קַמֵּיהּ, וְכָרוֹזֵי מַכְרְזֵי עֲלוֹי. וְחַד דִּינָא, כַּד עָיֵיל לְקִבְרָא וְחַד דִּינָא דְּקִבְרָא. וְחַד דִּינָא דְּתוֹלַעֲתָּא. וְחַד דִּינָא דְּגֵיהִנָּם. וְחַד דִּינָא דְּרוּחָא דְּאַזְלָא וְשָׁאט בְּעָלְמָא, וְלָא אַשְׁכַּח אֲתָר, עַד דְּיִשְׁתְּלִימוּ עוֹבָדוֹי. ודַּאי שִׁבְעָה עִדָנִין יַחְלְפוּן עֲלוֹי. בְּגִין כַּךְ בָּעֵי בַּר נָשׁ, כַּד אִיהוּ אִשְׁתְּכַח בְּהַאי עָלְמָא, לְדַחֲלָא מִן מָארֵיהּ, וּלְאִסְתַּכְּלָא בְּכָל יוֹמָא וְיוֹמָא בְּעוֹבָדוֹי, וְיֵיתוּב מִנַּיְיהוּ קַמֵּי מָרֵיהּ."],[[0,"ואי לא ישתכח","וכו׳: ואם לא נמצא עליו מליץ טוב. הוא מתחייב מן הדין להסתלק מן העולם. בשעה ההיא, כשהוא שוכב קשור בכבלים של המלך, בעוד שנושא עיניו, הוא רואה שבאים אליו שנים הכותבים לפניו כל מה שעשה בעולם הזה, וכל מה שהוציא מפיו, ונותן דין על הכל, וכותבים לפניו. ז״ש, כי הנה יוצר הרים ובורא רוח ומגיד לאדם מה שיחו וגו׳. והוא מודה עליהם."],[1,"מאי טעמא בגין","וכו׳: מהו הטעם שמודה על כל מעשיו. הוא משום שאותו מעשה שהוא עשה, עולה ועומד לפניו להעיד בו, וכל המעשים עומדים למעלה להעיד עליו, ויורדים כולם, ונרשמים לפניו, ועומדים לפניו, ואינם עוברים ממנו, עד השעה שנדון בהם בעולם ההוא. בוא וראה, כל אלו הדברים שעשה האדם בעולם הזה, כולם מוכנים ועומדים להעיד עליו, ואינם נאבדים ממנו. ובשעה שמוציאים אותו לקבר, כולם נועדים והולכים לפניו. וג׳ כרוזים מכריזים. אחד מלפניו, ואחד מימינו ואחד משמאלו. ואומרים זה הוא פלוני שמרד באדונו, מרד למעלה, מרד למטה, מרד בתורה, מרד במצותיו, ראו מעשיו, ראו דיבוריו, טוב לו שלא היה נברא."],[2,"עד דמטו לגבי","וכו׳: עד שמגיעים לבית הקברות, וכל המתים ירגזו עליו ממקומם, ואומרים אוי אוי, שזה נקבר בינינו. מעשיו ודבוריו מקדימים ובאים לתוך הקבר, ועומדים על אותו הגוף. ורוחו הולך ומשוטט ומתאבל על הגוף. כיון שהאדם נתכסה בקברו, המלאך דומה מקדים ויוצא, ותחת ידו ג׳ בתי דינים הממונים על דין הקבר, וג׳ שרביטי אש בידיהם, ודנים את הרוח והגוף יחד. אוי על דין ההוא, אוי על מעשיו."],[3,"בשעתא דאיהו תפיס","וכו׳: בשעה שהוא תפוס בכבלי המלך. דהיינו בשעה שהוא חולה ונקשר אל מטתו, ונידון דינו, ונשלם לחוב, כי לא נמצא עליו מליץ יושר. והממונה של המלך, דהיינו מלאך המות, יורד ועומד לפניו, למרגלותיו, וחרב חדה אחת בידו."],[4,"זקיף ב״נ עינוי","וכו׳: נושא האדם את עיניו, ורואה תחילה את כתלי הבית שלוהטים ממנו באש. ובתוך כך רואה אותו, כולו לפניו מלא עינים, ולבושו אש לוהט, עומד לפני האדם. ואע״פ שאחרים העומדים שמה אינם רואים אותו, כך הוא ודאי, כי כמה בני אדם רואים מלאך בשוק ועומדים לפניו, ושאר בני אדם אינם רואים אותו. \u0003סנטר,\u0004 פירושו ממונה, מלשון אפוטרופא או סנטר (ירושלמי ב״מ ה)."],[5,"ואי תימא הא","וכו׳: ואם תאמר, הרי כתוב, עושה מלאכיו רוחות וגו׳, ואיך אפשר לראותם בארץ. ומשיב, אלא דבר זה, הרי העמדנו. כיון שהמלאך יורד לארץ, הוא מתלבש בגוף ונראה למי שנראה באותו הלבוש שנתלבש בו. ואם לא היה מתלבש בלבוש, לא היה העולם יכול לסובלו ושיהיה נראה. כל שכן וכל שכן בזה, במלאך המות, שכל בני העולם צריכים אליו."],[6,"ג׳ טפין בחרביה","וכו׳: ג׳ טפות הם בחרבו, וכבר העמידו החברים (לעיל פקודי תתקט״ז). כיון שרואה אותו מזדעזע כל גופו ורוחו, ולבו אינו שוקט, משום שהוא מלך של כל הגוף. והרוח שלו הולך בכל אברי הגוף, ונפרד מהם, כאדם הנפרד מחבירו ללכת למקום אחר. אז הוא אומר, אוי לי על מה שעשיתי, ואינו מועיל לו, אלא אם הקדים הרפואה של תשובה מטרם שהגיע שעה ההיא."],[7,"דחיל ההוא ב״נ","וכו׳: מפחד האדם ורוצה להסתתר ואינו יכול. כיון שרואה שאינו יכול, הוא פותח את עיניו. ויש לו להסתכל בו. ומסתכל בו בעינים פקוחות. ואז הוא מוסר עצמו ונפשו. והשעה ההיא היא העת של הדין הגדול שאדם נידון בעולם הזה. ואז הולך הרוח בכל אברי הגוף ונפרד מהם. ומשוטט. בכל האברים, ומזדעזע לכל הצדדים. וכל אברי הגוף כולם מזדעזעים."],[8,"כד מטא רוחא","וכו׳: כשמגיע הרוח לכל אבר ואבר ונפרד ממנו, נופלת זיעה על אותו האבר, והרוח מסתלק ממנו, ומיד מת אותו האבר. וכן בכל האברים."],[9,"כיון דמטי רוחא","וכו׳: כיון שמגיע הרוח לצאת, כי כבד נפרד מכל אברי הגוף. אז השכינה עומדת עליו. ומיד פורח הרוח מן הגוף. אשרי חלקו של מי שנתדבק בה, בהשכינה, אוי לאלו הרשעים שהם רחוקים ממנה ולא נתדבקו בה."],[10,"וכמה בי דינא","וכו׳: וכמה בתי דין עוברים על האדם כשיוצא מעולם הזה. א׳, אותו דין העליון שאמרנו, כשהרוח יוצא מן הגוף. וא׳, הוא הדין בעת שמעשיו ודבוריו הולכים לפניו והכרוזים מכריזים עליו (כנ״ל אות קי״ג). וא׳, הדין כשנכנס לקבר (כנ״ל קיד). וא׳ דין הקבר (כמ״ש שם). וא׳ דין התולעים שאוכלים את בשרו. וא׳, דין הגיהנם. וא׳ דין הרוח ההולך ומשוטט בעולם ואינו מוצא מקום עד שישלים מעשיו. ודאי הם ז׳ עתים שעוברים עליו. משום זה צריך האדם, בעודו נמצא בעולם הזה, לירא מאדונו, ולהסתכל בכל יום ויום במעשיו, וישוב עליהם לפני אדונו."]],[[0,"","וְאִם לֹא יִמָּצֵא עָלָיו סָנֵגוֹר - הֲרֵי הִתְחַיֵּב מֵהַדִּין לְהִסְתַּלֵּק מֵהָעוֹלָם. בְּאוֹתָהּ שָׁעָה כְּשֶׁשּׁוֹכֵב בְּקוֹלַר הַמֶּלֶךְ, עַד שֶׁמֵּרִים עֵינָיו, רוֹאֶה שֶׁבָּאִים אֵלָיו שְׁנַיִם שֶׁכּוֹתְבִים לְפָנָיו כָּל מַה שֶּׁעָשָׂה בָּעוֹלָם הַזֶּה, וְכָל מַה שֶּׁהוֹצִיא מִפִּיו, וְנוֹתֵן דִּין (חשבון) עַל הַכֹּל וְכוֹתְבִים לְפָנָיו. זֶהוּ שֶׁכָּתוּב (עמוס ד) כִּי הִנֵּה יוֹצֵר הָרִים וּבֹרֵא רוּחַ וּמַגִּיד לְאָדָם מַה שֵּׂחוֹ וְגוֹ'. וְהוּא מוֹדֶה עֲלֵיהֶם."],[1,"","מָה הַטַּעַם? מִשּׁוּם שֶׁאוֹתוֹ מַעֲשֶׂה שֶׁעָשָׂה, עוֹלֶה וְעוֹמֵד עָלָיו לְהָעִיד בּוֹ, וְעוֹמְדִים לְהָעִיד עָלָיו, וְכֻלָּם יוֹרְדִים וְנִרְשָׁמִים לְפָנָיו וְעוֹמְדִים לְפָנָיו, וְלֹא עוֹבְרִים מִמֶּנּוּ עַד שָׁעָה שֶׁנִּדּוֹן בָּהֶם בְּאוֹתוֹ עוֹלָם. בּא רְאֵה, כָּל אוֹתָם דְּבָרִים שֶׁעָשָׂה בֶּן אָדָם בָּעוֹלָם הַזֶּה, כֻּלָּם זְמִינִים וְעוֹמְדִים לְהָעִיד בּוֹ, וְלֹא נֶאֶבְדוּ מִמֶּנּוּ. וּבְשָׁעָה שֶׁמּוֹצִיאִים אוֹתוֹ לַקֶּבֶר, כֻּלָּם מִזְדַּמְּנִים וְהוֹלְכִים לְפָנָיו. וּשְׁלֹשָׁה כָרוֹזִים מַכְרִיזִים., אֶחָד לְפָנָיו, וְאֶחָד מִימִינוֹ, וְאֶחָד מִשְּׂמֹאלוֹ, וְאוֹמְרִים: זֶה פְּלוֹנִי שֶׁמָּרַד בְּרִבּוֹנוֹ., מָרַד לְמַעְלָה, מָרַד לְמַטָּה, מָרַד בַּתּוֹרָה, מָרַד בְּמִצְווֹתָיו. רְאוּ מַעֲשָׂיו! רְאוּ דְבָרָיו! טוֹב לוֹ שֶׁלֹּא נִבְרָא!"],[2,"","עֵד שֶׁמַּגִּיעַ לַקֶּבֶר, כָּל הַמֵּתִים רוֹגְזִים עָלָיו מִמְּקוֹמָם וְאוֹמְרִים: אוֹי אוֹי שֶׁזֶּה נִקְבָּר בְּתוֹכֵנוּ! מַעֲשָׂיו וּדְבָרָיו מַקְדִּימִים וְנִכְנָסִים לַקֶּבֶר, וְעוֹמְדִים עַל אוֹתוֹ גּוּף, וְרוּחוֹ הוֹלֶכֶת וְשָׁטָה וּמִתְאַבֶּלֶת עַל הַגּוּף. כֵּיוָן שֶׁהָאָדָם נִטְמָן בְּבֵית הַקְּבָרוֹת, דּוּמָ\"ה מַקְדִּים וְיוֹצֵא תַּחַת יָדָיו שְׁלֹשָׁה בָּתֵּי דִינִים שֶׁמְּמֻנִּים עַל דִּין הַקֶּבֶר, וּשְׁלֹשָׁה שַׁרְבִיטֵי אֵשׁ בִּידֵיהֶם, וְדָנִים רוּחַ וָנֶפֶשׁ כְּאֶחָד. אוֹי עַל אוֹתוֹ הַדִּין! אוֹי עַל מַעֲשָׂיו!"],[3,"","בְּשָׁעָה שֶׁהוּא תָּפוּס בְּקוֹלַר הַמֶּלֶךְ וְנִדּוֹן דִּינוֹ וְנִשְׁלָם, שֶׁלֹּא נִמְצָא עָלָיו סָנֵגוֹר, וְשׁוֹטֵר הַמֶּלֶךְ נוֹחֵת, וְעוֹמֵד לְפָנָיו לְרַגְלָיו, וְחֶרֶב שְׁנוּנָה אַחַת בְּיָדוֹ."],[4,"","מֵרִים הָאִישׁ אֶת עֵינָיו, וְרוֹאֶה כָּתְלֵי הַבַּיִת לוֹהֲטִים בְּאֵשׁ (הזיו) מִמֶּנּוּ. וּבֵין כָּךְ רוֹאֶה אוֹתוֹ לְפָנָיו כֻּלּוֹ מָלֵא עֵינַיִם, לְבוּשׁוֹ אֵשׁ לוֹהֵט לִפְנֵי הָאָדָם. כָּךְ הוּא וַדַּאי, שֶׁהֲרֵי כַּמָּה בְּנֵי אָדָם רָאוּ מַלְאָךְ בַּשּׁוּק וְעָמְדוּ לְפָנָיו, וּשְׁאָר בְּנֵי אָדָם לֹא רָאוּ אוֹתוֹ."],[5,"","וְאִם תֹּאמַר, הֲרֵי כָּתוּב (תהלים קד) עֹשֶׂה מַלְאָכָיו רוּחוֹת וְגוֹ', אֵיךְ יָכוֹל לְהֵרָאוֹת בָּאָרֶץ? אֶלָּא דָּבָר זֶה כָּךְ בֵּאֲרוּהוּ: שֶׁכֵּיוָן שֶׁיּוֹרֵד מַלְאָךְ לָאָרֶץ, מִתְלַבֵּשׁ בְּגוּף, וְנִרְאֶה לְמִי שֶׁנִּרְאֶה בְּאוֹתוֹ לְבוּשׁ שֶׁהוּא לָבוּשׁ בּוֹ. וְאִם לֹא, לֹא יָכוֹל הָעוֹלָם לְסָבְלוֹ וּלְהֵרָאוֹת בּוֹ. כָּל שֶׁכֵּן וְכָל שֶׁכֵּן זֶה שֶׁכָּל בְּנֵי הָעוֹלָם צְרִיכִים אוֹתוֹ."],[6,"","שָׁלֹש טִפּוֹת בְּחַרְבּוֹ, וַהֲרֵי בֵּאֲרוּהוּ הַחֲבֵרִים. כֵּיוָן שֶׁרוֹאֵהוּ, מִזְדַּעֲזֵעַ כָּל גּוּפוֹ וְרוּחוֹ, וְלִבּוֹ לֹא שׁוֹכֵךְ, מִשּׁוּם שֶׁהוּא הַמֶּלֶךְ שֶׁל כָּל הַגּוּף. וְרוּחוֹ הוֹלֶכֶת בְּכָל אֵיבְרֵי הַגּוּף, וְנִפְרֶדֶת מֵהֶם, כְּמוֹ בֶּן אָדָם שֶׁנִּפְרָד מֵחֲבֵרוֹ לָלֶכֶת לְמָקוֹם אַחֵר. אָז הוּא אוֹמֵר אוֹי עַל מַה שֶּׁעָשָׂה - וְלֹא עוֹזֵר לוֹ, אֶלָּא אִם הִקְדִּים רְפוּאַת הַתְּשׁוּבָה עַד שֶׁלֹּא הִגִּיעָה אוֹתָהּ שָׁעָה."],[7,"","פּוֹחֵד אוֹתוֹ הָאִישׁ וְרוֹצֶה לְהִסְתַּתֵּר וְלֹא יָכוֹל. כֵּיוָן שֶׁרוֹאֶה שֶׁאֵינוֹ יָכוֹל, הוּא פּוֹתֵחַ עֵינָיו, וְיֵשׁ לוֹ לְהִסְתַּכֵּל בּוֹ, וּמִסְתַּכֵּל בּוֹ בְּעֵינַיִם פְּקוּחוֹת. וְאָז הוּא מוֹסֵר עַצְמוֹ וְנַפְשׁוֹ. וְאוֹתָהּ שָׁעָה הוּא זְמַן דִּין הַגָּדוֹל שֶׁהָאָדָם נִדּוֹן בּוֹ בָּעוֹלָם הַזֶּה, וְאָז הָרוּחַ הוֹלֶכֶת בְּכָל הָאֵיבָרִים שֶׁל הַגּוּף וְנִפְרֶדֶת מֵהֶם, וּמְשׁוֹטֶטֶת בְּכָל הָאֵיבָרִים וּמִזְדַּעֲזַעַת לְכָל הַצְּדָדִים, וְכָל אֵיבְרֵי הַגּוּף כֻּלָּם מִזְדַּעְזְעִים."],[8,"","כְּשֶׁמַּגִּיעָה הָרוּחַ לְכָל אֵיבָר וְאֵיבָר וְנִפְרֶדֶת מִמֶּנּוּ, נוֹפֶלֶת זֵיעָה עַל אוֹתוֹ אֵיבָר, וְהָרוּחַ מִסְתַּלֶּקֶת מִמֶּנּוּ, וּמִיָּד מֵת אוֹתוֹ אֵיבָר, וְכֵן בְּכֻלָּם."],[9,"","כֵּיוָן שֶׁמַּגִּיעָה הָרוּחַ לָצֵאת, שֶׁהֲרֵי נִפְרְדָה מִכָּל הַגּוּף, אָז הַשְּׁכִינָה עוֹמֶדֶת עָלָיו, וּמִיָּד פּוֹרַחַת מֵהַגּוּף. אַשְׁרֵי חֶלְקוֹ שֶׁל מִי שֶׁנִּדְבָּק בָּהּ! אוֹי לְאוֹתָם רְשָׁעִים שֶׁרְחוֹקִים מִמֶּנָּה וְלֹא מִתְדַּבְּקִים בָּהּ!"],[10,"","וְכַמָּה בָּתֵּי דִינִים עוֹבֵר הָאִישׁ כְּשֶׁיּוֹצֵא מֵהָעוֹלָם הַזֶּה? אֶחָד - אוֹתוֹ דִּין עֶלְיוֹן שֶׁאָמַרְנוּ כְּשֶׁיּוֹצֵאת הָרוּחַ מֵהַגּוּף. וְאֶחָד דִּין, כְּשֶׁמַּעֲשָׂיו וּדְבָרָיו הוֹלְכִים לְפָנָיו וְהַכָּרוֹזִים מַכְרִיזִים עָלָיו. וְאֶחָד דִּין כְּשֶׁנִּכְנָס לַקֶּבֶר. וְאֶחָד דִּין הַקֶּבֶר. וְאֶחָד דִּין הַתּוֹלַעַת. וְאֶחָד דִּין הַגֵּיהִנֹּם. וְאֶחָד דִּין הָרוּחַ שֶׁהוֹלֶכֶת וּמְשׁוֹטֶטֶת בָּעוֹלָם וְלֹא מוֹצֵאת מָקוֹם עַד שֶׁיִּשְׁתַּלְּמוּ מַעֲשָׂיו. וַדַּאי שִׁבְעָה עִדָּנִים יַחְלְפוּ עָלָיו. בִּגְלַל זֶה צָרִיךְ הָאָדָם כְּשֶׁהוּא נִמְצָא בָּעוֹלָם הַזֶּה לִירָא מֵרִבּוֹנוֹ וּלְהִסְתַּכֵּל בְּכָל יוֹם וָיוֹם בְּמַעֲשָׂיו, וְיָשׁוּב מֵהֶם לִפְנֵי רִבּוֹנוֹ."]]],[["כַּד אִסְתְּכַּל דָּוִד מַלְכָּא בְּאִינּוּן דִּינִין דְּבַר נָשׁ, כַּד אִסְתַּלָּק מֵהַאי עָלְמָא, אַקְדִּים וְאָמַר, (תהילים ק״ג:א׳) בָּרַכִי נַפְשִׁי אֶת יְיָ, עַד דְּלָא תִּפּוּק מֵעָלְמָא, הַשְׁתָּא דְּאַנְתְּ אִשְׁתְּכַחַת עִם גּוּפָא. וְכָל קְרָבַי אֶת שֵׁם קָדְשׁוֹ, אַתּוּן שַׁיְיפֵי דְּמִשְׁתַּתְּפֵי בְּרוּחָא, הַשְׁתָּא דְּאִשְׁתְּכָחַת עִמְּכוֹן, אַקְדִּימוּ לְבָרְכָא שְׁמָא קַדִּישָׁא, עַד לָא יִמְטֵי זִמְנָא, דְּלָא תֵּיכְלּוּן לְבָרְכָא לֵיהּ, וּלְאוֹדָאָה עָלַיְיכוּ.","תָּא חֲזֵי אִישׁ כִּי יַפְלִיא לִנְדּוֹר נֶדֶר, נָזִיר דְּאַקְדִּים בְּהַאי עָלְמָא, לְאִתְקַדְּשָׁא בִּקְדוּשָׁה דְּמָארֵיהּ (במדבר ו׳:ג׳) מִיַּיִן וְשֵׁכָר יַזִּיר חוֹמֶץ יַיִן וְגוֹ'. הָכָא אִית לְאִסְתַּכְּלָא, כֵּיוָן דְּאָסִיר לֵיהּ חַמְרָא, עֲנָבִים לָמָּה. דְּהָא בְּכַהֲנֵי כְּתִיב יַיִן וְשֵׁכָר אַל תֵּשְׁתְּ וְגוֹ', יָכוֹל עֲנָבִים נָמֵי לָא, בַּעֲנָבִים שָׁרֵי. הָכָא לַנָּזִיר, מַאי טַעְמָא אָסַר לֵיהּ עֲנָבִים.","אֶלָּא, עוֹבָדָא דָּא, וּמִלָּה דָּא, רָזָא עִלָּאָה הוּא, לְאִתְפָּרְשָׁא מִן דִּינָא בְּכֹלָּא. וְהָא יְדִיעָא הַהוּא אִילָנָא דְּחָב בֵּיהּ אָדָם קַדְמָאָה, עֲנָבִים הֲווֹ. וְדָא הוּא רָזָא דְּמִלָּה, דְּהָא יַיִן וְשֵׁכָר וַעֲנָבִים, בְּסִטְרָא חַד אִתְאֲחָדוּ. יַיִן לְעֵילָּא וְאוֹקְמוּהָ. שֵׁכָר לִשְׂמָאלָא, דְּהָא שֵׁכָר מִיַיִן נָפְקָא. עֲנָבִים דְּכָנִישׁ כֻּלְּהוּ לְגַבַּיְיהוּ, וְדָא הוּא אִילָנָא דְּחָב בֵּיהּ אָדָם קַדְמָאָה. בְּגִין כָּךְ כֹּלָּא בְּחַד סִטְרָא אִתְאֲחָד. וְאִי תֵּימָא דְּהַאי נָזִיר שָׁבִיק מְהֵימְנוּתָא עִלָּאָה. (ס\"א כלום) לָאו הָכִי, אֶלָּא לָא אִתְחֲזֵי בֵּיהּ עוֹבָדָא מִסְּטַר שְׂמָאלָא כְּלוּם.","תָּא חֲזֵי, דְּהָכִי אוֹלִיפְנָא מִסִּפְרָא דְּרַב הַמְנוּנָא סָבָא, וְהָכִי הוּא. כְּתִיב גַּדֵּל פֶּרַע שְׂעַר רֹאשׁוֹ, בָּעֵי דְּיִּתְרְבֵּי שְׂעַר רֵישֵׁיהּ וְדִיקְנֵיהּ, וְיִתְפְּרִשׁ מִיַיִן וְשֵׁכָר וַעֲנָבִים, בְּגִין דְּכֻלְּהוּ סְטָר שְׂמָאלָא, וְלָא תַּלְיָין שַׂעֲרָא. יַיִן אִימָּא עִלָּאָה. שֵׁכָר סִטְרָא דַאֲחִידוּ בֵּיהּ לֵיוָאֵי וְנַפְקֵי מִיַיִן עִלָּאָה וְלָא תָּלֵי שַׂעֲרָא. וּבְגִין כָּךְ כַּד סְלִיקוּ לֵיוָאֵי לְהַהוּא אֲתָר, בָּעֲיָין לְאַעְבְרָא כָּל שַׂעֲרָא דִּלְהוֹן, כְּמָה דְאַתְּ אָמֵר (במדבר ח׳:ז׳) וְהֶעֱבִירוּ תַעַר עַל כָּל בְּשָׂרָם. (קכ\"א ע\"ב).","עֲנָבִים אִימָּא תַּתָּאָה, דְּכָנִישׁ יַיִן וְשֵׁכָר לְגַוָּוהּ, וְעַל דָּא אִתְפְּרַשׁ מִכָּל סְטָר שְׂמָאלָא, דְּלָא לְאַחֲזָאָה עוֹבָדָא דִּילְהוֹן לְגַבֵּיהּ. עֲנָבִים דָּא לָא תָּלֵי שַׂעֲרָא וְדִיקְנָא. דְּהָא נוּקְבָּא בַּעְיָיא לְסַפְּרָא שַׂעֲרָא, כַּד אַתְיָא לְאִזְדַּוְּוגָא בִּדְכוּרָא, וְהָא דִּיקְנָא לָא אִשְׁתְּכַח בָּהּ. בְּגִין כָּךְ הוּא תָּלֵי שַׂעֲרָא דְּרֵישָׁא וְדִיקְנָא, וְרָזָא דְּמִלָּה (שופטים י״ג:ה׳) נְזִיר אֱלֹהִים אִקְרֵי, וְלָא נְזִיר יְיָ, פָּרִישׁ מִדִּינָא כֹּלָּא.","תָּא חֲזֵי, עַל דָּא כְּתִיב, וְכִפֶּר עָלָיו מֵאֲשֶׁר חָטָא עַל הַנָּפֶשׁ וְגוֹ'. עַל נַפְשׁוֹ לָא כְּתִיב, אֶלָּא עַל הַנָּפֶשׁ סְתָם. וּמַאי אִיהוּ. דָּא עֲנָבִים, דְּאִקְרֵי נֶפֶשׁ. וְעַל דָּא כְּתִיב חָטָא, בְּגִין דִּסְטָר דִּילֵיהּ יַיִן וְשֵׁכָר הוּא, וְגָרַע מִנֵּיהּ אֲתָר דִּינָא. חָטָא, מַאי חָטָא. אֶלָּא גָּרַע דִּינָא שֶׁל הַנֶּפֶשׁ.","אִי הָכִי, אֲמַאי וְכִפֶּר עָלָיו. בְּגִין דְּהַשְׁתָּא קָא אַתְיָא לְאִתְחַבְּרָא בַּהֲדַיְיהוּ, וְלָא מְקַבְּלָן לֵיהּ הָנֵי אַתְרֵי, עַד דְּיִמָּלֵךְ בְּכַהֲנָא, וִיכַפֵּר עָלֵיהּ, בְּגִין דְּאִיהוּ שָׁדֵי לוֹן לְבַר בְּקַדְמִיתָא, כֵּיוָן דְּהַשְׁתָּא אָתֵי לְגַבַּיְיהוּ, בָּעֵי לְאִתְחַבְּרָא תִּקּוּנָא דְּכַפָּרָה, וִיקַבְּלוּן לֵיהּ, וְדָא הוּא רָזָא דְּמִלָּה. (ודאי בכלא).","וְאִי תֵּימָא, שִׁמְשׁוֹן נְזִיר אֱלֹהִים הֲוָה, אֲמַאי אִתְעַנָּשׁ. אֶלָּא שַׁפִּיר הוּא מִלָּה, דְּבָעַל בַּת אֵל נֵכָר. וַהֲוָה לֵיהּ לְאִתְחַבְּרָא בְּדִידֵיהּ, בְּמָה דְּאִתְחֲזֵי לֵיהּ. וְהוּא דְּהֲוָה קַדִּישׁ, אַעְרָב הַהִיא קְדוּשָּׁה בְּבַת אֵל נֵכָר, וְשָׁבִיק אַתְרֵיהּ, דְּאִתְחֲזֵי לְהַהִיא קְדוּשָּׁה, וּבְגִין כָּךְ אִתְעַנָּשׁ.","וְאִית מַאן דְּאָמַר, דְּלֵית לֵיהּ חוּלָקָא בְּהַהוּא עָלְמָא. מַאי טַעְמָא בְּגִין דְּאָמַר (שופטים ט״ז:ל׳) תָמוּת נַפְשִׁי עִם פְּלִשְׁתִּים, וּמָסַר חוּלָקֵיהּ בְּחוּלָקָא דִּפְלִשְׁתָּאֵי, דִּיְּמוּת נַפְשֵׁיהּ עִמְּהוֹן בְּהַהוּא עָלְמָא. כַּךְ הֲווֹ מַכְרְזֵי עַל נְזִירָא, לֵךְ לֵךְ אַמְרִין נְזִירָא, סְחוֹר סְחוֹר, לְכַרְמָא לָא תִּקְרַב. וְהָא אוּקְמוּהָ חַבְרַיָּיא."],[[0,"כד אסתכל דוד","וכו׳: כשהסתכל דוד המלך באלו הדינים של אדם כשנפטר מן עולם הזה. הקדים ואמר ברכי נפשי את ה׳, מטרם שיוצאת מן העולם, עתה, כשעוד את נמצאת עם הגוף. וכל קרבי את שם קדשו, אתם האברים המחוברים עם הרוח, עתה בעוד שהרוח נמצא עמכם, הקדימו לברך את השם הקדוש, מטרם שמגיע הזמן שלא תוכלו לברכו, ולהודות לו בשבילכם."],[1,"ת״ח איש כי","וגו׳: בוא וראה, איש כי יפליא לנדור נדר נזיר. היינו שהקדים בעולם הזה להתקדש בקדושת אדונו. מיין ושכר יזיר חומץ יין וגו׳. כאן יש להסתכל, כיון שאסור לו יין, ענבים למה אסורים לו. שהרי בכהן כתוב, יין ושכר אל תשת וגו׳. יכול גם ענבים. אינו כן, אלא ענבים מותרים לו. וכאן בנזיר מהו הטעם שאסורים לו ענבים."],[2,"אלא עובדא דא","וכו׳: ומשיב, אלא מעשה זה ודבר זה הוא סוד עליון, שהנזיר בא להפרד מן הדין לגמרי. ועוד יותר מכהן. והרי ידוע, שאותו האילן שחטא בו אדם הראשון היה ענבים (כנ״ל תרומה אות של״ב). וזה הוא סוד הדבר, כי יין ושכר וענבים בצד אחד נאחזים, דהיינו בקו שמאל, \u0003יין\u0004 למעלה, בקו שמאל דבינה, הנקרא שם יין המשומר. והעמידוהו. (כנ״ל שמיני אות פ״ה) \u0003שכר,\u0004 הוא לשמאל דז״א, כי שכר יוצא מיין. כן קו שמאל דז״א נמשך מקו שמאל דבינה. \u0003ענבים,\u0004 מקבצים אצלם את כולם, שהם מלכות, המקבלת מכל העליונים. וזה הוא האילן שחטא בו אדם הראשון. משום זה הכל נאחז בצד אחד. שהוא שמאל של הבינה ושל ז״א ושל המלכות. ואם תאמר, שנזיר זה עזב האמונה העליונה, דהיינו שלא לקבל מבינה וז״א ומלכות העליונים, אינו כן, אלא אינו ראוי לו לעשות מעשה מצד השמאל כלום."],[3,"ת״ח דהכי אוליפנא","וכו׳: בוא וראה, כי כך למדתי מספרו של רב המנונא סבא, וכך הוא. כתוב גדל פרע שער ראשו. שצריך שיגדל שער ראשו וזקנו, ויפרוש מיין ושכר וענבים, משום שכולם הם צד שמאל ושערות אינן תלויות בהם. יין הוא אמא עלאה. \u0003שכר,\u0004 הוא צד שמאל שלוים אחוזים בהם, ויוצאים מיין העליון, דהיינו מאמא עלאיה, ושערות אינן תלויות בהם. משום זה כשעולים לוים למקום הזה, לשמאל, צריכים להעביר כל השער שלהם, כש״א, והעבירו תער על כל בשרם."],[3,"","פירוש, נודע שהארת החכמה נמשכת מקו שמאל דבינה, שה״ס יין. וקו שמאל דז״א מקבל הארת החכמה מקו שמאל דבינה, שה״ס שכר. ושניהם משפיעים הארת החכמה אל המלכות הנקראת ענבים. וסוד השערות נמשכות מבחינה ה \u0003י׳\u0004 שנכנסה ל \u0003אור\u0004 הבינה ונעשית \u0003אויר,\u0004 שה״ס נקודת החולם. שאז עוד החכמה אינה מאירה בה. וכשנגלתה נקודת השורק, שה״ס קו השמאל, שאז יוצאת ה \u0003י׳\u0004 מאויר הבינה וחזרה להיות אור, ונתגלתה בה החכמה (כנ״ל ב״א דף מ״ה ד״ה כד ע״ש) אז נעלמים השערות, כי כבר יצאה \u0003י׳\u0004 מאויר הבינה ששם שורש השערות. ועד״ז כשנמשכה הארת החכמה לקו שמאל דז״א ששם נאחזים הלוים, צריכים הלוים להעביר תער על כל בשרם ולהעביר מהם השערות. וכן כשמגיעה הארת החכמה אל המלכות בעת הזווג עם ז״א, נעברים בחינת השערות גם ממנה. אבל הנזיר הדבוק בימין, שה״ס חולם (עי׳ ב״א טו ד״ה ההוא) ששם נמצאת ה \u0003י׳\u0004 באויר הבינה, ע״כ הוא צריך לגדל פרע שער ראשו. באופן שמבחינת הימין גדלות השערות, ומבחינת הארת חכמה שבשמאל נושרות השערות או שמגלחים אותן."],[4,"ענבים אמא תתאה","וכו׳: ענבים הם אם התחתונה שהיא מלכות, שמאספת יין ושכר אליה, דהיינו הארת החכמה מקו שמאל של הבינה ומלכות כנ״ל. ועל כן הנזיר נפרש מכל צד השמאל, מיין ושכר וענבים, שלא להראות מעשה מהם אצלו. ענבים אלו שהם מלכות, אין שערות וזקן תלויות בהן, שהרי הנוקבא שהיא המלכות, צריכה לגזוז שערה, היינו שער הגוף, כשהיא באה להזדווג עם דכר, שהוא ז״א. וזקן לא נמצא בה. שהיא מטעם הנ״ל בדבור הסמוך, משום זה הנזיר, שהוא מימין, ששם שורש השערות כנ״ל, הוא בהיפך, שערות הראש וזקן תלויות בו ואסור לגלחם, וסוד הדבר, נזיר אלקים נקרא. דהיינו שהוא מופרש משם אלקים שהוא שמאל, ולא נזיר הויה, שהוא ימין. כי הוא נפרש מן הדין לגמרי. נזיר, פירושו נפרש."],[5,"ת״ח על דא","וכו׳: בוא וראה, על זה כתוב, וכפר עליו מאשר חטא על הנפש וגו׳. על נפשו לא כתוב, אלא על הנפש סתם. ומי היא, זו היא ענבים דהיינו מלכות, שנקראים נפש. ועל זה כתוב חטא, דהיינו שחטא למלכות, משום שהצד שלו הוא יין ושכר, כי המלכות נבנית בעיקר מן השמאל, והנזיר גרע ממנה מקום הדין, דהיינו הארת השמאל שואל \u0003חטא,\u0004 למה חטא בזה. ומשיב, אלא שחטא בזה שגרע הדין מן הנפש. דהיינו הארת החכמה שבה, הנמשכת עם הדינים דשמאל. (כנ״ל צו אות קי״ד)."],[6,"אי הכי אמאי","וכו׳: שואל, אם כן שנזיר מתדבק כל כך בימין, למה כתוב בו אח״כ וכפר עליו. ומשיב. הוא משום שבא עתה, אחר שהשלים ימי נזרו, להתחבר עמהם, עם ג׳ הבחינות דקו שמאל, ולהתירו ביין ושכר וענבים, אלו המקומות אין מקבלים אותו, עד שיתיעץ עם כהן, ויכפר עליו. כי משום שמתחילה השליך אותם לחוץ, כי התנזר מהם, כיון שעתה בא אליהם, צריך להתחבר עם תקונים של כפרה, ויקבלו אותו. וזה הוא סוד הדבר."],[7,"ואי תימא שמשון","וכו׳: ואם תאמר, שמשון שהיה נזיר אלקים, למה נענש. ומשיב, אלא יפה היה הדבר, כלומר שהיה ראוי לעונש, משום שבעל בת אל נכר, דהיינו דלילה, והיה לו להתחבר בשלו, במה שראוי לו. והוא שהיה קדוש, ערב קדושה ההיא בבת אל נכר, ועזב מקומו הראוי לקדושה ההיא, וע״כ נענש."],[8,"ואית מאן דאמר","וכו׳: ויש מי שאומר, שאין לו חלק בעולם ההוא. מהו הטעם. הוא, משום שאמר תמות נפשי עם פלשתים, ומסר חלקו עם חלק הפלשתים, שימות נפשו עמהם בעולם ההוא. כך היו מכריזים על הנזיר. לך לך אומרים לנזיר. סבב סבב, אל הכרם לא תקרב. וכבר העמידו החברים."]],[[0,"","כְּשֶׁהִסְתַּכֵּל דָּוִד הַמֶּלֶךְ בְּאוֹתָם דִּינֵי הָאָדָם כְּשֶׁמִּסְתַּלֵּק מֵהָעוֹלָם הַזֶּה, הִקְדִּים וְאָמַר, (תהלים קג) בָּרְכִי נַפְשִׁי אֶת ה', עַד שֶׁלֹּא תֵצֵא מֵהָעוֹלָם, כָּעֵת שֶׁאַתְּ נִמְצֵאת עִם הַגּוּף. וְכָל קְרָבַי אֶת שֵׁם קָדְשׁוֹ, אַתֶּם הָאֵיבָרִים שֶׁמִּשְׁתַּתְּפִים בָּרוּחַ, כָּעֵת שֶׁהִיא נִמְצֵאת אִתְּכֶם, הַקְדִּימוּ לְבָרֵךְ אֶת הַשֵּׁם הַקָּדוֹשׁ עַד שֶׁלֹּא יַגִּיעַ זְמַן שֶׁלֹּא תוּכְלוּ לְבָרְכוֹ וּלְהוֹדוֹת עֲלֵיכֶם."],[1,"","בֹּא רְאֵה, אִישׁ כִּי יַפְלִא לִנְדֹּר נֶדֶר. נָזִיר שֶׁהִקְדִּים בָּעוֹלָם הַזֶּה לְהִתְקַדֵּשׁ בִּקְדֻשַּׁת רִבּוֹנוֹ, מִיַּיִן וְשֵׁכָר יַזִּיר חֹמֶץ יַיִן וְגוֹ'. כָּאן יֵשׁ לְהִסְתַּכֵּל, כֵּיוָן שֶׁאָסוּר לוֹ יַיִן - עֲנָבִים לָמָּה? שֶׁהֲרֵי בַּכֹּהֲנִים כָּתוּב (ויקרא י) יַיִן וְשֵׁכָר אַל תֵּשְׁתְּ וְגוֹ'. יָכוֹל גַּם עֲנָבִים? לֹא. בַּעֲנָבִים מֻתָּר. כָּאן לַנָּזִיר, מָה הַטַּעַם אָסוּר לוֹ עֲנָבִים?"],[2,"","אֶלָּא מַעֲשֶׂה זֶה וְדָבָר זֶה סוֹד עֶלְיוֹן הוּא לְהִפָּרֵד מֵהַדִּין בַּכֹּל. וַהֲרֵי יָדוּעַ אוֹתוֹ עֵץ שֶׁחָטָא בּוֹ אָדָם הָרִאשׁוֹן, עֲנָבִים הָיוּ. וְזֶהוּ סוֹד הַדָּבָר, שֶׁהֲרֵי יַיִן וְשֵׁכָר וַעֲנָבִים בְּצַד אֶחָד נֶאֶחְזוּ. יַיִן לְמַעְלָה, וּפֵרְשׁוּהָ. שֵׁכָר לִשְׂמֹאל, שֶׁהֲרֵי שֵׁכָר יוֹצֵא מִיַּיִן. עֲנָבִים, שֶׁכּוֹנְסִים כֻּלָּם אֲלֵיהֶם, וְזֶהוּ עֵץ שֶׁחָטָא בּוֹ אָדָם הָרִאשׁוֹן. בִּגְלַל זֶה הַכֹּל נֶאֱחָז בְּצַד אֶחָד. וְאִם תֹּאמַר שֶׁנָּזִיר זֶה עָזַב אֱמוּנָה עֶלְיוֹנָה - (כלום) לֹא כָּךְ, אֶלָּא לֹא נִרְאָה בּוֹ מַעֲשֶׂה מִצַּד שְׂמֹאל כְּלוּם."],[3,"","בֹּא רְאֵה, שֶׁהֲרֵי לָמַדְנוּ מִסִּפְרוֹ שֶׁל רַב הַמְנוּנָא סָבָא, וְכָךְ הוּא: כָּתוּב גַּדֵּל פֶּרַע שְׂעַר רֹאשׁוֹ, צָרִיךְ שֶׁיִּתְרַבֶּה שְׂעַר רֹאשׁוֹ וּזְקָנוֹ, וְיִפְרשׁ מִיַּיִן וְשֵׁכָר וַעֲנָבִים, מִשּׁוּם שֶׁכֻּלָּם צַד שְׂמֹאל, וְהַשְּׂעָרוֹת לֹא תְלוּיוֹת. יַיִן - הָאֵם הָעֶלְיוֹנָה (בינה). שֵׁכָר - צַד שֶׁאֲחוּזִים בּוֹ לְוִיִּם, וְיוֹצֵא מִיַּיִן עֶלְיוֹן, וְלֹא תָלוּי הַשֵּׂעָר. וּמִשּׁוּם כָּךְ עוֹלִים הַלְוִיִּם לְאוֹתוֹ מָקוֹם, צָרִיךְ לְהַעֲבִיר כָּל שְׂעָרָם, כְּמוֹ שֶׁנֶּאֱמַר (במדבר ח) וְהֶעֱבִירוּ תַעַר עַל כָּל בְּשָׂרָם."],[4,"","עָנָבִים - הָאֵם הַתַּחְתּוֹנָה, שֶׁכּוֹנֶסֶת יַיִן וְשֵׁכָר לְתוֹכָהּ, וְעַל כָּךְ נִפְרָד מִכָּל צַד שְׂמֹאל, שֶׁלֹּא לְהַרְאוֹת מַעֲשֶׂה שֶׁלָּהֶם אֵלָיו. עֲנָבִים זֶה לֹא תוֹלֶה שֵׂעָר וְזָקָן, שֶׁהֲרֵי הַנְּקֵבָה צְרִיכָה לְסַפֵּר שְׂעָרָהּ כְּשֶׁבָּאָה לְהִזְדַּוֵּג בְּזָכָר, וַהֲרֵי זָקָן לֹא נִמְצָא בָּהּ. בִּגְלַל זֶה הוּא תּוֹלֶה שְׂעַר הָרֹאשׁ וְהַזָּקָן, וְסוֹד הַדָּבָר - נְזִיר אֱלֹהִים (שופטים יג) נִקְרָא, וְלֹא נְזִיר ה', פָּרוּשׁ מֵהַדִּין כֻּלּוֹ."],[5,"","בֹּא רְאֵה, עַל זֶה כָּתוּב, וְכִפֶּר עָלָיו מֵאֲשֶׁר חָטָא עַל הַנָּפֶשׁ וְגוֹ'. עַל נַפְשׁוֹ לֹא כָתוּב, אֶלָּא עַל הַנָּפֶשׁ סְתָם. וּמַהוּ? זֶה עֲנָבִים, שֶׁנִּקְרָא נֶפֶשׁ. וְלָכֵן כָּתוּב חָטָא, מִשּׁוּם שֶׁצַּד שֶׁלּוֹ יַיִן וְשֵׁכָר הוּא, וְגָרַע מִמֶּנּוּ מְקוֹם דִּין. חָטָא, מַה זֶּה חָטָא? אֶלָּא גָּרַע דִּין הַנֶּפֶשׁ."],[6,"","אִם כָּךְ, לָמָּה וְכִפֶּר עָלָיו? מִשּׁוּם שֶׁעַכְשָׁו בָּא לְהִתְחַבֵּר אִתָּם, וְלֹא מְקַבְּלִים אוֹתוֹ מְקוֹמוֹת אֵלֶּה, עַד שֶׁיִּמָּלֵךְ בַּכֹּהֵן וִיכַפֵּר עָלָיו. מִשּׁוּם שֶׁהוּא זָרַק אוֹתָם הַחוּצָה בַּהַתְחָלָה, כֵּיוָן שֶׁכָּעֵת בָּא אֲלֵיהֶם, צָרִיךְ לְהִתְחַבֵּר תִּקּוּן שֶׁל כַּפָּרָה וִיקַבְּלוּהוּ, וְזֶהוּ סוֹד הַדָּבָר. (ודאי בכל)."],[7,"","וְאִם תֹּאמַר, שִׁמְשׁוֹן נְזִיר אֱלֹהִים הָיָה, לָמָּה נֶעֱנַשׁ? אֶלָּא נָאֶה הוּא הַדָּבָר, שֶׁבָּעַל בַּת אֵל נֵכָר, וְהָיָה לוֹ לְהִתְחַבֵּר בְּשֶׁלּוֹ, בְּמַה שֶּׁרָאוּי לוֹ. וְהוּא, שֶׁהָיָה קָדוֹשׁ, עֵרַב אוֹתָהּ קְדֻשָּׁה בְּבַת אֵל נֵכָר, וְעָזַב מְקוֹמוֹ שֶׁרָאוּי לְאוֹתָהּ קְדֻשָּׁה, וְלָכֵן נֶעֱנַשׁ."],[8,"","וְיִשִׁ מִי שֶׁאוֹמֵר, שֶׁאֵין לוֹ חֵלֶק בְּאוֹתוֹ עוֹלָם. מָה הַטַּעַם? מִשּׁוּם שֶׁאָמַר (שופטים טז) תָּמֹת נַפְשִׁי עִם פְּלִשְׁתִּים, וּמָסַר חֶלְקוֹ בְּחֵלֶק פְּלִשְׁתִּים, שֶׁתָּמוּת נַפְשׁוֹ אִתָּם בָּעוֹלָם הַהוּא. כָּךְ הָיוּ מַכְרִיזִים עַל הַנָּזִיר: לֵךְ לֵךְ, אוֹמְרִים לְנָזִיר, סָבִיב סָבִיב, וְלַכֶּרֶם אַל תִקְרַב. וַהֲרֵי פֵּרְשׁוּהָ הַחֲבֵרִים."]]],[["לֵיוָאֵי מַה כְּתִיב בְּהוּ, (במדבר ח׳:ז׳) וְכֹה תַעֲשֶׂה לָהֶם לְטַהֲרָם הַזֶּה עֲלֵיהֶם מֵי חַטָּאת וְהֶעֱבִירוּ תַעַר עַל כָּל בְּשָׂרָם. כֵּיוָן דְּעַבְרֵי שַׂעֲרָא, וְעַבְדֵי כּוּלֵי הַאי, כְּדֵין אִקְרֵי לֵיוָאֵי טָהוֹר, וְלָא קָדוֹשׁ. אֲבָל הַאי נָזִיר בְּגִין דְּאִתְפְּרַשׁ מֵהַאי סִטְרָא, אִקְרֵי קָדוֹשׁ וְלָא טָהוֹר. בְּגִין כַּךְ כְּתִיב, כָּל יְמֵי נֶדֶר נִזְרוֹ וְגוֹ' אֲשֶׁר יַזִּיר לַיְיָ קָדוֹשׁ יִהְיֶה וְגוֹ'.","גַּדֵּל פֶּרַע שְׂעַר רֹאשׁוֹ, מִשּׁוּם הָא דִּכְתִּיב, (דניאל ז׳:ט׳) וּשְׂעַר רֵאשֵׁהּ כַּעֲמַר נְקֵא, דִּבְהַאי דָּמֵי לְגַוְונָא דִּלְעֵילָּא. אָמַר רִבִּי יְהוּדָה בַּר רַב, בְּשַׂעֲרֵי מַמָּשׁ אִשְׁתְּמוֹדַע דְּאִיהוּ קַדִּישָׁא, דִּכְתִּיב, (שיר השירים ה׳:י״א) קֶוִצּוֹתָיו תַּלְתַּלִּים.","תָּאנֵי רִבִּי שִׁמְעוֹן, אִלְמָלֵי יַדְעֵי בְּנֵי נָשָׁא, מַאי קָאַמְרֵי בְּהַאי שַׂעֲרָא, וּבְרָזָא דִּילֵיהּ, (ס\"א בהני שערי ובהני מילין) כְּמָה דְּאִיהוּ בְּרָזָא דְּרָזִין, אִשְׁתְּמוֹדְעָן לְמָארֵיהוֹן, בְּחָכְמְתָא עִלָּאָה. עַד כָּאן רָזֵי דְּאוֹרַיְיתָא, מִכָּאן וּלְהָלְאָה כִּתְרֵי (נ\"א סתרי) תּוֹרָה, (ישעיהו כ״ג:י״ח) סַחְרָהּ וְאֶתְנַנָּהּ קֹדֶשׁ לַיְיָ."],[[0,"ליואי מה כתיב","וכו׳: לוים מה כתוב בהם. וכה תעשה להם לטהרם הזה עליהם מי חטאת, והעבירו תער על כל בשרם. כיון שהעבירו השער, ועשו כל כך, אז נקראים הלוים טהור, ולא קדוש. אבל הנזיר הזה כיון שנפרש מצד הזה, דשמאל, נקרא קדוש ולא טהור (כמ״ש זה לעיל תזריע אות קכ״א בהסולם ע״ש) משום זה כתוב, כל ימי נדר נזרו וגו׳ אשר יזיר לה׳ \u0003קדוש\u0004 יהיה וגו׳."],[1,"גדל פרע שער ראשו:","הוא משום שכתוב, ושער ראשה כעמר נקא. שבזה היא דומה לאפן של מעלה. שהשערות שלו מושכים חסדים כמו למעלה, ואין בהם דין, להיותו כולו ימין. א״ר יהודה בר רב, בשערות ממש ניכר שהוא קדוש, שכתוב על הקב״ה קוצותיו תלתלים."],[2,"תאני ר׳ שמעון","וכו׳: תנא ר״ש, אם היו יודעים בני אדם מה שאומרים בשערות אלו ובסודות שלהם, כמו שהוא למעלה בסוד הסודות, היו נודעים לרבונם בחכמה עליונה. עד כאן סודות התורה, מכאן ולהלאה סתרי תורה. סחרה ואתננה קדש לה׳."]],[[0,"","לְוִיִּם, מַה כָּתוּב בָּהֶם? (במדבר ח) וְכֹה תַעֲשֶׂה לָהֶם לְטַהֲרָם הַזֵּה עֲלֵיהֶם מֵי חַטָּאת וְהֶעֱבִירוּ תַעַר עַל כָּל בְּשָׂרָם. כֵּיוָן שֶׁהֶעֱבִירוּ שֵׂעָר וְעָשׂוּ כָּל זֶה, אָז נִקְרָאִים הַלְוִיִּם טָהוֹר, וְלֹא קָדוֹשׁ. אֲבָל נָזִיר הַזֶּה, מִשּׁוּם שֶׁנִּפְרָד מִצַּד זֶה, נִקְרָא קָדוֹשׁ, וְלֹא טָהוֹר. בִּגְלַל כָּךְ כָּתוּב, כָּל יְמֵי נֶדֶר נִזְרוֹ וְגוֹ' אֲשֶׁר יַזִּיר לַה' קָדשׁ יִהְיֶה וְגוֹ'."],[1,"","גַּדֵּל פֶּרַע שְׂעַר רֹאשׁוֹ, מִשּׁוּם זֶה שֶׁכָּתוּב (דניאל ז) וּשְׂעַר רֹאשׁוֹ כְּצֶמֶר נָקִי, שֶׁבָּזֶה דּוֹמֶה לַגָּוֶן הָעֶלְיוֹן. אָמַר רַבִּי יְהוּדָה בַּר רַב, בַּשְּׂעָרוֹת מַמָּשׁ נוֹדָע שֶׁהוּא קָדוֹשׁ, שֶׁכָּתוּב (שיר השירים ה) ק1ְוֵצּוֹתָיו תַּלְתַּלִּים."],[2,"","שָׁנָה רַבִּי שִׁמְעוֹן, אִלְמָלֵא יָדְעוּ בְּנֵי אָדָם מָה אוֹמְרִים בַּשֵּׂעָר הַזֶּה וּבְסוֹדוֹ (באלו השערות ובאלו הדברים) כְּמוֹ שֶׁהוּא בְּסוֹד הַסּוֹדוֹת, יִוָּדְעוּ לְרִבּוֹנָם בְּחָכְמָה עֶלְיוֹנָה. עַד כָּאן סוֹדוֹת הַתּוֹרָה. מִכָּאן וָהָלְאָה כִּתְרֵי (סתרי) תוֹרָה, (ישעיה כג) סַחְרָהּ וְאֶתְנַנָּהּ קֹדֶשׁ לַה'."]]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[[],[],[]],[["(במדבר ו׳:כ״ג) דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו לֵאמֹר כֹּה תְבָרַכוּ וְגוֹ'. רִבִּי יִצְחָק פָּתַח וְאָמַר, (תהילים ק״ג:י״ז) וְחֶסֶד יְיָ מֵעוֹלָם וְעַד עוֹלָם עַל יְרֵאָיו וְצִדְקָתוֹ לִבְנֵי בָנִים. כַּמָה גְּדוֹלָה הַיִּרְאָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁבִּכְלַל הַיִּרְאָה עֲנָוָה, וּבִכְלַל הָעֲנָוָה חֲסִידוּת. נִמְצָא שֶׁכָּל מִי שֶׁיֵּשׁ בּוֹ יִרְאַת חֵטְא, יֶשְׁנוֹ בְּכֻלָן וּמִי שֶׁאֵינוֹ יְרֵא שָׁמַיִם, אֵין בּוֹ לֹא עֲנָוָה וְלֹא חֲסִידוּת.","תָּאנָא, מִי שֶׁיָּצָא מִן הַיִּרְאָה, וְנִתְלָבַּשׁ בַּעֲנָוָה, עֲנָוָה עָדִיף, וְנִכְלַל בְּכֻלְּהוּ. הֲדָא הוּא דִכְתִיב, (משלי כ״ב:ד׳) עֵקֶב עֲנָוָה יִרְאַת יְיָ. כָּל מִי שֶׁיֵּשׁ בּוֹ יִרְאַת שָׁמַיִם, זוֹכֶה לַעֲנָוָה. כָּל מִי שֶׁיֵּשׁ בּוֹ עֲנָוָה, זוֹכֶה לַחֲסִידוּת. וְכָל מִי שֶׁיֵּשׁ בּוֹ יִרְאַת שָׁמַיִם, זוֹכֶה לְכֻלָּם. לַעֲנָוָה, דִּכְתִּיב עֵקֶב עֲנָוָה יִרְאַת יְיָ. לַחֲסִידוּת, דִּכְתִּיב וְחֶסֶד יְיָ מֵעוֹלָם וְעַד עוֹלָם עַל יְרֵאָיו."],[[0,"דבר אל אהרן:","רבי יצחק פתח ואמר, וחסד ה׳ מעולם ועד עולם על יראיו וצדקתו לבני בנים. כמה גדולה היראה לפני הקב״ה, שבכלל היראה ענוה, ובכלל ענוה חסידות. נמצא שכל מי שיש בו יראת חטא ישנו בכולן. ומי שאינו ירא שמים אין בו לא ענוה ולא חסידות."],[1,"תאנא מי שיצא","וכו׳: למדנו, מי שיצא מן היראה, ונתלבש בענוה, ענוה יותר טוב, והוא נכלל בכולן, ז״ש עקב ענוה יראת ה'. כל מי שיש בו יראת שמים זוכה לענוה, כל מי שיש בו ענוה זוכה לחסידות, וכל מי שיש בו יראת שמים זוכה לכולן, לענוה, שכתוב, עקב ענוה יראת ה'. לחסידות, שכתוב, וחסד ה׳ מעולם ועד עולם על יראיו."]],[[0,"","דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו לֵאמֹר כֹּה תְבָרֲכוּ וְגוֹ'. רַבִּי יִצְחָק פָּתַח וְאָמַר, (תהלים קג) וְחֶסֶד ה' מֵעוֹלָם וְעַד עוֹלָם עַל יְרֵאָיו וְצִדְקָתוֹ לִבְנֵי בָנִים. כַּמָּה גְדוֹלָה הַיִּרְאָה לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁבִּכְלַל הַיִּרְאָה עֲנָוָה, וּבִכְלַל הָעֲנָוָה חֲסִידוּת. נִמְצָא שֶׁכָּל מִי שֶׁיֵּשׁ בּוֹ יִרְאַת חֵטְא, יֶשְׁנוֹ בְכֻלָּן. וּמִי שֶׁאֵינוֹ יְרֵא שָׁמַיִם, אֵין בּוֹ לֹא עֲנָוָה וְלֹא חֲסִידוּת."],[1,"","לָמַדְנוּ, מִי שֶׁיָּצָא מִן הַיִּרְאָה וְנִתְלַבֵּשׁ בַּעֲנָוָה - עֲנָוָה עָדִיף, וְנִכְלָל בְּכֻלָּם. זֶהוּ שֶׁכָּתוּב (משלי כח) עֵקֶב עֲנָוָה יִרְאַת ה'. כָּל מִי שֶׁיֵּשׁ בּוֹ יִרְאַת שָׁמַיִם, זוֹכֶה לַעֲנָוָה. כָּל מִי שֶׁיֵּשׁ בּוֹ עֲנָוָה, זוֹכֶה לַחֲסִידוּת. וְכָל מִי שֶׁיֵּשׁ בּוֹ יִרְאַת שָׁמַיִם, זוֹכֶה לְכֻלָּם. לַעֲנָוָה - שֶׁכָּתוּב עֵקֶב עֲנָוָה יִרְאַת ה'. לַחֲסִידוּת - שֶׁכָּתוּב (תהלים קג) וְחֶסֶד ה' מֵעוֹלָם וְעַד עוֹלָם עַל יְרֵאָיו."]]],[["תָּאנָא, כָּל אָדָם שֶׁיֵּשׁ בּוֹ חֲסִידוּת, נִקְרָא מַלְאַךְ יְיָ צְבָאוֹת. הֲדָא הוּא דִכְתִיב, (מלאכי ב׳:ז׳) כִּי שִׂפְתֵי כֹהֵן יִשְׁמְרוּ דַּעַת וְתוֹרָה יְבַקְשׁוּ מִפִּיהוּ כִּי מַלְאַךְ יְיָ צְבָאוֹת הוּא. מִפְּנֵי מַה זָכָה כֹּהֵן לְהִקָרֵא מַלְאַךְ יְיָ צְבָאוֹת. אָמַר רִבִּי יְהוּדָה, מַה מַלְאַךְ יְיָ צְבָאוֹת, כֹּהֵן לְמַעְלָה, אַף כֹּהֵן מַלְאַךְ יְיָ צְבָאוֹת לְמַטָּה.","וּמַאן הוּא מַלְאַךְ יְיָ צְבָאוֹת לְמַעְלָה. זֶה מִיכָאֵ\"ל הַשַּׂר הַגָּדוֹל, דְּאָתֵי מֵחֶסֶד שֶׁל מַעֲלָה, וְהוּא כֹּהֵן גָּדוֹל שֶׁל מַעֲלָה, כִּבְיָכוֹל, כֹּהֵן גָּדוֹל דִּלְתַּתָּא, אִקְרֵי מַלְאַךְ יְיָ צְבָאוֹת, מִשּׁוּם דְּאָתֵי מִסִּטְרָא דְּחֶסֶד. מַהוּ חֶסֶד. רַחֲמֵי גּוֹ רַחֲמֵי. וּבְגִין כַּךְ, כֹּהֵן לָא אִשְׁתְּכַח מִסִּטְרָא דְּדִינָא. מַאי טַעְמָא זָכָה כֹּהֵן לְחֶסֶד, בְּגִין הַיִּרְאָה. הֲדָא הוּא דִכְתִיב, (תהילים ק״ג:י״ז) וְחֶסֶד יְיָ מֵעוֹלָם וְעַד עוֹלָם עַל יְרֵאָיו.","עוֹלָם וְעוֹלָם מַהוּ. אָמַר רִבִּי יִצְחָק כְּמָה דְּאִתְתָּקַן בְּאִדָּרָא קַדִּישָׁא, עוֹלָם חַד, וְעוֹלָם תְּרֵי. אָמַר רִבִּי חִיָּיא אִי הָכִי מִן הָעוֹלָם וְעַד הָעוֹלָם מִבָּעֵי לֵיהּ. אָמַר לֵיהּ, תְּרֵי עָלְמֵי נִינְהוּ. וְאִתְהַדְּרוּ לְחַד. אָמַר רִבִּי אֶלְעָזָר לְרִבִּי יִצְחָק עַד מָתַי תִּסְתּוֹם דְּבָרִיךְ. מִן הָעוֹלָם וְעַד הָעוֹלָם, כְּלָלָא דְּרָזָא עִלָּאָה, אָדָם דִּלְעֵילָּא, וְאָדָם דִּלְתַּתָּא, וְהַיְינוּ עוֹלָם וְעוֹלָם. וּכְתִיב יְמֵי עוֹלָם, וּכְתִיב שְׁנוֹת עוֹלָם, וְהָא אוּקְמוּהָ בְּאִדָּרָא קַדִּישָׁא עִלָּאָה.","עַל יְרֵאָיו, דְּכָל מַאן דְּאִיהוּ דָּחִיל חַטָּאָה, אִקְרֵי אָדָם. אֵימָתַי. אָמַר רִבִּי אֶלְעָזָר, דְּאִית בֵּיהּ יִרְאָה עֲנָוָה חֲסִידוּת, כְּלָלָא דְּכֹלָּא.","אָמַר רִבִּי יְהוּדָה, וְהָא תָּנֵינָן אָדָם כְּלָלָא דִּדְכַר וְנוּקְבָּא. אָמַר לֵיהּ וַדַּאי הָכָא הוּא, בִּכְלָלָא דְּאָדָם, דְּמַאן דְּאִתְחַבָּר דְּכַר וְנוּקְבָּא, אִקְרֵי אָדָם, וּכְדֵין דָּחִיל חֲטָאָן. וְלֹא עוֹד אֶלָּא שַׁרְיָא בֵּיהּ עֲנָוָה. וְלֹא עוֹד אֶלָּא דְּשַׁרְיָא בֵּיהּ חֶסֶד. וּמַאן דְּלָא אִשְׁתְּכַח דְּכַר וְנוּקְבָּא, לָא הֲווֹ בֵּיהּ לֹא יִרְאָה וְלֹא עֲנָוָה וְלֹא חֲסִידוּת. וּבְגִין כַּךְ אִקְרֵי אָדָם כְּלָלָא דְּכֹלָּא, וְכֵיוָן דְּאִקְרֵי אָדָם, שַׁרְיָיא בֵּיהּ חֶסֶד, דִּכְתִּיב, (תהילים פ״ט:ג׳) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה וְגוֹ'. וְלָא יָכִיל לְאִתְבָּנָאָה, אִי לָא אִשְׁתְּכַח דְּכַר וְנוּקְבָּא.","וּכְתִיב וְחֶסֶד יְיָ מֵעוֹלָם וְעַד עוֹלָם עַל יְרֵאָיו. יְרֵאָיו כְּלָלָא דְּאָדָם. דָּבָר אַחֵר וְחֶסֶד יְיָ מֵעוֹלָם וְעַד עוֹלָם, אִלֵּין אִינּוּן כַּהֲנֵי דְּאָתוּ מִסִּטְרָא דְּחֶסֶד, וְאַחֲסִינוּ אַחֲסָנָא דָּא דְּנָחִית מֵעוֹלָם דִּלְעֵילָּא לְעוֹלָם דִּלְתַּתָּא. עַל יְרֵאָיו, כַּהֲנֵי דִּלְתַּתָּא, דִּכְתִּיב, (ויקרא ט״ז:ו׳) וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ לְאִתְכַּלְּלָא בִּכְלָלָא דְּאָדָם. וְצִדְקָתוֹ לִבְנֵי בָנִים, מִשּׁוּם דְּזָכָה לִבְנֵי בָּנִים. אָמַר רִבִּי יְהוּדָה, אִי הָכִי, מַהוּ וְצִדְקָתוֹ, וְחַסְדּוֹ מִבָּעֵי לֵיהּ.","אָמַר רִבִּי אֶלְעָזָר, הַיְינוּ רָזָא דְּתָנֵינָן בְּזֹאת, (בראשית ב׳:כ״ג) כִּי מֵאִישׁ לֻקֳּחָה זֹּאת. וּכְתִיב (בראשית ב׳:כ״ג) לְזֹאת יִקָּרֵא אִשָּׁה, וְזֹאת אִתְכְּלִילַת בְּאִישׁ, דְּהַיְינוּ חֶסֶד, וְזֹאת נוּקְבָּא. חֶסֶד דְּכַר. וּבְגִין כַּךְ דְּכַר דְּאָתֵי מִסִּטְרָא דְּחִוָּורָא דָּא, אִקְרֵי חֶסֶד. וְזֹאת אִתְקְרֵי צֶדֶק, דְּאַתְיָא מִסְטַר סוּמָקָא. וּבְגִין כַּךְ אִקְרֵי אִשָּׁה. וְהַיְינוּ דִּכְתִּיב וְצִדְקָתוֹ, מַאי וְצִדְקָתוֹ. צִדְקָתוֹ דְּחֶסֶד, בַּת זוּגוֹ, דְּאִתְבָּסְמָא דָּא בְּדָא. וּבְגִין כַּךְ תָּנֵינָן, כָּל כֹּהֵן שֶׁאֵין לוֹ בַּת זוּג, אָסוּר בַּעֲבוֹדָה, דִּכְתִּיב וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ.","אָמַר רִבִּי יִצְחָק, מִשּׁוּם דְּלֵית שְׁכִינְתָּא שַׁרְיָא, בְּמַאן דְּלָא אַנְסִיב, וְכַהֲנֵי בַּעְיָין יַתִּיר מִכָּל שְׁאַר עַמָּא, לְאַשְׁרְיָיא בְּהוּ שְׁכִינְתָּא. וְכֵיוָן דְּשָׁרַת בְּהוּ שְׁכִינְתָּא, שַׁרְיָא בְּהוּ חֶסֶד, וְאִקְרוּן חֲסִידִים. וּבַעְיָין לְבָרְכָא עַמָּא, הֲדָא הוּא דִכְתִיב (תהילים קמ״ה:י׳) וַחֲסִידֶיךָ יְבָרְכוּכָה. וּכְתִיב, (דברים ל״ג:ח׳) תֻּמֶּיךָ וְאוּרֶיךָ לְאִישׁ חֲסִידֶךָ. וּמִשּׁוּם דְּכַהֲנָא אִקְרֵי חָסִיד, בָּעֵי לְבָרְכָא. וּבְגִין כַּךְ כְּתִיב, דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו לֵאמֹר כֹּה תְבָרַכוּ. מַאי טַעֲמָא. מִשּׁוּם דְּאִקְרוּן חֲסִידִים, וּכְתִיב וַחֲסִידֶיךָ יְבָרְכוּכָה.","כֹּה תְבָרַכוּ אֶת בְּנֵי יִשְׂרָאֵל אָמוֹר לָהֶם, כֹּה תְבָרַכוּ, בְּלָשׁוֹן הַקֹּדֶשׁ. כֹּה תְבָרַכוּ, בְּיִרְאָה. כֹּה תְבָרַכוּ, בַּעֲנָוָה. אָמַר רִבִּי אַבָּא, כֹּה תְבָרַכוּ, תָּאנָא, הַאי צֶדֶ\"ק אִתְקְרֵי כֹּ\"ה, דְּכָל דִּינִין מִתְעָרִין מִכֹּ\"ה (נ\"א מניה), וְהַיְינוּ דְּאָמַר רִבִּי אֶלְעָזָר, מַהוּ מַכָּה רַבָּה. (ס\"א דכה) כְּלוֹמַר, מַכָּה מִן כֹּה. וּכְתִיב (שמות ז׳:ט״ז-י״ז) וְהִנֵּה לֹא שָׁמַעְתָּ עַד כֹּ\"ה, כְּמָה דְּאַגְזִים מֹשֶׁה. וּכְתִיב (שמות ז׳:י״ז) בְּזֹאת תֵּדַע כִּי אֲנִי יְיָ, וְכֹלָּא חַד, וּכְתִיב (שמות ז׳:כ״ג) וְלֹא שָׁת לִבּוֹ גַּם לָזֹאת, דִּזְמִינָא לְחַרְבָּא אַרְעֵיהּ."],[[0,"תאנא כל אדם","וכו׳: למדנו כל אדם שיש בו חסידות, נקרא מלאך ה׳ צבאות. ז״ש, כי שפתי כהן ישמרו דעת ותורה יבקשו מפיהו כי מלאך ה׳ צבאות הוא. מפני מה זכה כהן להקרא מלאך ה׳ צבאות. א״ר יהודה, מה מלאך ה׳ צבאות כהן למעלה בשמים, אף הכהן, מלאך ה׳ צבאות למטה."],[1,"ומאן הוא מלאך","וכו׳: ומי הוא מלאך ה׳ צבאות למעלה, זה הוא מיכאל השר הגדול, הבא מחסד שלמעלה, והוא כהן גדול של מעלה. כביכול, כהן גדול שלמטה נקרא מלאך ה׳ צבאות, משום שבא מצד החסד. מהו חסד. רחמים בתוך רחמים. ומשום זה לא נמצא כהן מצד הדין. מהו הטעם שזכה הכהן לחסד. משום היראה. ז״ש, וחסד ה׳ מעולם ועד עולם על יראיו."],[2,"עולם ועולם מהו","וכו׳: שואל, מה זה שאומר ב׳ פעמים עולם. דהיינו מעולם ועד עולם. א״ר יצחק, הוא כמו שנתתקן באדרא קדישא, עולם, הוא אחד, ועד עולם, הוא שני. שהם שני עולמות ז״א ומלכות (ועי׳ לעיל ויחי אות תת״י). א״ר חייא אי הכי מן העולם ועד העולם היה צריך לומר, עם ה׳ הידיעה. אמר לו ב׳ עולמות הם וחזרו לעולם אחד. כלומר שמתיחדים זב״ז. וע״כ אינו אומר בכל אחד ה׳ הידיעה. א״ר אלעזר לר׳ יצחק, עד מתי תסתום דבריך. מן העולם ועד העולם פירושו, הכלל של סוד העליון, דהיינו אדם שלמעלה שהוא ז״א, ואדם שלמטה, שהוא מלכות. והיינו שכתוב עולם ועולם. וכתוב, ימי עולם. וכתוב שנות עולם, וכבר העמידוהו באדרא קדישא עליונה, (באות קס\"ב) שהם נאמרים בז״א שנקרא עולם."],[3,"על יראיו:","היינו מה שאומר, וחסד ה׳ מעולם ועד עולם על יראיו. הוא להורות, שכל מי שהוא ירא חטא נקרא אדם. ששורים עליו ב׳ עולמות הנקראים אדם, מתי הוא. א״ר אלעזר אם יש בו יראה, ענוה, וחסידות, כי היראה היא כלל הכל."],[4,"א\"ר יהודה","וכו׳: אר״י, והרי למדנו, אדם הוא כלל של זכר ונקבה. אמר לו, ודאי כך הוא, שהוא בכלל אדם, כי מי שנתחבר דכר ונוקבא נקרא אדם, ואז הוא ירא שמים. ולא עוד אלא ששורה בו ענוה. ולא עוד אלא ששורה בו חסד. ומי שלא נמצא דכר ונוקבא, אין בו, לא יראה, ולא ענוה, ולא חסידות. ומשום זה נקרא אדם כלל הכל. וכיון שנקרא אדם, שורה בו חסד. שכתוב, אמרתי עולם חסד יבנה וגו', והעולם אינו יכול להבנות, אם לא נמצא דכר ונוקבא."],[5,"וכתיב וחסד ה׳","וגו׳: וכתוב, וחסד ה׳ מעולם ועד עולם על יראיו. כי יראיו, הם כלל אדם. דהיינו דכר ונוקבא, שאל״כ אין בו יראה. פירוש אחר \u0003וחסד ה׳ מעולם ועד עולם.\u0004 אלו הם הכהנים הבאים מצד החסד. והם נוחלים נחלה זו הבאה מעולם העליון שהוא ז״א, לעולם התחתון, שהוא מלכות. \u0003על יראיו,\u0004 הם הכהנים שלמטה, הכוללים דכר ונוקבא, שכתוב, וכפר בעדו ובעד ביתו. שהוא הנוקבא. כדי להכלל בסוד אדם. שהוא דכר ונוקבא. וצדקתו לבני בנים. היינו משום שזכה לבני בנים. אר״י, אם כן מהו וצדקתו, חסדו היה צריך לומר. שהרי ע״י החסד זכה לבני בנים."],[6,"אמר ר׳ אלעזר","וכו׳: אר״א היינו הסוד שלמדנו, \u0003בזאת,\u0004 שהיא המלכות. כי מאיש לקחה \u0003זאת.\u0004 וכתוב \u0003לזאת\u0004 יקרא אשה \u0003וזאת\u0004 נכללת באיש שהוא ז״א, שהוא חסד, \u0003וזאת\u0004 היא נוקבא, \u0003חסד\u0004 הוא דכר. ומשום זה הדכר הבא מצד הלבן הזה, שהוא חסד, נקרא חסד. \u0003וזאת\u0004 נקראת \u0003צדק\u0004 כי באה מצד האדום, שהוא שמאל ודין, ומשום זה נקראת אשה, שהוא לשון אש ודין. והיינו שכתוב, וצדקתו לבני בנים ולא כתוב וחסדו, מהו \u0003וצדקתו.\u0004 היינו צדקתו דחסד, בת זוגו, שנתבשמו זה בזה. ומשום שצדקתו כוללת גם הדכר, שהוא חסד, ע״כ כתוב וצדקתו. ומשום זה למדנו כל כהן שאין לו בת זוג אסור בעבודה, שכתוב, וכפר בעדו ובעד ביתו."],[7,"אמר ר׳ יצחק","וכו׳: אר״י, ע״כ הכהן אסור בעבודה כשאין לו אשה, משום שאין השכינה שורה במי שלא נשא אשה, והכהנים צריכים יותר מכל שאר העם שתשרה בהם השכינה. וכיון שהשכינה שורה בהם, שורה בהם חסד, ונקראים חסידים, וצריכים לברך את העם, ז״ש וחסידיך יברכוכה. וכתוב, תומיך ואוריך לאיש חסידיך. ומשום שהכהן נקרא חסיד, הוא צריך לברך. ומשום זה כתוב דבר אל אהרן ואל בניו לאמר כה תברכו. מהו הטעם. משום שנקראים חסידים, וכתוב וחסידיך יברכוכה."],[8,"כה תברכו","וגו׳: כה תברכו את בני ישראל אמור להם. \u0003כה\u0004 תברכו, היינו בלשון הקודש. \u0003כה\u0004 תברכו היינו ביראה. \u0003כה\u0004 תברכו היינו בענוה. כי המלכות נקראת \u0003כה,\u0004 שבה הקדושה והיראה והענוה. אמר ר׳ אבא, כה תברכו, למדנו צדק זה, שהוא המלכות, נקרא \u0003כה,\u0004 כי כל הדינין באים מן \u0003כה\u0004 כי כה, הוא מלשון כהה, דהיינו בזמן שהמלכות בבחינת שמאל שאז היא כהה ואינה מאירה, וכל הדינים נמשכים ממנה, והיינו דא״ר אלעזר, מהו מכה רבה. כלומר מכה מן כה. וכתוב, והנה לא שמעת עד \u0003כה.\u0004 והיינו כמו שמאיים משה, בהשם כה. וע״ד שכתוב, \u0003בזאת\u0004 תדע כי אני ה'. שהיה מאיים בהשם זאת. והכל אחד. כי המלכות נקראת כה ונקראת זאת. וכתוב, ולא שת לבו גם \u0003לזאת,\u0004 שהיא מוכנת להחריב ארצו."]],[[0,"","לָמַדְנוּ, כָּל אָדָם שֶׁיֵּשׁ בּוֹ חֲסִידוּת, נִקְרָא מַלְאַךְ ה' צְבָאוֹת. זֶהוּ שֶׁכָּתוּב (מלאכי ב) כִּי שִׂפְתֵי כֹהֵן יִשְׁמְרוּ דַעַת וְתוֹרָה יְבַקְשׁוּ מִפִּיהוּ כִּי מַלְאַךְ ה' צְבָאוֹת הוּא. מִפְּנֵי מָה זָכָה כֹּהֵן לְהִקָּרֵא מַלְאַךְ ה' צְבָאוֹת? אָמַר רַבִּי יְהוּדָה, מַה מַּלְאַךְ ה' צְבָאוֹת כֹּהֵן לְמַעְלָה, אַף כֹּהֵן מַלְאַךְ ה' צְבָאוֹת לְמַטָּה."],[1,"","וּמִי הוּא מַלְאַךְ ה' צְבָאוֹת לְמַעְלָה? (דניאל יב) זֶה מִיכָאֵ\"ל הַשַּׂר הַגָּדוֹל, שֶׁבָּא מֵחֶסֶד שֶׁל מַעְלָה, וְהוּא כֹּהֵן גָּדוֹל שֶׁל מַעְלָה. כִּבְיָכוֹל כֹּהֵן גָּדוֹל שֶׁלְּמַטָּה נִקְרָא מַלְאַךְ ה' צְבָאוֹת, מִשּׁוּם שֶׁבָּא מִצַּד הַחֶסֶד. מַהוּ חֶסֶד? רַחֲמִים תּוֹךְ רַחֲמִים. וּמִשּׁוּם כָּךְ כֹּהֵן לֹא נִמְצָא מִצַּד הַדִּין. מָה הַטַּעַם זָכָה כֹּהֵן לְחֶסֶד? בִּגְלַל הַיִּרְאָה. זֶהוּ שֶׁכָּתוּב (תהלים קג) וְחֶסֶד ה' מֵעוֹלָם וְעַד עוֹלָם עַל יְרֵאָיו."],[2,"","מַהוּ עוֹלָם וְעוֹלָם? אָמַר רַבִּי יִצְחָק, כְּמוֹ שֶׁהֻתְקַן בַּחֶדֶר הַקָּדוֹשׁ, עוֹלָם אֶחָד, וְעוֹלָם שְׁנַיִם. אָמַר רַבִּי חִיָּיא, אִם כָּךְ, מִן הָעוֹלָם וְעַד הָעוֹלָם צָרִיךְ לוֹ לִהְיוֹת! אָמַר לוֹ, שְׁנֵי עוֹלָמוֹת הֵם, וְחָזְרוּ לִהְיוֹת אֶחָד. אָמַר רַבִּי אֶלְעָזָר לְרַבִּי יִצְחָק, עַד מָתַי תִּסְתֹּם דְּבָרֶיךְ? מִן הָעוֹלָם וְעַד הָעוֹלָם כְּלָל שֶׁל סוֹד עֶלְיוֹן, אָדָם שֶׁלְּמַעְלָה וְאָדָם שֶׁלְּמַטָּה, וְהַיְנוּ עוֹלָם וְעוֹלָם. וְכָתוּב יְמֵי עוֹלָם, וְכָתוּב שְׁנוֹת עוֹלָם, וַהֲרֵי פֵּרְשׁוּהָ בַּחֶדֶר הַקָּדוֹשׁ הָעֶלְיוֹן."],[3,"","עַל יְרֵאָיו - שֶׁכָּל מִי שֶׁהוּא יְרֵא חֵטְא, נִקְרָא אָדָם. מָתַי? אָמַר רַבִּי אֶלְעָזָר, שֶׁיֵּשׁ בּוֹ יִרְאָה, עֲנָוָה, חֲסִידוּת, כְּלָל שֶׁל הַכֹּל."],[4,"","אָמַר רַבִּי יְהוּדָה, וַהֲרֵי שָׁנִינוּ, אָדָם כְּלַל זָכָר וּנְקֵבָה. אָמַר לוֹ, וַדַּאי כָּךְ זֶה בִּכְלָל שֶׁל אָדָם, שֶׁמִּי שֶׁמִּתְחַבֵּר זָכָר וּנְקֵבָה, נִקְרָא אָדָם, וְאָז יְרֵא חֵטְא. וְלֹא עוֹד, אֶלָּא שֶׁשּׁוֹרָה בּוֹ עֲנָוָה. וְלֹא עוֹד, אֶלָּא שֶׁשּׁוֹרֶה בּוֹ חֶסֶד. וּמִי שֶׁלֹּא נִמְצָא זָכָר וּנְקֵבָה, אֵין בּוֹ לֹא יִרְאָה וְלֹא עֲנָוָה וְלֹא חֲסִידוּת. וּמִשּׁוּם כָּךְ נִקְרָא אָדָם כְּלַל הַכֹּל. וְכֵיוָן שֶׁנִּקְרָא אָדָם, שׁוֹרֶה בּוֹ חֶסֶד, שֶׁכָּתוּב (שם פט) אָמַרְתִּי עוֹלָם חֶסֶד יִבָּנֶה וְגוֹ'. וְלֹא יָכוֹל לְהִבָּנוֹת אִם לֹא נִמְצָא זָכָר וּנְקֵבָה."],[5,"","וְכָתוּב (תהלים קג) וְחֶסֶד ה' מֵעוֹלָם וְעַד עוֹלָם עַל יְרֵאָיו. יְרֵאָיו - כְּלָל שֶׁל אָדָם. דָּבָר אַחֵר וְחֶסֶד ה' מֵעוֹלָם וְעַד עוֹלָם - אֵלֶּה אוֹתָם כֹּהֲנִים שֶׁבָּאוּ מִצַּד הַחֶסֶד, וְיָרְשׁוּ יְרֻשָּׁה זוֹ שֶׁיָּרְדָה מֵעוֹלָם שֶׁלְּמַעְלָה לָעוֹלָם שֶׁלְּמַטָּה. עַל יְרֵאָיו - כֹּהֲנִים שֶׁלְּמַטָּה, שֶׁכָּתוּב (ויקרא טז) וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ, לְהִתְכַּלֵּל בִּכְלָל שֶׁל אָדָם. (שם) וְצִדְקָתוֹ לִבְנֵי בָנִים, מִשּׁוּם שֶׁזָּכָה לִבְנֵי בָנִים. אָמַר רַבִּי יְהוּדָה, אִם כָּךְ, מַהוּ וְצִדְקָתוֹ? וְחַסְדּוֹ הָיָה צָרִיךְ לוֹ לִהְיוֹת!"],[6,"","אָמַר רַבִּי אֶלְעָזָר, הַיְנוּ סוֹד שֶׁשָּׁנִינוּ בְּזֹּאת, (בראשית ב) כִּי מֵאִישׁ לֻקֳחָה זֹּאת. וְכָתוּב לְזֹּאת יִקָּרֵא אִשָּׁה. וְזֹּאת נִכְלְלָה בָּאִישׁ, שֶׁהַיְנוּ חֶסֶד, וְזֹּאת נְקֵבָה. חֶסֶד זָכָר. וּמִשּׁוּם כָּךְ זָכָר שֶׁבָּא מִצַּד הַלָּבָן הַזֶּה, נִקְרָא חֶסֶד. וְזֹּאת נִקְרֵאת צֶדֶק, שֶׁבָּאָה מִצַּד אָדם, וּמִשּׁוּם כָּךְ נִקְרֵאת אִשָּׁה. וְהַיְנוּ מַה שֶּׁכָּתוּב וְצִדְקָתוֹ. מַה זֶּה וְצִדְקָתוֹ? צִדְקָתוֹ שֶׁל חֶסֶד, בַּת זוּגוֹ, לְהִתְבַּשֵּׂם זֶה בָּזֶה. וּמִשּׁוּם כָּךְ לָמַדְנוּ, כָּל כֹּהֵן שֶׁאֵין לוֹ בַּת זוּג, אָסוּר בָּעֲבוֹדָה, שֶׁכָּתוּב וְכִפֶּר בַּעֲדוֹ וּבְעַד בֵּיתוֹ."],[7,"","אָמַר רַבִּי יִצְחָק, מִשּׁוּם שֶׁאֵין שְׁכִינָה שׁוֹרָה בְּמִי שֶׁלֹּא נָשָׂא אִשָּׁה, וְכֹהֲנִים צְרִיכִים יוֹתֵר מִכָּל שְׁאָר הָעָם לְהַשְׁרוֹת בָּהֶם שְׁכִינָה. וְכֵיוָן שֶׁשּׁוֹרָה בָהֶם שְׁכִינָה, שׁוֹרֶה בָהֶם חֶסֶד, וְנִקְרָאִים חֲסִידִים, וּצְרִיכִים לְבָרֵךְ אֶת הָעָם. זֶהוּ שֶׁכָּתוּב (תהלים קמה) וַחֲסִידֶיךְ יְבָרְכוּכָה. וְכָתוּב (דברים לג) תֻּמֶּיךְ וְאוּרֶיךְ לְאִישׁ חֲסִידֶךְ. וּמִשּׁוּם שֶׁכֹּהֵן נִקְרָא חָסִיד, צָרִיךְ לְבָרֵךְ. וּמִשּׁוּם כָּךְ כָּתוּב, דַּבֵּר אֶל אַהֲרֹן וְאֶל בָּנָיו לֵאמֹר כֹּה תְבָרֲכוּ. מָה הַטַּעַם? מִשּׁוּם שֶׁנִּקְרָאִים חֲסִידִים, וְכָתוּב וַחֲסִידֶיךְ יְבָרְכוּכָה."],[8,"","כֹּה תְבָרַכוּ אֶת בְּנֵי יִשְׂרָאֵל אָמוֹר לָהֶם. כֹּה תְבָרֲכוּ - בִּלְשׁוֹן הַקֹּדֶשׁ. כֹּה תְבָרֲכוּ - בְּיִרְאָה. כֹּה תְבָרֲכוּ - בַּעֲנָוָה. אָמַר רַבִּי אַבָּא, כֹּה תְבָרֲכוּ - לָמַדְנוּ, הַצֶּדֶק הַזֶּה נִקְרָא כֹּ\"ה, שֶׁכָּל הַדִּינִים מִתְעוֹרְרִים מִכֹּ\"ה (ממנו), וְהַיְנוּ מַה שֶּׁאָמַר רַבִּי אֶלְעָזָר, מַה זֶּה מַכָּה (שכה) רַבָּה? כְּלוֹמַר, מַכָּה מִכֹּה. וְכָתוּב (שמות ז) וְהִנֵּה לֹא שָׁמַעְתָּ עַד כֹּ\"ה, כְּמוֹ שֶׁהִפְחִיד מֹשֶׁה. וְכָתוּב בְּזֹּאת תֵּדַע כִּי אֲנִי ה', וְהַכֹּל אֶחָד. וְכָתוּב וְלֹא שָׁת לִבּוֹ גַּם לָזֹּאת, שֶׁהִזְמִינָהּ לְהַחֲרִיב אֶת אַרְצוֹ."]]],[["וּמֵהַאי כֹּ\"ה מִתְעָרִין דִּינִין. וּמִדְּאִתְחַבָּר עִמָּהּ חֶסֶד, אִתְבַּסְּמַת. וּבְגִין כַּךְ, אִתְמְסַר דָּא לַכֹּהֵן, דְּאָתֵי מֵחֶסֶד, בְּגִין דְּתִתְבָּרֵךְ וְתִתְבְּסָם כֹּ\"ה, הֲדָא הוּא דִכְתִיב כֹּה תְבָרַכוּ, כְּלוֹמַר, אַף עַל גַּב דְּהַאי כֹּה אִשְׁתְּכָחַת בְּדִינִין, תְּבַסְּמוּן לָהּ, וּתְבָרְכוּן לָהּ, דִּכְתִּיב כֹּה תְבָרַכוּ אֶת בְּנֵי יִשְׂרָאֵל, תְבָרַכוּ בְּהַאי חֶסֶד לְכֹ\"ה, וּתְבַסְּמוּן לָהּ לָקֳבְלַיְיהוּ דְּיִשְׂרָאֵל, בְּגִין דְּלָא יִשְׁתַּכְּחוּן בָּהּ דִּינִין.","הֲדָא הוּא דִכְתִיב כֹּה תְבָרַכוּ אֶת בְּנֵי יִשְׂרָאֵל אָמוֹר לָהֶם. אִמְרוּ לֹא כְּתִיב, אֶלָּא אָמוֹר, לְאַפָּקָא מִשֶּׁרָבּוּ הַפָּרִיצִים, דְּלָא מְפַרְסְמִין מִלָּה, דְּהָא לָא אִתְפְּקָדוּ לְפַרְסְמָא שְׁמָא, מַשְׁמַע דִּכְתִּיב אָמוֹר לָהֶם. אָמוֹר סְתָם. דָּבָר אַחֵר אָמוֹר כֵּיוָן דִּכְתִּיב כֹּה תְבָרַכוּ, אֲמַאי לָא כְּתִיב תֹּאמְרוּ. אֶלָּא תָּנֵי רִבִּי יְהוּדָה, אָמוֹר לָהֶם. זָכוּ לָהֶם, לֹא זָכוּ אָמוֹר סְתָם.","רִבִּי יִצְחָק פָּתַח, (דניאל י׳:ז׳) וְרָאִיתִי אֲנִי דָּנִיֵאל לְבַדִּי אֶת הַמַּרְאָה וְהָאֲנָשִׁים אֲשֶׁר הָיוּ עִמִּי לֹא רָאוּ אֶת הַמַּרְאָה וְגוֹ'. וְרָאִיתִי אֲנִי דָּנִיאֵל לְבַדִּי. וְהָא תָּנֵינָן, אִינְהוּ נְבִיאֵי, וְאִיהוּ לָאו נָבִיא, וּמַאן נִינְהוּ. חַגַּי זְכַרְיָה וּמַלְאָכִי. אִי הָכִי, אִתְעָבִיד קֹדֶשׁ חוֹל, וְהָא כְּתִיב לֹא רָאוּ, אֲמַאי דְּחִילוּ. וּבְדָנִיֵּאל כְּתִיב וְרָאִיתִי אֲנִי, וְלָא דָּחִיל. וְאִיהוּ לָאו נָבִיא, הָא חוֹל קֹדֶשׁ.","אֶלָּא הָכִי תָּאנָא, כְּתִיב (תהילים כ״ז:ג׳) אִם תַּחֲנֶה עָלַי מַחֲנֶה לֹא יִירָא לִבִּי אִם תָּקוּם עָלַי מִלְחָמָה בְּזֹאת אֲנִי בוֹטֵחַ. בְּזֹאת, הָא דְּאַמָרָן זֹאת עַדְבָא חוּלָקֵיהּ, לְאִתְחַסָנָא, וּלְמֶעְבַּד לֵיהּ נוּקְמִין. וְתָנָא, עֲבַיד קוּדְשָׁא בְּרִיךְ הוּא לְדָוִד, רְתִיכָא קַדִּישָׁא עִם אֲבָהָתָא, כִּתְרִין עִלָּאִין קַדִּישִׁין דְּכֹלָּא, דְּאַחֲסִינוּ אֲבָהָתָא. וְתָאנָא, מָלְכוּ יָרִית דָּוִד לִבְנוֹי בַּתְרוֹי. וּבַאֲתָר מַלְכוּ דִּלְעֵילָּא, אִתָּקַף, וְאַחֲסִין הוּא וּבְנוֹי מָלְכוּ דָּא, דְּלָא אַעְדֵּי מִשׁוּלְטָנֵהוֹן לְדָרֵי דָּרִין.","וְתָאנָא, בְּשַׁעֲתָא דְּהַאי כִּתְרָא דְּמַלְכוּתָא אִתְּעַר לִבְנוֹי דְּדָוִד, לֵית מַאן דְּקָאִים קַמֵּיהּ. וְרָאִיתִי אֲנִי דָּנִיֵאל לְבַדִּי אֶת הַמַּרְאָה, מִשּׁוּם דְּמִבְּנוֹי דְּדָוִד הֲוָה, דִּכְתִּיב, (דניאל א׳:ו׳) וַיְהִי בָהֶם מִבְּנֵי יְהוּדָה דָּנִיֵאל חֲנַנְיָה וְגוֹ'. וְהוּא חָמָא וְחַדֵּי בְּהַאי דְּהוּא מִסְּטַר אַחֲסָנַת חוּלָקָא עַדְבָא דַּאֲבוֹי, וּמִשּׁוּם דְּהֲוָה דִּילֵיהּ הוּא סָבִיל, וְאַחֲרִינֵי לָא סַבְלֵי. דְּאָמַר רִבִּי שִׁמְעוֹן, בְּשַׁעֲתָא דְּהַאי כֹּ\"ה אִתְּעַר בְּדִינוֹי, לָא יַכְלִין בְּנֵי עָלְמָא לְמֵיקָם קָמֵיהּ.","וּבְשַׁעֲתָא דְּפַרְסִין כַּהֲנֵי יְדַיְיהוּ, דְּאַתְיָין מֵחֶסֶד, אִתְּעַר חֶסֶד דִּלְעֵילָּא, וְאִתְחַבָּר בְּהַאי כֹּה, וּמִתְבַּסְּמָא וּמִתְבָּרְכָא בְּאַנְפִּין נְהִירִין לִבְנֵי יִשְׂרָאֵל, וְאִתְעָדֵי מִנְּהוֹן דִּינִין, הֲדָא הוּא דִכְתִיב כֹּה תְבָרַכוּ אֶת בְּנֵי יִשְׂרָאֵל, וְלָא לִשְׁאַר עַמִּין.","בְּגִין כַּךְ כֹּהֵן, וְלָא אַחֲרָא. כֹּהֵן בְּגִין דְּיִתְּעַר הַאי כִּתְרָא דִּילֵיהּ חֶסֶ\"ד, עַל יְדוֹי, דְּאִקְרֵי חָסִיד, דִּכְתִּיב, (דברים ל״ג:ח׳) לְאִישׁ חֲסִידֶךָ. וְהוּא אָתֵי מִסִּטְרָא דְּחֶסֶד. וּכְתִיב (תהילים קמ״ה:י׳) וַחֲסִידֶיךָ יְבָרְכוּכָה, אַל תִּקְרֵי יְבָרְכוּכָה, אֶלָּא יְבָרְכוּ כֹּ\"ה. כֹּה תְבָרַכוּ, בְּשֵׁם הַמְּפוֹרָשׁ. כֹּה תְבָרַכוּ, בְּלְשׁוֹן הַקֹּדֶשׁ.","תָּאנָא, אָמַר רִבִּי יְהוּדָה, בְּשַׁעֲתָא דְּכַהֲנָא דִּלְתַּתָּא קָם וּפָרִיס יְדוֹי, כָּל כִּתְרִין קַדִּישִׁין דִּלְעֵילָּא מִתְעָרִין, וּמִתְתַּקְּנִין לְאִתְבָּרְכָא, וְנַהֲרִין מֵעוּמְקָא דְּבֵירָא, דְּאִתְמְשָׁךְ לְהוּ מֵהַהוּא עוּמְקָא דְּנָפַק תָּדִיר, וְלָא פָּסִיק בִּרְכָאן דְּנַבְעִן, מַבּוּעִין לְכֻלְּהוּ עָלְמִין וּמִתְבָּרְכָן וּמִתְשַׁקְיָין מְכֻּלְּהוּ.","וְתָאנָא, בְּהַהוּא זִמְנָא, לְחִישׁוּתָא וּשְׁתִּיקוּתָא הֲוִי בְכָל עָלְמִין. לְמֶלֶךְ דְּבָעֵי לְאִזְדַּוְּוגָא בְּמַטְרוֹנִיתָא, וּבָעֵי לְמֵעַאל לָהּ בִּלְחִישׁוּ, וְכָל שַׁמָּשִׁין מִתְעָרִין בְּהַהוּא זִמְנָא וּמִתְלַחֲשִׁין, הָא מַלְכָּא אָתֵי לְאִזְדַּוְּוגָא בְּמַטְרוֹנִיתָא. מַאן מַטְרוֹנִיתָא. דָּא כְּנֶסֶת יִשְׂרָאֵל. מַאן כְּנֶסֶת יִשְׂרָאֵל. כְּנֶסֶת יִשְׂרָאֵל סְתָם.","תָּאנָא אָמַר רִבִּי יִצְחָק, כֹּהֵן בָּעֵי לְזַקְפָא יְמִינָא עַל שְׂמָאלָא, דִּכְתִּיב, (ויקרא ט׳:כ״ב) וְיִשָּׂא אַהֲרֹן אֶת יָדָו אֶל הָעָם וַיְבָרַכֵם. יָדוֹ כְּתִיב, וְלָא יָדָיו. מִשּׁוּם דִּשְׁבָחָא דִּימִינָא עַל שְׂמָאלָא. אָמַר רִבִּי אֶלְעָזָר, רָזָא הוּא, מִשּׁוּם דִּכְתִּיב, (בראשית ג׳:ט״ז) וְהוּא יִמְשׁוֹל בָּךְ."],[[0,"ומהאי כה מתערין","וכו׳: ומן \u0003כה\u0004 ההוא, שהיא המלכות, מתעוררים דינים וכשנתחבר עמה חסד, נתבשמה. ומשום זה נמסר זה לכהן הבא מחסד, כדי שתתברך ותתבשם אותה \u0003כה,\u0004 ז״ש \u0003כה תברכו,\u0004 כלומר אע\"פ ש \u0003כה\u0004 זו נמצאת בדינים תבשמו אותה ותברכו אותה, שכתוב, כה תברכו את בני ישראל, שפירושו, תברכו בחסד הזה אל \u0003כה,\u0004 ותבשמו אותה בשביל בני ישראל, שלא ימצאו בה דינים."],[1,"הה״ד כה תברכו","וכו׳: ז\"ש כה תברכו את בני ישראל אמור להם. אמרו לא כתוב, אלא אמור. בא להוציא, אשר משרבו הפריצים אין מפרסמין דבר. כי לא נצטוו לפרסם השם \u0003כה,\u0004 זה משמע משכתוב, אמור להם אמור סתם, ולא אמרו להם. פירוש אחר, אמור, כיון שכתוב כה תברכו למה לא כתוב תאמרו להם אלא תני ר׳ יהודה, \u0003אמור להם\u0004 זכו הוא \u0003להם,\u0004 שהברכות מגיעות לישראל. לא זכו הוא \u0003אמור\u0004 סתם."],[2,"ר׳ יצחק פתח","וכו׳: רי״פ, וראיתי אני דניאל לבדי את המראה והאנשים אשר היו עמי לא ראו את המראה וגו׳. שואל, וראיתי אני לבדי, הרי למדנו שהם היו נביאים והוא לא היה נביא, ומי הם. חגי זכריה ומלאכי. א״כ נעשה קדש חול. והרי כתוב לא ראו ולמה יראו. ובדניאל כתוב, וראיתי אני ולא היה מתירא והוא אינו נביא. הרי חול קדש. כלומר מי שאינו נביא קדוש יותר מנביא."],[3,"אלא הכי תאנא","וכו׳: אלא כך למדנו, כתוב, אם תחנה עלי מחנה לא יירא לבי אם תקום עלי מלחמה בזאת אני בוטח. ב \u0003זאת\u0004 היינו זו שאמרנו, שהיא מלכות. \u0003זאת\u0004 היתה גורלו וחלקו להתחזק ולעשות נקמות. ותאנא עשה הקב״ה את דוד מרכבה קדושה עם האבות, וקבל כתרים עליונים קדושים דכל שהנחילו לו האבות. ולמדנו מלכות ירש דוד, ולבניו אחריו. ובמקום מלכות העליונה נתחזק, וירשו הוא ובניו מלכות הזו אשר לא זזה מממשלתם לדורי דורות."],[4,"ותאנא בשעתא","וכו׳: ולמדנו בשעה שספירה זו מלכות נתעוררה לבניו של דוד אין מי שיקום לפניהם. וז\"ש, וראיתי אני דניאל לבדי את המראה, שהיא המלכות הנקראת מראה, משום שהיה מבניו של דוד, שכתוב, ויהי בהם מבני יהודה דניאל חנניה וגו׳. ע״כ הוא ראה ושמח בה, שהיא מצד נחלת חלקו וגורלו של אביו, דוד. ומשום שהיתה שלו, הוא סבל אותה, ולא היה מתירא, והאחרים לא יכלו לסבול, והיו מתיראים. ואע״פ שלא ראו מזלם ראו. דאמר ר׳ שמעון, בשעה ש \u0003כה\u0004 זו מתעוררת בדיניה, אין בני העולם יכולים לקום מפניה."],[5,"ובשעתא דפרסין כהני","וכו': אלא בשעה שהכהנים פורשים ידיהם הבאות מחסד, מתעורר חסד שלמעלה ומתחבר בכה הזו, ומתבסמת ומתברכת בפנים מאירות לבני ישראל, והדינים סרים מהם, ז\"ש, כה תברכו את בני ישראל, ולא לשאר העמים."],[6,"בגין כך כהן","וכו׳: ומשום זה כהן מברך, ולא אחר, כהן, כדי שתתעורר על ידו הספירה שלו חסד, כי הוא נקרא חסיד, שכתוב, לאיש חסידך, והוא בא מצד החסד. וכתוב, וחסידיך יברכוכה, אל תקרא יברכוכה אלא יברכו כה. \u0003כה\u0004 תברכו היינו בשם המפורש. \u0003כה\u0004 תברכו, בלשון הקדש."],[7,"תאנא אמר ר' יהודה","וכו׳: למדנו, אמר ר״י, בשעה שהכהן שלמטה קם ופורש ידיו, כל הספירות הקדושות שלמעלה מתעוררות ומתתקנות להתברך, ומאירים מעומק הבאר שהוא בינה, שנמשך להן מעומק ההוא היוצא תמיד, ולא נפסקו הברכות הנובעות ונעשות מבועים לכל העולמות. המתברכים ונשקים מכולם."],[8,"ותאנא בהאי זמנא","וכו׳: ולמדנו בזמן ההוא, שהכהנים נושאים ידיהם, לחש ושתיקה נעשו בכל העולמות. בדומה למלך שרצה להזדווג עם המלכה ורצה לבא אליה בחשאי. וכל המשמשים מתעוררים בזמן ההוא ומתלחשים, הרי המלך בא להזדווג עם המלכה. מי היא המלכה. זו היא כנסת ישראל. מי היא כנסת ישראל. כנסת ישראל סתם. שהיא המלכות."],[9,"תאנא אמר ר׳ יצחק","וכו׳: למדנו אר״י, הכהן צריך לשאת יד ימין על השמאל, שכתוב, וישא אהרן את \u0003ידו\u0004 אל העם ויברכם. ידו כתוב, ולא ידיו. שהוא משום שבח יד ימין על השמאל. אמר רבי אלעזר, סוד הוא משום שכתוב, והוא ימשול בך. אשר הדכר שהוא ימין, ימשול על הנוקבא, שהוא שמאל."]],[[0,"","מֵהַכֹּ\"ה הַזֹּאת מִתְעוֹרְרִים הַדִּינִים, וּמִשֶּׁהִתְחַבֵּר עִמָּהּ חֶסֶד, מִתְבַּשֶּׂמֶת. וּמִשּׁוּם כָּךְ נִמְסָר זֶה לַכֹּהֵן שֶׁבָּא מֵחֶסֶד, כְּדֵי שֶׁתִּתְבָּרֵךְ וְתִתְבַּשֵּׂם כֹּ\"ה. זֶהוּ שֶׁכָּתוּב כֹּה תְבָרֲכוּ. כְּלוֹמַר, אַף עַל גַּב שֶׁהַכֹּה הַזֹּאת נִמְצֵאת בְּדִינִים, תְּבַשְּׂמוּ אוֹתָהּ וּתְבָרְכוּ אוֹתָהּ, שֶׁכָּתוּב כֹּה תְבָרֲכוּ אֶת בְּנֵי יִשְׂרָאֵל. תְּבָרְכוּ בְחֶסֶד זֶה אֶת כֹּ\"ה, וּתְבַשְּׂמוּ אוֹתָהּ מוּל יִשְׂרָאֵל, כְּדֵי שֶׁלֹּא יִמָּצְאוּ בָהּ דִּינִים."],[1,"","זְהִוּ שֶׁכָּתוּב כֹּה תְבָרֲכוּ אֶת בְּנֵי יִשְׂרָאֵל אָמוֹר לָהֶם. לֹא כָתוּב אִמְרוּ, אֶלָּא אָמוֹר, לְהוֹצִיא מִשֶּׁרַבּוּ הַפָּרִיצִים שֶׁלֹּא מְפַרְסְמִים דָּבָר, שֶׁהֲרֵי לֹא הִצְטַוּוּ לְפַרְסֵם הַשֵּׁם, מַשְׁמָע שֶׁכָּתוּב אָמוֹר לָהֶם. אָמוֹר סְתָם. דָּבָר אַחֵר אָמוֹר - כֵּיוָן שֶׁכָּתוּב כֹּה תְבָרֲכוּ, לָמָּה לֹא כָתוּב תֹּאמְרוּ? אֶלָּא שָׁנָה רַבִּי יְהוּדָה, אָמוֹר לָהֶם, זָכוּ - לָהֶם. לֹא זָכוּ - אָמוֹר סְתָם."],[2,"","רַבִּי יִצְחָק פָּתַח, (דניאל י) וְרָאִיתִי אֲנִי דָנִיֵּאל לְבַדִּי אֶת הַמַּרְאָה וְהָאֲנָשִׁים אֲשֶׁר הָיוּ עִמִּי לֹא רָאוּ אֶת הַמַּרְאָה וְגוֹ'. וְרָאִיתִי אֲנִי דָנִיֵּאל לְבַדִּי?! וַהֲרֵי שָׁנִינוּ, הֵם נְבִיאִים, וְהוּא לֹא נָבִיא, וּמִי הֵם? חַגַּי זְכַרְיָה וּמַלְאָכִי. אִם כָּךְ, נַעֲשָׂה קֹדֶשׁ חֹל, וַהֲרֵי כָּתוּב לֹא רָאוּ, לָמָּה פָּחֲדוּ? וּבְדָנִיֵּאל כָּתוּב וְרָאִיתִי אֲנִי, וְלֹא פָחַד, וְהוּא לֹא נָבִיא, הֲרֵי חֹל קֹדֶשׁ?"],[3,"","אֶלָּא כָּךְ לָמַדְנוּ, כָּתוּב (תהלים כז) אִם תַּחֲנֶה עָלַי מַחֲנֶה לֹא יִירָא לִבִּי אִם תָּקוּם עָלַי מִלְחָמָה בְּזֹּאת אֲנִי בוֹטֵחַ. בְּזֹּאת, זֶה שֶׁאָמַרְנוּ. זֹּאת חֶבֶל חֶלְקוֹ לִירַשׁ וְלַעֲשׂוֹת לוֹ נְקָמוֹת. וְשָׁנִינוּ, עָשָׂה הַקָּדוֹשׁ בָּרוּךְ הוּא אֶת דָּוִד מֶרְכָּבָה קְדוֹשָׁה עִם הָאָבוֹת, כְּתָרִים עֶלְיוֹנִים קְדוֹשִׁים שֶׁל הַכֹּל, שֶׁיָּרְשׁוּ הָאָבוֹת. וְלָמַדְנוּ שֶׁדָּוִד הוֹרִישׁ מַלְכוּת לְבָנָיו, וּבִמְקוֹם מַלְכוּת הָעֶלְיוֹנָה הִתְחַזֵּק וְיָרַשׁ הוּא וּבָנָיו מַלְכוּת זוֹ שֶׁלֹּא תַעֲבֹר מִשִּׁלְטוֹנָם לְדוֹרֵי דוֹרוֹת."],[4,"","וְלָמַדְנוּ, בְּשָׁעָה שֶׁכֶּתֶר הַמַּלְכוּת הַזֶּה הִתְעוֹרֵר לִבְנֵי דָוִד, אֵין מִי שֶׁיַּעֲמֹד לְפָנָיו. וְרָאִיתִי אֲנִי דָנִיֵּאל לְבַדִּי אֶת הַמַּרְאָה, מִשּׁוּם שֶׁמִּבְּנֵי דָוִד הָיָה, שֶׁכָּתוּב (דניאל א) וַיְהִי בָהֶם מִבְּנֵי יְהוּדָה דָּנִיֵּאל חֲנַנְיָה וְגוֹ'. וְהוּא רָאָה וְשָׂמַח בָּזֶה שֶׁהוּא מִצַּד יְרֻשַּׁת חֵלֶק חֶבֶל אָבִיו, וּמִשּׁוּם שֶׁהָיָה שֶׁלּוֹ הוּא סָבַל, וַאֲחֵרִים לֹא סָבְלוּ. שֶׁאָמַר רַבִּי שִׁמְעוֹן, בְּשָׁעָה שֶׁהַכֹּ\"ה הַזֹּאת מִתְעוֹרֶרֶת בְּדִינֶיהָ, לֹא יְכוֹלִים בְּנֵי הָעוֹלָם לַעֲמֹד לְפָנֶיהָ."],[5,"","וּבְשָׁעָה שֶׁהַכֹּהֲנִים פּוֹרְשִׂים יְדֵיהֶם, שֶׁבָּאִים מֵחֶסֶד, מִתְעוֹרֵר חֶסֶד שֶׁלְּמַעְלָה וּמִתְחַבֵּר בַּכֹּ\"ה הַזֹּאת, וּמִתְבַּשֶּׂמֶת וּמִתְבָּרֶכֶת בְּפָנִים מְאִירוֹת לִבְנֵי יִשְׂרָאֵל, וּמַעֲבִירִים מֵהֶם דִּינִים. זֶהוּ שֶׁכָּתוּב כֹּה תְבָרַכוּ אֶת בְּנֵי יִשְׂרָאֵל, וְלֹא אֶת שְׁאָר הָעַמִּים."],[6,"","בִּגְלַל כָּךְ כֹּהֵן וְלֹא אַחֵר. כֹּהֵן, כְּדֵי שֶׁיִּתְעוֹרֵר הַכֶּתֶר הַזֶּה שֶׁלּוֹ, חֶסֶד, עַל יָדוֹ, שֶׁנִּקְרָא חָסִיד, שֶׁכָּתוּב (דברים לג) לְאִישׁ חֲסִידֶךְ. וְהוּא בָּא מִצַּד הַחֶסֶד. וְכָתוּב (תהלים קמה) וַחֲסִידֶיךְ יְבָרְכוּכָה. אַל תִּקְרֵי יְבָרְכוּכָה, אֶלָּא יְבָרְכוּ כֹ\"ה. כֹּה תְבָרֲכוּ - בַּשֵּׁם הַמְפֹרָשׁ. כֹּה תְבָרֲכוּ - בִּלְשׁוֹן הַקֹּדֶשׁ."],[7,"","לָמַדְנוּ, אָמַר רַבִּי יְהוּדָה, בְּשָׁעָה שֶׁהַכֹּהֵן שֶׁלְּמַטָּה קָם וּפוֹרֵשׂ יָדָיו, כָּל הַכְּתָרִים (ספירות) הַקְּדוֹשִׁים שֶׁלְּמַעְלָה מִתְעוֹרְרִים וּמְתֻקָּנִים לְהִתְבָּרֵךְ, וּמְאִירִים מֵעֹמֶק הַבְּאֵר שֶׁנִּמְשָׁךְ לָהֶם מֵאוֹתוֹ עֹמֶק שֶׁיּוֹצֵא תָמִיד, וְלֹא פוֹסְקִים הַבְּרָכוֹת הַנּוֹבְעוֹת מַבּוּעִים לְכָל הָעוֹלָמוֹת, וּמִתְבָּרְכִים וּמֻשְׁקִים מִכֻּלָּם."],[8,"","וְלָמַדְנוּ, בְּאוֹתוֹ זְמַן לַחַשׁ וּשְׁתִיקָה יֵשׁ בְּכָל הָעוֹלָמוֹת. לְמֶלֶךְ שֶׁרוֹצֶה לְהִזְדַּוֵּג בַּמַּלְכָּה וְרוֹצֶה לְהִכָּנֵס אֵלֶיהָ בְּלַחַשׁ, וְכָל הַשַּׁמָּשִׁים מִתְעוֹרְרִים בְּאוֹתוֹ זְמַן וּמִתְלַחֲשִׁים: הֲרֵי הַמֶּלֶךְ בָּא לְהִזְדַּוֵּג בַּמַּלְכָּה. מִי הַמַּלְכָּה? זוֹ כְּנֶסֶת יִשְׂרָאֵל. מִי כְּנֶסֶת יִשְׂרָאֵל? כְּנֶסֶת יִשְׂרָאֵל סְתָם."],[9,"","לָמַדְנוּ, אָמַר רַבִּי יִצְחָק, כֹּהֵן צָרִיךְ לִזְקֹף יָמִין עַל שְׂמֹאל, שֶׁכָּתוּב (ויקרא ט) וַיִּשָּׂא אַהֲרֹן אֶת יָדָו אֶל הָעָם וַיְבָרַכֵם. יָדוֹ כָּתוּב, וְלֹא יָדָיו, מִשּׁוּם שֶׁשֶּׁבַח הַיָּמִין עַל הַשְּׂמֹאל. אָמַר רַבִּי אֶלְעָזָר, סוֹד הוּא, מִשּׁוּם שֶׁכָּתוּב (בראשית ג) וְהוּא יִמְשָׁל בָּךְ."]]],[["תָּאנָא, כֹּהֵן דְּבָעֵי לְפָרְסָא יְדוֹי, בָּעֵי דְּיִתּוֹסַף קְדוּשָּׁה עַל קְדוּשָּׁה דִּילֵיהּ, דְּבָעֵי לְקַדְּשָׁא יְדוֹי, עַל יְדָא דְּקַדִּישָׁא. מַאן יְדָא דְּקַדִּישָׁא. דָּא לֵיוָאָה. דְּבָעֵי כַּהֲנָא לִיטוֹל קְדוּשָּׁה דְּמַיָיא מִיְּדוֹי, דִּכְתִּיב וְקִדַּשְׁתָּ אֶת הַלְּוִיִּם, הָא אִינּוּן קַדִּישִׁין. וּכְתִיב בְּהוּ בַּלְוִיִּם, (במדבר י״ח:ב׳) וְגַם אֶת אַחֶיךָ מַטֵּה לֵוִי וְגוֹ'. שֵׁבֶט אָבִיךָ כְּלָל. מִכָּאן, דְּכָל כֹּהֵן דְּפָרִיס יְדוֹי, בָּעֵי לְאִתְקַדְּשָׁא עַל יְדֵי דְּקַדִּישָׁא, לִיתוֹסַף קְדוּשָּׁה עַל קְדוּשָׁתֵיהּ. וְעַל דָּא, לָא יִטּוֹל קְדוּשָּׁה דְּמַיָיא, מִבַּר נָשׁ אַחֲרָא, דְּלָא הֲוִי קַדִּישָׁא.","וּבִצְנִיעוּתָא דְּסִפְרָא תָּאנָא, לֵוִי דְּאִתְקַדָּשׁ כַּהֲנָא עַל יְדוֹי, בָּעֵי הוּא לְאִתְקַדְּשָׁא בְּקַדְמִיתָא. וַאֲמַאי לֵוִי, וְיִתְקַדַּשׁ עַל יְדָא דְּכַהֲנָא אַחֲרָא. תָּאנָא, כַּהֲנָא אַחֲרָא לָא בָּעֵי, דְּהָא כֹּהֵן דְּלָא שְׁלִים, לָא בָּעֵי הַאי כַּהֲנָא שְׁלִים, לְאִתְפְּגַם עַל יְדָא דִּפְגִימָא דְּלָא שְׁלִים. אֲבָל לֵוִי דְּאִיהוּ שְׁלִים, וְאִתְחַזֵּי לְסַלְּקָא בְּדוּכָנָא, וּלְמִפְלַח בְּמִשְׁכַּן זִמְנָא, הָא שְׁלִים הוּא, וְהָא אִקְרֵי קָדוֹשׁ, דִּכְתִּיב וְקִדַּשְׁתָּ אֶת הַלְּוִיִּם. אָמַר רִבִּי תַּנְחוּם, אַף אִקְרֵי טָהוֹר, דִּכְתִּיב, (במדבר ח׳:ו׳) וְטִהַרְתָּ אוֹתָם. וּבְגִין כַּךְ בָּעֵי לְאוֹסָפָא כַּהֲנָא קְדוּשָּׁה עַל קְדוּשָׁתֵיהּ.","תָּאנָא, כַּהֲנָא דְּפָרִיס יְדוֹי, בָּעֵי דְּלָא יִתְחַבְּרוּן אֶצְבְּעָן דָּא בְּדָא, בְּגִין דְּיִתְבָּרְכוּן כִּתְרִין קַדִּישִׁין, כָּל חַד וְחַד בִּלְחוֹדוֹי, כְּמָה דְּאִתְחֲזֵי לֵיהּ. בְּגִין דִּשְׁמָא קַדִּישָׁא בָּעֵי לְאִתְפָּרְשָׁא בְּאַתְוָון רְשִׁימִין דְּלָא לְאַעְרְבָא דָּא בְּדָא. וְלָא יִתְכַּוְון (נ\"א ולאתכוונא) בְּאִינּוּן מִלִּין.","אָמַר רִבִּי יִצְחָק, בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא דְּיִתְבָּרְכוּן עִלָּאֵי, בְּגִין דְּיִתְבָּרְכוּן תַּתָּאֵי, וְיִתְבָּרְכוּן עִלָּאֵי דְּאִינּוּן קַדִּישִׁין בִּקְדוּשָּׁה עִלָּאָה, עַל יְדָא דְּתַתָּאֵי, דְּאִינּוּן קַדִּישִׁין בִּקְדוּשָּׁה עִלָּאָה, דְּאִינּוּן קַדִּישִׁין מִכָּל קַדִּישִׁין דִּלְתַּתָּא, דִּכְתִּיב, (תהילים קמ״ה:י׳) וַחֲסִידֶיךָ יְבָרְכוּכָה.","אָמַר רִבִּי יְהוּדָה, כָּל כֹּהֵן דְּלָא יָדַע רָזָא דָּא, וּלְמַאן מְבָרֵךְ, וּמַאן הִיא בִּרְכָתָא דִּמְבָרֵךְ, לָאו בִּרְכָתָא דִּילֵיהּ בִּרְכָתָא, וְהַיְינוּ דִּכְתִּיב, (מלאכי ב׳:ז׳) כִּי שִׂפְתֵי כֹּהֵן יִשְׁמְרוּ דַעַת וְתוֹרָה יְבַקְשׁוּ מִפִּיהוּ. מַאי דַעַת. דַעַת סְתָם. וְתוֹרָה יְבַקְשׁוּ מִפִּיהוּ, עִלָּאִין, יְבַקְשׁוּ מִפִּיהוּ. וּמַאי יְבַקְשׁוּ מִפִּיהוּ. תּוֹרָה. תּוֹרָה סְתָם, הֵיךְ אֲחִידָא תּוֹרָה דִּלְעֵילָּא דְּאִקְרֵי תּוֹרָה סְתָם. דְּתַנְיָא, תּוֹרָה שֶׁבִּכְתָּב וְתוֹרָה שֶׁבְּעַל פֶּה בְּאִינּוּן כִּתְרִין עִלָּאִין דְּאִתְקְרוּן הָכִי. מַאי טַעְמָא. כִּי מַלְאַךְ יְיָ צְבָאוֹת הוּא. וְתָנֵינָא, דְּבָעֵי כַּהֲנָא לְכַוְּונָא בְּאִינּוּן מִלִּין דִּלְעֵילָּא, לְיַחֲדָא שְׁמָא קַדִּישָׁא כְּמָה דְּאִצְטְרִיךְ.","אָמַר רַבִּי שִׁמְעוֹן, תָּאנָא בִּצְנִיעוּתָא דְּסִפְרָא, שְׁמָא קַדִישָׁא אִתְגַּלְיָיא וְאִתְכַּסְיָיא. דְּאִתְגַּלְיָיא, כְּתִיב בְּיוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. דְּאִתְכַּסְיָיא כְּתִיב בְּאַתְוָון אַחֲרָן, וּמְהַהוּא דְּאִתְכַּסְיָיא הַהוּא טְמִירָא (ס\"א אחרנין וההוא דאתכסייא הוא טמירו) דְּכֹלָּא. אָמַר רִבִּי יְהוּדָה, וַאֲפִילּוּ הַהוּא דְּאִתְגַּלְיָיא, אִתְכַּסְיָא בְּאַתְוָון אַחֲרָן, בְּגִין הַהוּא טְמִירָא דִּטְמִירִין בְּגוֹ.","דְּהָא הָכָא בָּעֵי כַּהֲנָא לְצָרְפָא שְׁמָא קַדִּישָׁא, וּלְמֵיחַת רַחֲמֵי, (כלהו) דְּכֻלְּהוּ כְּלִילָן בְּדִיבּוּר דְכ\"ב אַתְוָון (ס\"א דכלהו מכילן) (ס\"א בתרי כתרי) כִּתְרֵי דְּרַחֲמֵי. וּבְהָנֵי אַתְוָון דְּהַאי שְׁמָא, סְתִימָאן כ\"ב מְכִילָן דְּרַחֲמֵי, וי\"ג דַעֲתִּיקָא סָתִים וְגָנִיז מִכֹּלָּא, וְט' דְּאִתְגַּלְּיָין מִזְּעֵיר אַנְפִּין (בזעיר אנפין) וּמִתְחַבְּרָן כֻּלְּהוּ בְּצֵרוּפָא דִּשְׁמָא חַד, דְּהֲוָה מְכַוִּון כַּהֲנָא כַּד פְּרֵיס יְדוֹי בְּכ\"ב אַתְוָון גְּלִיפָן.","וְתָאנָא, כַּד הֲוָה צְנִיעוּתָא בְּעָלְמָא, הֲוָה מִתְגַּלְיָיא שְׁמָא דָּא לְכֹלָּא. מִדְּאַסְגֵי חֲצִיפוּתָא בְּעָלְמָא, סָתִים בְּאַתְווֹי. דְּכַד הֲוָה מִתְגַּלְיָיא. כַּהֲנָא מְכַוִּין, וּשְׁמָא מִתְפְּרַשׁ. בְּמַאי מְכַוִּין. מְכַוִּין בִּסְתִּימָא דְּטָמִיר וְגָנִיז, וּמִתְגַּלְיָיא וּמִתְפְּרַשׁ. מִדְּאַסְגֵי חֲצִיפוּתָא בְּעָלְמָא, סָתִים כֹּלָּא בְּאַתְוָון רְשִׁימִין."],[[0,"תאנא כהן דבעי","וכו׳: למדנו כהן הרוצה לישא את כפיו, צריך שיתוסף קדושה על קדושתו, דהיינו שצריך לקדש ידיו על יד הקדוש. ומי הוא יד קדוש. זה הוא הלוי, שהכהן צריך ליטול קדושת המים מידיו. שכתיב, וקדשת את הלוים. הרי שהם קדושים. וכתוב בהם בלוים, וגם את אחיך מטה לוי שבט אביך וגו׳. שהם בכלל שבט אביך. מכאן שכל כהן שנושא כפיו צריך להתקדש על ידי קדוש, שיתוסף קדושה על קדושתו. וע״כ לא יטול קדושת המים מאדם אחר שאינו קדוש."],[1,"ובצניעותא דספרא תאנא","וכו': ולמדנו בספרא דצניעותא, הלוי, שהכהן מתקדש על ידיו, צריך הוא להתקדש תחלה. שואל, למה לוי, ויתקדש על ידי כהן אחר. ומשיב, כהן אחר אין צריך לקדש כהן חברו, כי הוא יכול להיות כהן שאינו שלם, שאסור בעבודה, וכהן השלם אינו צריך שיופגם ע״י הפגום שאינו שלם. אבל לוי שהוא שלם, וראוי לעלות בדוכן לעבוד עבודת אהל מועד, הרי הוא שלם, וזה נקרא קדוש, שכתוב, וקדשת את הלוים. א״ר תנחום אף נקרא טהור, שכתוב וטהרת אותם. ומשום זה צריך הכהן להוסיף קדושה על קדושתו. שיהיה נכלל גם מלוי. כי בחינת הטהרה רק בלוי היא (כנ״ל תזריע אות קכ״ג)."],[2,"תאנא כהנא דפריס","וכו׳: למדנו, כהן הנושא את כפיו, צריך שלא יתחברו אצבעותיו זו בזו, כדי שיתברכו ספירות הקדושות כל אחת בפני עצמה כמו שראוי לה. משום שהשם הקדוש צריך להתפרש באותיות רשומות שלא לערב זו בזו. ויכוון באלו הדברים."],[3,"א״ר יצחק","וכו׳: אר״י, רצה הקב״ה שיתברכו העליונים כדי שיתברכו התחתונים. כי אחר שספירות העליונות מתמלאות משפע הברכות הן מברכות את התחתונים. ויתברכו העליונים שהם קדושים בקדושה עליונה, על ידי התחתונים שהם קדושים בקדושה עליונה, והם קדושים מכל הקדושים שלמטה. דהיינו הכהנים. שכתוב, וחסידיך יברכוכה."],[4,"א״ר יהודה כל","וכו׳: אר״י, כל כהן שאינו יודע סוד הזה, ולמי הוא מברך, ומה היא הברכה שמברך אין הברכה שלו ברכה. והיינו שכתוב, כי שפתי כהן ישמרו דעת ותורה יבקשו מפיהו. מהו דעת. הוא דעת סתם. דהיינו ספירת הדעת המיחדת חו״ב. ותורה יבקשו מפיהו, העליונים יבקשו מפיהו. ומה יבקשו מפיהו. תורה. דהיינו תורה סתם. שהוא ז״א, שיבקשו מפיהו, לדעת איך מתיחדת התורה שלמעלה הנקראת תורה סתם. שלמדנו, תורה שבכתב ותורה שבעל פה הם בכתרים העליונים הנקראים כך. דהיינו בז״א הנקרא תורה שבכתב, ובמלכות הנקראת תורה שבעל פה. מהו הטעם, שיודע כל כך. מסיים הכתוב, כי מלאך ה׳ צבאות הוא. ולמדנו שהכהן צריך לכוון באלו הדברים שלמעלה ליחד השם הקדוש כמו שצריך."],[5,"אמר ר״ש תאנא","וכו׳: אר״ש, למדנו בספרא דצניעותא. השם הקדוש מגולה ומכוסה. המגולה כתוב ביוד הא ואו הא. המכוסה כתוב באותיות אחרות. ואותו שנתכסה הוא נסתר מכל. אר״י, ואפילו אותו שנתגלה מכוסה באותיות אחרות, משום אותו הנסתר מכל נסתר שבפנים."],[5,"","פירוש. השם המגולה הוא ז״א, והנסתר הוא א״א. וז״ש, \u0003דאתגלייא כתיב ביוד הא ואו הא,\u0004 דהיינו ז״א, \u0003ודאתכסיא כתיב באתוון אחרנין.\u0004 דהיינו אהיה, שהוא שם הכתר. וא״א הוא מלובש בפנימיות ז״א. וז״ש, \u0003ואפילו ההוא דאתגלייא אתכסייא באתוון אחרן,\u0004 דהיינו בשם אדנ\"י, שהוא המלכות. \u0003בגין ההוא טמירא דטמירין בגו.\u0004 משום שא״א מלובש בפנימיות ז״א, ע״כ גם ז״א מכוסה. ואינו נגלה רק אדנ״י לבדה."],[6,"דהא הכא בעי","וכו׳: כי כאן צריך הכהן לצרף השם הקדוש ולהוריד רחמים, שכולם כלולים בדבור של כ״ב אותיות כתרי הרחמים. שה״ס השם של כ״ב אותיות, אנקתם וכו', המובא בברכת כהנים. ובאותיות אלו של שם הזה סתומים כ״ב מדות הרחמים, שהם י״ג תקוני דיקנא דעתיקא הסתום והגנוז מכל (כנ\"ל באדרא רבא אות ע״ב) וט׳ תקוני דיקנא שנגלו מז״א (כנ״ל באד״ר אות רמ״ז) ט׳ וי״ג הם כ״ב. ומתחברים כל כ״ב מדות הרחמים בצרוף שם אחד שהיה הכהן מכוון, כשנושא את ידיו, בכ״ב אותיות חקוקות. דהיינו בשם כ״ב, אנקת״ם וכו'."],[7,"ותאנא כד הוה","וכו׳: ולמדנו, כשהיה צניעות בעולם, היה מתגלה שם הזה, של כ״ב אותיות, לכל. וכשנתרבה החוצפה בעולם, נסתם באותיותיו. שבעת שהשם היה מגולה, היה הכהן מכוין, והשם מתפרש ומתגלה. במה היה מכוין. היה מכוין בסתום הנסתר והגנוז, והשם מתגלה ומתפרש. משנתרבה החוצפה בעולם, נסתם הכל באותיות רשומות, דהיינו בכ״ב אותיות."]],[[0,"","לָמַדְנוּ, כֹּהֵן שֶׁרוֹצֶה לִפְרֹשׂ יָדָיו, צָרִיךְ שֶׁיִּתּוֹסֵף קְדֻשָּׁה עַל קְדֻשָּׁתוֹ, שֶׁצָּרִיךְ לְקַדֵּשׁ יָדָיו עַל יַד הַקָּדוֹשׁ. מִי יָד שֶׁל הַקָּדוֹשׁ? זֶה לֵוִי, שֶׁצָּרִיךְ כֹּהֵן לִטֹּל קְדֻשָּׁה שֶׁל מַיִם מִיָּדָיו, שֶׁכָּתוּב וְקִדַּשְׁתָּ אֶת הַלְוִיִּם. הֲרֵי הֵם קְדוֹשִׁים. וְכָתוּב בַּלְוִיִּם, (במדבר יח) וְגַם אֶת אַחֶיךְ מַטֵּה לֵוִי וְגוֹ'. שֵׁבֶט אָבִיךְ - כְּלָל. מִכָּאן שֶׁכָּל כֹּהֵן שֶׁפּוֹרֵשׂ יָדָיו, צָרִיךְ לְהִתְקַדֵּשׁ עַל יְדֵי קָדוֹשׁ, לְהוֹסִיף קְדֻשָּׁה עַל קְדֻשָּׁתוֹ. וְלָכֵן לֹא יִטֹּל קְדֻשָּׁה שֶׁל מַיִם מִבֶּן אָדָם אַחֵר שֶׁאֵינֶנּוּ קָדוֹשׁ."],[1,"","וּבְסִפְרָא דִצְנִיעוּתָא לָמַדְנוּ, לֵוִי שֶׁהִתְקַדֵּשׁ כֹּהֵן עַל יָדוֹ, צָרִיךְ הוּא לְהִתְקַדֵּשׁ בַּתְּחִלָּה. וְלָמָּה לֵוִי? שֶׁיִּתְקַדֵּשׁ עַל יְדֵי כֹהֵן אַחֵר. לָמַדְנוּ, כֹּהֵן אַחֵר לֹא צָרִיךְ, שֶׁהֲרֵי כֹּהֵן שֶׁאֵינוֹ שָׁלֵם, לֹא צָרִיךְ זֶה הַכֹּהֵן הַשָּׁלֵם לְהִפָּגֵם עַל יְדֵי פָגוּם שֶׁלֹּא שָׁלֵם. אֲבָל לֵוִי שֶׁהוּא שָׁלֵם וְרָאוּי לַעֲלוֹת לַדּוּכָן וְלַעֲבֹד בְּאֹהֶל מוֹעֵד, הֲרֵי הוּא שָׁלֵם, וַהֲרֵי נִקְרָא קָדוֹשׁ, שֶׁכָּתוּב וְקִדַּשְׁתָּ אֶת הַלְוִיִּם. אָמַר רַבִּי תַנְחוּם, אַף נִקְרָא טָהוֹר, שֶׁכָּתוּב וְטִהַרְתָּ אֹתָם. וּמִשּׁוּם כָּךְ צָרִיךְ לְהוֹסִיף כֹּהֵן קְדֻשָּׁה עַל קְדֻשָּׁתוֹ."],[2,"","לָמַדְנוּ, כֹּהֵן שֶׁפּוֹרֵשׂ יָדָיו, צָרִיךְ שֶׁהָאֶצְבָּעוֹת לֹא יִתְחַבְּרוּ זוֹ בָּזוֹ, כְּדֵי שֶׁיִּתְבָּרְכוּ כְתָרִים קְדוֹשִׁים כָּל אֶחָד וְאֶחָד לְבַדּוֹ כְּמוֹ שֶׁרָאוּי לוֹ, מִשּׁוּם שֶׁשֵּׁם הַקָּדוֹשׁ צָרִיךְ לְהִתְפָּרֵשׁ בְּאוֹתִיּוֹת רְשׁוּמוֹת שֶׁלֹּא לְעָרֵב זֶה בָּזֶה, וְלֹא יִתְכַּוֵּן (ולהתכון) בְּאוֹתָם דְּבָרִים."],[3,"","אָמַר רַבִּי יִצְחָק, רוֹצֶה הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁיִּתְבָּרְכוּ עֶלְיוֹנִים כְּדֵי שֶׁיִּתְבָּרְכוּ תַחְתּוֹנִים, וְיִתְבָּרְכוּ עֶלְיוֹנִים שֶׁהֵם קְדוֹשִׁים בִּקְדֻשָּׁה עֶלְיוֹנָה עַל יְדֵי הַתַּחְתּוֹנִים, שֶׁהֵם קְדוֹשִׁים בִּקְדֻשָּׁה עֶלְיוֹנָה, שֶׁהֵם קְדוֹשִׁים מִכָּל קְדוֹשִׁים שֶׁלְּמַטָּה, שֶׁכָּתוּב (תהלים קמה) וַחֲסִידֶיךְ יְבָרְכוּכָה."],[4,"","אָמַר רַבִּי יְהוּדָה, כָּל כֹּהֵן שֶׁלֹּא יוֹדֵעַ סוֹד זֶה, וּלְמִי מְבָרֵךְ, וּמַהִי הַבְּרָכָה שֶׁמְּבָרֵךְ - אֵין בִּרְכָתוֹ בְּרָכָה, וְהַיְנוּ מַה שֶּׁכָּתוּב (מלאכי ב) כִּי שִׂפְתֵי כֹהֵן יִשְׁמְרוּ דַעַת וְתוֹרָה יְבַקְשׁוּ מִפִּיהוּ. מַה זֶּה דַּעַת? דַּעַת סְתָם. וְתוֹרָה יְבַקְשׁוּ מִפִּיהוּ, עֶלְיוֹנִים יְבַקְשׁוּ מִפִּיהוּ. וּמַה יְבַקְשׁוּ מִפִּיהוּ? תּוֹרָה. תּוֹרָה סְתָם. אֵיךְ אֲחוּזָה תוֹרָה שֶׁלְּמַעְלָה שֶׁנִּקְרֵאת תּוֹרָה סְתָם? שֶׁלָּמַדְנוּ, תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה בְּאוֹתָם כְּתָרִים עֶלְיוֹנִים שֶׁנִּקְרְאוּ כָּךְ. מָה הַטַּעַם? כִּי מַלְאַךְ ה' צְבָאוֹת הוּא. וְלָמַדְנוּ שֶׁצָּרִיךְ הַכֹּהֵן לְכַוֵּן בְּאוֹתָם דְּבָרִים שֶׁלְּמַעְלָה לְיַחֵד אֶת הַשֵּׁם הַקָּדוֹשׁ כְּפִי שֶׁצָּרִיךְ."],[5,"","אָמַר רַבִּי שִׁמְעוֹן, לָמַדְנוּ בְּסִפְרָא דִּצְנִיעוּתָא, שֵׁם הַקָּדוֹשׁ גָּלוּי וּמְכֻסֶּה, שֶׁגָּלוּי הֲרֵי כָּתוּב בְּיוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. שֶׁמְּכֻסֶּה כָּתוּב בְּאוֹתִיּוֹת אֲחֵרוֹת, וְאוֹתוֹ שֶׁמְּכֻסֶּה הוּא הַנִּסְתָּר (אחרים, ואותו שמכסה הוא נסתר) שֶׁל הַכֹּל. אָמַר רַבִּי יְהוּדָה, וַאֲפִלּוּ אוֹתוֹ שֶׁמְּגֻלֶּה מְכֻסֶּה בְּאוֹתִיּוֹת אֲחֵרוֹת, בִּגְלַל אוֹתוֹ טְמִיר הַטְּמִירִים בִּפְנִים."],[6,"","שֶׁהֲרֵי כָּאן צָרִיךְ הַכֹּהֵן לְצָרֵף שֵׁם הַקָּדוֹשׁ וּלְהוֹרִיד רַחֲמִים, (כלם) שֶׁכֻּלָּם כְּלוּלִים בְּדִבּוּר שֶׁל עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת (שכלן מדות) (בשני כתרים) כִּתְרֵי הָרַחֲמִים. וּבְאוֹתִיּוֹת אֵלּוּ שֵׁל הַשֵּׁם הַזֶּה סְתוּמִים עֶשְׂרִים וּשְׁתַּיִם מִדּוֹת הָרַחֲמִים, וּשְׁלֹשׁ עֶשְׂרֵה שֶׁל הָעַתִּיק נִסְתָּר וְגָנוּז מֵהַכֹּל. וְתֵשַׁע שֶׁהִתְגַּלּוּ מִזְּעֵיר אַנְפִּין (בזעיר אנפין), וּמִתְחַבְּרִים כֻּלָּם בְּצֵרוּף שֵׁם אֶחָד שֶׁהָיָה הַכֹּהֵן מְכַוֵּן כְּשֶׁפָּרַס יָדָיו בְּעֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת חֲקוּקוֹת."],[7,"","וְלָמַדְנוּ, כְּשֶׁהָיְתָה צְנִיעוּת בָּעוֹלָם, הָיָה מִתְגַּלֶּה שֵׁם זֶה לַכֹּל. מִשֶּׁרָבְתָה הַחֻצְפָּה בָּעוֹלָם, נִסְתַּר בְּאוֹתִיּוֹתָיו. שֶׁכְּשֶׁהָיָה מִתְגַּלֶּה, הַכֹּהֵן הָיָה מְכַוֵּן, וְהַשֵּׁם מִתְפָּרֵשׁ. בַּמֶּה מְכַוֵּן? מְכַוֵּן בַּנִּסְתָּר שֶׁטָּמִיר וְגָנוּז, וּמִתְגַּלֶּה וּמִתְפָּרֵשׁ. מִשֶּׁהִתְרַבְּתָה הַחֻצְפָּה בָּעוֹלָם, נִסְתַּר הַכֹּל בְּאוֹתִיּוֹת רְשׁוּמוֹת."]]],[["וְתָּא חֲזֵי, דְּכָל הָנֵי כ\"ב אַתְוָון (ס\"א רחמי) (ס\"א דכל הני כ\"ב מכילן דרחמי), מֹשֶׁה אֲמָרָן בִּתְרֵי זִמְנֵי. זִמְנָא קַדְמָאָה אָמַר, י\"ג מְכִילָן דְעַתִּיקָא דְּעַתִּיקִין סְתִימָא דְּכֹלָּא, לְנַחְתָּא אִלֵּין לְאֲתָר דְּדִינָא אִשְׁתְּכַח, לְאַכְפְּיָא לְהוּ. זִמְנָא תִּנְיָינָא, אָמַר ט' מְכִילָן דְּרַחֲמֵי, דִּכְלִילָן בִּזְעֵיר אַנְפִּין, וּנְהִירִין מֵעַתִּיקָא סְתִימָאָה דְּכֹלָּא. וְכֻלְּהוּ כָּלִיל כַּהֲנָא כַּד פְּרֵיס יְדוֹי לְבָרְכָא עַמָּא, וּמִשְׁתַּכְחָן דְּמִתְבָּרְכִין כֻּלְּהוּ (ס\"א עלאין) עָלְמִין בְּסִטְרָא דְּרַחֲמֵי, דְּאִתְמַשְּׁכָן מֵעַתִּיקָא טְמִירָא סְתִימָאָה דְּכֹלָּא. וְכָל הָנֵי כ\"ב אַתְוָון, מְכִילָן סְתִימָאן.","יְבָרֶכְךָ יְיָ וְיִשְׁמְרֶךָ, אִלֵּין תְּלַת קְרָאֵי, וְג' שְׁמָהָן דִּתְרֵיסָר אַתְוָון כְּלִילָן לָקֳבְלֵיהוֹן, וּבְכֹלָּא אִתְכְּוָון כַּהֲנָא. וְכָל עִלָּאֵי וְתַתָּאֵי מִתְבַסְּמָן בְּכ\"ב אַתְוָון, דִּסְתִּימִין בְּהָנֵי ג' קְרָאֵי, לָקֳבֵיל כ\"ב (אתוון) מְכִילָן דְּרַחֲמֵי דְּכָלִיל כֹּלָּא. וּבְגִין כָּךְ כְּתִיב אָמוֹר, וְלָא אִמְרוּ, כְּמָה דְּאוֹקִימְנָא. אָמוֹר. דְּבָעֵי לְכַוְּונָא בְּכָל הָנֵי סְתִימִין, בְּכָל הָנֵי דַּרְגִין. אָמוֹר: בְּמִלִּין סְתִימִין דִּלְעֵילָּא. אָמוֹר: חוּשְׁבָן רמ\"ח אֵבָרִין דִּבְאָדָם חָסֵר חַד. מַאי טַעְמָא. דִּבְחַד תַּלְיָין כֻּלְּהוּ. וְכֻלְּהוּ מִתְבָּרְכָאן בְּהַאי בִּרְכָתָא, בְּהָנֵי תְּלַת קְרָאֵי, כִּדְאַמָרָן. לָהֶם: לְאִתְכַּלְּלָא בְּהַאי בִּרְכָתָא עִלָּאִין וְתַתָאִין.","תָּאנָא, אָמַר רִבִּי יוֹסֵי, יוֹמָא חַד יָתִיבְנָא קַמֵּיהּ דְּרִבִּי אֶלְעָזָר בֶּן רִבִּי שִׁמְעוֹן, שָׁאִילְנָא לֵיהּ, אֲמֵינָא, רִבִּי מַאי קָא חָמָא דָּוִד דְּקָאָמַר (תהילים ל״ו:ז׳) אָדָם וּבְהֵמָה תּוֹשִׁיעַ יְיָ, אָדָם תִּינַח, בְּהֵמָה לָמָּה. אָמַר לֵיהּ יָאוּת שָׁאַלְתָּ, כֹּלָּא בְּמִנְיָינָא הוּא, זָכוּ אָדָם, לֹא זָכוּ בְּהֵמָה.","אֲמֵינָא, רִבִּי, רָזָא דְּמִלָּה קָא בָּעֵינָא. אָמַר לֵיהּ כֹּלָּא אִתְּמַר, וְתָּא חֲזֵי, קָרָא קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל אָדָם, כְּגַוְונָא דִּלְעֵילָּא. וְקָרָא לְהוּ בְּהֵמָה, וְכֹלָּא בְּחַד קְרָא, דִּכְתִיב (יחזקאל ל״ד:ל״א) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי וְגוֹ'. וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי, הָא בְּהֵמָה. אָדָם אַתֶּם, הָא אָדָם. וְיִשְׂרָאֵל אִקְרוּ אָדָם וּבְהֵמָה, וּבְגִין כָּךְ אָדָם וּבְהֵמָה תּוֹשִׁיעַ יְיָ. וְעוֹד רָזָא דְּמִלָּה, זָכוּ אָדָם כְּגַוְונָא דִּלְעֵילָּא. לֹא זָכוּ, בְּהֵמָה אִקְרוּן. וְכֻלְּהוּ מִתְבָּרְכָאן בְּשַׁעֲתָא חֲדָא. אָדָם דִּלְעֵילָּא. וּבְהֵמָה דִּלְתַּתָּא. וְכָּל שֶׁכֵּן דְּכֹלָּא אִית בְּהוּ בְּיִשְׂרָאֵל, הֲדָא הוּא דִכְתִיב אָדָם וּבְהֵמָה תּוֹשִׁיעַ יְיָ.","וְתָּא חֲזֵי, לֵית בִּרְכָתָא לְתַתָא אִשְׁתְּכַח, עַד דְּיִשְׁתְּכַח לְעֵילָּא. וּמִדְּאִשְׁתְּכַח לְעֵילָּא אוּף לְתַתָּא אִשְׁתְּכַח, וְכֹלָּא הָכִי תַּלְיָא לְטָב וּלְבִישׁ. לְטָב, דִּכְתִיב (הושע ב׳:כ״ג) אֶעֱנֶה אֶת הַשָּׁמָיִם וְהֵם יַעֲנוּ אֶת הָאָרֶץ. לְבִישׁ, דִּכְתִיב (ישעיהו כ״ד:כ״א) יִפְקוֹד יְיָ עַל צְבָא הַמָּרוֹם בַּמָּרוֹם וְעַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה.","אָמַר רִבִּי יְהוּדָה, בְּגִין כָּךְ (האי תפארת פתח ביה) כְּתִיב אָמוֹר לָהֶם סְתָם, לְאִתְבָּרְכָא עִלָּאִין וְתַתָּאִין, כֻּלְּהוּ כַּחֲדָא. דִּכְתִיב כֹּה תְבָרַכוּ בַּתְחִלָּה, וְאַחַר כַּךְ אֶת בְּנֵי יִשְׂרָאֵל אָמוֹר לָהֶם סְתָם, לְאִתְבָּרְכָא כֻּלְּהוּ כַּחֲדָא, יְבָרֶכְךָ יְיָ, לְעֵילָּא. וְיִשְׁמְרֶךָ, לְתַתָּא. יָאֵר יְיָ פָּנָיו, לְעֵילָּא. וִיחֻנֶּךָ, לְתַתָּא. יִשָּׂא יְיָ פָּנָיו, לְעֵילָּא. וְיָשֵׂם לְךָ שָׁלוֹם לְתַתָּא.","רִבִּי אַבָּא אָמַר, כֻּלְּהוּ כַּחֲדָא מִתְבָּרְכָאן, בְּכ\"ב אַתְוָון גְּלִיפָן דִּשְׁמָא קַדִישָׁא דְּאִתְכְּלַל וְסָתִים הָכָא, בְּכ\"ב אַתְוָון מִתְבָּרְכָאן כֻּלְּהוּ. וְאִינּוּן רַחֲמֵי גּוֹ רַחֲמֵי, דְּלָא אִשְׁתְּכַח בְּהוּ דִּינָא. וְלָא, וְהָכְּתִיב יִשָּׂא יְיָ פָּנָיו אֵלֶיךָ. אָמַר רִבִּי אַבָּא, יִשָּׂא: יְסָלַּק וְיַעְבָּר בְּגִין דְּלָא יִשְׁתְּכַח דִּינָא כְּלָל.","תָּאנָא, אָמַר רִבִּי יוֹסֵי, בְּשַׁעֲתָא דְּכַהֲנָא פְּרֵיס יְדוֹי, אָסִיר לֵיהּ לְעַמָּא לְאִסְתַּכְּלָא בֵּיהּ, מִשּׁוּם דִּשְׁכִינְתָּא שַׁרְיָא בִּידוֹי. אָמַר רִבִּי יִצְחָק, אִי הָכִי, כֵּיוָן דְּלָא חָמָאן מַה אִכְפַּת לְהוּ, דְּהָא כְּתִיב (שמות ל״ג:כ׳) כִּי לֹא יִרְאַנִי הָאָדָם וָחָי, בְּחַיֵּיהוֹן לָא חָמָאן, אֲבָל בְּמִיתָתְהוֹן חָמָאן. אָמַר לֵיהּ, מִשּׁוּם דִּשְׁמָא קַדִּישָׁא רְמִיזָא בְּאֶצְבְּעָן דִּידוֹי, וּבָעֵי בַּר נָשׁ לְדַחֲלָא, אַף עַל גַּב דְּלָא חָמָאן שְׁכִינְתָּא, לָא בָּעָאן לְאִסְתַּכְּלָא בִּידַיְיהוּ דְּכַהֲנֵי, בְּגִין דְּלָא יִשְׁתַּכְחוּן עַמָּא חֲצִיפָאן לְגַבֵּי שְׁכִינְתָּא.","תָּאנָא, בְּהַהִיא שַׁעֲתָא דְּכַהֲנָא פְּרֵיס יְדוֹי, צְרִיכִין עַמָּא לְמֵיתַב בִּדְחִילוּ, בְּאֵימָתָא, וְלִינְדַע דְּהַהִיא שַׁעֲתָא, עִידָן רְעוּתָא אִשְׁתְּכַח בְּכֻלְּהוּ עָלְמִין, וּמִתְבָּרְכָן עִלָּאִין וְתַתָּאִין, וְלֵית דִּינָא בְּכֻלְּהוּ. וְהוּא שַׁעֲתָא, דְּאִתְגְּלֵי סְתִימָא עַתִּיקָא דְּעַתִּיקִין בִּזְעֵיר אַנְפִּין וְאִשְׁתְּכַח שְׁלָמָא בְּכֹלָּא."],[[0,"ות״ח דכל הני","וכו׳: ובוא וראה, שכל אלו כ״ב מדות הרחמים אמרם משה בב׳ פעמים. בפעם הא׳ אמר, י״ג מדות של עתיק דעתיקין הסתום מכל, שהוא א״א. להורידם למקום שהדין נמצא, שהוא ז״א, להכניע הדינים. שה״ס י״ג מדות הרחמים שאמר בפרשת כי תשא: אל רחום וחנון וגו׳. ופעם שניה אמר ט׳ מדות הרחמים הכלולים בז״א, ומאירים מעתיקא סתימאה דכלא. והיינו האמורות בפרשת שלח: ארך אפים ורב חסד וגו׳. (כנ״ל באדרא רבא אות צ״ח) וכולם כולל הכהן כשנושא ידיו לברך העם, ונמצא שכל העולמות מתברכים בצד הרחמים הנמשכים מעתיקא הגנוז הסתום מכל. וכל אלו כ״ב אותיות, שבשם היוצא מברכת כהנים, אנקת״ם וכו', הן מדות סתומות. שהם כ״ב מדות הרחמים כנ\"ל."],[1,"יברכך ה׳ וישמרך:","בג׳ מלות, יברכך הויה וישמרך, יש ט״ו אותיות, שאלו ג׳ פסוקים שבברכת כהנים, וג׳ שמות, שבכל פסוק, שם הויה אחד, שהם שתים עשרה אותיות, כי בכל שם ד׳ אותיות, ג״פ ד׳ הן י״ב. ועם ג׳ פסוקים הם ט״ו. שהם כלולים כנגדם בט״ו אותיות דיברכך הויה וישמרך. ובכל זה נתכוון הכהן. וכל העליונים והתחתונים מתבשמים בכ״ב אותיות, דהיינו בהשם כ״ב, הסתומות באלו ג׳ פסוקים דברכת כהנים, שהם כנגד כ״ב מדות הרחמים הכוללות הכל. ומשום זה כתוב אמור להם ולא אמרו להם, כמו שהעמדנו (באות קמ״ז) \u0003אמור,\u0004 היינו שצריך לכוון בכל אלו סודות הסתומים הנ״ל, בכל אלו המדרגות. \u0003אמור,\u0004 היינו בדברים הסתומים של מעלה. \u0003אמור,\u0004 הוא בחשבון רמ״ח אברים שבאדם חסר אחד. שסודם נתבאר לעיל (באד״ר אות ש״ט) מה הטעם חסר אחד. משום שבאחד העליון שהוא א״א, תלוים כל רמ״ח, וכולם מתברכים בברכה הזו בג׳ פסוקים אלו, כמו שאמרנו. להם. שכתוב אמור \u0003להם.\u0004 היינו לכלול בברכה ההיא העליונים והתחתונים."],[2,"תאנא א\"ר יוסי","וכו׳: למדנו אר״י, יום אחד ישבתי לפני ר׳ אלעזר ב״ר שמעון, שאלתי אותו, אמרתי, רבי מה ראה דוד שאמר אדם ובהמה תושיע ה׳. אדם, יפה הוא, אבל בהמה למה. אמר לי יפה שאלת, הכל הוא בחשבון הישועה, אם זכו נושעים כאדם, אם לא זכו נושעים כבהמה."],[3,"אמינא רבי רזא","וכו׳: אמרתי, רבי, הסוד של הדבר אני רוצה לדעת. אמר לו הכל אמור, הן הסוד והן הפשט, ובוא וראה, הקב״ה קרא לישראל אדם, כעין של מעלה, שהוא ז״א. וקרא אותם בהמה. והכל בפסוק אחד, שכתוב ואתן צאני צאן מרעיתי אדם אתם וגו׳. ואתן צאני צאן מרעיתי, הרי שקרא אותם בהמה. אדם אתם, הרי שקרא אותם אדם. כי ישראל נקראים אדם ובהמה, ומשום זה אדם ובהמה תושיע ה'. ועוד, סוד הדבר, זכו נקראים אדם כעין של מעלה. לא זכו נקראים בהמה. וכולם מתברכים בשעה אחת אדם שלמעלה שה״ס ז״א, הנק' הויה במילוי אלפין שבגי׳ אדם. ובהמה שלמטה, שה״ס המלכות הנק׳ הויה במילוי ההין, שהוא בגי׳ בהמה. וכל שכן שהכל יש בישראל, שגם בישראל יש ב׳ מדרגות אדם ובהמה, דהיינו אותם הנשמות הנמשכות מז״א ואותם הנשמות הנמשכות ממלכות. וז\"ש אדם ובהמה תושיע ה׳."],[4,"ות״ח לית ברכתא","וכו׳: ובוא וראה אין ברכה נמצאת למטה, עד שתהיה נמצאת למעלה תחלה, וכשנמצאת למעלה, היא נמצאת גם כן למטה. והכל תלוי כך למעלה, הן לטוב והן לרע. לטוב, שכתוב, אענה את השמים והם יענו את הארץ. לרע, שכתוב, יפקוד ה׳ על צבא המרום במרום ועל מלכי האדמה על האדמה."],[5,"א״ר יהודה בג״כ","וכו׳: אר״י, משום זה כתוב, אמור \u0003להם\u0004 סתם, שמורה, שיתברכו העליונים והתחתונים כולם יחד. שכתוב, כה תברכו בתחלה, ואח״כ, את בני ישראל אמור להם סתם, שלא כתוב אמור לישראל, והיינו שיתברכו כולם יחד, העליונים והתחתונים: יברכך ה'. הוא למעלה, וישמרך, הוא למטה, יאר ה׳ פניו, הוא למעלה. ויחנך הוא למטה. ישא ה׳ פניו, הוא למעלה. וישם לך שלום הוא למטה."],[6,"ר' אבא אמר","וכו׳: רא״א, כולם יחד מתברכים בכ\"ב אותיות חקוקות של השם הקדוש הנכלל וסתום כאן, בברכת כהנים, בהשם כ״ב אותיות מתברכים הכל. והם רחמים בתוך רחמים, שלא נמצא בהם דין. שואל, ולא, והרי כתוב, ישא ה׳ פניו אליך, וישא הוא דין, אמר ר׳ אבא, \u0003ישא\u0004 פירושו, יסלק ויעביר כדי שלא יהיה נמצא דין כלל."],[7,"תאנא א״ר יוסי","וכו׳: למדנו אר״י, בשעה שהכהן נושא ידיו אסור לעם להסתכל בו, משום שהשכינה שורה בידיו. א\"ר יצחק, א״כ, כיון שאינם רואים, מה זה מזיק להם. כי כתוב, כי לא יראני האדם וחי. שבחייהם אינם רואים רק במיתתם רואים. אמר לו משום שהשם הקדוש רמוז באצבעות ידיהם, וצריך האדם לירא, ואע״פ שאינם רואים השכינה, אינם צריכים להסתכל בידיהם של הכהנים, כדי שהעם לא יהיו מחוצפים כלפי השכינה."],[8,"תאנא בההיא שעתא","וכו׳: למדנו בשעה ההיא שהכהן נושא כפיו צריך העם לשבת ביראה באימה, ולדעת שבשעה ההיא נמצא עת רצון בכל העולמות, והעליונים והתחתונים מתברכים, ואין דין בכולם. והיא השעה שנגלה הסתום עתיק דעתיקין בז\"א, ונמצא שלום בכל העולמות."]],[[0,"","וּבֹא רְאֵה שֶׁכָּל אֵלּוּ עֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת (רחמים) (שכל אלו עשרים ושתים מדות הרחמים), מֹשֶׁה אָמַר אוֹתָן בִּשְׁתֵּי פְעָמִים. פַּעַם רִאשׁוֹנָה אָמַר שְׁלֹשׁ עֶשְׂרֵה מִדּוֹת שֶׁל עַתִּיק הָעַתִּיקִים, נִסְתַּר הַכֹּל, לְהוֹרִיד אֵלֶּה לְמָקוֹם שֶׁנִּמְצָא הַדִּין, לִכְפּוֹתָם. פַּעַם שְׁנִיָּה אָמַר תֵּשַׁע מִדּוֹת רַחֲמִים שֶׁכְּלוּלִים בַּזְּעֵיר אַנְפִּין, וּמְאִירִים מֵהָעַתִּיק נִסְתַּר הַכֹּל. וְכֻלָּם כּוֹלֵל הַכֹּהֵן כְּשֶׁפּוֹרֵשׂ יָדָיו לְבָרֵךְ אֶת הָעָם, וְנִמְצָאִים שֶׁמִּתְבָּרְכִים כָּל (העליונים) הָעוֹלָמוֹת בְּצַד הָרַחֲמִים שֶׁנִּמְשָׁכִים מֵהָעַתִּיק הַטָּמִיר, נִסְתַּר הַכֹּל. וְכָל הָעֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת הַלָּלוּ מִדּוֹת נִסְתָּרוֹת."],[1,"","יְבָרֶכְךָ ה' וְיִשְׁמְרֶךְ, אֵלּוּ שְׁלֹשָׁה פְסוּקִים וּשְׁלֹשָׁה שֵׁמוֹת שֶׁל שְׁתֵּים עֶשְׂרֵה אוֹתִיּוֹת הַכְּלוּלוֹת כְּנֶגְדָּם, וּבַכֹּל הִתְכַּוֵּן הַכֹּהֵן. וְכָל עֶלְיוֹנִים וְתַחְתּוֹנִים מִתְבַּשְּׂמִים בְּעֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת שֶׁנִּסְתָּרוֹת בִּשְׁלֹשֶׁת הַפְּסוּקִים הַלָּלוּ, כְּנֶגֶד עֶשְׂרִים וּשְׁתַּיִם (אותיות) מִדּוֹת רַחֲמִים שֶׁכּוֹלְלוֹת הַכֹּל. וְלָכֵן כָּתוּב אָמוֹר, וְלֹא אִמְרוּ, כְּמוֹ שֶׁבֵּאַרְנוּ. אָמוֹר - שֶׁצָּרִיךְ לְכַוֵּן בְּכָל הַנִּסְתָּרִים הַלָּלוּ בְּכָל הַמַּעֲלוֹת הַלָּלוּ. אָמוֹר - בִּדְבָרִים נִסְתָּרִים שֶׁל מַעְלָה. אָמוֹר - חֶשְׁבּוֹן רמ\"ח אֵיבָרִים שֶׁבָּאָדָם חָסֵר אֶחָד. מָה הַטַּעַם? שֶׁבְּאֶחָד כֻּלָּם תְּלוּיִים. וְכֻלָּם מִתְבָּרְכִים בִּבְרָכָה זוֹ בִּשְׁלֹשֶׁת הַפְּסוּקִים הַלָּלוּ כְּמוֹ שֶׁבֵּאַרְנוּ. לָהֶם - לִכְלֹל בִּבְרָכָה זוֹ עֶלְיוֹנִים וְתַחְתּוֹנִים."],[2,"","לָמַדְנוּ, אָמַר רַבִּי יוֹסֵי, יוֹם אֶחָד יָשַׁבְתִּי לִפְנֵי רַבִּי אֶלְעָזָר בֶּן רַבִּי שִׁמְעוֹן וְשָׁאַלְתִּי אוֹתוֹ, אָמַרְתִּי, רַבִּי, מָה רָאָה דָוִד שֶׁאָמַר (תהלים לו) אָדָם וּבְהֵמָה תוֹשִׁיעַ ה'? אָדָם מֵילָא, בְּהֵמָה לָמָּה? אָמַר לוֹ, יָפֶה שָׁאַלְתָּ, הַכֹּל הוּא בְּמִנְיָן. זָכוּ - אָדָם. לֹא זָכוּ - בְּהֵמָה."],[3,"","אָמַרְתִּי, רַבִּי, סוֹד הַדָּבָר אֲנִי רוֹצֶה. אָמַר לוֹ, הַכֹּל נֶאֱמַר, וּבֹא רְאֵה, הַקָּדוֹשׁ בָּרוּךְ הוּא קָרָא לְיִשְׂרָאֵל אָדָם, כְּדֻגְמָה שֶׁלְּמַעְלָה, וְקָרָא לָהֶם בְּהֵמָה, וְהַכֹּל בְּפָסוּק אֶחָד, שֶׁכָּתוּב וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי וְגוֹ'. (יחזקאל לד) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי - הֲרֵי בְּהֵמָה. אָדָם אַתֶּם - הֲרֵי אָדָם. וְיִשְׂרָאֵל נִקְרְאוּ אָדָם וּבְהֵמָה, וּמִשּׁוּם זֶה אָדָם וּבְהֵמָה תוֹשִׁיעַ ה'. וְעוֹד סוֹד הַדָּבָר, זָכוּ - אָדָם כְּדֻגְמָה שֶׁלְּמַעְלָה, לֹא זָכוּ - נִקְרְאוּ בְהֵמָה, וְכֻלָּם מִתְבָּרְכִים בִּזְמַן אֶחָד - אָדָם שֶׁלְּמַעְלָה וּבְהֵמָה שֶׁלְּמַטָּה. וְכָל שֶׁכֵּן שֶׁהַכֹּל יֵשׁ בָּהֶם בְּיִשְׂרָאֵל. זֶהוּ שֶׁכָּתוּב אָדָם וּבְהֵמָה תוֹשִׁיעַ ה'."],[4,"","וּבֹא רְאֵה, הַבְּרָכָה לֹא נִמְצֵאת לְמַטָּה עַד שֶׁתִּמָּצֵא לְמַעְלָה, וּמִשֶּׁנִּמְצְאָה לְמַעְלָה - גַּם לְמַטָּה נִמְצֵאת, וְהַכֹּל תָּלוּי כָּךְ לְטוֹב וּלְרַע. לְטוֹב, שֶׁכָּתוּב (הושע ב) אֶעֱנֶה אֶת הַשָּׁמָיִם וְהֵם יַעֲנוּ אֶת הָאָרֶץ. לְרַע, שֶׁכָּתוּב (ישעיה כד) יִפְקֹד ה' עַל צְבָא הַמָּרוֹם בַּמָּרוֹם וְעַל מַלְכֵי הָאֲדָמָה עַל הָאֲדָמָה."],[5,"","אָמַר רַבִּי יְהוּדָה, בִּגְלַל זֶה (התפארת הזו פתח בו) כָּתוּב אָמוֹר לָהֶם, סְתָם, לְהִתְבָּרֵךְ עֶלְיוֹנִים וְתַחְתּוֹנִים כֻּלָּם כְּאֶחָד, שֶׁכָּתוּב כֹּה תְבָרֲכוּ בַּתְּחִלָּה, וְאַחַר כָּךְ אֶת בְּנֵי יִשְׂרָאֵל אָמוֹר לָהֶם סְתָם, לְהִתְבָּרֵךְ כֻּלָּם כְּאֶחָד. יְבָרֶכְךְ ה' - לְמַעְלָה. וְיִשְׁמְרֶךְ - לְמַטָּה. יָאֵר ה' פָּנָיו - לְמַעְלָה. וִיחֻנֶּךָּ - לְמַטָּה. יִשָּׂא ה' פָּנָיו - לְמַעְלָה. וְיָשֵׂם לְךְ שָׁלוֹם - לְמַטָּה."],[6,"","רַבִּי אַבָּא אָמַר, כֻּלָּם מִתְבָּרְכִים כְּאֶחָד בְּעֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת חֲקוּקוֹת שֶׁל הַשֵּׁם הַקָּדוֹשׁ שֶׁנִּכְלָל וְנִסְתָּר כָּאן, בְּעֶשְׂרִים וּשְׁתַּיִם אוֹתִיּוֹת כֻּלָּם מִתְבָּרְכִים. וְהֵם רַחֲמִים תּוֹךְ רַחֲמִים, שֶׁלֹּא נִמְצָא בָהֶם דִּין. וָלֹא? וַהֲרֵי כָּתוּב יִשָּׂא ה' פָּנָיו אֵלֶיךְ! אָמַר רַבִּי אַבָּא, יִשָּׂא - יְסַלֵּק וְיַעֲבִיר כְּדֵי שֶׁלֹּא יִמָּצֵא דִין כְּלָל."],[7,"","לָמַדְנוּ, אָמַר רַבִּי יוֹסֵי, בְּשָׁעָה שֶׁהַכֹּהֵן פּוֹרֵשׂ יָדָיו, אָסוּר לָעָם לְהִסְתַּכֵּל בּוֹ, מִשּׁוּם שֶׁשְּׁכִינָה שׁוֹרָה בְיָדָיו. אָמַר רַבִּי יִצְחָק, אִם כָּךְ, כֵּיוָן שֶׁלֹּא רוֹאִים, אָז מָה אִכְפַּת לָהֶם, שֶׁהֲרֵי כָּתוּב (שמות לג) כִּי לֹא יִרְאַנִי הָאָדָם וָחַי, בְּחַיֵּיהֶם לֹא רוֹאִים, אֲבָל בְּמִיתָתָם רוֹאִים? אָמַר לוֹ, מִשּׁוּם שֶׁהַשֵּׁם הַקָּדוֹשׁ רָמוּז בְּאֶצְבְּעוֹת יָדָיו, וְצָרִיךְ הָאָדָם לִפְחֹד. אַף עַל גַּב שֶׁלֹּא רוֹאֶה שְׁכִינָה, לֹא צָרִיךְ לְהִסְתַּכֵּל עַל הַיָּדַיִם שֶׁל הַכֹּהֲנִים, כְּדֵי שֶׁהָעָם לֹא יִמָּצֵא בְחֻצְפָּה אֶל הַשְּׁכִינָה."],[8,"","לָמַדְנוּ, בְּשָׁעָה שֶׁהַכֹּהֵן פּוֹרֵשׂ יָדָיו, צָרִיךְ הָעָם לָשׁוּב בְּיִרְאָה, בְּאֵימָה, וְלָדַעַת שֶׁאוֹתָהּ שָׁעָה עֵת רָצוֹן נִמְצָא בְּכָל הָעוֹלָמוֹת, וּמִתְבָּרְכִים עֶלְיוֹנִים וְתַחְתּוֹנִים וְאֵין דִּין בְּכֻלָּם, וְהִיא הַשָּׁעָה שֶׁמִּתְגַּלֶּה הַנִּסְתָּר עַתִּיק הָעַתִּיקִים בִּזְעֵיר אַנְפִּין, וְנִמְצָא שָׁלוֹם בַּכֹּל."]]],[["אָמַר רִבִּי שִׁמְעוֹן, בְּהָנֵי תְּלַת קְרָאֵי רֵישֵׁיהוֹן יוֹ\"ד יוֹ\"ד יוֹ\"ד, יְ\"בָרֶכְךָ יָ\"אֵר יִ\"שָּׂא. כֻּלְּהוּ לְאַחֲזָאָה מְהֵימְנוּתָא שְׁלֵימָא. וּלְאִתְבָּרְכָא מֵעַתִּיקָא מַאן דְּאִצְטְרִיךְ. יוֹ\"ד יוֹ\"ד יוֹ\"ד, לְאִתְבָּרְכָא זְעֵיר אַנְפִּין מֵעַתִּיקָא דְּכֹלָּא. וּבְגִין כָּךְ יְבָרֶכְךָ יְיָ לְעֵילָּא, וְיִשְׁמְרֶךָ הוּא לְתַתָּא, וְכֵן כֻּלְּהוּ. וְתָאנֵי תָּנָא קָמֵיהּ דְּרַבִּי שִׁמְעוֹן, הַאי מַאן דִּמְצָעֵר בְּחֶלְמֵיהּ, לֵיתֵי בְּשַׁעֲתָא דְּכַהֲנֵי פַּרְסֵי יְדַיְיהוּ, וְלֵימָא רִבּוֹנוֹ שֶׁל עוֹלָם אֲנִי שֶׁלָּךְ וַחֲלוֹמוֹתַי שֶׁלָּךְ וְכוּ'. אֲמַאי. מִשּׁוּם דְּהַהִיא שַׁעֲתָא אִשְׁתְּכָחוּ רַחֲמֵי בְּעָלְמִין כֻּלְּהוּ, וּמַאן דְּיִבְעֵי צְלוֹתֵיהּ בְּצַעֲרֵיהּ, אִתְהַפָּךְ לֵיהּ דִּינָא לְרַחֲמֵי.","\u0003רעיא מהימנא\u0004 פִּקּוּדָא (כ\"ב) דָּא לְבָרְכָא כַּהֲנָא יַת עַמָּא בְּכָל יוֹמָא, בִּזְקִיפוּ דְּאֶצְּבְּעָן. וּלְבָרְכָא בִּרְכָתָא בְּכָל יוֹמָא, לְאִשְׁתַּכְּחָא בִּרְכָאן עֵילָּא וְתַתָּא. דְּהָא אֶצְּבָּעָאן קַיְימָן בְּרָזָא עִלָּאָה, חָמֵשׁ גּוֹ חָמֵשׁ. חָמֵשׁ דִּימִינָא, וְחָמֵשׁ דִּשְׂמָאלָא. חָמֵשׁ דִּימִינָא, אִינּוּן שְׁבָחָא יְתֵירָא עַל אִינּוּן דִּשְׂמָאלָא, בְּגִין, דְּהָא יְמִינָא אִית לֵיהּ שְׁבָחָא יְתֵירָא עַל שְׂמָאלָא. וְעַל דָּא בְּבִרְכָתָא דְּקָא בָּרִיךְ כַּהֲנָא יַת עַמָּא, אִצְּטְרִיךְ לְזַקְפָא יְמִינָא עַל שְׂמָאלָא. וּלְעַיְּינָא בְּעֵינָא טָבָא.","וְכַד פָּרִישׂ יְדוֹי כַּהֲנָא, שְׁכִינְתָּא שַׁרְיָא עַל אִינּוּן אֶצְּבְּעָן, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא אִסְתְּכַם עִמֵּיהּ דְּכַהֲנָא בְּאִינּוּן בִּרְכָאן. וְיִשְׂרָאֵל מִתְבָּרְכִין מִתְּרֵין סִטְרִין מֵעֵילָּא וְתַתָּא. מֵעֵילָּא, שְׁכִינְתָּא דְּשַׁרְיָא עַל אִינּוּן אֶצְּבְּעָן. וְכַהֲנָא דְּקָא מְבָרֵךְ.","תָּא חֲזֵי, מִלִּין דְּקָא עַבְדֵי, מִתְעָרִין מִלִּין לְעֵילָּא. כְּגַוְונָא דָּא בִּפְרִישׁוּ דְּאֶצְּבְּעָן דְּכַהֲנָא לְתַתָּא, אִתְּעָרַת שְׁכִינְתָּא לְמֵיתֵי וּלְשַׁרְיָא עֲלָן. וְכֵן כַּמָה מִלִּין אִינּוּן בְּעָלְמָא, דְּמִתְעֲרִין מִלִּין לְעֵילָּא. דְּהָא בְּאִתְעָרוּתָא דִּלְתַּתָּא, אִתְּעַר חֵילָא אַחֲרָא לְעֵילָּא. וְהָא אוֹקִימְנָא בְּכַמָּה דּוּכְתֵּי. וְהַיְינוּ טַעֲמָא דְּלוּלָב, וְהַיְינוּ טַעֲמָא דְּשׁוֹפָר. וּכְמָּה אִינּוּן בְּהַאי גַּוְונָא עֶשֶׂר אֶצְּבָּעָן, מִתְעָרֵי שְׁכִינְתָּא לְשַׁרְיָיא עָלַיְיהוּ. מִתְעָרֵי עֶשֶׂר דַּרְגִּין אַחֲרָנִין לְעֵילָּא לְאַנְהָרָא, וְכֹלָּא בְּשַׁעֲתָא חֲדָא.","וְעַל דָּא, אָסִיר לֵיהּ לְבַר נָשׁ לְזַקְפָא אֶצְּבְּעָן בִּזְקִיפוּ לְמַגָּנָא, אֶלָּא בִּצְּלוֹתָא, וּבְבִרְכָּאן, וּבִשְׁמָא דְקוּדְשָׁא בְּרִיךְ הוּא. וְהָא אוֹקִימְנָא, דְּאִינּוּן אַתְּעֲרוּ דִּשְׁמָא קַדִּישָׁא, וְרָזָא דִּמְהֵימְנוּתָא. זְקִיפוּ דְּאֶצְּבְּעָאן, מְמָנָן בְּהַהוּא זְקִיפוּ דִּלְהוֹן, עֲשְׂרָה שַׁלִּיטִין, כְּמָה דְּאוּקְמוּהָ. וְכַהֲנָא בָּעֵי לְבָרְכָא בְּעֵינָא טָבָא, בְּאִסְתַּכְּמוּתָא דִּשְׁכִינְתָּא, כְּמָה דְּאִתְּמַר.","בְּהַהִיא שַׁעֲתָא דְּבִרְכְתָא דָּא נָפְקָא מִפּוּמֵיהּ דְּכַהֲנָא, אִינּוּן שִׁתִּין אַתְוָון, נָפְקִין וְטָסִין בִּרְקִיעָא, וּמְמָנָן שִׁתִּין רַבְרְבִין, עַל כָּל אָת וְאָת. וְכֻלְּהוּ אוֹדָן עַל כָּל אִלֵּין בִּרְכָאן. מַאי טַעֲמָא שִׁתִּין אַתְוָון בְּבִרְכָן אִלֵּין. בְּגִין דְּיִשְׂרָאֵל שִׁתִּין רִבּוֹא אִינּוּן, וְרָזָא דְּשִׁתִּין רִבּוֹא קַיְימִין בְעָלְמָא, וְכָל חַד וְחַד אִיהוּ חַד רִבּוֹא.","שְׁמָא קַדִּישָׁא דְּנָפְקָא מֵהַאי, סַלְּקָא לְעֵילָּא, עַד הַהוּא כֻּרְסְיָיא דִּלְעֵילָּא. וְכֹלָּא שְׁכִינְתָּא עִלָּאָה, וּשְׁכִינְתָּא דִּלְתַּתָּא, אוֹדָן בְּכַהֲנָא בְּאִינּוּן בִּרְכָאָן, וְכָל אִינּוּן שִׁתִּין מְמָנָן. וְעַל דָּא כְּתִיב, וְשָׂמוּ אֶת שְׁמִי עַל בְּנֵי יִשְׂרָאֵל וַאֲנִי אֲבָרַכֵם. וּכְדֵין קוּדְשָׁא בְּרִיךְ הוּא מְבָרֵךְ לוֹן לְיִשְׂרָאֵל. (ע\"כ) (פקודא כ\"ג לכבד אב וכו' פ\"ג ע\"א)","\u0003רעיא מהימנא\u0004 פִּקּוּדָא בָּתַר דָּא, בִּרְכַּת כֹּהֲנִים יְבָרֶכְךָ יְיָ. יָאֵר יְיָ. יִשָֹּׁא יְיָ. מְקוֹרָא מִתְּלַת שְׁמָהָן אִלֵּין, יו\"ד ה\"א וא\"ו ה\"א (ס\"א יו\"ד ה\"י וא\"ו ה\"י). קְדוּשָּׁה, אֶהְיְ\"ה אֶהְיֶ\"ה אֶהְיֶ\"ה, דִּמְקוֹרָא דִּילֵיהּ, יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. קִשּׁוּרָא דְּתַרְוַיְהוּ, יִחוּד דְּתַרְוַויְיהוּ, אֲדֹנָ\"י, דְּבֵיהּ א\"י, דִּרְמִיזִין איהדונה\"י (ס\"א יאהדונהי ודא עמודא דאמצעיתא ושכינתא איהי יאהדונהי) (ס\"א מקורא מג' שמהן אלין יו\"ד ה\"י וי\"ו ה\"י דרמיזין יאהדונהי ודא עמודא דאמצעיתא שכינתא איההדונה\"י נ\"א אידהונה\"י) וּרְמִיזִין א\"י רְבִיעָאָה, מִתְּרֵי שְׁמָהָן מְפָרְשָׁן, דִּרְשִׁימִין בְּהוֹן (ע\"כ רעיא מהימנא) (תצא רע\"ז ע\"א כי ימצא איש נערה)","(במדבר ו׳:כ״ז) וְשָׂמוּ אֶת שְׁמִי. מַהוּ וְשָׂמוּ אֶת שְׁמִי. אָמַר רִבִּי יְהוּדָה, יְתָּקְּנוּ. כְּמָה דִּכְתִּיב, (במדבר ד׳:י״ט) וְשָׂמוּ אוֹתָם אִישׁ אִישׁ עַל עֲבוֹדָתוֹ וְאֶל מַשָּׂאוֹ. לְאַתְקְּנָא בְּבִרְכָתְהוֹן כִּתְרִין דִּימִינָא לִימִינָא, וְכִתְרִין דִּשְׂמָאלָא לִשְׂמָאלָא, כַּדְּקָא חֲזֵי. דְּבַעְיָא דְּלָא יִטְעוּן בְּהוֹן, לְאַתְקְּנָא כֹּלָּא, בְּגִין דְּיִתְבָּרְכוּן עִלָּאִין וְתַתָּאִין.","וְאִי יַעַבְדוּן הָכִי, מַה כְּתִיב. וַאֲנִי אֲבָרַכֵם. לְמַאן. לְאִינּוּן כַּהֲנֵי, דִּכְתִּיב, (בראשית כ״ז:כ״ט) וּמְבָרַכֶיךָ בָּרוּךְ. וּכְתִיב (בראשית י״ב:ג׳) וַאֲבָרְכָה מְבָרַכֶיךָ. אִינּוּן מְבָרְכִין לְעַמָּא, וַאֲנָא אֲבָרֵךְ לְהוּ. וּלְפִיכָךְ כְּתִיב וְשָׂמוּ, וְלָא כְּתִיב יֹאמְרוּ, אוֹ יִזְכְּרוּ.","תָּאנָא, כָּל כֹּהֵן דְּלָא רַחֲמִין לֵיהּ עַמָּא, לָא יִפְרוֹס יְדוֹי. וְעוֹבָדָא הֲוָה בְּחַד כֹּהֵן דְּקָם וּפָרִיס יְדוֹי, וְעַד דְּלָא אַשְׁלִים, אִתְעָבִיד תִּלָּא דְּגַרְמֵי. מַאי טַעְמָא. מִשּׁוּם דְּלָא בְּרִיךְ בַּחֲבִיבוּתָא. וְקָם אַחֵר וּפָרִיס יְדוֹי וּבָרִיךְ, וְאִתְתָּקַּן הַהוּא יוֹמָא. כָּל כֹּהֵן דְּהוּא לָא רָחִים לְעַמָּא, אוֹ עַמָּא לָא רַחֲמִין לֵיהּ, לָא יִפְרוֹס יְדוֹי לְבָרְכָא לְעַמָּא, דִּכְתִּיב, (משלי כ״ב:ט׳) טוֹב עַיִן הוּא יְבוֹרָךְ אַל תִּקְרֵי יְבוֹרָךְ, אֶלָּא יְבָרֵךְ.","תָּאנָא, אָמַר רִבִּי יִצְחָק, בֹּא וּרְאֵה מַה כְּתִיב בְּהַהוּא רָשָׁע דְּבִלְעָם, בְּשַׁעֲתָא דְּאִתְּמְסַר לֵיהּ לְבָרְכָא לְיִשְׂרָאֵל, הֲוָה מַשְׁגַּח בְּעֵינָא בִּישָׁא, בְּגִין דְּלָא יִתְקְיָּים בִּרְכָתָא, וַהֲוָה תָּלֵי מִלּוֹי בְּהַהוּא עֵינָא בִּישָׁא, דִּכְתִּיב, (במדבר כ״ד:ג׳) נְאֻם בִּלְעָם בְּנוֹ בְּעוֹר. מַאי בְּנוֹ בְּעוֹר. מֵהַהוּא דְּהֲוָה סָאנֵי לְהוּ יַתִּיר מִכָּל בְּנֵי עָלְמָא. וּנְאֻם הַגֶּבֶר שְׁתוּם הָעָיִן, דְּסָתִים עֵינָא טָבָא מִנַּיְיהוּ, בְּגִין דְּלָא יִתְבָּרְכוּן, וְלָא יִתְקַיֵּים בִּרְכָתָא.","אָמַר רִבִּי יְהוּדָה, הָכִי הוּא ודַּאי, דְּאִשְׁתְּכַח פְּקִיעָא (ס\"א דאשתכחן פקיחא) דְּעֵינָא לְבָרְכָא, דִּכְתִּיב, (דניאל ט) פְּקַח עֵינֶיךָ, בְּגִין לְבָרְכָא. וּבִרְכָתָא דְּרַב הַמְנוּנָא סָבָא, הָכִי אָמַר, קוּדְשָׁא בְּרִיךְ הוּא יִפְקַח עֵינוֹי עֲלָךְ. וּבְהַהוּא רָשָׁע כְּתִיב, שְׁתוּם הָעָיִן. בְּגִין דְּלָא יִתְבָּרְכוּן עַל יְדוֹי. וְאָמַר רִבִּי יִצְחָק, בְּגִין כָּךְ כַּהֲנָא דְּבָרִיךְ בְּעֵינָא טָבָא, בִּרְכָתֵיהּ אִתְקְיָּים. וּדְלָא מְבָרֵךְ בְּעֵינָא טָבָא, כְּתִיב, (משלי כ״ג:ו׳) אַל תִּלְחַם אֶת לֶחֶם רַע עָיִן וְאַל תִּתְאָו לְמַטְעַמּוֹתָיו, כְּלוֹמַר אַל תִּבְעוּ מִנֵּיהּ בִּרְכָתָא כְּלָל.","אָמַר רִבִּי יוֹסֵי, תָּא חֲזֵי, כְּתִיב (דברים כ״ג:ו׳) וְלֹא אָבָה יְיָ אֱלֹהֶיךָ לִשְׁמוֹעַ אֶל בִּלְעָם וְגוֹ'. לִשְׁמוֹעַ אֶל בִּלְעָם, אֶל בָּלָק מִבָּעֵי לֵיהּ, דְּהָא עָבִיד בָּלָק כֹּלָּא, מַהוּ אֶל בִּלְעָם. אֶלָּא מִשּׁוּם דְּהֲוָה סָתִים עֵינוֹי, בְּגִין דְּלָא יִתְבָּרְכוּן יִשְׂרָאֵל. תָּאנָא, אָמַר רִבִּי יוֹסֵי, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְבִלְעָם, רָשָׁע, אַתְּ סָתִים עֵינַךְ בְּגִין דְּלָא יִתְבָּרְכוּן בָּנַי. אֲנָא אַפְקַח עֵינָי, וְכָל מִלִּין דְּתֵימָא, אֶהֱפֹךְ לְהוּ לְבִרְכָאן. הֲדָא הוּא דִכְתִיב, וַיַהֲפֹךְ ה' אֱלֹהֶיךָ לְךָ אֶת הַקְּלָלָה לִבְרָכָה כִּי אַהֵבְךָ וְגוֹ'.","וְעַל דָּא כְּתִיב, טוֹב עַיִן הוּא יְבוֹרָךְ כִּי נָתַן מִלַּחְמוֹ לַדָּל. מַהוּ מִלַּחְמוֹ. כְּמָה דְּאוֹקִימְנָא, דִּכְתִּיב, (ויקרא כ״א:כ״ב) לֶחֶם אֱלֹהָיו מְקָּדְשֵׁי הַקֳּדָשִׁים וְגוֹ'. מַשְׁמַע דְּקָדְשֵׁי הַקֳדָשִׁים לֶחֶם אֱלֹהָיו נָפַק מִנֵּיהּ. וּבְגִין כָּךְ כִּי נָתַן מִלַּחְמוֹ לַדָּל. תַּנְיָא, כַּמָה חֲבִיבִין יִשְׂרָאֵל קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, דְּעִלָאֵי לָא מִתְבָּרְכֵי אֶלָּא בְּגִינֵיהוֹן דְּיִשְׂרָאֵל.","דְּתָנֵינָן, אָמַר רִבִּי יְהוּדָה, אָמַר רִבִּי חִיָּיא, אָמַר רִבִּי יוֹסֵי, נִשְׁבַּע הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁלֹּא יִכָּנֵס בִּיְרוּשָׁלַם שֶׁל מַעֲלָה, עַד שֶׁיִּכָּנְסוּ יִשְׂרָאֵל בִּיְרוּשָׁלַ ם שֶׁל מַטָּה, שֶׁנֶּאֱמַר (הושע י״א:ט׳) בְּקִרְבְּךָ קָדוֹשׁ וְלֹא אָבֹא בְּעִיר. כְּלוֹמַר, כָּל זִמְנָא דִּשְׁכִינְתָּא הָכָא בְּגָלוּתָא, שְׁמָא דִּלְעֵילָּא לָא אִשְׁתְּלִים. וְכָל תִּקּוּנִין לָא אִתְּקָנוּ, כִּבְיָכוֹל אִשְׁתְּאַר שְׁמָא קַדִּישָׁא חַסְרָא."],[[0,"","[א] \u0003אמר רבי שמעון\u0004 וכו׳: אר״ש, בג׳ פסוקים אלו בתחילתם, יש יוד יוד יוד, דהיינו \u0003י׳\u0004 דיברכך, \u0003י׳\u0004 דיאר, \u0003י'\u0004 דישא. כולן באות להראות האמונה השלמה, ושיתברך מעתיקא, שה״ס \u0003י׳\u0004 דהויה, מי שצריך להתברך. \u0003י' י׳ י׳\u0004 ג׳ פעמים, הן, שיתברך ז״א מעתיק מכל, וג' יודין הם כנגד ג׳ קוין. כי יברכך הוא קו ימין, יאר הוא קו שמאל, ישא הוא קו האמצעי. ומשום זה, \u0003יברכך ה',\u0004 הוא למעלה, לז״א שיקבל מעתיקא, \u0003וישמרך,\u0004 הוא למטה. לישראל. וכן כולם (כנ״ל אות קס״ט)."],[0,"","[ב] \u0003ותנא תנא קמיה\u0004 וכו׳: ולמד תנא לפני ר׳ שמעון, כל מי שמצטער בחלומו, יבא בשעה שהכהנים פורשים ידיהם, ויאמר, רבונו של עולם, אני שלך וחלומותי שלך וכו'. למה. משום שבאותה שעה נמצאים רחמים בכל העולמות, ומי שיתפלל תפלתו על צערו, מתהפך לו הדין לרחמים."],[1,"פקודא דא לברכא","וכו׳: מצוה זו, שיברך הכהן את העם בכל יום בזקיפת האצבעות, ולברך ברכה בכל יום שתמצאנה הברכות למעלה ולמטה. כי האצבעות נמצאות בסוד העליון, חמש תוך חמש, חמש של ימין וחמש של שמאל, החמש של ימין יש להם חשיבות יתרה על אלו שבשמאל, משום שהימין חשוב יותר מן השמאל, וע״כ בברכה שהכהן מברך את העם, צריך להגביה הימין על השמאל. ולעיין בברכות בעין טוב."],[2,"וכד פריש ידוי","וכו׳: וכשהכהן פורש ידיו, השכינה שורה על אלו אצבעות, כי הקב״ה מסכים עם הכהן בברכות אלו, וישראל מתברכים מב׳ צדדים, ממעלה וממטה, ממעלה, הוא מהשכינה השורה על האצבעות, ומלמטה, הוא מהכהן שמברך."],[3,"ת״ח מלין דקא","וכו׳: בוא וראה, הדברים שעושים למטה מעוררים דברים כנגדם למעלה. כעין זה בפרישת האצבעות של הכהן למטה, מתעוררת השכינה לבא ולשרות עליהן. וכן כמה דברים הם בעולם שמעוררים דברים למעלה, כי בהתעוררות שלמטה, מתעורר כח אחר למעלה. וכבר העמדנו בכמה מקומות. וזהו הטעם של נטילת לולב, וזהו הטעם של תקיעת שופר. וכמו שהם בענין זה עשר אצבעות, כן מתעוררת השכינה לשרות עליהן, ומתעוררות עשר מדרגות אחרות למעלה, שהן ע״ס דז״א, להאיר, והכל בשעה אחת."],[4,"וע״ד אסיר ליה","וכו׳: וע״כ אסור לו לאדם לזקוף אצבעותיו בזקיפה בחנם, אלא בתפלה, ובברכות, ובשמו של הקב״ה. וכבר העמדנו, שזקיפת אצבעות היא התעוררות השם הקדוש, וסוד האמונה. זקיפת האצבעות ממנים בזקיפתם עשרה שליטים. משום שהאצבעות רומזות על גילוי חכמה (כנ״ל בראשית א׳ דף ק״כ ד\"ה אצבען ע״ש) וכתוב, החכמה תעוז לחכם מעשרה שליטים (קהלת ז׳). כמו שהעמדנו. והכהן צריך לברך בעין טובה בהסכמת השכינה, כמו שלמדנו."],[5,"בההיא שעתא דברכתא","וכו׳: בשעה ההיא שברכה זו יוצאת מפיו של הכהן, אלו ששים אותיות הנמצאות בברכת כהנים, יוצאות ומעופפות ברקיע, וממנים ששים שרים על כל אות ואות, וכולם מודים על כל אלו הברכות. מהו הטעם, שיש ששים אותיות בברכות אלו. הוא משום שישראל הם ששים רבוא, ובסוד ששים רבוא הם נמצאים תמיד בעולם, וכל אחת ואחת שבאותיות שבברכות, היא רבוא אחד. וע״כ הן כנגד ששים רבוא שבישראל."],[6,"שמא קדישא דנפקא","וכו׳: השם הקדוש היוצא מברכת כהנים עולה למעלה עד כסא ההוא שלמעלה, שהוא בינה. והכל, שכינה העליונה שהיא בינה, ושכינה תחתונה, שהיא מלכות, מודים ומסכימים עם הכהן בברכות האלו, וכל אלו ששים ממונים שעל כל אות ואות כנ״ל בדבור הסמוך, מתברכים. וע״כ כתוב, ושמו את שמי על בני ישראל ואני אברכם. ואז הקב״ה מברך את ישראל."],[7,"פקודא בתר דא","וכו׳: מצוה שלאחר זה היא ברכת כהנים. יברכך ה', יאר ה', ישא ה', המקור מג׳ שמות אלו הוא יוד הי ואו הי. \u0003קדושה\u0004 אהיה אהיה אהיה, שממקור שלו, יוד הא ואו הא. הקשר של שניהם \u0003היחוד\u0004 של שניהם, הוא אדני, שבו \u0003א״י.\u0004 ורמוזים \u0003א״י\u0004 רביעי, משני שמות המפורשים בהם. (דרמיזין איהדונה״י, אינו מן הזהר, אלא גליון שהכניסוהו בפנים)."],[7,"","פירוש. מבאר כאן השם יב״ק, שהוא ר״ת \u0003יחוד ברכה קדושה,\u0004 שסודם ג׳ שמות, אהי״ה הוי״ה אדנ״י, שבגי׳ יב״ק. ומפרש תחלה \u0003הברכה\u0004 שה״ס ברכת כהנים, וז״ש, \u0003יברכך ה׳ יאר ה׳ ישא ה׳, מקורא דתלת שמהן אלין יוד הי ואו הי.\u0004 דהיינו שברכה הוא הויה, והם ג׳ שמות הויה שבברכת כהנים, שהם כנגד ג׳ קוין, שה״ס ג׳ יודין שבהויה במילוי ס״ג, יוד הי' ואו הי'. דהיינו שג' יודין דס״ג, הם ר״ת דג׳ הויות אלו. ועתה מפרש \u0003קדושה, וז״ש, קדושה, אהיה אהיה אהיה, דממקורא דיליה, יוד הא ואו הא.\u0004 שקדושה ה״ס אהיה, והם ג׳ אהיה, כנגד ג׳ קוין וה״ס ג׳ אלפין שבהויה במילוי מ״ה, כזה יוד ה \u0003א\u0004 ו \u0003א\u0004 ו ה \u0003א.\u0004 כי ג׳ אלפין אלו הם ר״ת של ג׳ אהי\"ה. ועתה מפרש \u0003יחוד,\u0004 וז״ש, \u0003קשורא דתרויהו יחוד דתרויהו אדני,\u0004 שהיחוד של אלו ב׳ שמות הויה אהיה שבקדושה ובברכה, הוא בסוד השם אדנ״י, \u0003דביה א״י,\u0004 שע״כ נמצאים בו ראשי התיבות של ב׳ שמות אהיה הויה, שהם \u0003א׳\u0004 דאהיה, \u0003י׳\u0004 דהויה, שזה רומז שב׳ שמות אהיה הויה, מתיחדים ב \u0003א״י\u0004 ד \u0003א\u0004 דנ \u0003י\u0004. וכיון שיש ג׳ אהיות וג׳ הויות כנגד ג׳ קוין, שה״ס ג׳ יודין שבהויה דס״ג וג׳ אלפין שבהויה דמ״ה, נמצא שלאחר יחודם זה בזה הם ג׳ פעמים \u0003א״י\u0004 כי בכל קו יש \u0003א״י\u0004 כנגד ראשי תיבות הויה אהיה, ו \u0003א״י\u0004 שבאדני, שה״ס מלכות, הם מקבלים מג׳ א״י שבג׳ קוין אלו. וז״ש, \u0003ורמיזין א\"י רביעאה, מתרי שמהן מפרשן דרשימין בהון,\u0004 אשר \u0003א״י\u0004 דאדני הוא \u0003א״י\u0004 רביעי הנעשה מיחוד ב׳ שמות אהיה הויה. שהוא מקבל מג׳ \u0003א״י\u0004 שבג׳ קוין כנ״ל. (ע״כ רעיא מהימנא)"],[8,"ושמו את שמי:","שואל, מהו ושמו את שמי. א״ר יהודה, שפירושו יתקנו. כמ״ש ושמו אותם איש איש על עבודתו ואל משאו. דהיינו שהנהנים יתקנו בברכתם, הספירות של ימין לימין, והספירות של שמאל לשמאל, כראוי. שצריך שלא יטעו בהן, ויתקנו הכל, כדי שיתברכו העליונים והתחתונים. פירוש, שג׳ פסוקים ה״ס ג׳ קוין, וצריך שיכוין הכהן ביברכך וגו׳ לימין. וביאר וגו', לשמאל. ובישא וגו׳ לאמצע."],[9,"ואי יעבדון הכי","וכו׳: ואם יעשו כן, מה כתוב, \u0003ואני אברכם,\u0004 למי. היינו לאלו הכהנים. שכתוב, ומברכיך ברוך. וכתוב, ואברכה מברכך. אלו מברכים לעם, ואני אברך אותם המברכים. ולפיכך כתוב, \u0003ושמו,\u0004 ולא כתוב יאמרו, או יזכרו."],[10,"תאנא כל כהן","וכו׳: למדנו כל כהן שהעם אינם אוהבים אותו, לא ישא את כפיו. ומעשה היה בכהן אחד, שקם ונשא כפיו, ומטרם שהשלים נעשה גל של עצמות, מה הטעם. משום שלא ברך באהבה. וקם כהן אחר ונשא ידיו וברך ותקן יום ההוא. כל כהן שהוא אינו אוהב את העם, או העם אינו אוהב אותו, לא ישא ידיו לברך את העם, שכתוב, טוב עין הוא יבורך. אל תקרי יבורך, אלא יברך."],[11,"תאנא א״ר יצחק","וכו׳: למדנו אר״י, בוא וראה מה כתוב באותו רשע בלעם. בשעה שמסר עצמו לברך את ישראל, היה מסתכל בעין רעה, כדי שלא תתקיים הברכה. והיה תולה דבריו בעין רעה ההוא, שכתוב, נאום בלעם בנו בעור. מהו בנו בעור. היינו מאותו שהיה שונא להם יותר מכל בני העולם. כי בעור הוא לשון שנאה כמו עירין. ונאם הגבר שתום העין, פירושו, שסתם העין הטובה מהם, כדי שלא יתברכו ולא תתקיים הברכה."],[12,"א\"ר יהודה הכי","וכו׳: אר״י, כך היא ודאי שנמצא פקיחת העין כדי לברך. שכתוב, פקח עיניך. כדי לברך. והברכה של רב המנונא סבא, היה אומר כך, הקב״ה יפקח עיניו עליך. וברשע ההיא כתוב שתום העין. והיינו כדי שלא יתברכו על ידו. וא\"ר יצחק משום זה, הכהן המברך בעין טובה ברכתו מתקיימת, ושאינו מברך בעין טובה כתוב, אל תלחם את לחם רע עין ואל תתאו למטעמותיו. כלומר, אל תרצו ממנו ברכה כלל."],[13,"אמר ר׳ יוסי","וכו׳: אר״י, בוא וראה כתוב, ולא אבה ה׳ אלקיך לשמוע אל בלעם וגו׳. שואל, לשמוע אל בלעם, אל בלק היה צריך לומר, שהרי הכל עשה בלק, מהו אל בלעם. ומשיב, אלא משום שהיה סותם עיניו כדי שלא יתברכו ישראל. למדנו א״ר יוסי, אמר לו הקב״ה לבלעם, רשע, אתה סתמת עיניך כדי שלא יתברכו בני, אני אפקח עיני, וכל הדברים שתאמר אהפך אותם לברכות. ז״ש, ויהפך ה׳ אלקיך לך את הקללה לברכה כי אהבך וגו׳."],[14,"וע״ד כתיב טוב","וגו׳: וע״כ כתוב, טוב עין הוא יבורך כי נתן מלחמו לדל. מהו מלחמו, הוא כמו שהעמדנו, שכתוב לחם אלקיו מקדשי הקדשים וגו׳. משמע דקדשי הקדשים לחם אלקיו יוצא ממנו. ומשום זה כי נתן מלחמו לדל. למדנו כמה חביבים ישראל לפני הקב״ה, שהעליונים אינם מתברכים אלא בשביל ישראל."],[14,"","פירוש. \u0003טוב עין,\u0004 הוא יסוד. \u0003דל\u0004 הוא המלכות דלית לה מגרמה ולא מידי. והבינה נקראת קדשי הקדשים. וז״ש, \u0003משמע דקדשי הקדשים,\u0004 שהוא בינה, \u0003לחם אלקיו נפק מניה,\u0004 יוצא ממנה השפע הנקרא לחם אלקיו. \u0003ובג״כ כי נתן מלחמו לדל\u0004 שז״ש הכתוב, אשר \u0003טוב עין,\u0004 שהוא יסוד \u0003נתן מלחמו,\u0004 דהיינו שפע הבינה הנקרא לחם אלקיו, נתן אל ה \u0003דל\u0004 שהוא המלכות."],[15,"דתנינן אמר רבי יהודה","וכו׳: שלמדנו, אר״י א\"ר חייא אמר ר׳ יוסי, נשבע הקב״ה שלא יכנס בירושלים של מעלה, שה״ס זווג השלם של \u0003י״ה,\u0004 עד שיכנסו ישראל בירושלים של מטה. דהיינו עד הגאולה השלמה, שנאמר בקרבך קדוש ולא אבוא בעיר. כלומר כל זמן שהשכינה היא בגלות, השם שלמעלה אינו שלם. וכל זמן שכל התקונים לא נתקנו, דהיינו מטרם גמר התקון, כביכול, נשאר השם הקדוש חסר."],[15,"","פירוש. כי יש ב׳ זווגים באו״א, זווג פנימי וזווג חצון. ונשבע ה׳ שלא יכנס בירושלם של מעלה, היינו בזווג פנימי די״ה, שהם או\"א. אבל זווג חצוני דאו״א נוהג גם בשתא אלפי שני. ועל הזווג הפנימי אומר, \u0003כביכול אשתאר שמא חסר.\u0004 ולא על הזווג החצוני."]],[[0,"","אָמַר רַבִּי שִׁמְעוֹן, בְּרָאשֵׁי שְׁלֹשֶׁת הַפְּסוּקִים הַלָּלוּ יוֹ\"ד יוֹ\"ד יוֹ\"ד: יְ\"בָרֶכְךְ יָ\"אֵר יִ\"שָּׂא. כֻּלָּם לְהַרְאוֹת אֱמוּנָה הַשְּׁלֵמָה, וּלְהִתְבָּרֵךְ מֵהָעַתִּיק מִי שֶׁצָּרִיךְ. יוֹ\"ד יוֹ\"ד יוֹ\"ד, לְהִתְבָּרֵךְ זְעֵיר אַנְפִּין מֵעַתִּיק הַכֹּל. וּמִשּׁוּם כָּךְ, יְבָרֶכְךְ ה' לְמַעְלָה, וְיִשְׁמְרֶךְ הוּא לְמַטָּה, וְכֵן כֻּלָּם. וְשָׁנָה הַתַּנָּא לִפְנֵי רַבִּי שִׁמְעוֹן, מִי שֶׁמִּצְטַעֵר בַּחֲלוֹמוֹ, שֶׁיָּבא בְשָׁעָה שֶׁהַכֹּהֲנִים פּוֹרְשִׂים יְדֵיהֶם, וְיֹאמַר: רִבּוֹנוֹ שֶׁל עוֹלָם, אֲנִי שֶׁלְּךְ וַחֲלוֹמוֹתַי שֶׁלְּךְ וְכוּ'. לָמָּה? מִשּׁוּם שֶׁאוֹתָהּ שָׁעָה נִמְצָאִים רַחֲמִים בְּכָל הָעוֹלָמוֹת, וּמִי שֶׁיְּבַקֵּשׁ תְּפִלָּתוֹ בְצַעֲרוֹ, מִתְהַפֵּךְ לוֹ דִּין לְרַחֲמִים."],[1,"","מִצְוָה (כ\"ב) זוֹ לְבָרֵךְ הַכֹּהֵן אֶת הָעָם בְּכָל יוֹם בִּזְקִיפוּת הָאֶצְבָּעוֹת, וּלְבָרֵךְ בְּרָכָה בְּכָל יוֹם, לְהִמָּצֵא בְרָכוֹת מַעְלָה וּמַטָּה. שֶׁהֲרֵי הָאֶצְבָּעוֹת עוֹמְדוֹת בְּסוֹד עֶלְיוֹן, חָמֵשׁ תּוֹךְ חָמֵשׁ. חָמֵשׁ שֶׁל הַיָּמִין וְחָמֵשׁ שֶׁל שְׂמֹאל. חָמֵשׁ שֶׁל הַיָּמִין הֵן שֶׁבַח יוֹתֵר עַל אוֹתָן שֶׁל שְׂמֹאל, מִשּׁוּם שֶׁיָּמִין זוֹ יֵשׁ לָהּ שֶׁבַח יָתֵר עַל שְׂמֹאל. וְעַל זֶה בַּבְּרָכָה שֶׁמְּבָרֵךְ הַכֹּהֵן אֶת הָעָם, צָרִיךְ לִזְקֹף יָמִין עַל שְׂמֹאל וּלְעַיֵּן בְּעַיִן טוֹבָה."],[2,"","וּכְשֶׁפּוֹרֵשׂ הַכֹּהֵן אֶת יָדָיו, הַשְּׁכִינָה שׁוֹרָה עַל אוֹתָן הָאֶצְבָּעוֹת, שֶׁהֲרֵי הַקָּדוֹשׁ בָּרוּךְ הוּא הִסְכִּים עִם הַכֹּהֵן בְּאוֹתָן בְּרָכוֹת. וְיִשְׂרָאֵל מִתְבָּרְכִים מִשְּׁנֵי צְדָדִים - מִלְמַעְלָה וּמִלְּמַטָּה. מִלְמַעְלָה - הַשְּׁכִינָה שֶׁשּׁוֹרָה עַל אוֹתָן אֶצְבָּעוֹת, וְהַכֹּהֵן שֶׁמְּבָרֵךְ."],[3,"","בֹּא רְאֵה, דְּבָרִים שֶׁעוֹשִׂים, מְעוֹרְרִים דְּבָרִים לְמַעְלָה. כְּמוֹ זֶה בִּפְרִישַׂת אֶצְבְּעוֹת הַכֹּהֵן לְמַטָּה, מִתְעוֹרֶרֶת הַשְּׁכִינָה לָבֹא וְלִשְׁרוֹת עָלֵינוּ. וְכֵן כַּמָּה דְבָרִים הֵם בָּעוֹלָם שֶׁמְּעוֹרְרִים דְּבָרִים לְמַעְלָה, שֶׁהֲרֵי בַּהִתְעוֹרְרוּת שֶׁלְּמַטָּה מִתְעוֹרֵר כֹּחַ אַחֵר לְמַעְלָה, וְזֶה בֵּאַרְנוּ בְּכַמָּה מְקוֹמוֹת. וְהַיְנוּ טַעַם הַלּוּלָב וְהַיְנוּ טַעַם הַשּׁוֹפָר. וּכְמוֹ הֵם בְּגָוֶן זֶה עֶשֶׂר אֶצְבָּעוֹת מְעוֹרְרוֹת הַשְּׁכִינָה לִשְׁרוֹת עֲלֵיהֶן. מִתְעוֹרְרוֹת עֶשֶׂר מַעֲלוֹת אֲחֵרוֹת לְהָאִיר, וְהַכֹּל בְּשָׁעָה אַחַת."],[4,"","וְעַל כָּךְ אָסוּר לְבֶן אָדָם לִזְקֹף אֶצְבָּעוֹת בִּזְקִיפוּת לְחִנָּם, אֶלָּא בַּתְּפִלָּה וּבִבְרָכוֹת וּבַשֵּׁם שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. וַהֲרֵי בֵּאַרְנוּ, שֶׁהֵם הַמְּעוֹרְרִים אֶת הַשֵּׁם הַקָּדוֹשׁ וְסוֹד הָאֱמוּנָה. זְקִיפוּת הָאֶצְבָּעוֹת, מְמֻנִּים בְּאוֹתָהּ זְקִיפוּת שֶׁלָּהֶן עֲשָׂרָה שַׁלִּיטִים, כְּמוֹ שֶׁבֵּאַרְנוּ. וְהַכֹּהֵן צָרִיךְ לְבָרֵךְ בְּעַיִן טוֹבָה בְּהַסְכָּמַת הַשְּׁכִינָה, כְּמוֹ שֶׁנִּתְבָּאֵר."],[5,"","בְּאוֹתָהּ שָׁעָה שֶׁבְּרָכָה זוֹ יוֹצֵאת מִפִּי הַכֹּהֵן, אוֹתָן שִׁשִּׁים אוֹתִיּוֹת יוֹצְאוֹת וְטָסוֹת בָּרָקִיעַ, וּמְמֻנִּים שִׁשִּׁים גְּדוֹלִים עַל כָּל אוֹת וְאוֹת, וְכֻלָּם מוֹדִים עַל כָּל הַבְּרָכוֹת הַלָּלוּ. מָה הַטַּעַם שִׁשִּׁים אוֹתִיּוֹת בַּבְּרָכוֹת הַלָּלוּ? מִשּׁוּם שֶׁיִּשְׂרָאֵל הֵם שִׁשִּׁים רִבּוֹא, וְסוֹד שִׁשִּׁים רִבּוֹא עוֹמְדִים בָּעוֹלָם, וְכָל אֶחָד וְאֶחָד הוּא (רבוא) אֶחָד."],[6,"","הַשֵּׁם הַקָּדוֹשׁ שֶׁיּוֹצֵא מִזֶּה עוֹלֶה לְמַעְלָה עַד אוֹתוֹ הַכִּסֵּא שֶׁלְּמַעְלָה. וְהַכֹּל, שְׁכִינָה עֶלְיוֹנָה וּשְׁכִינָה תַּחְתּוֹנָה, מוֹדִים לַכֹּהֵן בְּאוֹתָן הַבְּרָכוֹת וְעַל אוֹתָם שִׁשִּׁים מְמֻנִּים. וְעַל זֶה כָּתוּב, וְשָׂמוּ אֶת שְׁמִי עַל בְּנֵי יִשְׂרָאֵל וַאֲנִי אֲבָרֲכֵם. וְאָז הַקָּדוֹשׁ בָּרוּךְ הוּא מְבָרֵךְ אֶת יִשְׂרָאֵל. (ע\"כ רעיא מהימנא)."],[7,"","מִצְוָה אַחַר זוֹ - בִּרְכַּת כֹּהֲנִים. יְבָרֶכְךְ ה', יָאֵר ה', יִשָּׂא ה'. מָקוֹר מִשְּׁלֹשָׁה שֵׁמוֹת אֵלּוּ: יוֹד הֵ\"א וָא\"ו הֵ\"א (יו\"ד ה\"י וא\"ו ה\"י). קְדֻשָּׁה, אֶהְיֶ\"ה אֶהְיֶ\"ה אֶהְיֶ\"ה, שֶׁמְּקוֹרוֹ יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. הַקִּשּׁוּר שֶׁל שְׁנֵיהֶם, הַיִּחוּד שֶׁל שְׁנֵיהֶם - אֲדנָ\"י, שֶׁבּוֹ א\"י, שֶׁרְמוּזִים איהדונה\"י (יאהדונה\"י, וזה העמוד האמצעי, והשכינה היא יאהדונה\"י) (מקור מג' שמות אלו יו\"ד ה\"י וי\"ו ה\"י שרמוזים יאהדונה\"י, וזה העמוד האמצעי, השכינה איההדונה\"י) (אידהונה\"י), וּרְמוּזִים א\"י רְבִיעִי מִשְּׁנֵי שֵׁמוֹת מְפֹרָשִׁים שֶׁרְשׁוּמִים בָּהֶם."],[8,"","וְשָׂמוּ אֶת שְׁמִי. מַה זֶּה וְשָׂמוּ אֶת שְׁמִי? אָמַר רַבִּי יְהוּדָה, יְתַקְּנוּ, כְּמוֹ שֶׁכָּתוּב (במדבר ד) וְשָׂמוּ אוֹתָם אִישׁ אִישׁ עַל עֲבדָתוֹ וְאֶל מַשָּׂאוֹ. לְהַתְקִין בְּבִרְכָתָם כְּתָרִים שֶׁל יָמִין לְיָמִין, וּכְתָרִים שֶׁל שְׂמֹאל לִשְׂמֹאל כָּרָאוּי, שֶׁצָּרִיךְ שֶׁלֹּא יִטְעוּ בָהֶם לְהַתְקִין הַכֹּל כְּדֵי שֶׁיִּתְבָּרְכוּ עֶלְיוֹנִים וְתַחְתּוֹנִים."],[9,"","וְאִם יַעֲשׂוּ כָּךְ, מַה כָּתוּב? וַאֲנִי אֲבָרַכֵם. לְמִי? לְאוֹתָם כֹּהֲנִים, שֶׁכָּתוּב (בראשית כז) וּמְבָרֲכֶיךְ בָּרוּךְ. וְכָתוּב (שם יב) וַאֲבָרְכָה מְבָרֲכֶיךְ. הֵם מְבָרְכִים אֶת הָעָם, וַאֲנִי אֲבָרֵךְ אוֹתָם, וּלְפִיכָךְ כָּתוּב וְשָׂמוּ, וְלֹא כָתוּב יֹאמְרוּ אוֹ יִזְכְּרוּ."],[10,"","לָמַדְנוּ, כָּל כֹּהֵן שֶׁלֹּא אוֹהֲבִים אוֹתוֹ הָעָם, לֹא יִפְרֹשׂ יָדָיו. וּמַעֲשֶׂה הָיָה בְּכֹהֵן אֶחָד שֶׁקָּם וּפָרַשׂ יָדָיו, וְעַד שֶׁלֹּא הִשְׁלִים נַעֲשָׂה גַּל עֲצָמוֹת. מָה הַטַּעַם? מִשּׁוּם שֶׁלֹּא בֵרַךְ בַּחֲבִיבוּת. וְקָם אָחֵר וּפָרַשׂ יָדָיו וּבֵרַךְ, וְהִתְתַּקֵּן אוֹתוֹ הַיּוֹם. כָּל כֹּהֵן שֶׁאֵינוֹ אוֹהֵב אֶת הָעָם אוֹ הָעָם לֹא אוֹהֲבִים אוֹתוֹ, לֹא יִפְרֹשׂ יָדָיו לְבָרֵךְ אֶת הָעָם, שֶׁכָּתוּב (משלי כב) טוֹב עַיִן הוּא יְבֹרָךְ, אַל תִּקְרֵי יְבֹרָךְ, אֶלָּא יְבָרֵךְ."],[11,"","לָמַדְנוּ, אָמַר רַבִּי יִצְחָק, בֹּא וּרְאֵה מַה כָּתוּב בְּאוֹתוֹ בִּלְעָם הָרָשָׁע. בְּשָׁעָה שֶׁנִּמְסַר לוֹ לְבָרֵךְ אֶת יִשְׂרָאֵל, הָיָה מַשְׁגִּיחַ בְּעַיִן רָעָה כְּדֵי שֶׁלֹּא תִתְקַיֵּם הַבְּרָכָה, וְהָיָה תּוֹלֶה דְבָרָיו בְּאוֹתָהּ עַיִן רָעָה, שֶׁכָּתוּב (במדבר כד) נְאֻם בִּלְעָם בְּנוֹ בְעֹר. מַה זֶּה בְּנוֹ בְעֹר? מֵאוֹתוֹ שֶׁהָיָה שׂוֹנֵא אוֹתוֹ יוֹתֵר מִכָּל בְּנֵי הָעוֹלָם. וּנְאֻם הַגֶּבֶר שְׁתֻם הָעָיִן, שֶׁסְּתוּם הָעַיִן טוֹב מֵהֶם, כְּדֵי שֶׁלֹּא יִתְבָּרְכוּ וְלֹא תִתְקַיֵּם הַבְּרָכָה."],[12,"","אָמַר רַבִּי יְהוּדָה, כָּךְ הוּא בְּוַדַּאי, שֶׁנִּמְצֵאת פְּתִיחַת (שנמצאת פקיחת) עַיִן לְבָרֵךְ, שֶׁכָּתוּב (דניאל ט) פְּקַח עֵינֶיךְ, כְּדֵי לְבָרֵךְ. וּבִרְכַּת רַב הַמְנוּנָא סָבָא כָּךְ הָיָה אוֹמֵר: הַקָּדוֹשׁ בָּרוּךְ הוּא יִפְקַח עֵינוֹ עָלֶיךְ. וּבְאוֹתוֹ רָשָׁע כָּתוּב שְׁתֻם הָעָיִן, כְּדֵי שֶׁלֹּא יִתְבָּרְכוּ עַל יָדוֹ. וְאָמַר רַבִּי יִצְחָק, לָכֵן צָרִיךְ הַכֹּהֵן לְבָרֵךְ בְּעַיִן טוֹבָה, בִּרְכָתוֹ תִתְקַיֵּם. וְשֶׁלֹּא מְבָרֵךְ בְּעַיִן טוֹבָה, כָּתוּב (משלי כג) אַל תִּלְחַם אֶת לֶחֶם רַע עָיִן וְאַל תִּתְאָו לְמַטְעַמֹּתָיו. כְּלוֹמַר, אַל תְּבַקֵּשׁ מִמֶּנּוּ בְּרָכָה כְּלָל."],[13,"","אָמַר רַבִּי יוֹסֵי, בּא רְאֵה, כָּתוּב (דברים כג) וְלֹא אָבָה ה' אֱלֹהֶיךְ לִשְׁמֹעַ אֶל בִּלְעָם וְגוֹ'. לִשְׁמֹעַ אֶל בִּלְעָם?! אֶל בָּלָק הָיָה צָרִיךְ לוֹ לִהְיוֹת, שֶׁהֲרֵי בָּלָק עָשָׂה הַכֹּל! מַה זֶּה אֶל בִּלְעָם? אֶלָּא מִשּׁוּם שֶׁהָיָה סוֹתֵם עֵינָיו כְּדֵי שֶׁלֹּא יִתְבָּרְכוּ יִשְׂרָאֵל. לָמַדְנוּ, אָמַר רַבִּי יוֹסֵי, אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא לְבִלְעָם: רָשָׁע, אַתָּה סוֹתֵם עֵינֶיךְ כְּדֵי שֶׁלֹּא יִתְבָּרְכוּ בָנַי - אֲנִי אֶפְקַח עֵינַי, וְכָל הַדְּבָרִים שֶׁתֹּאמַר, אֶהְפֹּךְ אוֹתָם לִבְרָכָה. זֶהוּ שֶׁכָּתוּב (שם) וַיַּהֲפֹךְ ה' אֱלֹהֶיךְ לְּךְ אֶת הַקְּלָלָה לִבְרָכָה כִּי אֲהֵבְךְ וְגוֹ'."],[14,"","וְעַל כֵּן כָּתוּב, (משלי כב) טוֹב עַיִן הוּא יְבֹרָךְ כִּי נָתַן מִלַּחְמוֹ לַדָּל. מַה זֶּה מִלַּחְמוֹ? כְּמוֹ שֶׁבֵּאַרְנוּ, שֶׁכָּתוּב (ויקרא כא) לֶחֶם אֱלֹהָיו מִקָּדְשֵׁי הַקְּדָשִׁים וְגוֹ'. מַשְׁמָע שֶׁקָּדְשֵׁי הַקְּדָשִׁים, לֶחֶם אֱלֹהָיו יָצָא מִמֶּנּוּ, וְלָכֵן כִּי נָתַן מִלַּחְמוֹ לַדָּל. לָמַדְנוּ כַּמָּה חֲבִיבִים יִשְׂרָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא, שֶׁעֶלְיוֹנִים וְתַחְתּוֹנִים מִתְבָּרְכִים רַק בִּגְלַל יִשְׂרָאֵל."],[15,"","שֶׁלְּמַדְנוּ, אָמַר רַבִּי יְהוּדָה אָמַר רַבִּי חִיָּיא אָמַר רַבִּי יוֹסֵי, נִשְׁבַּע הַקָּדוֹשׁ בָּרוּךְ הוּא שֶׁלֹּא יִכָּנֵס בִּירוּשָׁלַיִם שֶׁל מַעְלָה עַד שֶׁיִּכָּנְסוּ יִשְׂרָאֵל בִּירוּשָׁלַיִם שֶׁל מַטָּה, שֶׁנֶּאֱמַר (הושע יא) בְּקִרְבְּךְ קָדוֹשׁ וְלֹא אָבוֹא בְּעִיר. כְּלוֹמַר, כָּל זְמַן שֶׁהַשְּׁכִינָה כָּאן בַּגָּלוּת, הַשֵּׁם שֶׁלְּמַעְלָה לֹא נִשְׁתַּלֵּם, וְכָל הַתִּקּוּנִים לֹא נִתְקְנוּ, כִּבְיָכוֹל נִשְׁאָר הַשֵּׁם הַקָּדוֹשׁ חָסֵר."]]],[["רִבִּי אַבָּא הֲוָה אָזִיל לְלוּד, פָּגַע בֵּיהּ רִבִּי זֵירָא בַּר רַב, אָמַר לֵיהּ הָא חֲמֵינָא אַפֵּי שְׁכִינְתָּא, וּמַאן דְּחָמֵי אַפֵּי שְׁכִינְתָּא, בָּעֵי לְמֵיזָל וּלְרַהֲטָא בַּתְרָאָה. הֲדָא הוּא דִכְתִיב, (הושע ו׳:ג׳) וְנֵדְעָה נִרְדְּפָה לָדַעַת אֶת ה'. וּכְתִיב (ישעיהו ב׳:ג׳) וְהָלְכוּ עַמִּים רַבִּים וְאָמְרוּ לְכוּ וְנַעֲלֶה אֶל הַר יְיָ וְגוֹ'. כִּי מִצִּיּוֹן תֵּצֵא תּוֹרָה וְגוֹ'. וַאֲנָא בָּעֵינָא לְמֵהַךְ בָּתְרָךְ, וּלְמֵילַף מֵאִינּוּן מִלֵּי מְעַלְּיָיתָא, דְּאַתּוּן טַעֲמִין כָּל יוֹמָא, מֵאִדָּרָא קַדִּישָׁא.","מַאי דִּכְתִּיב, (בראשית ט״ו:ו׳) וְהֶאֱמִין בַּיְיָ וַיַּחְשְׁבֶהָ לוֹ צְדָקָה, אִי קוּדְשָׁא בְּרִיךְ הוּא חֲשָׁבָהּ לְאַבְרָהָם, אוֹ אַבְרָהָם לְּקוּדְשָׁא בְּרִיךְ הוּא. וַאֲנָא שְׁמַעְנָא, דְקוּדְשָׁא בְּרִיךְ הוּא חֲשָׁבָהּ לְאַבְרָהָם, וְלָא אִתְיַשְּׁבָא בְּלִבָּאִי. אָמַר לֵיהּ הָכִי אוֹקִימְנָא, וְלָאו הָכִי הֲוִי. תָּא חֲזֵי, וַיַּחְשְׁבֶהָ, ויַחְשׁוֹב לוֹ לָא כְּתִיב, אֶלָּא וַיַּחְשְׁבֶהָ, אַבְרָהָם ודַּאי חֲשָׁבָהּ לְּקוּדְשָׁא בְּרִיךְ הוּא. דְּתַנְיָא, כְּתִיב (בראשית ט״ו:ה׳) וַיּוֹצֵא אוֹתוֹ הַחוּצָה, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, צֵא מֵאִצְטַגְנִינוּת שֶׁלְּךָ, לָאו הַהוּא אוֹרְחָא לְמִנְדַּע שְׁמִי, אַת חָמֵי, וַאֲנָא חֲמֵינָא, אַבְרָם אֵינוֹ מוֹלִיד, אַבְרָהָם מוֹלִיד. מִכָּאן וּלְהָלְאָה, אִשְׁתְּדָלוּ בְּאָרְחָא אַחֲרָא, כֹּ\"ה יִהְיֶה זַרְעֶךָ. מַאי כֹּ\"ה. הִיא כִּתְרָא עֲשִׂירָאָה קַדִּישָׁא דְּמַלְכָּא, לְמִנְדַּע שְׁמֵיהּ, וְהִיא כִּתְרָא דְּדִינִין מִתְעָרִין מִנָּהּ.","וְתָאנָא, כֹּה יִהְיֶה זַרְעֶךָ מַמָּשׁ. בְּהַהִיא שַׁעֲתָא חַדֵּי אַבְרָהָם, לְאִסְתַּכְּלָא וּלְמִנְדַּע שְׁמֵיהּ, וּלְאִתְדַּבְּקָא בֵּיהּ, מִשּׁוּם דְּאִתְבְּשַׂר בְּכ\"ה, וְאַף עַל גַּב דְּדִינִין מִתְעָרִין מִנָּהּ, חֲשָׁבָהּ אַבְרָהָם לְהַהוּא כִּתְרָא, אַף עַל גַּב דְּהִיא דִּינָא, כְּאִלּוּ הִיא רַחֲמֵי. הֲדָא הוּא דִכְתִיב, וַיַּחְשְׁבֶהָ. מַאי וַיַּחְשְׁבֶהָ. לְהַהוּא כִּתְרָא. צְדָקָה רַחֲמֵי. אָמַר רִבִּי יִצְחָק, כֹּ\"ה כִּתְרָא עֲשִׂירָאָה הִיא, וְאִתְקְרֵי צֶדֶ\"ק, וְדִינִין מִתְעָרִין מִנָּהּ, וְאַבְרָהָם אַף עַל גַּב דְּיָדַע דְּדִינִין מִתְעָרִין מִנָּהּ מֵהַאי צֶדֶק. הוּא חֲשָׁבָהּ צְדָקָה, דְּדִינִין לָא מִתְעָרִין מִנָּהּ, בְּגִין דְּהוּא רַחֲמֵי.","תּוּ אָמַר רִבִּי אַבָּא, מַאי דִּכְתִּיב, (בראשית כ״ד:א׳) וַיְיָ בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל, כְּמָה דְאַתְּ אָמֵר (דברי הימים א כ״ט:י״א) כִּי כָל בַּשָׁמַיִם וּבָאָרֶץ. וּכְתִיב כֹּה תְבָרַכוּ, דִּבְגִּינַיְיהוּ דְּיִשְׂרָאֵל מִתְבָּרֵךְ הַאי כֹּ\"ה עַל יְדָא דְּכַהֲנָא, בְּגִין דְּיִתְבָּרְכוּן יִשְׂרָאֵל לְתַתָּא, וְיִשְׁתְּכַּח בִּרְכָתָא בְּכֹלָּא וּלְזִמְנָא דְּאָתֵי (ס\"א כתיב) כְּמָה דְאַתְּ אָמֵר (תהילים קל״ד:ג׳) יְבָרֶכְךָ יְיָ מִצִּיּוֹן וְגוֹ'. (תהילים קל״ה:כ״א) בָּרוּךְ יְיָ מִצִּיּוֹן שׁוֹכֵן יְרוּשָׁלַ ם.","(במדבר ז׳:א׳) וַיְהִי בְּיוֹם כַּלֹּת מֹשֶׁה וְגוֹ'. תָּנָא רִבִּי יוֹסֵי, בְּיוֹם שֶנִכְנָסָה כַּלָּה לַחוּפָּה. בְּמַאי אוֹקִימְנָא בְּיוֹם כַּלֹּת מֹשֶׁה. אֶלָּא מְלַמֵּד, דְּעַל יְדוֹי דְּמֹשֶׁה נִכְנָסָה. אָמַר רִבִּי יְהוּדָה, וְכִי עַד הַשְׁתָּא אִתְעַכָּבַת דְּלָא עַיְילַת לְדוּכְתָּהּ, וְהָכְּתִיב (שמות מ׳:ל״ה) וְלָא יָכוֹל מֹשֶׁה לָבֹא אֶל אֹהֶל מוֹעֵד וְגוֹ'. אָמַר רִבִּי יִצְחָק אֵין מוּקְדָם וּמְאוּחָר בַּתּוֹרָה.","וַיְהִי בְּיוֹם כַּלֹּת מֹשֶׁה, כַּלַּת שֶׁל מֹשֶׁה וַדַּאי. דְּתָנֵינָן אָמַר רַבִּי שִׁמְעוֹן, מַאי דִּכְתִּיב, (תהילים ס״ח:י״ט) עָלִיתָ לַמָּרוֹם שָׁבִיתָ שֶׁבִי וְגוֹ'. אֶלָּא בְּשָׁעָה שֶׁאָמַר לוֹ קוּדְשָׁא בְּרִיךְ הוּא, (שמות ג׳:ה׳) שַׁל נְעָלֶיךָ מֵעַל רַגְלֶיךָ, אִזְדַּעְזָע הָהָר, אָמַר מִיכָאֵל קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, רִבּוֹנוֹ שֶׁל עוֹלָם תִּבְעֵי לִסְתּוֹר אָדָם. וְהָא כְּתִיב (בראשית ה׳:ב׳) זָכָר וּנְקֵבָה בְּרָאָם וַיְבָרֶךְ אוֹתָם, וְלֵית בִּרְכָתָא אִשְׁתְּכַח, אֶלָּא בְּמַאן דְּאִיהוּ דְּכַר וְנוּקְבָּא, ואַתְּ אַמָרְת לְאִתְפָּרְשָׁא מְאִתְּתֵיהּ.","אָמַר לֵיהּ הָא קִיֵּים מֹשֶׁה פִּרְיָה וּרְבִיָּה, הַשְׁתָּא אֲנָא בָּעֵינָא דְּיִתְנְסַב בִּשְׁכִינְתָּא, וּבְגִינֵיהּ יֵחוּת שְׁכִינְתָּא לְדַיְּירָא עִמֵּיהּ, הֲדָא הוּא דִכְתִיב עָלִיתָ לַמָּרוֹם שָׁבִיתָ שֶׁבִי. וּמַאי שֶׁבִי. שְׁכִינְתָּא דְּאִתְנְסִיבַת עִמָּךְ. לָקַחְתָּ מַתָנוֹת בָּאָדָם. בְּאָדָם לָא כְּתִיב, אֶלָּא בָּאָדָם הַיָּדוּעַ לְמַעְלָה. וּבְיוֹמָא דְּנַחְתַּת שְׁכִינְתָּא, הַהוּא יוֹמָא דְּאִתְנַסְּבָא בְּמֹשֶׁה נַחְתָּא, הֲדָא הוּא דִכְתִיב כַּלֹּת מֹשֶׁה, כַּלַּת מֹשֶׁה מַמָּשׁ.","וּבִיהוֹשֻעַ דְּאַנְפּוֹי כְּאַנְפֵּי סִיהֲרָא כְּתִיב, (יהושע ה) שַׁל נַעַלְךָ, דְּלָא אִתְפְּרַשׁ אֶלָּא בְּזִמְנִין יְדִיעָן, דְּהָא לָא אִתְנְסִיבַת עִמֵּיהּ שְׁכִינְתָּא כָּל כַּךְ, וְלָא אִתְחֲזֵי לֵיהּ, דִּכְתִּיב (יהושע ה׳:י״ד) וַיִּפֹּל יְהוֹשֻׁעַ עַל פָּנָיו אַרְצָה. אֲבָל הָכָא כַּלַּת מֹשֶׁה וַדַּאי. מַתָנוֹת בָּאָדָם, מַתְּנַת כְּתִיב, זַכָּאָה חוּלָקֵיהּ דְּמֹשֶׁה, דְּמָארֵיהּ בָּעֵי בִּיקָרֵיהּ, עַל כָּל שְׁאָר בְּנֵי עָלְמָא.","(במדבר ז׳:י״א) וַיֹּאמֶר יְיָ אֶל מֹשֶׁה נָשִׂיא אֶחָד לַיּוֹם. מַהוּ לַיּוֹם. אָמַר רִבִּי יְהוּדָה, יוֹמִין דִּלְעֵילָּא, דְּאִתְחַנְּכוּ לְאִתְבָּרְכָא, בְּאִינּוּן תְּרֵיסָר תְּחוּמִין, דְּמִתְפָּרְשָׁא, וְכָל חַד אִתְתָּקַּן וְאִתְחַנָּךְ בְּבִרְכָתָא עַל יְדוֹי דְּאִלֵּין דִּלְתַּתָּא. תָּאנָא, כֻּלְּהוּ מִתְבָּרְכָן בְּגִין מַדְבְּחָא דִּלְעֵילָּא, וַאֲפִילּוּ תַּתָאָה וַאֲפִילּוּ עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת מִתְבָּרְכָן."],[[0,"רבי אבא הוה","וכו׳: ר״א היה הולך ללוד. פגע בו ר׳ זירא בר רב. אמר לו הרי ראיתי פני השכינה, ומי שרואה פני השכינה צריך ללכת ולרוץ אחריה. ז״ש ונדעה נרדפה לדעת את ה׳. וכתוב, והלכו עמים רבים ואמרו, לכו ונעלה אל הר ה׳ וגו׳ כי מציון תצא תורה וגו׳. ואני רוצה ללכת אחריך וללמוד מאלו הדברים הטובים שאתם טועמים בכל יום מחדרו הקדוש של רשב״י."],[1,"מאי דכתיב והאמין","וכו׳: מה שכתוב, והאמין בה׳ ויחשבה לו צדקה. אם הפירוש הוא שהקב״ה חשבה לאברהם צדקה. או אברהם להקב״ה. ואני שמעתי שהקב״ה חשבה לאברהם. ולא נתיישב בלבי. אמר לו, כך העמדנו, ולא היה כן. בוא וראה, ויחשבה לו, ויחשוב לו לא כתוב, אלא ויחשבה, שהיא לשון נקבה, משמע, שאברהם ודאי חשב אותה להקב״ה. שלמדנו כתוב, ויוצא אותו החוצה, אמר לו הקב״ה, צא מאצטגנינות שלך, שהיה אברהם רואה באצטגנינות שלא יוליד. אין זה הדרך לדעת את שמי. אתה רואה ואני רואה. אברם אינו מוליד אבל אברהם מוליד. מכאן והלאה תשתדלו בדרך אחר לדעת שמי. כי \u0003כה\u0004 יהיה זרעך. מהו \u0003כה.\u0004 היא ספירה עשירית הקדושה של המלך, לדעת שמו. והיא ספירה שהדינים מתעוררים ממנה."],[2,"ותאנא כה יהיה","וגו׳: ולמדנו, כה יהיה זרעך ממש. שהזרע שלו יהיה ממלכות ממש, ואם לא ספירת המלכות לא יהיה לו זרע. ובזה נתהפכה לו המלכות לרחמים. בשעה ההיא שמח אברהם להסתכל ולדעת שמו ולהתדבק בו, משום שנתבשר ב \u0003כה,\u0004 ואע״פ שדינים מתעוררים ממנה, חשבה אברהם לספירה ההיא אע״פ שהיא דין, כאלו היתה רחמים. כי זולתה לא יהיה לו בנים. ז״ש ויחשבה, לשון נקבה, מהו ויחשבה, היינו לספירה ההיא מלכות, חשבה \u0003צדקה\u0004 שהיא רחמים כי צדק הוא דין וצדקה היא רחמים. אמר רבי יצחק \u0003כה\u0004 ספירה אחרונה היא, דהיינו מלכות. ונקראת \u0003צדק,\u0004 ודינין מתעוררים ממנה. ואברהם אע״פ שידע דדינים מתעוררים ממנה מן \u0003צדק\u0004 הזה, הוא חשבה \u0003לצדקה\u0004 שאין דינים מתעוררים ממנה, משום שהיא רחמים."],[3,"תו אמר ר׳ אבא","וכו׳: עוד אמר ר״א מה שכתוב, וה׳ ברך את אברהם \u0003בכל.\u0004 הוא כמו שאתה אומר, כי \u0003כל\u0004 בשמים ובארץ. כלומר שברך את אברהם בספירת היסוד, שנקרא \u0003כל,\u0004 שהוא המשפיע ומברך למדת המלכות, כמ״ש כי כל בשמים ובארץ. שה \u0003כל\u0004 שהוא יסוד מקבל משמים שהוא ז״א ומשפיע לארץ שהיא המלכות. וכתוב כה תברכו, שפירושו שהכהנים יברכו את המלכות שנקראת \u0003כה\u0004 כי בשביל ישראל מתברכת \u0003כה\u0004 הזו על ידי הכהן, כדי שיתברכו ישראל למטה, והברכה תמצא בכל, ולעתיד לבא כתוב, יברכך ה׳ מציון וגו׳. ברוך ה׳ מציון שוכן ירושלים וגו׳. דהיינו שהמלכות לא תהיה צריכה שיברכו אותה תחילה, אלא הברכה תהיה מצויה בה תמיד. ציון היא פנימית המלכות וירושלים ה״ס חיצוניות המלכות."],[4,"ויהי ביום כלת משה","וגו׳: ר׳ יוסי למד, שפירושו, ביום שנכנסה הכלה לחופה. שהיא השכינה, ושואל א״כ, במה נעמיד ביום כלת משה. היה מספיק שיאמר ביום כלת. ומשיב, אלא מלמד שעל ידי משה נכנסה. אמר ר׳ יהודה׳ וכי עד עתה נתעכבה השכינה ולא נכנסה למקומה, והרי כתוב, ולא יכול משה לבא אל אהל מועד וגו׳. הרי שהשכינה היתה באהל מועד מטרם יום הזה. א\"ר יצחק אין מוקדם ומאוחר בתורה. שהכתוב, ולא יכול משה וגו׳, הוא מאוחר מהכתוב שבכאן."],[5,"ויהי ביום כלת משה:","היינו השכינה הנקראת כלת משה, שהיא כלת של משה ודאי. שלמדנו אמר ר״ש מה שכתוב עלית למרום שבית שבי וגו׳. אלא בשעה שאמר לו הקב״ה של נעליך מעל רגליך, נזדעזע ההר. אמר המלאך מיכאל לפני הקב״ה, רבונו של עולם, תרצה לסתור בנין אדם, והרי כתוב, זכר ונקבה בראם ויברך אותם. ואין ברכה נמצאת אלא במי שהוא זכר ונקבה, ואתה אמרת למשה להפרד מאשתו. כי של נעליך מעל רגליך, פירושו שיפרד מאשתו. שהכתוב מדבר בלשון נקיה."],[6,"א\"ל הא קיים","וכו׳: אמר לו הקב״ה, הרי קיים משה פריה ורביה, עתה אני רוצה שישא את השכינה, ובשבילו תרד השכינה לדור עמו. ז״ש עלית למרום שבית שבי. מהו שבי. הוא השכינה שנשאת עמך. לקחת מתנות באדם. באדם עם ב' שואית לא כתוב, אלא באדם עם ב׳ קמוצה. שיורה על האדם הידוע למעלה. שהוא ז״א. ומתנה, היא השכינה שז״א נתן לו. וביום שירדה השכינה, ביום ההוא שנשאת למשה ירדה, ז״ש כלת משה. כלת משה ממש."],[7,"וביהושע דאנפוי כאנפי","וכו׳: וביהושע, שפניו היה כפני הלבנה כתוב, של נעלך. שלא נפרד מאשתו אלא בזמנים ידועים, לצורך הנבואה, כי השכינה לא נשאת עמו כל כך, ולא היה ראוי לה. שכתוב, ויפל יהושע על פניו ארצה. אבל כאן כלת משה ודאי. \u0003מתנות באדם,\u0004 מתנת כתוב, בלא \u0003ו׳\u0004 שהיא סימן הרבים. כי סובב על השכינה, שהיא יחידה. אשרי חלקו של משה שאדונו רצה ביקרו על כל שאר בני העולם."],[8,"ויאמר וגו' נשיא אחד ליום:","שואל מהו ליום. א״ר יהודה הם הימים שלמעלה שנתחנכו להתברך, שהם אלו י״ב גבולים, דהיינו חו״ג תו״מ שבכ״א ג׳ קוין, שה״ס י״ב גבולים (כנ״ל לך ח׳ ד״ה ומכח) המתחלקים, וכל אחד מתתקן ומתחנך בברכה על ידי אלו הנשיאים שלמטה. שכל נשיא היה מתקן יום אחד. למדנו כולם מתברכים בשביל מזבח של מעלה, שהוא בינה. ואפילו העולם התחתון, ואפילו אומות העולם מתברכים."]],[[0,"","רַבִּי אַבָּא הָיָה הוֹלֵךְ לְלוֹד, פָּגַע בּוֹ רַבִּי זֵירָא בַּר רַב. אָמַר לוֹ, הֲרֵי רָאִיתִי פְּנֵי הַשְּׁכִינָה, וּמִי שֶׁרוֹאֶה פְּנֵי הַשְּׁכִינָה, צָרִיךְ לָלֶכֶת וְלָרוּץ אַחֲרֶיהָ. זֶהוּ שֶׁכָּתוּב (הושעו) וְנֵדְעָה נִרְדְּפָה לָדַעַת אֶת ה'. וְכָתוּב (ישעיה ב) וְהָלְכוּ עַמִּים רַבִּים וְאָמְרוּ לְכוּ וְנַעֲלֶה אֶל הַר ה' וְגוֹ'. כִּי מִצִּיּוֹן תֵּצֵא תוֹרָה וְגוֹ'. וַאֲנִי רוֹצֶה לָלֶכֶת אַחֲרֶיךְ וְלִלְמֹד מֵאוֹתָם דְּבָרִים מְעֻלִּים שֶׁאַתֶּם טוֹעֲמִים כָּל יוֹם מֵהַחֶדֶר הַקָּדוֹשׁ."],[1,"","מַה זֶּה שֶׁכָּתוּב, (בראשית טו) וְהֶאֱמִן בַּה' וַיַּחְשְׁבֶהָ לּוֹ צְדָקָה? אִם הַקָּדוֹשׁ בָּרוּךְ הוּא חָשַׁב אוֹתָהּ לְאַבְרָהָם אוֹ אַבְרָהָם לַקָּדוֹשׁ-בָּרוּךְ-הוּא? וַאֲנִי שָׁמַעְתִּי שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא חָשַׁב אוֹתָהּ לְאַבְרָהָם, וְלֹא הִתְיַשֵּׁב בְּלִבִּי. אָמַר לוֹ, כָּךְ בֵּאַרְנוּ, וְלֹא הָיָה כָּךְ. בֹּא רְאֵה, וַיַּחְשְׁבֶהָ, לֹא כָתוּב וַיַּחְשֹׁב לוֹ, אֶלָּא וַיַּחְשְׁבֶהָ, וַדַּאי שֶׁאַבְרָהָם חָשַׁב אוֹתָהּ לַקָּדוֹשׁ-בָּרוּךְ-הוּא. שֶׁלָּמַדְנוּ, כָּתוּב וַיּוֹצֵא אֹתוֹ הַחוּצָה. אָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא, צֵא מֵאִצְטַגְנִינוּת שֶׁלְּךְ, לֹא אוֹתָהּ הַדֶּרֶךְ לָדַעַת שְׁמִי, אַתָּה רוֹאֶה וַאֲנִי רוֹאֶה, אַבְרָם אֵינוֹ מוֹלִיד, אַבְרָהָם מוֹלִיד. מִכָּאן וָהָלְאָה הִשְׁתַּדְּלוּ בְדֶרֶךְ אַחֶרֶת, כֹּ\"ה יִהְיֶה זַרְעֶךְ. מַה זֶּה כֹּ\"ה? הִיא כֶּתֶר עֲשִׂירִי הַקָּדוֹשׁ שֶׁל הַמֶּלֶךְ לָדַעַת אֶת שְׁמוֹ, וְהִיא הַכֶּתֶר שֶׁהַדִּינִים מִתְעוֹרְרִים מִמֶּנָּה."],[2,"","וְלָמַדְנוּ, כֹּה יִהְיֶה זַרְעֶךְ מַמָּשׁ. בְּאוֹתָהּ שָׁעָה שָׂמַח אַבְרָהָם לְהִסְתַּכֵּל וְלָדַעַת אֶת שְׁמוֹ וּלְהִדָּבֵק בּוֹ, מִשּׁוּם שֶׁהִתְבַּשֵּׂר בְּכֹ\"ה, וְאַף עַל גַּב שֶׁמִּתְעוֹרְרִים מִמֶּנָּה הַדִּינִים, חָשַׁב אַבְרָהָם לְאוֹתוֹ הַכֶּתֶר, אַף עַל גַּב שֶׁהִיא דִין, כְּאִלּוּ הִיא רַחֲמִים. זֶהוּ שֶׁכָּתוּב וַיַּחְשְׁבֶהָ. מַה זֶּה וַיַּחְשְׁבֶהָ? אֶת אוֹתוֹ הַכֶּתֶר, צְדָקָה וְרַחֲמִים. אָמַר רַבִּי יִצְחָק, כֹּ\"ה הִיא כֶּתֶר עֲשִׂירִי, וְנִקְרֵאת צֶדֶק, וּמִמֶּנָּה מִתְעוֹרְרִים הַדִּינִים. וְאַבְרָהָם, אַף עַל גַּב שֶׁיָּדַע שֶׁמֵּהַצֶּדֶק הַזֶּה מִתְעוֹרְרִים הַדִּינִים, הוּא חָשַׁב אוֹתָהּ צְדָקָה שֶׁלֹּא מִתְעוֹרְרִים מִמֶּנָּה הַדִּינִים, בִּגְלַל שֶׁהִיא רַחֲמִים."],[3,"","עוֹד אָמַר רַבִּי אַבָּא, מַה שֶּׁכָּתוּב (שם כד) וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל, כְּמוֹ שֶׁנֶּאֱמַר (דברי הימים א כט) כִּי כֹל בַּשָּׁמַיִם וּבָאָרֶץ. וְכָתוּב כֹּה תְבָרֲכוּ. שֶׁבִּגְלַל יִשְׂרָאֵל מִתְבָּרֶכֶת הַכֹּ\"ה עַל יְדֵי הַכֹּהֵן, בִּשְׁבִיל שֶׁיִּתְבָּרְכוּ יִשְׂרָאֵל לְמַטָּה, וְתִמָּצֵא בְרָכָה בַּכֹּל. וְלֶעָתִיד לָבֹא (כתוב) כְּמוֹ שֶׁנֶּאֱמַר, (תהלים קלד) יְבָרֶכְךְ ה' מִצִּיּוֹן וְגוֹ'. (שם קלה) בָּרוּךְ ה' מִצִּיּוֹן שֹׁכֵן יְרוּשָׁלם."],[4,"","וַיְהִי בְּיוֹם כַּלּוֹת מֹשֶׁה וְגוֹ'. שָׁנָה רַבִּי יוֹסֵי, בַּיּוֹם שֶׁנִּכְנְסָה כַּלָּה לַחֻפָּה. בַּמָּה בֵּאַרְנוּ בְּיוֹם כַּלּוֹת מֹשֶׁה? אֶלָּא מְלַמֵּד שֶׁעַל יְדֵי מֹשֶׁה נִכְנְסָה. אָמַר רַבִּי יְהוּדָה, וְכִי עַד עַכְשָׁו הִתְעַכְּבָה שֶׁלֹּא נִכְנְסָה לִמְקוֹמָהּ, וַהֲרֵי כָּתוּב (שמות מ) וְלֹא יָכֹל מֹשֶׁה לָבוֹא אֶל אֹהֶל מוֹעֵד וְגוֹ'? אָמַר רַבִּי יִצְחָק, אֵין מֻקְדָּם וּמְאֻחָר בַּתּוֹרָה."],[5,"","וַיְהִי בְּיוֹם כַּלּוֹת מֹשֶׁה, וַדַּאי כַּלָּתוֹ שֶׁל מֹשֶׁה. שֶׁשָּׁנִינוּ, אָמַר רַבִּי שִׁמְעוֹן, מַהוּ שֶׁכָּתוּב (תהלים סח) עָלִיתָ לַמָּרוֹם שָׁבִיתָ שֶּׁבִי וְגוֹ'? אֶלָּא בְּשָׁעָה שֶׁאָמַר לוֹ הַקָּדוֹשׁ בָּרוּךְ הוּא (שמות ג) שַׁל נְעָלֶיךְ מֵעַל רַגְלֶיךְ, הִזְדַּעֲזַע הָהָר. אָמַר מִיכָאֵל לִפְנֵי הַקָּדוֹשׁ בָּרוּךְ הוּא: רִבּוֹנוֹ שֶׁל עוֹלָם, הֲתִרְצֶה לִסְתֹּר אָדָם? וַהֲרֵי כָּתוּב (בראשית ה) זָכָר וּנְקֵבָה בְּרָאָם וַיְבָרֶךְ אֹתָם, וְאֵין נִמְצֵאת הַבְּרָכָה אֶלָּא בְּמִי שֶׁהוּא זָכָר וּנְקֵבָה, וְאַתָּה אוֹמֵר לְהִפָּרֵד מֵאִשְׁתּוֹ?"],[6,"","אָמַר לוֹ: הֲרֵי קִיֵּם מֹשֶׁה פְּרִיָּה וּרְבִיָּה, כָּעֵת אֲנִי רוֹצֶה שֶׁיִּשָּׂא אֶת הַשְּׁכִינָה, וּבִשְׁבִילוֹ תֵרֵד הַשְּׁכִינָה לָדוּר עִמּוֹ. זֶהוּ שֶׁכָּתוּב עָלִיתָ לַמָּרוֹם שָׁבִיתָ שֶּׁבִי. וּמַהוּ הַשֶּׁבִי? שְׁכִינָה שֶׁנִּשְׂאָה לְךְ. לָקַחְתָּ מַתָּנוֹת בָּאָדָם. בְּאָדָם לֹא כָתוּב, אֶלָּא בָּאָדָם הַיָּדוּעַ לְמַעְלָה. וּבַיּוֹם שֶׁיָּרְדָה הַשְּׁכִינָה, אוֹתוֹ יוֹם שֶׁנִּשְׂאָה לְמֹשֶׁה הִיא יָרְדָה, זֶהוּ שֶׁכָּתוּב כַּלּוֹת מֹשֶׁה, כַּלַּת מֹשֶׁה מַמָּשׁ."],[7,"","וּבִיהוֹשֻׁעַ שֶׁפָּנָיו כִּפְנֵי הַלְּבָנָה, כָּתוּב (יהושע ה) שַׁל נַעַלְךְ, שֶׁלֹּא נִפְרַד אֶלָּא בִּזְמַנִּים יְדוּעִים, שֶׁהֲרֵי הַשְּׁכִינָה לֹא נִשְׂאָה לוֹ כָּל כָּךְ וְלֹא נִרְאֲתָה לוֹ, שֶׁכָּתוּב (שם) וַיִּפֹּל יְהוֹשֻׁעַ אֶל (על) פָּנָיו אַרְצָה. אֲבָל כָּאן כַּלַּת מֹשֶׁה וַדַּאי. מַתָּנוֹת בָּאָדָם, מַתְּנַת כָּתוּב. אַשְׁרֵי חֶלְקוֹ שֶׁל מֹשֶׁה שֶׁרִבּוֹנוֹ חָפֵץ בִּיקָרוֹ עַל כָּל שְׁאָר בְּנֵי הָעוֹלָם."],[8,"","וַיֹּאמֶר ה' אֶל מֹשֶׁה נָשִׂיא אֶחָד לַיּוֹם. מַהוּ לַיּוֹם? אָמַר רַבִּי יְהוּדָה, יָמִים שֶׁלְּמַעְלָה שֶׁהִתְחַנְּכוּ לְהִתְבָּרֵךְ בְּאוֹתָם שְׁנֵים עָשָׂר תְּחוּמִים שֶׁנִּפְרָדִים, וְכָל אֶחָד הִתְתַּקֵּן וְהִתְחַנֵּךְ בִּבְרָכָה עַל יְדֵי אוֹתָם שֶׁלְּמַטָּה. לָמַדְנוּ, כֻּלָּם מִתְבָּרְכִים בִּגְלַל מִזְבֵּחַ שֶׁלְּמַעְלָה, וַאֲפִלּוּ הַתַּחְתּוֹן, וַאֲפִלּוּ עוֹבְדֵי כוֹכָבִים וּמַזָּלוֹת מִתְבָּרְכִים."]]],[["דְּתַנְיָא, אָמַר רִבִּי שִׁמְעוֹן, אִלְמָלֵא לָא אַקְרִיבוּ אִלֵּין תְּרֵיסָר נְשִׂיאִין, לָא יָכִיל עָלְמָא לְמֵיקָם קַמֵּי תְּרֵיסָר נְשִׂיאֵי יִשְׁמָעֵאל, דִּכְתִּיב, (בראשית כ״ה:ט״ז) שְׁנֵים עָשָׂר נְשִׂיאִים לְאוּמוֹתָם. מִדְּאַקְרִיבוּ אִלֵּין דְּיִשְׂרָאֵל, נָסִיבוּ שׁוּלְטָנוּתָא דְּכֻלְּהוּ, בְּגִין כָּךְ נָשִׂיא אֶחָד לַיּוֹם.","וְכָל מַה דְּאַקְרִיבוּ, כְּגַוְונָא דִּלְעֵילָּא אַקְרִיבוּ, בְּגִין דְּיִתְבָּרְכוּן כֻּלְּהוֹן. אֵילִם שִׁשִּׁים, עַתּוּדִים שִׁשִּׁים, כְּמָה דִּכְתִּיב, (שיר השירים ג׳:ז׳) שִׁשִּׁים גִּבּוֹרִים סָבִיב לָהּ, דְּבִסְטַר גְּבוּרָה. כַּף אַחַת עֲשָׂרָה זָהָב וְגוֹ', וְהָא אִתְּמַר, זַכָּאָה חוּלָקֵיהוֹן דְּצַדִּיקַיָּיא, דְקוּדְשָׁא בְּרִיךְ הוּא מֵרִיק עָלַיְיהוּ בִּרְכָאן, וְצַיִית צְלוֹתְהוֹן, וְעָלַיְיהוּ כְּתִיב, (תהילים ק״ב:י״ח) פָּנָה אֶל תְּפִלַּת הָעַרְעָר וְלֹא בָזָה אֶת תְּפִלָּתָם וְגוֹ'. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן. יִמְלוֹךְ ה' לְעוֹלָם אָמֵן וְאָמֵן."],[[0,"דתניא א\"ר שמעון","וכו׳: שלמדנו א״ר שמעון, אם לא היו מקריבים אלו י״ב הנשיאים לא היה יכול העולם לעמוד לפני י״ב נשיאי ישמעאל, שכתוב, שנים עשר נשיאים לאומותם. משהקריבו י״ב נשיאי ישראל ניטלה השליטה מכולם. משום זה, נשיא אחד ליום."],[1,"וכל מה דאקריבו","וכו׳: וכל מה שהקריבו כעין שלמעלה הקריבו, כדי שיתברכו כולם. אילים ששים עתודים ששים, הוא כמו שכתוב ששים גבורים סביב לה. שה״ס חג״ת נה״י דז״א שמצד הגבורה, שכל אחד כולל עשר והם ששים. כף אחת עשרה זהב וגו׳. היא כנגד המלכות. וכבר למדנו. אשרי חלקם של הצדיקים שהקב״ה מריק עליהם ברכות ושומע תפלתם. ועליהם כתוב, פנה אל תפלת הערער ולא בזה את תפלתם וגו׳. ברוך ה׳ לעולם אמן ואמן ימלוך ה׳ לעולם אמן ואמן."]],[[0,"","שֶׁלָּמַדְנוּ, אָמַר רַבִּי שִׁמְעוֹן, אִלְמָלֵא לֹא הִקְרִיבוּ שְׁנֵים עָשָׂר נְשִׂיאִים אֵלּוּ, לֹא יָכֹל הָעוֹלָם לַעֲמֹד לִפְנֵי שְׁנֵים עָשָׂר נְשִׂיאֵי יִשְׁמָעֵאל, שֶׁכָּתוּב, (בראשית כה) שְׁנֵים עָשָׂר נְשִׂיאִים לְאֻמֹּתָם. מִשֶּׁהִקְרִיבוּ אֵלּוּ שֶׁל יִשְׂרָאֵל, לָקְחוּ שִׁלְטוֹן שֶׁל הַכֹּל, מִשּׁוּם כָּךְ נָשִׂיא אֶחָד לַיּוֹם."],[1,"","וְכָל מַה שֶּׁהִקְרִיבוּ, כְּדֻגְמָה שֶׁלְּמַעְלָה הִקְרִיבוּ, כְּדֵי שֶׁיִּתְבָּרְכוּ כֻלָּם. אֵילִם שִׁשִּׁים, עַתּוּדִים שִׁשִּׁים, כְּמוֹ שֶׁכָּתוּב (שיר השירים ג) שִׁשִּׁים גִּבֹּרִים סָבִיב לָהּ, שֶׁבְּצַד הַגְּבוּרָה. כַּף אַחַת עֲשָׂרָה זָהָב וְגוֹ', וַהֲרֵי נִתְבָּאֵר. אַשְׁרֵי חֶלְקָם שֶׁל הַצַּדִּיקִים שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא מוֹרִיק עֲלֵיהֶם בְּרָכוֹת וּמַקְשִׁיב לִתְפִלּוֹתֵיהֶם, וַעֲלֵיהֶם כָּתוּב (תהלים קב) פָּנָה אֶל תְּפִלַּת הָעַרְעָר וְלֹא בָזָה אֶת תְּפִלָּתָם וְגוֹ'."]]]]};
